    "question": "選挙権及び選挙制度に関する次のアからウまでの各記述について、正しいものには○、誤ってい\nるものには×を付した場合の組合せを、後記1から8までの中から選びなさい。\nア．最高裁判所は、国民の選挙権行使の制限は原則として許されず、国には、国民が選挙権を行\n使できない場合、そのような制限なしには選挙の公正の確保に留意しつつ選挙権行使を認める\nことが事実上不可能ないし著しく困難でない限り、選挙権行使を可能にするための所要の措置\nを執るべき責務があるというべきであり、このことは、精神的原因によって投票所に行くこと\nが困難な有権者の選挙権についても当てはまるとした。\nイ．最高裁判所は、政見放送は民主政治の根幹をなす政治上の表現の自由に基づくものであり、\nいかなる政見放送であってもそのまま放送されるべきであるから、放送事業者が政見放送にお\nいて用いられた差別的言動を削除したことは、当然に不法行為法上、法的利益の侵害に当たる\nとした。\nウ．最高裁判所は、1人別枠方式の意義は、衆議院議員選挙制度の変更に伴い、国政における安\n定性、連続性の確保を図るための暫定的な措置であるということにあると解されるから、その\n合理性には時間的な限界があり、新しい選挙制度である小選挙区比例代表並立制が定着し、安\n定した運用がされるようになった段階ではその合理性が失われるとした。",
