    "question": "衆議院の解散に関する次のアからウまでの各記述について、正しいものには○、誤っているもの\nには×を付した場合の組合せを、後記1から8までの中から選びなさい。\nア．衆議院が解散決議をして自律的に解散することはできないとする見解は、自律的解散を認め\nると、衆議院の多数派の意思によって少数派の議員たる地位を奪うことが可能になることや、\n自律的解散について憲法に明文の規定がないことをその根拠としている。\nイ．衆議院の解散に係る天皇の国事行為を定める憲法第7条第3号に、内閣の衆議院解散権の根\n拠を求める見解に対しては、最初から形式的行為にすぎない天皇の国事行為に対する内閣の助\n言と承認を、衆議院解散の実質的決定権の根拠とすることはできないとの批判がある。\nウ．最高裁判所は、衆議院の解散は憲法第81条にいう「処分」であって、裁判所の違憲審査の\n対象となるが、極めて政治性の高い国家統治の基本に関する行為であるから、その法律上の有\n効無効を審査することは裁判所の権限の外にあるものとした。",
