    "subject": "憲法",
    "label": "第12問",
    "question": "次の対話は、地方自治に関する教授と学生の対話である。教授の各質問に対する次のアからウま\nでの学生の各回答について、正しいものには○、誤っているものには×を付した場合の組合せを、\n後記1から8までの中から選びなさい。\n教授．憲法は、国会が国権の最高機関であることを定めるとともに、内閣総理大臣は国会議員の\n中から選出され、国務大臣の過半数は国会議員の中から選ばなければならないと定めていま\nすが、地方公共団体における議会と首長の関係はどのようなものですか。\nア．地方公共団体においては、議会の議員だけでなく、首長も住民による直接選挙によって選\n出され、法律上、議会の議員と首長との兼職が禁止されています。また、国会が国権の最高\n機関であるのと異なり、地方公共団体においては、議会が自治権の最高機関たる地位にある\nものではありません。\n教授．同じく国会と内閣の関係に関し、憲法は、内閣が衆議院を解散できると定めていますが、\nこの点につき、地方公共団体における議会と首長の関係ではどうですか。\nイ．法律上、地方公共団体では、首長も住民による直接選挙によって選出され、議会と首長は\n独立対等の関係とされていますので、首長に議会の解散権は認められていません。\n教授．議員の地位に関し、国会議員には、憲法上、発言・表決に対する免責特権と会期中の不逮\n捕特権が保障されており、その地位が厚く保護されていますが、この点につき、地方公共団\n体の議会の議員はどうですか。\nウ．地方公共団体の議会の議員は、憲法上、免責特権も不逮捕特権も保障されておらず、法律\n上、住民による解職請求が認められています。",
