    "question": "学生Ａ、Ｂ及びＣは、【事例】について、【会話】のとおり議論している。【会話】中の①から\n⑪までの（ ）内に【語句群】から適切なものを入れた場合、正しいものの組合せは1から5まで\nのうちどれか。なお、①から⑪までの（ ）内には、それぞれ異なるものが入る。\n【事 例】\n甲及び乙は、Ｘに対して傷害を負わせる旨の共謀を遂げ、それぞれ鉄パイプでＸを殴った。甲\nは、Ｘが反抗的な態度を示したため激高し、Ｘに対する殺意を抱き、傷害の故意にとどまる乙と\n共にＸに暴行を加えたことにより、Ｘは死亡した。\n【会 話】\n学生Ａ．共同正犯の本質について（①）に立った場合、共同正犯の成立は（②）ので、【事例】\nでは（③）ということになりますね。\n学生Ｂ．その考え方は（④）という問題があるのではないでしょうか。さらに、乙には（⑤）の\n故意がないのに、（⑤）罪の共同正犯の成立を認めることにも疑問があります。\n学生Ｃ．共同正犯の本質について（⑥）に立った場合、共同正犯の成立は（⑦）ので、【事例】\nでは（⑧）ということになりますね。\n学生Ａ．その考え方を一貫させると（⑨）という問題があるのではないでしょうか。\n学生Ｂ．共同正犯の本質について（①）に立ちつつ、構成要件が同質的で重なり合う限りにおい\nて共同正犯の成立を認める見解に立った場合、【事例】では（⑩）ということになります\nね。\n学生Ｃ．その考え方によると、【事例】において、乙の行為から死亡結果が発生した場合、甲に\n（⑪）罪の単独犯が成立するにとどまってしまうという問題があるのではないでしょうか。\n【語句群】\nａ．犯罪共同説 ｂ．行為共同説\nｃ．同一罪名に限られる ｄ．異なる罪名でも認められる\nｅ．甲に殺人罪の共同正犯、乙に傷害致死罪の共同正犯が成立する\nｆ．甲及び乙に傷害致死罪の共同正犯が成立し、甲に殺人罪の単独犯が成立する\nｇ．甲及び乙に殺人罪の共同正犯が成立し、乙は傷害致死罪の限度で科刑される\nｈ．共同正犯の成立範囲が広がりすぎる ｉ．罪名と科刑が分離する\nｊ．殺人 ｋ．殺人未遂 ｌ．傷害致死",
