    "question": "放火及び失火の罪に関するアからオまでの各記述を検討した場合、正しいものの組合せは1から\n5までのうちどれか。\nア．甲は、自己所有の家屋に一人で居住していたが、同家屋に掛けた火災保険の保険金をだまし\n取ろうと考え、同家屋に放火して全焼させ、公共の危険を生じさせた。この場合、甲に他人所\n有非現住建造物等放火罪が成立する。\nイ．甲は、自己所有の無人倉庫に放火しようと考え、同倉庫に置かれた新聞紙に火をつけたが、\n同新聞紙が燃えたにとどまり、同倉庫は焼損しなかった。この場合、甲に自己所有非現住建造\n物等放火罪の未遂罪が成立する。\nウ．甲は、Ａ所有の自動車に放火しようと考え、同放火に使用するガソリンとライターを持って\n同車に近づいたが、甲に不審を抱いた警察官から職務質問を受けたため、同車に放火するに至\nらなかった。この場合、甲に放火予備罪が成立する。\nエ．甲は、自己所有の無人倉庫を失火により焼損し、それによって公共の危険を生じさせた。こ\nの場合、甲に失火罪が成立する。\nオ．甲は、Ａが居住するＡ所有の家屋に放火しようと考え、同家屋近くの消火栓から放水できな\nいように同消火栓を損壊したが、放火するに至らなかった。この場合、甲に消火妨害罪が成立\nする。",
