    "question": "学生Ａ及びＢは、【会話】のとおり議論している。【会話】中の①から⑧までの（ ）内に【語\n句群】から適切なものを入れた場合、正しいものの組合せは1から5までのうちどれか。なお、①\nから⑧までの（ ）内には、それぞれ異なるものが入る。\n【会 話】\n学生Ａ．支払意思・能力がないことを秘して飲食店で注文し、飲食物の提供を受けた無銭飲食の\n事案について、詐欺罪は成立しますか。\n学生Ｂ．私は、判例と同様に、（①）といえ、（②）に当たるので、詐欺罪が成立すると考えま\nす。\n学生Ａ．約款により暴力団関係者の施設利用を拒絶しているゴルフ場において、暴力団関係者が\nその旨を申告することなく施設利用をした場合はどう考えますか。\n学生Ｂ．私は、判例と同様に、事案によっては詐欺罪が成立しない場合もあると考えます。詐欺\n罪が成立するとした判例では、（②）を認定できる事情がありました。一方、詐欺罪が成\n立しないとした判例では、ゴルフ場側が（③）するなどして、暴力団関係者による施設利\n用を（④）する意向を示していたものの、それ以上に（⑤）する措置は講じていなかった\nという事情がありました。また、（③）している周辺のゴルフ場において、暴力団関係者\nの施設利用を（⑥）する例が多数あったことなど、（②）を認定することが困難な事情が\nありました。そのため、暴力団関係者であることを申告せずに施設利用を申し込んだとし\nても、（⑦）ので、（⑧）としました。\n【語句群】\nａ．飲食後、直ちに代金を支払う意思・能力がないことを告知する義務があるのに、その義務に\n違反して真実を告げていない\nｂ．飲食店における注文は、暗黙の前提として、飲食後、直ちに代金を支払う意思・能力がある\nとの意思表示を内包している\nｃ．挙動による欺罔行為 ｄ．不作為による欺罔行為\nｅ．利用客に対して暴力団関係者でないことを確認\nｆ．暴力団関係者の施設利用を拒絶する旨の立看板を設置\nｇ．許可・黙認 ｈ．拒絶\nｉ．利用客は正規の利用料金を支払っており、ゴルフ場に経済的な不利益はない\nｊ．申込者が当然に暴力団関係者でないことまで表しているとは認められない\nｋ．財産的損害が発生していない ｌ．欺罔行為に当たらない",
