    "question": "学生Ａ及びＢは、【会話】のとおり議論している。【会話】中の①から⑧までの（ ）内に、\n【語句群】から適切なものを入れた場合、正しいものの組合せは1から5までのうちどれか。なお、\n①から⑧までの（ ）内には、それぞれ異なるものが入る。\n【会 話】\n学生Ａ．判例は、複写機による公文書のコピーについて、公文書偽造罪の客体になり得ることを\n（①）し、その場合の名義人を（②）としていますね。\n学生Ｂ．その判例に対しては、（③）という批判があります。\n学生Ａ．市長の代決者である課長を補助する係長など補助公務員にも市長名義の公文書の作成権\n限が認められる場合があるかについて、（④）とした判例がありますね。\n学生Ｂ．その判例に対しては、（⑤）という批判があります。\n学生Ａ．補助公務員が職務上起案を担当する文書につき虚偽のものを起案し、事情を知らない作\n成権限者である上司を利用して同文書を作成させた場合、判例は、（⑥）罪の間接正犯は\n（⑦）としていますね。\n学生Ｂ．公務員でない者が虚偽の申立てをして、事情を知らない公務員を利用して虚偽の公文書\nを作成させた場合、判例は、（⑧）罪の場合以外は（⑥）罪の間接正犯は処罰しないのが\n刑法の趣旨であると解するのが相当としていますね。\n【語句群】\nａ．肯定 ｂ．否定 ｃ．原本作成名義人 ｄ．コピー作成者\nｅ．原本のコピーは、写しとはいえ、原本と同一の意識内容を保有し、証明文書として原本と同\n様の社会的機能と信用性を有するものと認められるので、公文書偽造罪の客体とすべきである\nｆ．コピーそれ自体を原本として行使する場合を除き、コピーの作成名義人はコピー作成者であ\nり、コピーにはその記載を欠くので文書偽造罪にいう文書ということはできない\nｇ．補助公務員である以上、一律に作成権限を有することはない\nｈ．公文書の内容の正確性を確保することなど、その者への授権を基礎付ける一定の基本的な条\n件に従う限度において作成権限を有している\nｉ．作成権限に一定の条件を付することは可能である\nｊ．刑法が公文書偽造と虚偽公文書作成を区別している以上、文書の内容が正確ならば作成権限\nがあるという解釈は、その建前に反する\nｋ．虚偽公文書作成 ｌ．公正証書原本不実記載等\nｍ．成立し得る ｎ．成立し得ない",
