    "subject": "刑法",
    "label": "第9問",
    "question": "学生Ａ及びＢは、【事例】について、【会話】のとおり議論している。【会話】中の①から⑨ま\nでの（ ）内に【語句群】から適切なものを入れた場合、正しいものの組合せは1から5までのう\nちどれか。なお、①から⑨までの（ ）内には、それぞれ異なるものが入る。\n【事 例】\n甲は、殺人事件を目撃し、その犯人はＸに見えたという記憶であるが、大人しいＸが殺人事件\nを起こすはずがなく、真実はＸとよく似たＹが犯人であると考え、Ｘを被告人とする殺人事件の\n公判廷において、宣誓の上、「犯人はＹである。」と自己の記憶に反する証言をした。客観的な\n真実としては、上記殺人事件の犯人はＹではなくＸであった。\n【会 話】\n学生Ａ．甲に偽証罪が成立するか否かは、刑法第169条の「虚偽」の解釈によりますね。私は、\n証人が経験した内容を正確に反映することが刑事司法にとって重要であると考えるので、\n「虚偽」とは（①）ことであると考えます。\n学生Ｂ．私は、Ａさんとは異なり、「虚偽」とは（②）ことであると考えます。\n学生Ａ．私の立場からすると、（③）ので、甲の証言は「虚偽」に当たります。甲は、（④）の\nで、（⑤）。\n学生Ｂ．私の立場からすると、（⑥）ので、甲の証言は「虚偽」に当たります。甲は、（⑦）の\nで、（⑧）。\n学生Ａ．判例は、（⑨）と同様の立場に立っていますね。\n【語句群】\nａ．客観的真実に反する ｂ．証人の記憶に反する\nｃ．客観的にはＸが犯人である ｄ．甲の記憶ではＸが犯人である\nｅ．自己の記憶に反する証言をしていると認識しており、故意も認められる\nｆ．真実を証言していると認識している以上、故意が認められない\nｇ．偽証罪が成立します ｈ．偽証罪は成立しません\nｉ．Ｂさん ｊ．私",
