    "year_label": "R7",
    "subject": "刑事訴訟法",
    "label": "第16問",
    "question": "次のⅠないしⅢの【見解】は、逮捕・勾留の要件が備わらないＡ事実での逮捕・勾留に先立って、\n逮捕・勾留の要件が備わっているＢ事実で逮捕・勾留する場合の適法性に関するものである。【見\n解】に関する後記アからオまでの【記述】のうち、誤っているものの組合せは、後記1から5まで\nのうちどれか。\n【見解】\nⅠ．Ｂ事実について逮捕・勾留の要件が備わっていたとしても、捜査機関がＢ事実による逮捕・\n勾留を専ら又は主としてＡ事実の捜査に利用する意図である場合には、Ｂ事実による逮捕・勾\n留は実質的にＡ事実による逮捕・勾留と評価され、違法となる。\nⅡ．Ｂ事実について逮捕・勾留の要件が備わっているか否かを基準に適法性を判断すべきであり、\nＢ事実について逮捕・勾留の要件が備わっている限り、Ｂ事実による逮捕・勾留は適法である。\nⅢ．Ｂ事実によって逮捕・勾留された後の身体拘束期間が主としてＡ事実の捜査のために利用さ\nれるに至った場合には、それ以降の身体拘束は、Ｂ事実による逮捕・勾留としての実体を喪失\nし、Ａ事実による身体拘束となっていると評価され、違法となる。\n【記述】\nア．Ⅰの見解でも、Ｂ事実による身体拘束期間にＢ事実の取調べと並行してＡ事実の取調べを行\nった場合、その身体拘束が違法にならないことがある。\nイ．Ⅱの見解では、Ｂ事実による身体拘束が適法に行われたものである以上、仮にその身体拘束\n期間中に専らＡ事実の取調べが行われており、Ｂ事実の取調べが全く行われていないような場\n合でも、Ａ事実の取調べが違法となることはない。\nウ．Ⅲの見解は、逮捕・勾留期間につき、その理由とされた被疑事実について被疑者の逃亡・罪\n証隠滅を防止した状態で起訴・不起訴の決定に向けた捜査を行う期間であると捉える考えと整\n合しない。\nエ．Ⅰの見解に対しては、逮捕・勾留の場面において、裁判官が捜査機関の意図・目的を審査す\nることは現実的には容易ではないとの批判がある。\nオ．Ⅱの見解に対しては、捜査機関による身体拘束の濫用という問題の本質を無視する考え方で\nあるとの批判がある。",
