    "question": "公判前整理手続に関する次のアからオまでの各記述のうち、誤っているものの組合せは、後記1\nから5までのうちどれか。\nア．被告人は、裁判員裁判の対象事件ではない事件について、事件を公判前整理手続に付するこ\nとを求めることができる。\nイ．裁判所は、裁判員裁判の対象事件ではない事件について、検察官と弁護人の双方が公判前整\n理手続に付することを求めている場合には、事件を公判前整理手続に付さなければならない。\nウ．検察官は、公判前整理手続に付された事件において、検察官請求証拠の開示をした後、被告\n人又は弁護人から請求があったときは、速やかに、被告人又は弁護人に対し、検察官が保管す\nる証拠の一覧表の交付をしなければならない。\nエ．検察官は、公判前整理手続において取調べを請求した証人について、被告人又は弁護人に対\nし、同証人が公判期日において供述すると思料する内容が明らかになる書面等を閲覧する機会\nを与えなければならない。\nオ．裁判所は、公判前整理手続において検察官及び弁護人が行った証拠調べの請求の全てについ\nて、同手続終結までに、証拠調べをする決定又は証拠調べの請求を却下する決定をしなければ\nならない。",
