    "subject": "刑事訴訟法",
    "label": "第19問",
    "question": "次の【事例】について述べた後記アからオまでの【記述】のうち、誤っているものの組合せは、\n後記1から5までのうちどれか。\n【事例】\nＨ県Ｉ警察署の司法警察員Ｘは、同県内の時計店で発生した高級腕時計を被害品とする窃盗事件\nについて捜査に従事していたところ、令和6年7月15日午後1時頃、Ｉ市内の飲食店で無銭飲食\nがあったとの通報を受けて同店に急行し、同日午後1時15分、同店内にいた甲を詐欺罪の現行犯\n人として逮捕した。甲は、逮捕後の取調べにおいて、逮捕時に所持していたショルダーバッグ内に\n入っていた新品の高級腕時計について、「これは趣味で集めている時計で、海外で自分で買ったも\nのだ。」と供述した。Ｘは、前記窃盗事件及び前記詐欺事件について、それぞれ被害店舗の実況見\n分や被害店舗従業員らの取調べを行った上で、同月17日午後1時に詐欺罪の事実で甲をＨ地方検\n察庁検察官に送致する手続をした。同日午後1時30分に甲の送致を受けたＨ地方検察庁検察官Ｙ\nは、甲に弁解の機会を与え、留置の必要があると判断したので、同月18日正午、Ｈ地方裁判所裁\n判官に、詐欺罪の事実で甲の勾留を請求し、同裁判所裁判官Ｚは、同日午後3時、被疑者を甲、罪\n名を詐欺とする勾留状を発付した。これを受けて、司法警察員Ｘは、同日午後4時、同勾留状を執\n行した。その後、甲の勾留期間は延長されなかった。\n【記述】\nア．検察官Ｙは、令和6年7月18日正午に勾留を請求しているが、同日午後1時30分までに\n勾留を請求すれば足りる。\nイ．検察官Ｙは、裁判官Ｚが、罪証を隠滅すると疑うに足りる相当な理由がないことを理由とし\nて勾留請求を却下した場合、これに不服があるときでも、Ｈ地方裁判所に対し、その裁判を取\nり消して甲を勾留するよう請求することは許されない。\nウ．詐欺罪の事実について勾留の理由又は必要がなくなった場合、検察官Ｙは、窃盗罪の事実に\nついて捜査の必要があることを理由として甲の勾留を継続することは許されない。\nエ．検察官Ｙが、窃盗罪の事実について甲を逮捕しないまま、詐欺罪の事実に窃盗罪の事実を併\nせて勾留を請求した場合、勾留請求を受けた裁判官は、詐欺及び窃盗のいずれについても勾留\nの理由及び必要性が認められると判断したとき、両罪について勾留状を発付することができる。\nオ．甲の勾留期間の満了日は、令和6年7月27日である。",
