    "subject": "刑事訴訟法",
    "label": "第20問",
    "question": "次の【事例】について述べた後記アからオまでの【記述】のうち、正しいものは幾つあるか。後\n記1から6までのうちから選びなさい。\n【事例】\n令和7年2月1日午前1時50分頃、司法警察員Ｘは、近隣住民から「Ｔ公園で男性が血を流し\nて倒れている。」との通報を受け、Ｔ公園に向かい、同日午前2時頃、頭から血を流して倒れてい\nるＶを発見した。Ｖは、Ｘに「男に金属バットで頭を殴られ、迷彩柄の財布を奪われた。」と説明\nした。そこで、Ｖを被害者とする強盗傷人事件の捜査が開始された。\nＸは、同日午前3時頃、Ｔ公園内の人気のない草むらで、血痕が付着した金属バットを発見し、\n①その場でこれを押収した。また、ＸがＴ公園内に設置された防犯カメラの映像を確認したところ、\n同日午前1時頃に金属バットを手に持っている男（甲）が映っていた。\nＸは、同日午前5時頃、Ｔ公園から約1キロメートル離れた公道上を歩いている甲を見付け、②\n甲の尾行を開始した。その尾行中、Ｘは、甲が迷彩柄の財布を上着のポケットから取り出し、再び\n同ポケットに戻したことを確認したため、甲に声を掛け、自らが警察官であることを告げた上で、\n所持品を見せるよう求めた。すると、甲は、上着のポケットから何かを取り出そうとしたが、その\n際、透明のポリ袋を路上に落とした。Ｘは、甲の同意を得て同ポリ袋を拾い、中に白色粉末が入っ\nていることを確認した。Ｘは、同粉末について、③覚醒剤の予試験を実施したところ、覚醒剤であ\nるとの試験結果が得られた。そこで、Ｘは、④甲を覚醒剤取締法違反（所持）の被疑事実で逮捕し、\n⑤同ポリ袋とともに、甲の上着のポケット内にあった迷彩柄の財布を押収した。\n【記述】\nア．下線部①につき、Ｘは、金属バットを押収するに当たり、裁判官による令状の発付を受ける必要\nがある。\nイ．下線部②につき、Ｘは、甲を尾行するに当たり、裁判官による令状の発付を受ける必要があ\nる。\nウ．下線部③につき、Ｘは、予試験を実施するに当たり、甲が同意しているか否かを問わず、裁\n判官による令状の発付を受ける必要がある。\nエ．下線部④につき、Ｘは、甲を逮捕するに当たり、裁判官による令状の発付を受ける必要があ\nる。\nオ．下線部⑤につき、Ｘは、証拠物を押収するに当たり、ポリ袋と財布のいずれについても、裁\n判官による令状の発付を受ける必要がある。",
