    "subject": "刑事訴訟法",
    "label": "第21問",
    "question": "弁護人に関する次のアからオまでの各記述のうち、正しいものの組合せは、後記1から5までの\nうちどれか。ただし、判例がある場合には、それに照らして考えるものとする。\nア．裁判所は、被告人の私選弁護人の数を制限することはできない。\nイ．勾留を請求された被疑者は、国選弁護人の選任を請求するに当たり、その資力のいかんを問\nわず、あらかじめ、その勾留の請求を受けた裁判官の所属する裁判所の所在地を管轄する地方\n裁判所の管轄区域内に在る弁護士会に私選弁護人の選任の申出をしていなければならない。\nウ．特定の被疑事実について裁判官に選任された被疑者の国選弁護人は、当該被疑事実について\nの勾留が取り消され、被疑者が釈放されたとしても、当該被疑事実について検察官の終局処分\nがされるまでは、被疑者の国選弁護人としての地位を失うことはない。\nエ．被告人に氏名を記載することができない合理的な理由がないのに、被告人の署名のない弁護\n人選任届によってした私選弁護人の選任は無効である。\nオ．被告人又は被疑者の法定代理人、保佐人、配偶者、直系の親族及び兄弟姉妹は、独立して私\n選弁護人を選任することができる。",
