    "question": "控訴に関する次のアからオまでの各記述のうち、正しいものの組合せは、後記1から5までのう\nちどれか。ただし、判例がある場合には、それに照らして考えるものとする。\nア．控訴をするには、申立書を控訴裁判所に差し出さなければならない。\nイ．控訴裁判所は、被告人のみが控訴をした事件につき、原判決の刑より重い刑を言い渡すこと\nができる。\nウ．控訴の取下げをした者は、その事件について更に控訴をすることができない。\nエ．控訴審は事後審であるから、控訴裁判所は、第一審判決後に生じた刑の量定に影響を及ぼす\n情状について取り調べることはできない。\nオ．控訴審における事実誤認の審査は、第一審判決が行った証拠の信用性評価や証拠の総合判断\nが論理則、経験則等に照らして不合理といえるかという観点から行うべきである。",
