    "label": "第23問",
    "question": "次の【事例】について述べた後記アからオまでの【記述】のうち、誤っているものの組合せは、\n後記1から5までのうちどれか。\n【事例】\n甲は、「令和6年11月8日午後11時頃、Ｈ市内の路上において、Ｖをナイフで刺して殺害し\nた」との殺人の事実により、Ｈ地方裁判所に起訴された。公判において、甲は、本件殺人事件につ\nいて犯人ではないと否認し、甲の知人Ａ、犯行を目撃したＶの知人Ｂ、甲と同居する甲の父親Ｃの\n証人尋問が、それぞれ実施された。\nＡは、「令和6年11月7日午後5時頃、甲が私に電話してきて『①明日Ｖを殺そうと思う。手\n伝ってくれないか。』と言ってきたが、断った。すると、甲は、『それならば一人でやるしかない。\n②ナイフを用意した。これでＶを刺す。』と言ってきた。また、同月9日午前8時頃、再び甲が私\nに電話してきて『予定どおりやってやった。③昨晩、Ｈ市内の路上にＶを呼び出し、ナイフで刺し\nて逃げてきた。』と言ってきた。」と証言した。\nＢは、「令和6年11月8日午後11時頃、Ｈ市内の路上でＶを見掛け、声を掛けようとしたと\nころ、知らない男がＶに近付いた。Ｖは、その男に向かって『④甲、何の用だ。』と言った。その\n直後、その男がＶに刃物のようなものを突き刺して逃げていった。」と証言した。\nＣは、「令和6年11月9日午前10時頃、自宅において、甲から『⑤昨日午後11時頃は、俺\nはＩ市内をドライブしていた。』と言われた。」と証言した。\n【記述】\nア．Ａの証言中の下線部①は、要証事実を「甲がＡにＶの殺害を手伝うよう言ったこと」とした\n場合、伝聞証拠に当たる。\nイ．Ａの証言中の下線部②は、要証事実を「甲が凶器としてナイフを用意していたこと」とした\n場合、伝聞証拠に当たる。\nウ．Ａの証言中の下線部③は、要証事実を「Ｖを殺したのが甲であったこと」とした場合、伝聞\n証拠に当たる。\nエ．Ｂの証言中の下線部④は、要証事実を「犯人がＶから甲と呼ばれていたこと」とした場合、\n伝聞証拠に当たる。\nオ．Ｃの証言中の下線部⑤は、要証事実を「事件発生時、甲が事件現場から離れた場所にいたこ\nと」とした場合、伝聞証拠に当たる。",
