    "question": "刑事訴訟法第321条第1項の書面に関する次のアからオまでの各記述のうち、正しいものは幾\nつあるか。後記1から6までのうちから選びなさい。ただし、判例がある場合には、それに照らし\nて考えるものとする。\nア．同項第1号の「裁判官の面前における供述を録取した書面」は、当該事件に関して作成され\nたものに限られ、被告人以外の者に対する事件の公判廷における同人の被告人としての供述を\n録取したものは含まれない。\nイ．共同被告人の検察官に対する供述調書は、共同被告人が被害者その他の純然たる証人とその\n本質を異にするから、同項第2号の「検察官の面前における供述を録取した書面」に当たらな\nい。\nウ．証人が公判廷において証言を拒否した場合、同項第2号前段の「公判期日において供述する\nことができないとき」に該当し、期日を改めて期間をおけば証言が得られる見込みがあったこ\nとを考慮する余地はない。\nエ．同項第2号ただし書の「前の供述を信用すべき特別の情況」（相対的特信情況）は、供述が\nなされた際の外部的・付随的情況を指すから、その存否を判断する際に供述内容自体を考慮す\nることはできない。\nオ．被告人以外の者の司法警察員に対する供述調書で供述者の署名又は押印のあるものは、供述\n者の供述不能の要件が存在し、かつ、その供述が特に信用すべき情況（絶対的特信情況）の下\nにされたものであることが認められれば、同項第3号により証拠能力が認められる。",
