    "question": "意思表示等に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組み合\nわせたものは、後記1から5までのうちどれか。\nア．意思表示の相手方が意思表示を受けた時点において保佐開始の審判を受けていたときであっ\nても、表意者は、その意思表示をもってその相手方に対抗することができる。\nイ．意思表示の相手方が意思表示を受けた時点において未成年者であったときでも、その法定代\n理人がその意思表示を知った後は、表意者は、その意思表示をもってその相手方に対抗するこ\nとができる。\nウ．債権譲渡通知は、債権の譲渡人が債務者の所在を知ることができないときであっても、公示\nの方法によってすることができない。\nエ．解除の意思表示を含む内容証明郵便が、その意思表示の相手方である受取人が不在のため一\n定期間郵便局に留置された後に差出人に返送された場合において、その受取人がその内容証明\n郵便の内容を十分に推知することができなかったとしても、留置期間内に容易にそれを受領す\nることができたときは、その意思表示は、到達したものと認められる。\nオ．意思表示の相手方が正当な理由なくその意思表示の通知が到達することを妨げたときは、そ\nの通知は、相手方がその到達を妨げた時に到達したものとみなされる。",
