    "question": "Ａは、自己に代理権がないことを知りながら、Ｂの代理人としてＣと契約を締結した。Ｃは、契\n約当時、Ａに代理権がないことを知らなかった。この事例に関する次のアからオまでの各記述のう\nち、判例の趣旨に照らし正しいものを組み合わせたものは、後記1から5までのうちどれか。（解\n答欄は、）\nア．Ａがした契約をＢが追認しない間は、Ｃは、その契約を取り消すことができる。\nイ．ＣがＢに対し、相当の期間を定めて、その期間内にＡがした契約を追認するかどうかを確答\nすべき旨の催告をした場合において、Ｂがその期間内に確答をしないときは、その契約を追認\nしたものとみなされる。\nウ．ＣがＡに代理権がなかったことを過失によって知らなかったときは、Ａは、Ｃに対して無権\n代理人の責任を負わない。\nエ．ＢがＡのした契約について追認を拒絶したときは、その後ＡがＢを相続したとしても、その\n契約が有効になるものではない。\nオ．Ｃから無権代理人の責任として契約の履行を求められたＡは、その履行に代えて、損害の賠\n償をすることができる。",
