    "question": "時効に関する次のアからオまでの各記述のうち、判例の趣旨に照らし誤っているものを組み合わ\nせたものは、後記1から5までのうちどれか。\nア．後順位抵当権者は、先順位抵当権の被担保債権の消滅により後順位抵当権者の抵当権の順位\nが上昇すれば配当額が増加することになるときであっても、先順位抵当権の被担保債権の消滅\n時効を援用することができない。\nイ．債務者は、債務について消滅時効が完成した後に、時効完成の事実を知らずに債権者に対し\n債務の承認をしたときであっても、消滅時効を援用することができる。\nウ．抵当権が設定された不動産の第三取得者は、その抵当権の被担保債権の消滅時効を援用する\nことができる。\nエ．同一の当事者間に数個の金銭消費貸借契約に基づく各元本債務が存在する場合において、借\n主が、弁済を充当すべき債務を指定することなく全債務を完済するのに足りない額の弁済をし\nたときは、その弁済は、特段の事情のない限り、各元本債務についての承認に当たる。\nオ．自己の所有物については、所有権の取得時効を援用することができない。",
