    "question": "Ａ及びＢが甲土地を共有している場合に関する次のアからオまでの各記述のうち、判例の趣旨に\n照らし正しいものを組み合わせたものは、後記1から5までのうちどれか。\nア．Ａが甲土地の管理のために費用を支払った後、Ｂがその持分をＣに譲渡したときは、Ａは、\nＣに対しても、Ｃの持分に応じてその費用の償還を求めることができる。\nイ．Ａは、甲土地を不法に占有するＤに対し、単独で甲土地全部の明渡しを求めることができな\nい。\nウ．Ａの債権者Ｅは、自己の費用で、甲土地の分割に参加することができる。\nエ．Ｂが甲土地を単独で使用する場合において、ＡとＢとの間の別段の合意がないときは、Ｂは、\n自己の持分を超える使用について、Ａに対し、その対価の償還の義務を負わない。\nオ．Ａが死亡した場合において、Ａに相続人がないときは、Ａの持分は、国庫に帰属する。",
