    "question": "ＡがＡ所有の甲建物をＢに売る契約の解除に関する次のアからオまでの各記述のうち、判例の趣\n旨に照らし誤っているものを組み合わせたものは、後記1から5までのうちどれか。\nア．Ａが本件契約をＢの債務不履行により解除した場合におけるＡのＢに対する原状回復請求権\nは、Ａが解除権の発生を知った時から5年間行使しないときは、時効によって消滅する。\nイ．Ｂが本件契約をＡの債務不履行により解除した場合において、ＡがＢに対し代金の返還義務\nを負うときは、Ａは、代金の受領の時から利息を付さなければならない。\nウ．Ａが本件契約をＢの債務不履行により解除したときは、甲建物の所有権は、遡及的にＡに復\n帰する。\nエ．Ａが本件契約をＢの債務不履行により解除したときは、Ａは、Ｂに対し、代金債務の履行に\n代わる損害賠償を請求することができる。\nオ．Ａが本件契約に基づく代金債権をＣに譲渡し、その譲渡について第三者対抗要件が備えられ\nたときは、Ｃは、その後にＢが本件契約をＡの債務不履行により解除したとしても、代金債権\nを失わない。",
