    "question": "不法行為に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組み合わ\nせたものは、後記1から5までのうちどれか。\nア．良好な景観に近接する地域内に居住し、その恵沢を日常的に享受している者は、この者が有\nする良好な景観の恵沢を享受する利益が違法に侵害されたことをもって、不法行為による損害\n賠償を請求することができる。\nイ．疾病のため死亡した患者の診療に当たった医師の医療行為が、その過失によって医療水準に\nかなったものでなかった場合において、医療水準にかなった医療が行われていたとすれば患者\nがその死亡の時点でなお生存していた相当程度の可能性の存在が証明されたときは、その医療\n行為と患者の死亡との間における因果関係が肯定される。\nウ．ある事実を基礎としての論評の表明によって他人の名誉を毀損した場合において、その行為\nが公共の利害に関する事実に係り、かつ、その目的が専ら公益を図ることにあったときは、人\n身攻撃に及ぶなど論評としての域を逸脱したものでない限り、その行為は、違法でない。\nエ．労働者Ａが、第三者Ｂの過失による事故によって負傷し、この事故を原因として労働者災害\n補償保険法に基づく保険給付を受けた。この場合におけるＢのＡに対する損害賠償責任につい\nて、Ａの過失をもって過失相殺をすべきであり、かつ、Ａが受けた保険給付の価額を控除すべ\nきときは、損害賠償の額は、まず過失相殺による減額をし、その残額から保険給付の価額を控\n除する方法により算定する。\nオ．人の身体を害する不法行為による損害賠償請求権は、被害者又はその法定代理人が損害及び\n加害者を知った時から3年間行使しないときは、時効によって消滅する。",
