    "label": "第16問",
    "question": "株式会社の発起設立に関する次のアからオまでの各記述のうち、誤っているものを組み合わせた\nものは、後記1から5までのうちどれか。\nア．発起人は、株式会社の成立後は、錯誤を理由として設立時発行株式の引受けの取消しをする\nことができない。\nイ．株式会社が成立しなかったときは、発起人は、連帯して、株式会社の設立に関して支出した\n費用を負担する。\nウ．現物出資財産を給付した発起人は、株式会社の成立の時における当該現物出資財産の価額が\n定款に記載又は記録された当該現物出資財産の価額に著しく不足する場合には、検査役の調査\nを経たときであっても、当該株式会社に対し、当該不足額を支払う義務を負う。\nエ．発起人は、公証人による定款の認証を受けた後であっても、株式会社の成立の時までに、発\n起人の全員の同意によって、当該定款を変更して本店の所在地を変更することができる。\nオ．判例の趣旨によれば、定款に記載又は記録しないでされた財産引受けは、成立後の株式会社\nが追認することにより、遡って有効になる。",
