    "question": "株式会社についての訴訟に関する次のアからオまでの各記述のうち、誤っているものを組み合わ\nせたものは、後記1から5までのうちどれか。\nア．株主総会決議不存在確認の訴えに係る請求を認容する確定判決は、第三者に対してもその効\n力を有する。\nイ．株式会社の取締役が退任した後に当該株式会社の株主となった者は、当該取締役の責任を追\n及する株主代表訴訟を提起することができない。\nウ．会社法上の公開会社でない株式会社は、株主から取締役の責任を追及する訴えの提起の請求\nを受けた場合において、当該請求の日から60日以内に当該訴えを提起しないときであって、\n当該請求をした株主から請求を受けたときは、当該株主に対し、遅滞なく、当該訴えを提起し\nない理由を通知しなければならない。\nエ．株主代表訴訟を提起した株主は、当該訴訟の係属中に株式交換により株主でなくなった場合\nには、当該株式交換により株式交換完全親会社の株式を取得したときであっても、当該訴訟を\n追行することができない。\nオ．監査役設置会社は、当該監査役設置会社の取締役を補助するため、当該監査役設置会社の株\n主が提起した当該取締役の責任を追及する株主代表訴訟に参加するには、監査役（監査役が2\n人以上ある場合にあっては、各監査役）の同意を得なければならない。",
