    "question": "訴えの利益に関する次のアからオまでの各記述のうち、判例の趣旨に照らし誤っているものを組\nみ合わせたものは、後記1から5までのうちどれか。\nア．Ｘは、Ｙを被告として、売買契約に基づき売買代金1000万円の支払を請求する訴えを提\n起し、Ｙに同額の支払を命じる判決が確定した。その後、無資力のＹが売買代金を支払わない\n状態が続き、裁判上の請求以外に消滅時効の完成猶予の方法がなかった。Ｘが、Ｙを被告とし\nて、消滅時効が完成する前に、再度、同売買代金の支払を請求する訴えを提起した場合におい\nて、当該訴えには、訴えの利益が認められる。\nイ．被相続人Ａが死亡し、その相続人は妻Ｘ、子Ｙ1及び子Ｙ2のみであった。Ｘ、Ｙ1及びＹ\n2の間において、Ａ名義の複数の不動産のうち甲土地がＡの遺産に属するか否かの争いがあっ\nた。Ｘが、Ｙ1及びＹ2を被告として、甲土地がＡの遺産に属することの確認を求める訴えを\n提起した場合において、当該訴えには、確認の利益が認められない。\nウ．被相続人Ａが死亡し、その相続人は子Ｘ及び子Ｙのみであった。Ｘ及びＹの間において、相\n続人の範囲や遺産の範囲については争いがなかったものの、Ｙは、成人してからも全く収入が\nなく、Ａが死亡するまでの約30年間にわたって、毎月、Ａから高額の生活費の支払を受けて\nおり、これが特別受益財産に当たるか否かの争いがあった。Ｘが、Ｙを被告として、ＡからＹ\nに支払われた上記生活費が特別受益財産であることの確認を求める訴えを提起した場合におい\nて、当該訴えには、確認の利益が認められない。\nエ．甲建物について、ＸからＹに所有権移転登記がされ、更にＹからＺに所有権移転登記がされ\nた。Ｘは、ＸからＹへの所有権移転登記はＸに無断でされたものであり、Ｘが甲建物を所有し\nていると主張して、Ｚを被告とし、ＹからＺへの所有権移転登記の抹消登記手続を求める訴え\nを提起したものの、Ｘの請求を棄却する判決が確定した。さらに、Ｘが、Ｙを被告として、Ｘ\nからＹへの所有権移転登記の抹消登記手続を求める訴えを提起した場合において、当該訴えに\nは訴えの利益が認められる。\nオ．甲土地上にはＹが所有する乙建物があるが、Ｘ及びＹの間においては甲土地の所有権をいず\nれが有しているのかにつき争いがある。Ｘが、Ｙを被告として、甲土地の所有権に基づき、乙\n建物を収去し甲土地を明け渡すことを求める訴えを提起することができる場合には、ＸがＹを\n被告として甲土地についてＸの所有権の確認を求める訴えには、確認の利益が認められない。",
