    "question": "将来給付の訴えに関する次のアからオまでの各記述のうち、判例の趣旨に照らし誤っているもの\nを組み合わせたものは、後記1から5までのうちどれか。\nア．将来給付の訴えにおける請求権としての適格を有しない請求権に基づく将来給付の訴えは、\nあらかじめその請求をする必要がある場合であっても、不適法なものとして許されない。\nイ．継続的不法行為に基づき、将来発生すべき損害の賠償を請求する将来給付の訴えは、不適法\nなものとして許されない。\nウ．物の現実の引渡しの請求に併せて、その執行不能の場合における履行に代わる損害賠償を請\n求する将来給付の訴えは、不適法なものとして許されない。\nエ．Ｘ及びＹが共有する土地につき、Ｙのみが駐車場として賃貸して収益を得ている場合に、Ｘ\nがＹに対し、事実審の口頭弁論終結後にＹが得る収益のうち、Ｙの持分割合を超える部分につ\nいて不当利得の返還を請求する将来給付の訴えは、不適法なものとして許されない。\nオ．本来の給付請求に併せて、その執行不能の場合における履行に代わる損害賠償を請求する将\n来給付の訴えは、本来の給付請求の強制執行が不能となることがあり得ない場合には、不適法\nなものとして許されない。",
