    "question": "釈明権の行使に関する次のアからオまでの各記述のうち、判例の趣旨に照らし誤っているものを\n組み合わせたものは、後記1から5までのうちどれか。\nア．陪席裁判官は、裁判長の許可がなくても、裁判長に告げれば釈明権を行使することができる。\nイ．裁判所が、判決において、原告と被告が共に主張しておらず、従前の訴訟の経過からは予測\nが困難な法律構成である信義則上の義務違反を認める判断をする場合に、当該信義則上の義務\n違反を基礎付ける事実が主張されていれば、原告に信義則上の義務違反の点について主張する\nか否かを明らかにするよう促す措置がとられていなくても、釈明権の行使を怠った違法がある\nとはいえない。\nウ．原告が主張する請求原因によっては原告の請求を認容することができないが、従前の訴訟の\n経過や訴訟資料からみて、別個の法律構成に基づく請求原因が主張されれば原告の請求を認容\nすることができるにもかかわらず、原告が明らかに誤解又は不注意によりそのような主張をし\nていないと認められる場合に、裁判長が原告に対して釈明権の行使としてその別個の法律構成\nを示唆することは、釈明権行使の範囲を逸脱した違法なものではない。\nエ．当事者は、相手方に対し、直接釈明権を行使することができる。\nオ．釈明権の行使は、口頭弁論の期日又は期日外においてすることができる。",
