    "question": "次の対話は、地方自治に関する教授と学生の対話である。教授の各質問に対する次のアからウま\nでの学生の各回答について、それぞれ正しい場合には1を、誤っている場合には2を選びなさい。\n\n教授．地方公共団体が、住民に関係する施策に対する賛否を問う住民投票を実施した場合におい\nて、その地方公共団体の長がその投票の結果を尊重するものとする旨を定める条例が設けら\nれていた場合、その地方公共団体の長は、その住民投票の結果に従うべき法的な義務を負う\nでしょうか。\n\nア．条例による住民投票の結果に法的拘束力を肯定すると、間接民主制によって地方政治を行\nおうとする現行法の制度原理と整合しない結果を招来することになりかねないため、その地\n方公共団体の長は、その結果に従うべき法的な義務を負うものではありません。\n教授．条例によって罰則を設けることは、罪刑法定主義との関係で問題はないでしょうか。また、\n条例によって罰則を設けることができるとした場合、その罰則には、法律上、何らかの制限\nは課されているでしょうか。",
