    "question": "損失補償に関する次のアからウまでの各記述について、最高裁判所の判例に照らし、正しいもの\nに○、誤っているものに×を付した場合の組合せを、後記1から8までの中から選びなさい。（解\n答欄は、）\nア．都市計画法第53条により、同条の施行区域内の土地に対し長期間にわたって建築制限が課\nされてきた場合、当該建築制限による損失は、その内容や程度にかかわらず、特別の犠牲とし\nて補償の対象となる。\n（参照条文）都市計画法\n第53条 都市計画施設の区域又は市街地開発事業の施行区域内において建築物の建築をし\nようとする者は、国土交通省令で定めるところにより、都道府県知事等の許可を受けなけ\nればならない。ただし、次に掲げる行為については、この限りでない。\n一～五 （略）\n2、3 （略）\nイ．旅館Ａで火災が発生し、消防団長が消火活動に当たり、旅館Ａに隣接する建物Ｂを破壊した\n際、建物Ｂへの延焼のおそれはなかったものの、付近の建物への延焼防止のため建物Ｂを破壊\nする緊急の必要性があった場合、建物Ｂの損失は補償の対象とならない。\nウ．Ｘ社が自己所有地の地下にガソリンタンクを適法に設置したところ、その後、国が地下道を\n新設したため、上記ガソリンタンクの設置状況が消防法違反の状態となりその移転を余儀なく\nされた場合でも、Ｘ社の支出した移転費用は道路法第70条の規定する補償の対象とならない。\n（参照条文）道路法\n第70条 土地収用法第93条第1項の規定による場合の外、道路を新設し、又は改築した\nことに因り、当該道路に面する土地について、通路、みぞ、かき、さくその他の工作物を\n新築し、増築し、修繕し、若しくは移転し、又は切土若しくは盛土をするやむを得ない必\n要があると認められる場合においては、道路管理者は、これらの工事をすることを必要と\nする者（中略）の請求により、これに要する費用の全部又は一部を補償しなければならな\nい。（以下略）\n2～4 （略）",
