    "question": "次のアからオまでの各記述を判例の立場に従って検討した場合、正しいものの組合せは、後記1\nから5までのうちどれか。\nア．甲は、真冬の深夜、甲から暴行を受けて衰弱したＡを河川堤防上に連れて行き、未必の殺意\nをもって、Ａを脅迫して護岸際まで追い詰め、さらに、Ａに対して殴りかかる態度を示したた\nめ、逃げ場を失ったＡが足を滑らせて堤防から3メートル下の川に転落して溺死した。この場\n合、甲に殺人罪は成立しない。\nイ．非科学的な力による難病治療を標ぼうしていた甲は、小児Ａがインスリンを定期的に摂取し\nなければ死亡する現実的な危険性がある重度の糖尿病患者であることを認識しながら、甲を信\n頼するＡの母親Ｂに対し、Ａへのインスリンの不投与を執ようかつ強度に働き掛けた。Ｂは、\nＡを完治させるためには甲の指導に従う以外に方法はないといちずに考え、Ａへのインスリン\nの投与という期待された作為に出ることができない精神状態に陥り、甲から言われるがままＡ\nへのインスリン投与を中止したため、Ａはその後間もなく死亡した。この場合、甲に殺人罪が\n成立する。\nウ．甲は、Ａの殺害を企て、致死量の毒物を混入した砂糖を、情を知らない郵便配達員を介して、\n贈答品を装ってＡに郵送し、Ａがこれを受領したが、Ａは、毒物の混入に気付いたため、同砂\n糖を食用に供することはなかった。この場合、甲に殺人未遂罪が成立する。\nエ．甲は、Ａに成り済ましてＡの管理する資材置場に保管されていたＡ所有の建設機械を自己の\n所有物であるかのように装って中古機械業者Ｂに売却し、甲をＡと思い込んでいたＢが甲との\n約定に基づき同建設機械を同置場から搬出した。この場合、甲にＡに対する窃盗罪は成立しな\nい。\nオ．医師ではない甲は、妊婦であるＡから依頼を受けてＡの堕胎手術を開始したが、医術により\n胎児を排出しなければＡの生命に危険を及ぼすおそれが生じたため、医師であるＢに胎児の排\n出を求めた。Ｂは、Ａの生命に対する危険を避けるため胎児をＡの母体外に排出させた。Ｂに\n緊急避難が成立する場合、甲に同意堕胎罪は成立しない。",
