    "question": "学生Ａ及びＢは、次の【事例】における甲の罪責について、後記の【会話】のとおり議論してい\nる。【会話】中の①から⑥までの（ ）内に後記【語句群】から適切なものを入れた場合、正しい\nものの組合せは、後記1から5までのうちどれか。なお、①から⑥までの（ ）内にはそれぞれ異\nなるものが入る。\n【事 例】\n甲は、返還期限を1年後と定めて甲所有の絵画を乙に無償で貸与したが、同期限経過後に、甲\nが何度も返還を求めても、乙は同絵画を返還しなかった。そのため、甲は、乙に対し、「俺をな\nめているのか。あの絵を返さないのなら殺すぞ。」などと言って脅し、乙は畏怖して上記絵画を\n甲に返還した。\n【会 話】\n学生Ａ．甲に恐喝罪が成立するか否かは、刑法第251条で準用される同法第242条の他人の\n「（①）」の解釈が問題になりますね。私は、他人の「（①）」は（②）と考えます。\n学生Ｂ．私は、他人の「（①）」は（③）と考えます。Ａさんの立場からすると、（④）ことか\nら、乙の（①）は他人の「（①）」に該当せず、甲の行為は、恐喝罪の構成要件に該当し\nないことになりますね。\n学生Ａ．そのとおりです。ただ、（⑤）が成立する余地はあります。Ｂさんの立場からすると、\n乙の（①）は他人の「（①）」に該当し、甲の行為は、恐喝罪の構成要件に該当すること\nになりますが、その結論は絵画の返還請求権を有する甲にとって酷ではありませんか。\n学生Ｂ．私の立場からも、権利実現のために実力行使に出る必要性、緊急性、手段の相当性の要\n件を満たすときは、（⑥）として違法性が阻却される余地があるので、酷ではないと考え\nます。\n【語句群】\nア．財物 イ．占有 ウ．権原に基づくものに限られる\nエ．事実上の所持で足りる オ．絵画の返還期限が経過している\nカ．絵画の平穏な占有が継続している キ．恐喝未遂罪 ク．脅迫罪\nケ．正当防衛 コ．自救行為",
