    "question": "財産罪の客体に関して、学生Ａ及びＢが次の【会話】のとおり議論している。【会話】中の①か\nら⑥までの（ ）内から適切なものを選んだ場合、正しいものの組合せは、後記1から5までのう\nちどれか。\n【会 話】\n学生Ａ．私は、財産罪の客体となる「財物」の意義について、①（ａ．一定の空間を占める物体\n・ｂ．人が管理し得る対象）を意味すると考えますので、電気を盗む行為は、刑法第24\n5条があって初めて処罰できることになると考えます。\n学生Ｂ．Ａさんは、同条を②（ｃ．注意規定・ｄ．処罰創設規定）と考えるわけですね。それで\nは、Ａさんは、甲が名簿業者に販売する目的で、勤務先会社の書庫において、同所で管理\nされていた同社従業員名簿を管理権者の許可なく、自分の携帯電話機で撮影し、その画像\nデータを保存した同携帯電話機を社外に持ち出した事案について、甲の窃盗罪の成否をど\nう考えますか。\n学生Ａ．私は、甲に窃盗罪が③（ｅ．成立する・ｆ．成立しない）と考えます。\n学生Ｂ．Ａさんは、「財物」の財産的価値についてどう考えますか。\n学生Ａ．私は、判例と同じく、財産罪の客体としての「財物」には、金銭的・経済的価値を④\n（ｇ．要する・ｈ．要しない）と考えます。この点、判例は、再利用する目的で使用済み\nの収入印紙を持ち出した事案について窃盗罪の財物性を⑤（ｉ．肯定・ｊ．否定）してい\nます。\n学生Ｂ．ところで、詐欺罪の客体である「財物」に関して、判例は、不動産を含むと解していま\nすよね。それでは、乙が代金を支払う意思も能力もないのに、これらがあるように装って、\n不動産の所有者丙に同不動産の購入を申し込み、同不動産を乙に売却する契約を締結させ、\nその後、乙名義に所有権移転登記をさせた事案について、刑法第246条第1項の詐欺罪\nの既遂時期をいつと考えますか。\n学生Ａ．私は、判例と同様、⑥（ｋ．所有権移転の意思表示があった時点・ｌ．現実に占有移転\nさせ、又は所有権取得の登記を経た時点）で既遂となると考えます。",
