    "subject": "刑法",
    "label": "第8問",
    "question": "中止犯における中止行為の任意性の判断基準に関する次の各【見解】についての後記アからオま\nでの各【記述】のうち、正しいものの組合せは、後記1から5までのうちどれか。\n【見 解】\nＡ説：行為者が、やろうと思えばできたが中止した場合を中止犯とし、やろうと思ってもできな\nかった場合は中止犯としない。\nＢ説：犯罪を中止した原因が社会通念に照らして犯罪続行の障害と考えられる事情かどうかによ\nって任意性を判断し、社会通念に照らして一般人であれば中止しないのが通例であると考え\nられるにもかかわらず、中止した場合を中止犯とする。\n【記 述】\nア．Ａ説の立場からは、中止行為が反省・悔悟等の自己の行為に対する否定的な感情に基づく場\n合に限り、中止犯が成立する。\nイ．Ａ説の立場からは、中止犯が成立するためには、行為者が犯罪意思を完全に放棄する必要が\nあり、犯罪に着手し、そのまま遂行可能であったが、他の機会を待つことが得策だと考えて中\n止した場合に中止犯が成立することはない。\nウ．建物に放火しようと考え媒介物に火を放ったが、犯行の発覚を恐れて焼損に至る前にその火\nを消した場合に、犯行の発覚を恐れることが一般に犯罪の遂行を妨げる事情たり得るとして中\n止犯の成立を否定する考え方は、Ｂ説と親和的である。\nエ．Ｂ説は、中止犯の刑の減免の根拠について責任が減少すると考える見解からは支持すること\nができない。\nオ．Ｂ説に対しては、任意性の判断は行為者の主観を問題とするのであるから、妥当ではないと\nの批判がある。",
