    "subject": "刑法",
    "label": "第11問",
    "question": "学生Ａ、Ｂ及びＣは、急迫不正の侵害に対してやむを得ずにした反撃行為（第1暴行）に続けて、\n侵害終了後も継続して追撃行為（第2暴行）に及んだ事例に関して、次の各【見解】のうち、いず\nれか異なる見解を採り、後記【会話】のとおり議論している。学生Ａ、Ｂ及びＣの採る見解として\n正しいものの組合せは、後記1から5までのうちどれか。\n【見 解】\nア．防衛の意思が継続している限りで、侵害現在時の第1暴行と侵害終了後の第2暴行を一体的\nに評価し、1個の過剰防衛の成立を認める。\nイ．防衛の意思が継続しているか否かにかかわらず、第1暴行については正当防衛の成立を認め、\n第2暴行については単なる違法行為として扱う。\nウ．防衛の意思が継続している限りで、第1暴行については正当防衛の成立を認め、第2暴行に\nついては過剰防衛の成立を認める。\n【会 話】\n学生Ａ．第1暴行から傷害結果が発生した場合、第1暴行を単独で評価すれば正当防衛となり、\n相手方に対する傷害結果は適法とされるはずなのに、Ｂさんの見解だと、同じ傷害結果を\n違法と評価することになってしまい不都合ですよね。\n学生Ｂ．そうでしょうか。むしろ、私は、社会的にひとまとまりのエピソードとみられる事態に\nついては、1個の法的評価を与えるべきだと考えます。私の見解によれば、第1暴行と第\n2暴行のどちらから結果が生じたのかが分からない場合であっても、生じた結果に対する\n責任を問うことができます。\n学生Ｃ．正当防衛から生じた可能性のある結果に責任を問うのは不当ではありませんか。\n学生Ａ．その点はＣさんに賛成です。しかし、私は、第2暴行については、違法性の減少を認め\nることができないので、Ｃさんと同じ見解は採りません。\n学生Ｃ．私は、追撃行為についても、防衛行為としての性格をなお肯定できる限りで、過剰防衛\nを認めてよいだけの責任減少があると考えます。",
