    "question": "次のアからオまでの各記述を判例の立場に従って検討した場合、正しいものの組合せは、後記1\nから5までのうちどれか。\nア．甲は、恐喝事件の被疑者としてＡに逮捕状が発せられていると知りながら、Ａが犯人ではな\nいと信じてＡを自宅にかくまったが、その後、Ａが逮捕され、Ａに対する有罪判決が確定した。\nこの場合、Ａが犯人蔵匿罪の「罪を犯した者」ではないと甲が誤信していたから、甲に同罪は\n成立しない。\nイ．甲は、Ａが窃盗事件の犯人であると知りながら、甲が所有する船舶にＡを乗船させてかくま\nった。この場合、甲が窃盗罪の法定刑が罰金以上の刑であることを認識していなくても、甲に\n犯人蔵匿罪が成立する。\nウ．甲は、Ａを被疑者とする覚醒剤取締法違反事件の参考人として警察官の取調べを受け、真実\nはＡが覚醒剤を所持したことがなかったのに、それを警察官に隠してＡが覚醒剤を所持してい\nたとの虚偽の内容の供述をして、それを信じた警察官に同内容の供述調書を作成させ、同調書\nに署名押印した。この場合、甲が虚偽の供述調書を作成させた以上、甲に証拠偽造罪が成立す\nる。\nエ．甲は、Ａを被疑者とする殺人未遂事件につき、Ｂが必要な知識を有する参考人として警察官\nの取調べを受ける可能性があることを察知し、知人宅にＢをかくまった。この場合、Ｂが捜査\n段階における参考人であったとしても、甲に証拠隠滅罪が成立する。\nオ．甲は、Ａを被告人とする恐喝事件の公判に証人として出廷したＢの証言後、Ｂに対し、同公\n判係属中、同証言をしたことに対して報復する旨の脅迫文言を記載した文書を郵送して閲読さ\nせた。この場合、Ｂが証言を終えているから、甲に証人威迫罪は成立しない。",
