    "subject": "刑事訴訟法",
    "label": "第14問",
    "question": "犯罪の証明に関する次のアからオまでの各記述のうち、誤っているものの組合せは、後記1から\n5までのうちどれか。ただし、判例がある場合には、それに照らして考えるものとする。（解答欄\nは、）\nア．刑事裁判における有罪認定に必要とされる「合理的な疑いを差し挟む余地のない程度の立\n証」とは、反対事実が存在する疑いを全く残さない場合をいうものではなく、反対事実が存在\nするとの疑いをいれる余地があっても、健全な社会常識に照らして、その疑いに合理性がない\nと一般的に判断される場合には、有罪認定を可能とする趣旨である。\nイ．情況証拠は、一般的に、目撃供述や被告人の自白といった直接証拠に比べて証明力が低いか\nら、情況証拠によって事実を認定すべき場合には、直接証拠によって事実を認定すべき場合よ\nりも証明の程度が高度である必要がある。\nウ．証拠の証明力は、裁判官の自由な判断に委ねられるが、裁判官の恣意的な判断を許すもので\nはないから、その判断は、論理則や経験則に照らし合理的なものでなければならない。\nエ．略式手続は、公判を開くことなく書面審理によって行われる簡易な手続であるから、犯罪の\n証明の程度は、証拠の優越で足りる。\nオ．共謀共同正犯における共謀の事実は、共謀共同正犯における「罪となるべき事実」に含まれ\nるから、刑事訴訟法の規定により証拠能力が認められ、かつ、公判廷における適式な証拠調べ\nを経た証拠による証明を要する。",
