    "question": "公判前整理手続に関する次のアからオまでの各記述のうち、正しいものの組合せは、後記1から\n5までのうちどれか。\nア．検察官又は弁護人は、裁判所に対し、公判前整理手続に付すことを請求できない。\nイ．検察官は、証人の尋問を請求する場合、争点及び証拠の整理のために、その者の供述録取書\n等のうち、その者が公判期日において供述すると思料する内容が明らかになるものを裁判所に\n提出しなければならない。\nウ．弁護人は、公判前整理手続に付された事件の公判において被告人の行為が正当防衛に該当す\nるとの主張を行う予定がある場合、公判前整理手続において、裁判所及び検察官に対し、これ\nを明らかにする必要がある。\nエ．公判前整理手続に付された事件の公判では、検察官、被告人及び弁護人が公判前整理手続に\nおいて取調べを請求しなかった証拠について、裁判所が職権で証拠調べをすることはできない。\nオ．裁判所は、公判前整理手続において鑑定を行うことを決定した場合、鑑定の結果の報告がな\nされるまでに相当の期間を要すると認めるときには、公判前整理手続内において、鑑定人に鑑\n定の手続の一部を行わせることができる。",
