    "subject": "刑事訴訟法",
    "label": "第16問",
    "question": "次のアからオまでの各記述のうち、正しいものの組合せは、後記1から5までのうちどれか。\n\nア．弁護人は、検察官から取調べの請求がなされた書証について、被告人の明示した意思に反し\nて、それを証拠とすることに同意することができる。\nイ．控訴審では、被告人自身が弁論をすることはできず、控訴趣意書を被告人が差し出した場合\nでも、それに基づく弁論は弁護人が行う。\nウ．弁護人は、あらかじめ証拠を保全しておかなければその証拠を使用することが困難な事情が\nあるときは、公訴の提起前に限り、裁判官に押収、捜索、検証、証人の尋問又は鑑定の処分を\n請求することができる。\nエ．原審における弁護人は、被告人の明示した意思に反して、被告人のため上訴をすることがで\nきない。\nオ．弁護人は、捜査機関が令状の発付を受けて行う捜索差押えに立ち会う権利を有する。",
