    "subject": "刑事訴訟法",
    "label": "第17問",
    "question": "次の【事例】で、Ｘの公判において、以下の各供述録取書を証拠として用いる場合（刑事訴訟法\n第326条及び同法第328条の場合を除く。）、その証拠能力について述べた後記アからオまで\nの【記述】のうち、正しいものには1を、誤っているものには2を選びなさい。\n【事例】\nＸは、令和5年5月1日午後11時頃、甲市内の路上で、帰宅途中の女性の横をバイクで通り過\nぎる際に、その腕からハンドバッグをひったくったという窃盗の被疑事実で逮捕された。逮捕直後\nの警察官による取調べにおいて、Ｘは、上記の犯行が行われたとされる日は、午後7時に帰宅して\n以降、外出しておらず、本件犯行は自分が行ったものではない旨供述し、それが書面に録取された\n（供述録取書①）。しかし、その後の取調べで、警察官が、犯行現場付近に設置された防犯カメラ\nに、同日午後10時58分にその場を通り過ぎるＸのバイクが映っていることを告げると、Ｘは、\n同日午後11時頃に、酒を買うために犯行現場付近にあるコンビニエンスストアに出かけたことを\n失念しており、その際に犯行現場である道路をバイクで通ったことを思い出したが、本件犯行は自\n分が行ったものではない旨供述を変更し、それが書面に録取された（供述録取書②）。さらに、数\n日後の取調べにおいて、警察官から、上記のコンビニエンスストアの防犯カメラの同年5月1日夜\nの録画記録にはＸは全く映っていなかったことを告げられると、Ｘは観念した様子で、上記のひっ\nたくりを行ったことを認める供述をした。そこで、警察官はその供述を書面に録取した（供述録取\n書③）。\n【記述】\nア．Ｘが起訴され、公判期日において供述した場合、供述録取書①の証拠能力が認められること\nはない。\nイ．供述録取書①については、Ｘの供述の任意性に疑いがなければ、証拠能力が認められる。\n\nウ．供述録取書②については、供述録取書③と同じ要件の下で、証拠能力が認められる。\nエ．供述録取書③については、刑事訴訟法第319条第1項は適用されず、同法第322条第1\n項ただし書が適用される。\nオ．供述録取書③が、検察官による取調べにおいて作成された場合であっても、証拠能力が認め\nられる要件は同じである。",
