    "year_label": "R6",
    "subject": "刑事訴訟法",
    "label": "第18問",
    "question": "接見交通権に関する次のアからオまでの各記述のうち、誤っているものは幾つあるか。後記1か\nら6までのうちから選びなさい。ただし、判例がある場合には、それに照らして考えるものとする。\n\nア．接見交通権は、身体の拘束を受けている被告人又は被疑者が弁護人と相談し、その助言を受\nけるなど弁護人から援助を受ける機会を確保する目的で設けられたものであり、憲法の保障に\n由来するものである。\nイ．刑事訴訟法第39条第3項の「捜査のため必要があるとき」とは、接見等を認めると取調べ\nの中断等により捜査に顕著な支障が生ずる場合に限られるところ、捜査機関が弁護人から身体\nの拘束を受けている被疑者との接見の申出を受けた時に、現に被疑者を取調べ中である場合や\n実況見分、検証等に立ち会わせている場合、また、間近い時に取調べ等をする確実な予定があ\nって、弁護人の申出に沿った接見を認めたのでは、取調べ等が予定どおり開始できなくなるお\nそれがある場合などは、原則として取調べの中断等により捜査に顕著な支障が生ずる場合に当\nたる。\nウ．弁護人を選任することができる者の依頼により弁護人となろうとする者と被疑者との逮捕直\n後の初回の接見は、これを速やかに行うことが被疑者の防御の準備のために特に重要であるの\nで、捜査機関は、現に被疑者を取調べ中であって、弁護人の申出に沿った即時の接見を認める\nと捜査に顕著な支障が生じる場合であっても、直ちに取調べを中断して、接見させなければな\nらない。\nエ．勾留されている被告人が同時に余罪の被疑者として勾留されている場合、検察官は、その余\n罪である被疑事件の捜査のため必要があるときは、被告事件についての防御権の不当な制限に\nわたらない限り、被告事件の弁護人と被告人との接見に関し、その日時等を指定することがで\nきる。\nオ．検察官が検察庁の庁舎内に接見設備のある部屋等が存在しないことを理由として接見の申出\nを拒否したにもかかわらず、弁護人がなお同庁舎内における即時の接見を求め、即時に接見す\nる必要性が認められる場合には、検察官は、例えば立会人のいる部屋での短時間の接見などの\nように、いわゆる秘密交通権が十分に保障されないような態様の短時間の接見であってもよい\nかどうかという点につき、弁護人の意向を確かめ、弁護人がそのような接見であっても差し支\nえないとの意向を示したときは、それができるように特別の配慮をすべき義務がある。",
