    "question": "私人による現行犯逮捕に関する次のアからオまでの各記述のうち、正しいものは幾つあるか。後\n記1から6までのうちから選びなさい。ただし、判例がある場合には、それに照らして考えるもの\nとする。\nア．私人は、急速を要する場合に限り、その理由を告げた上で現行犯人を逮捕することができる。\nイ．司法警察員は、私人から現行犯人の引渡しを受けた場合、直ちに裁判官の逮捕状を求める手\n続をしなければならない。\nウ．私人が現行犯逮捕する場合には、その私人が犯行を現に目撃していなければならない。\nエ．司法警察員は、私人から現行犯人の引渡しを受け、留置の必要があると思料する場合、逮捕\nされた時からではなく、その者を受け取った時から、48時間以内に検察官に送致する手続を\nしなければならない。\nオ．現行犯人を逮捕した私人は、逮捕の現場で令状によらずに捜索差押えをすることができる。",
