    "subject": "刑事訴訟法",
    "label": "第20問",
    "question": "次の【見解】は、刑事訴訟法第328条の趣旨及び同条によって許容される証拠の範囲に関する\nものである。後記アからオまでの【証拠】のうち、【見解】に照らし、同条によって許容される証\n拠に当たるものには1を、当たらないものには2を選びなさい。なお、被告人ＡがⅤを包丁で刺し\nて殺害したとする殺人被告事件の公判期日において、本件犯行当日に犯行を目撃したとするＷが、\n「Ｖを包丁で刺したのはＡでした。」と証言しているものとする。また、いずれの証拠との関係で\nも、同法第326条の同意はなされていないものとする。\n【見解】\n「刑事訴訟法第328条は、公判準備又は公判期日における被告人、証人その他の者の供述が、\n別の機会にしたその者の供述と矛盾する場合に、矛盾する供述をしたこと自体の立証を許すことに\nより、公判準備又は公判期日におけるその者の供述の信用性の減殺を図ることを許容する趣旨のも\nのであり、別の機会に矛盾する供述をしたという事実の立証については、同法が定める厳格な証明\nを要する趣旨であると解するのが相当である。\nそうすると、同条により許容される証拠は、信用性を争う供述をした者のそれと矛盾する内容の\n供述が、同人の供述書、供述を録取した書面（同法が定める要件を満たすものに限る。）又は同人\nの供述を聞いたとする者の公判期日の供述の中に現れている部分に限られるというべきである。」\n【証拠】\nア．Ｗの知人Ｚによる、「Ｗは、本件の翌日に、『私は昨日ＢがⅤを包丁で刺すのを見た。』と\n言っていた。」とする公判期日の供述\nイ．本件当日の日付のＷの日記で、「今日ＢがⅤを包丁で刺すのを見てしまった。」との記載が\nあるもの\nウ．Ｗが本件の捜査段階において司法警察員Ｋの聞き込みに応じてした「私はＢがⅤを包丁で刺\nすのを見た。」という供述が記載されている、Ｋ作成に係る捜査報告書で、Ｗの署名及び押印\nがないもの\nエ．Ｗが本件の捜査段階において司法警察員の取調べを受けてした「私はＢがⅤを包丁で刺すの\nを見た。」という供述を録取した書面で、Ｗの署名及び押印があるもの\nオ．Ｗとは別の地点から本件を目撃したとするＹが本件の捜査段階において検察官の取調べを受\nけてした「私はＢがⅤを包丁で刺すのを見た。」という供述を録取した書面で、Ｙの署名及び\n押印があるもの",
    "question_no": 26,
