    "question": "被疑者の勾留に関する次のアからオまでの各記述のうち、正しいものの組合せは、後記1から5\nまでのうちどれか。\nア. 裁判官は、勾留の請求を受けて被疑者に被疑事件を告げる際、被疑者が既に弁護人を選任し\nている場合でも、弁護人選任権を告げる必要がある。\nイ. 30万円以下の罰金に当たる刑法の罪に係る事件については、被疑者が罪を犯したと疑うに\n足りる相当な理由があり、かつ、逃亡すると疑うに足りる相当な理由がある場合であっても、\n被疑者の住居が不定でなければ被疑者を勾留することはできない。\nウ. 検察官から勾留の請求があった翌日に裁判官が被疑者を勾留する旨の裁判をした場合、その\n勾留期間は、同裁判があった日から起算する。\nエ. 勾留されている被疑者について、裁判官が接見禁止の裁判をした場合、被疑者の弁護人であ\nっても、被疑者と接見することはできない。\nオ. 勾留されている被疑者に対する接見禁止の裁判は、検察官の請求がなくとも、裁判官が職権\nですることができる。",
