    "subject": "刑事訴訟法",
    "label": "第22問",
    "question": "次の【事例】について述べた後記アからオまでの【記述】のうち、正しいものの組合せは、後記\n1から5までのうちどれか。ただし、判例がある場合には、それに照らして考えるものとする。\n\n【事例】\n司法警察員Ｘは、甲が自宅において覚醒剤を密売しているとの被疑事実により、捜索すべき場所\nを甲宅、差し押さえるべき物を覚醒剤、パソコン等とする捜索差押許可状（以下「本件許可状」と\nいう。）の発付を受けて、甲宅に赴いた。甲宅には、甲のみが在宅していたところ、Ｘは、甲に本\n件許可状を呈示した上で、甲宅に立ち入り、日没前から①甲を立会人として捜索を開始した。甲宅\nの捜索を実施中、甲と同居する母親Ａが帰宅したため、②Ｘは、Ａが許可なく甲宅へ立ち入ること\nを禁止した。Ｘは、甲が覚醒剤密売の顧客リストをパソコンに保存しているとの情報を基に捜索を\n進めていたところ、甲宅リビングルームのテーブルの上にパソコン1台を発見したことから、③同\nパソコンを差し押さえた。その後もＸは、捜索の必要があると判断し、④本件許可状に「夜間でも\n執行することができる」旨の記載がなかったものの、日没後も捜索を継続した。その後、宅配便の\n配達員によって甲宛の小包が配達されたことから、甲は、甲宅内でこれを受領した。Ｘは、甲に対\nして開封を求めたが、甲がこれを拒否したため、⑤Ｘにおいて同小包を開封したところ、覚醒剤が\n発見されたことから、これを差し押さえた。\n【記述】\nア．下線部①につき、仮に甲宅に誰も在宅していなかった場合でも、甲宅の隣人を立会人として\n捜索することができる。\nイ．下線部②につき、Ａは甲宅の居住者であるため、Ａが許可なく甲宅に立ち入るのを禁止する\nことは違法である。\nウ．下線部③につき、当該パソコンに覚醒剤密売の顧客リストが記録されている蓋然性があり、\nその場で確認していたのではその情報を損壊される危険があると認められる場合は、内容を確\n認することなく当該パソコンを差し押さえることも許される。\nエ．下線部④につき、本件許可状に「夜間でも執行することができる」旨の記載がないことから、\n日没後に捜索を継続することは違法である。\nオ．下線部⑤につき、本件許可状の効力はその呈示後に甲宅に搬入された物品には及ばないため、\n当該小包を開封したことは違法である。",
    "question_no": 28,
