    "subject": "刑事訴訟法",
    "label": "第23問",
    "question": "取調べに関する次のアからオまでの各記述のうち、正しいものの組合せは、後記1から5までの\nうちどれか。\nア．検察官又は検察事務官は、裁判員の参加する合議体で取り扱うべき事件について逮捕又は勾\n留されている被疑者を取り調べるときは、被疑者の供述及びその状況を録音及び録画を同時に\n行う方法により記録媒体に必ず記録しておかなければならない。\nイ．検察官は、被疑者以外の者が取調べに対して出頭を拒否した場合、その者が犯罪の捜査にど\nの程度関連した知識を有しているか明らかでなくとも、第1回の公判期日前であれば、その者\nの証人尋問を裁判官に請求することができる。\nウ．司法警察職員は、被疑者の供述録取書につき、これを被疑者に閲覧させ、又は読み聞かせて、\n誤りがないかどうかを問い、被疑者が増減変更の申立てをしたときは、その供述を調書に記載\nしなければならず、被疑者が調書に誤りのないことを申し立てたときは、これに署名押印する\nことを求めることができる。\nエ．逮捕又は勾留されていない被疑者は、司法警察職員から出頭を求められた場合、これを拒む\nことができるが、検察官又は検察事務官から出頭を求められた場合、これを拒むことはできな\nい。\nオ．司法警察職員は、日本語に通じない被疑者を通訳を介して取り調べる場合、その供述録取書\nを日本語で作成しても違法ではない。",
