    "subject": "刑事訴訟法",
    "label": "第24問",
    "question": "以下のⅠからⅢまでの【結論】は、次の①及び②の【設問】に関するものである。【結論】に関\nする後記アからオまでの【記述】のうち、正しいものの組合せは、後記1から5までのうちどれか。\n\n【設問】\n① 被告人が犯行を否認している場合、被告人と共に犯行を行った旨の共犯者の自白のみで被告\n人を有罪とすることが許されるか。\n② 共犯者だけでなく、被告人も犯行を行ったことを認めている場合、共犯者の自白で被告人の\n自白を補強して被告人を有罪とすることが許されるか。\n【結論】\nⅠ．①及び②のいずれの場合も、被告人を有罪とすることが許されない。\nⅡ．①の場合には、被告人を有罪とすることが許されないが、②の場合には、被告人を有罪とす\nることが許される。\nⅢ．①及び②のいずれの場合も、被告人を有罪とすることが許される。\n【記述】\nア．共犯者に対しては反対尋問が可能であり、反対尋問を経ない被告人の自白より反対尋問を経\nた共犯者の自白の証明力が強いのは当然であると考えると、結論Ⅰに結び付きやすい。\nイ．刑事訴訟法第319条第2項の規定は、自由心証主義の例外であるから限定的に解すべきで\nあると考えると、結論Ⅰに結び付きやすい。\nウ．結論Ⅱとする立場は、憲法第38条第3項の「本人の自白」に共犯者の自白も含まれるのは、\n被告人が否認し、共犯者が自白している場合に限られると考えることになる。\nエ．自白の証明力の過大評価を防止するという刑事訴訟法第319条第2項の規定の趣旨からす\nれば、被告人の自白と共犯者の自白を区別する理由がないと考えると、結論Ⅲに結び付きやす\nい。\nオ．結論Ⅲとする立場に対しては、ほかに補強証拠がない限り、否認した被告人が有罪、自白し\nた共犯者が無罪になるという非常識な結論が生じかねないとの批判がある。",
