    "label": "第25問",
    "question": "起訴状一本主義に関する次のアからオまでの各記述のうち、誤っているものの組合せは、後記1\nから5までのうちどれか。ただし、判例がある場合には、それに照らして考えるものとする。（解\n答欄は、）\nア．起訴状一本主義に違反した公訴提起の手続は無効であり、裁判所は、判決で公訴を棄却しな\nければならない。\nイ．前科の事実を手段・方法として恐喝したという事実で公訴を提起する場合には、公訴事実中\nに被告人の前科を記載することも許される。\nウ．刑事訴訟法第256条第6項により、起訴状には裁判官に事件につき予断を生じさせるおそ\nれのある書類その他の物を添付することが禁止されているので、検察官が勾留されている被疑\n者について公訴を提起する際に、裁判所に起訴状を提出すると同時に、被告人の逮捕状や勾留\n状をその裁判所の裁判官に差し出すことは許されない。\nエ．公判審理を担当する裁判所は、証拠開示に関する裁定のためであっても、第1回公判期日前\nには証拠の提示を求めることはできない。\nオ．略式命令を請求する場合において、その請求と同時に検察官が立証に必要があると思料する\n書類及び証拠物を裁判所に差し出しても、刑事訴訟法第256条第6項に反しない。",
