    "question": "強制採尿に関する次のアからオまでの各記述のうち、正しいものの組合せは、後記1から5まで\nのうちどれか。ただし、判例がある場合には、それに照らして考えるものとする。\nア．膀胱にたまっている尿は物ではなく身体の一部であるから、捜索差押許可状によって、強制\n採尿を行うことはできない。\nイ．強制採尿は、尿道にカテーテルを挿入するという身体への侵襲を伴うから、鑑定処分許可状\nが必要である。\nウ．強制採尿が現行法上の強制処分として認められる以上、それが尿を獲得するための最終的手\n段でなくとも、裁判官はそのための令状を発付することができる。\nエ．被疑者から尿を採取するに当たり、被疑者が錯乱状態に陥っていて任意の尿の提出が期待で\nきない状況にあるときは、任意提出の機会を提供せずに、令状によって強制採尿を行うことが\nできる。\nオ．裁判官は、強制採尿のための令状を発付するに当たり、医師をして医学的に相当と認められ\nる方法により行わせなければならない旨の条件を付さなければならない。",
