    "label": "第2問",
    "question": "時効取得に関する次のアからオまでの各記述のうち、判例の趣旨に照らし誤っているものを組み\n合わせたものは、後記1から5までのうちどれか。\nア．土地の占有者が所有者からの明渡請求を拒否して占有を継続してきたときは、取得時効の要\n件である平穏な占有があるとはいえない。\nイ．所有権の取得時効期間の計算においては、占有の開始の時が午前零時でなかったときであっ\nても、占有開始の日が算入される。\nウ．土地の賃借権の取得時効が成立するためには、土地の継続的用益が賃借の意思に基づくこと\nが客観的に表現されていることが必要である。\nエ．所有権の取得時効は、占有者が他人によって物の占有を奪われたときであっても、占有回収\nの訴えにより現実にその物の占有を回復したときは、中断しない。\nオ．所有権以外の財産権を、自己のためにする意思をもって、平穏に、かつ、公然と行使する者\nは、法定の期間を経過した後、その権利を時効によって取得する。",
