    "question": "不動産の物権変動に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを\n組み合わせたものは、後記1から5までのうちどれか。\nア．ＡがＡ所有の甲土地をＢに売却した後、Ａが甲土地をＣにも売却した。ＡからＢへの所有権\n移転登記も、ＡからＣへの所有権移転登記もされていない。この場合、Ｂは、甲土地の所有権\nの取得を第三者Ｃに対抗することができる。\nイ．Ａ所有の甲土地について、Ｂが、Ａに無断で、Ｂを所有権の登記名義人とする登記を備えた。\nＢと善意無過失のＣとの間で甲土地の売買がされ、ＢからＣへの所有権移転登記がされたとき\nは、Ｃは、甲土地の所有権を取得する。\nウ．ＡがＡ所有の甲土地をＢに売却し、ＡからＢへの所有権移転登記がされた後、Ａは、詐欺を\n理由に甲土地の売買契約を取り消した。Ｂは、その取消し後に甲土地をＣに売却した。この場\n合、Ａは、甲土地の所有権がＡに復帰した旨の登記を備えなければ、そのことを第三者Ｃに対\n抗することができない。\nエ．ＡとＢが共有する土地について、ＡがＡの共有持分を放棄し、その共有持分をＢが取得した\n場合において、その旨の登記がされる前に、Ａの債権者ＣがＡの共有持分を差し押さえたとき\nは、Ｂは、Ａの共有持分の取得を第三者Ｃに対抗することができない。\nオ．ＡがＡ所有の甲土地をＢに売却した後、ＡからＢへの所有権移転登記がされないままＡが死\n亡した。ＣがＡの唯一の相続人である場合において、Ｃが相続により甲土地の所有権を取得し\nた旨の登記がされたときは、Ｂは、甲土地の所有権の取得をＣに対抗することができない。",
