    "question": "婚姻及び離婚に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組み\n合わせたものは、後記1から5までのうちどれか。\nア．父と母が、子に嫡出子の地位を得させるための便法としてすることを合意して婚姻の届出を\nしたものの、父母の双方に真に社会観念上夫婦であると認められる関係の設定を欲する効果意\n思がなかったときは、婚姻は、無効である。\nイ．夫婦としての実質的生活関係が存続している男女が婚姻意思に基づいて婚姻届を作成したも\nのの、婚姻届の提出の時にその一方が昏睡状態に陥っていたときは、婚姻は、無効である。\nウ．夫婦としての実質的生活関係が存在している男女の一方が他方の意思に基づかずに婚姻届を\n作成し、これを提出したものの、後に他方が当該届出の事実を知ってこれを追認したときは、\n婚姻は、その追認の時から有効となる。\nエ．夫婦が、法律上の婚姻関係を解消する意思の合致に基づいて離婚の届出をしたものの、その\n届出が生活保護費の受給を継続するための方便としてのものであり、その後も夫婦としての実\n質的生活関係を継続したときは、離婚は、無効である。\nオ．夫婦が、離婚意思に基づいて離婚届を作成し、夫婦の一方がいったん保管した後にこれを提\n出したものの、他方が届出時までに翻意していたことが明確であったときは、離婚は、無効で\nある。",
