    "question": "個人商人（小商人に当たる者を除く。）の商号に関する次のアからオまでの各記述のうち、正し\nいものを組み合わせたものは、後記1から5までのうちどれか。\nア．商号の譲渡は、営業とともにする場合には、登記をしなくても、第三者に対抗することがで\nきる。\nイ．自己の商号を使用して営業を行うことを他人に許諾した商人は、当該他人と取引をした者に\nおいて当該商人が当該営業を行うものと誤認したか否かにかかわらず、当該取引によって生じ\nた債務を弁済する責任を負う。\nウ．商人は、その商号を登記しなければならない。\nエ．営業を譲り受けた商人（以下「譲受人」という。）が営業を譲渡した商人（以下「譲渡人」\nという。）の商号を引き続き使用しない場合であっても、譲渡人の営業によって生じた債務を\n引き受ける旨の広告をしたときは、当該債務の引受けがされたと信じた譲渡人の債権者は、当\n該広告を見たか否かにかかわらず、譲受人に対して弁済の請求をすることができる。\nオ．判例の趣旨によれば、商人は、数種の独立した営業を行い、又は数個の営業所を有する場合\nには、その各営業又は営業所につき別異の商号を有することができる。",
    "question_no": 27,
    "options": [
      "ア イ",
      "ア エ",
      "イ ウ",
      "ウ オ",
      "エ オ"
    ],
    "answer": 1,
