    "subject": "商法",
    "label": "第28問",
    "question": "甲株式会社（以下「甲社」という。）を買主、乙株式会社（以下「乙社」という。）を売主とす\nる売買に関する次のアからオまでの各記述のうち、正しいものを組み合わせたものは、後記1から\n5までのうちどれか。\nア．甲社の従業員が、乙社との間で売買契約を締結する代理権を甲社から授与された場合におい\nて、甲社のためにすることを示さないで乙社との間で売買契約を締結したときは、乙社は、甲\n社に対し、その履行を請求することができない。\nイ．甲社が乙社から買った目的物の代金をその弁済期になっても支払わない場合には、別段の意\n思表示がない限り、乙社は、甲社から修理のために預かっていた別の動産であって甲社が所有\nするものの返還を拒むことができる。\nウ．甲社は、これまでに取引関係になかった乙社から売買の申込みを受けるとともにその目的物\nの引渡しを受けた場合において、その目的物と同種の目的物を第三者から継続的に買っており、\n乙社との間で売買契約を締結する意思がないときは、乙社から引渡しを受けた目的物の価額に\nかかわらず、直ちにその目的物を廃棄することができる。\nエ．判例の趣旨によれば、乙社が品質に関して契約の内容に適合しない目的物をそのことを知ら\nずに甲社に引き渡した場合において、その不適合が直ちに発見することができないものである\nときは、受領後1年を経過した後にその不適合を発見した甲社は、直ちに乙社に対してその旨\nの通知を発すれば、乙社に対し、品質に関して契約の内容に適合する目的物の引渡しを請求す\nることができる。\nオ．売買の性質上、特定の日時に目的物を引き渡さなければ契約をした目的を達することができ\nない場合において、乙社がその日時に当該目的物を甲社に引き渡さなかったときは、甲社が直\nちにその履行の請求をした場合を除き、契約の解除をしたものとみなされる。",
