    "question": "訴えの取下げに関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組み\n合わせたものは、後記1から5までのうちどれか。\nア．和解の期日においては、訴えの取下げを口頭ですることはできない。\nイ．訴えの取下げは、口頭弁論期日が開かれた後は、相手方が訴えの却下を求め、その理由のみ\nを主張している場合であっても、相手方の同意を得なければ、その効力を生じない。\nウ．当事者双方が、連続して2回、口頭弁論期日に出頭しなかったときは、被告の同意を得なく\nても、訴えの取下げの効力を生ずる。\nエ．判決言渡期日の前日に訴えの取下げが書面でされた場合において、訴えの取下げに相手方が\n異議を述べるかどうかが判明していないときは、裁判所は予定していた判決言渡期日において、\n判決を言い渡すことができない。\nオ．終局判決があった後に訴えの取下げをした当事者は、新たな訴えの利益又は必要性が存する\nときは、前訴と当事者及び訴訟物を同一とする訴えを提起することができる。",
