    "question": "確定判決の既判力に関する次のアからオまでの各記述のうち、判例の趣旨に照らし誤っているも\nのを組み合わせたものは、後記1から5までのうちどれか。\nア．買主Ｘが売主Ｙに対し、売買契約により建物の所有権を取得したとして所有権の確認を求め\nる訴えを提起し、請求を認容する判決が確定した後、ＹがＸに対し、同一の建物について所有\n権の確認を求めて訴えを提起し、その訴状において上記売買契約を詐欺により取り消すとの意\n思表示をした場合には、後訴裁判所がＹの主張を認めてＹの請求を認容する判決をすることは、\n前訴の確定判決の既判力に反し許されない。\nイ．土地の賃貸人Ｘが、その土地上に建物を所有する賃借人Ｙに対し、賃貸借契約の終了に基づ\nき、建物を収去して土地を明け渡すことを求める訴えを提起し、請求を認容する判決が確定し\nた後、ＹがＸに対し、請求異議の訴えを提起し、その訴状において建物買取請求権を行使する\nとの意思表示をした場合には、後訴裁判所が建物買取請求権行使の効果を異議の事由として認\nめてＹの請求を認容する判決をすることは、前訴の確定判決の既判力に反し許されない。\nウ．受贈者Ｘが贈与者Ｙに対し、贈与契約に基づく土地の引渡しを求める訴えを提起し、請求を\n認容する判決が確定した後、ＹがＸに対し、請求異議の訴えを提起し、その訴状において上記\n贈与契約は書面によらないものであるとして解除するとの意思表示をした場合には、後訴裁判\n所が解除の効果を異議の事由として認めてＹの請求を認容する判決をすることは、前訴の確定\n判決の既判力に反し許されない。\nエ．売主Ｘが買主Ｙに対し、絵画の売買契約が無効であったと主張して、所有権に基づく絵画の\n引渡しを求める訴えを提起し、請求を棄却する判決が確定した後、ＸがＹに対し、再び所有権\nに基づく同一の絵画の引渡しを求める訴えを提起し、その訴状においてＹが前訴判決の確定後\nも代金を支払わないとして上記売買契約を解除するとの意思表示をした場合に、後訴裁判所が\nＸの主張を認めてＸの請求を認容する判決をすることは、前訴の確定判決の既判力に反しない。\nオ．貸主Ｘが借主Ｙに対し、消費貸借契約に基づく貸金の返還を求める訴えを提起し、請求を認\n容する判決が確定した後、ＹがＸに対し、請求異議の訴えを提起し、その訴状において、前訴\nにおける事実審の口頭弁論終結前から存在し、かつ相殺適状にあったＸに対する反対債権をも\nって相殺する旨の意思表示をした場合には、後訴裁判所が相殺の意思表示の効果を異議の事由\nとして認めてＹの請求を認容する判決をすることは、前訴の確定判決の既判力に反し許されな\nい。",
