    "question": "多数当事者訴訟に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組\nみ合わせたものは、後記1から5までのうちどれか。\nア．Ｘの所有する甲土地上に乙建物を所有していたＡが死亡し、Ｙ1とＹ2がＡを相続した。こ\nの場合において、ＸがＹ1のみを被告として乙建物を収去して甲土地を明け渡すことを求める\n訴えを提起したときは、裁判所は、この訴えを不適法なものとして却下しなければならない。\nイ．鉄道事故の被害者Ｘが、鉄道会社Ｙを被告として不法行為に基づき損害賠償を求める訴えを\n提起した。この場合において、同一事故の別の被害者Ｚは、Ｙに対して不法行為に基づく損害\n賠償を求めるため、Ｘを被参加人として、上記訴訟に共同訴訟参加をすることはできない。\nウ．株式会社Ｙの株主Ｘが、Ｙを被告として、Ｚを取締役に選任した株主総会決議の取消しを求\nめる訴えを提起したところ、ＺがＹを被参加人として補助参加をした。この訴訟につき、第一\n審裁判所がＸの請求を認容する判決をした場合において、Ｙの控訴期間が経過した後であって\nも、Ｚが判決書の送達を受けた日から2週間以内に控訴を提起したときは、Ｚによる控訴は適\n法である。\nエ．ＸがＹを被告として甲土地の所有権の確認を求める訴えを提起し、その係属中に、Ｙは、Ｚ\nに対して甲土地を譲渡した。その後、Ｚにこの訴訟を引き受けさせる決定があった場合におい\nては、Ｚを除いてＸとＹとの間で訴訟上の和解をすることはできない。\nオ．債権者Ｘが、主債務者Ｙとその連帯保証人Ｚを共同被告とし、Ｙに対して貸金の返還を、Ｚ\nに対して連帯保証債務の履行を求める訴えを提起した。この訴訟において、Ｙが自己による弁\n済の事実を主張し、Ｚが当該弁済の事実を主張せず、Ｘが当該弁済の事実を争った場合でも、\n裁判所は、審理の結果、当該弁済の事実が認められるとの心証に至ったときは、当該弁済を理\n由として、ＸのＺに対する請求を棄却する旨の判決をすることができる。",
