    "question": "法の下の平等に関する次のアからウまでの各記述について、最高裁判所の判例の趣旨に照らして、\n正しいものには○、誤っているものには×を付した場合の組合せを、後記1から8までの中から選\nびなさい。\nア．憲法第14条第1項前段の法の下の平等は法適用の平等を意味し、行政府と司法府を拘束す\nるが、同項後段の「人種、信条、性別、社会的身分又は門地」による差別は歴史的に存在した\n特に不合理な差別として限定的に列挙されたものなので、行政府と司法府のみならず、立法府\nをも拘束する。\nイ．憲法第94条で地方公共団体の条例制定権が認められていることに照らすと、地域によって\n条例による規制内容に差異が生じることは当然に予期されることであるから、ある行為の取締\nりのために各地方公共団体が各別に条例を制定する結果、その取扱いに差異が生じることがあ\nっても地域差の故に違憲ということはできない。しかし、全国一律の規制になじむ行為を取り\n締まる場合には、法律で全国一律に規制しなければ、憲法第14条第1項に違反する。\nウ．選挙権に関しては、憲法第14条第1項に定める法の下の平等は、国民はすべて政治的価値\nにおいて平等であるべきとする徹底した平等化を志向するもので、各選挙人の投票の価値の平\n等も憲法の要求するところであるから、両議院の議員一人当たりの人口が最大の選挙区と最小\nの選挙区との間で、一票の重みの較差がおおむね2対1以上に開いた場合、投票価値の平等の\n要請に正面から反し、違憲といわざるを得ない。",
