    "question": "表現の自由に関する次のアからウまでの各記述について、最高裁判所の判例の趣旨に照らして、\n正しいものには○、誤っているものには×を付した場合の組合せを、後記1から8までの中から選\nびなさい。\nア．ある事実を基礎とする意見を表明する行為が、公共の利害に関する事実に係り、かつ、その\n目的が専ら公益を図ることにあった場合であっても、意見の前提となる事実がその重要な部分\nについて真実であることの証明がなければ、当該表現行為は、名誉毀損と評価されることとな\nる。\nイ．ある者が刑事事件について被疑者とされ、被告人として公訴提起されて有罪判決を受け、服\n役した事実は、その者の名誉あるいは信用に直接に関わる事項であり、その者は、みだりに上\n記の前科等に関わる事実を公表されないことにつき、法的保護に値する利益を有すると考えら\nれ、この点は、前科等に関わる事実の公表が公的機関によるものであっても、私人又は私的団\n体によるものであっても違いはない。\nウ．人格権としての個人の名誉を害する内容を含む表現行為の事前差止めは、その対象が公務員\nや公職選挙の候補者に対する評価、批判等である場合には原則として許されないが、その表現\n内容が真実でなく、又は専ら公益を図る目的のものでないことが明白であって、かつ、被害者\nが重大にして著しく回復困難な損害を被るおそれがあるときは、例外的に許される。",
