    "question": "司法権の範囲ないし限界に関する次のアからウまでの各記述について、最高裁判所の判例の趣旨\nに照らして、正しいものには〇、誤っているものには×を付した場合の組合せを、後記1から8ま\nでの中から選びなさい。\nア．裁判所がその固有の権限に基づいて審判することのできる対象は、裁判所法第3条にいう\n「法律上の争訟」、すなわち当事者間の具体的な権利義務ないし法律関係の存否に関する紛争\nであって、かつ、それが法令の適用により終局的に解決することができるものに限られる。し\nたがって、具体的な権利義務ないし法律関係に関する紛争であっても、法令の適用による終局\n的解決に適しないものは裁判所の司法審査の対象になり得ない。\nイ．特定の者の宗教活動上の地位の存否を審理、判断するにつき、宗教団体の教義ないし信仰の\n内容に立ち入って審理、判断することが必要不可欠である場合には、裁判所は、その者が宗教\n活動上の地位にあるか否かを審理、判断することができず、その結果、宗教活動上の地位に基\nづく宗教法人の代表役員の地位の存否についても審理、判断することができない。この場合に\nは、宗教法人の代表役員の地位の存否の確認を求める訴えは、裁判所法第3条にいう「法律上\nの争訟」に当たらない。\nウ．大学の単位の授与（認定）という行為は、学生が履修した授業科目について合格したことを\n確認する教育上の措置であり、卒業の要件をなすものであるから、一般市民法秩序と直接の関\n係を有するものであることは明らかである。それゆえ、純然たる大学内部の問題とはいえず、\n大学の自主的、自律的な判断のみに委ねられるべきものではなく、裁判所の司法審査の対象と\nなる。\n1．ア〇 イ〇 ウ〇 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ〇\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ〇 6．ア× イ〇 ウ×\n7．ア× イ× ウ〇 8．ア× イ× ウ×",
