    "question": "公立学校施設の管理者がした目的外使用の許否に係る裁量処分の司法審査に関する最高裁判所平\n成18年2月7日第三小法廷判決（民集60巻2号401頁。以下「本判決」という。）の次の判\n示を読み、本判決に関する後記アからウまでの各記述について、正しいものに○、誤っているもの\nに×を付した場合の組合せを、後記1から8までの中から選びなさい。\n「管理者の裁量判断は、許可申請に係る使用の日時、場所、目的及び態様、使用者の範囲、使用\nの必要性の程度、許可をするに当たっての支障又は許可をした場合の弊害若しくは影響の内容及\nび程度、代替施設確保の困難性など許可をしないことによる申請者側の不都合又は影響の内容及\nび程度等の諸般の事情を総合考慮してされるものであり、その裁量権の行使が逸脱濫用に当たる\nか否かの司法審査においては、その判断が裁量権の行使としてされたことを前提とした上で、そ\nの判断要素の選択や判断過程に合理性を欠くところがないかを検討し、その判断が、重要な事実\nの基礎を欠くか、又は社会通念に照らし著しく妥当性を欠くものと認められる場合に限って、裁\n量権の逸脱又は濫用として違法となるとすべきものと解するのが相当である。」\nア．本判決による審査方法は、裁判所が裁量処分について、全面的にその当否を審査し直し、裁\n判所が出した結論と行政庁の処分内容とが異なる場合に、当該裁量処分が違法となると判断す\nるもので、これにより密度の高い審査を行うことができるという特徴がある。\nイ．本判決による審査方法については、いかなる判断要素を選択し、その評価をどのように行う\nのかという点に関し、基準が明確ではないという問題点が指摘できる。\nウ．本判決による審査方法によれば、従来の裁量処分の審査において用いられてきた平等原則や\n比例原則の観点は、裁量処分の審査に当たり考慮すべき要素にはならない。",
