    "question": "原告適格に関する次のアからウまでの各記述について、最高裁判所の判例に照らし、正しいもの\nに○、誤っているものに×を付した場合の組合せを、後記1から8までの中から選びなさい。（解\n答欄は、）\nア．森林法に基づく林地開発許可について、同法の規定は、開発区域周辺の土地の所有権等の財\n産権を個々人の個別的利益として保護すべきものとする趣旨を含むから、開発区域周辺の土地\nを所有する者は、当該許可の取消しを求める原告適格を有する。\nイ．自転車競技法に基づく場外車券発売施設の設置許可については、同法の規定を受けて、学校\nその他の文教施設及び病院その他の医療施設（以下、これらを併せて「医療施設等」とい\nう。）から相当の距離を有し、文教上又は保健衛生上著しい支障を来すおそれがないことを許\n可の基準として定めた同法施行規則の規定が、医療施設等の開設者が健全で静穏な環境の下で\n円滑に業務を行うことのできる利益をその個別的利益として保護する趣旨をも含むと解するこ\nとはできないから、医療施設等の開設者が、当該許可の取消しを求める原告適格を有すること\nはない。\nウ．風俗営業等の規制及び業務の適正化等に関する法律に基づく風俗営業の許可については、同\n法の委任を受けて定められた政令が「住居が多数集合しており、住居以外の用途に供される土\n地が少ない地域」を条例で風俗営業の制限地域とすべき基準として定めており、住民が良好な\n風俗環境の中で生活する利益をその個別的利益として保護する趣旨を含むと解されるから、当\n該基準に従って規定された同法の施行条例が定める地域に居住する者は、当該許可の取消しを\n求める原告適格を有する。",
