    "question": "行政不服審査法（以下「法」という。）に関する次のアからウまでの各記述について、法又は最\n高裁判所の判例に照らし、正しいものに○、誤っているものに×を付した場合の組合せを、後記1\nから8までの中から選びなさい。\nア．審査請求の対象である処分には事実上の行為が含まれ、処分である事実上の行為が違法又は\n不当であり、当該処分である事実上の行為に対する審査請求に理由がある場合には、処分庁の\n上級行政庁である審査庁は、裁決で、当該処分である事実上の行為の全部若しくは一部を取り\n消し、又はこれを変更する。\nイ．法第7条第2項に規定する「固有の資格」とは、一般私人とは異なり、国の機関等であるか\nらこそ立ち得る特有の立場をいい、その資格の有無は、処分に係る事務又は事業の実施主体が\n国の機関等に限られているか否か、また、限られていない場合であっても当該事務又は事業を\n実施し得る地位の取得について、国の機関等が一般私人に優先するなど特別に取り扱われてい\nるか否か等を考慮して判断すべきものである。\nウ．法は、処分に関する不服申立てについて、他の法律に特別の定めがある場合を除くほか、法\nの定めるところによると規定しているから、条例に基づく処分に対する不服申立てに関し、条\n例による特別の定めを設けることを認めていない。",
