    "question": "暴行罪及び傷害罪に関する次のアからオまでの各記述を判例の立場に従って検討した場合、誤っ\nているものの個数を後記1から5までの中から選びなさい。\nア．相手方の眼前に抜き身の日本刀を突き付けたとしても、その刃が同人に接触しない限り、暴\n行罪が成立することはない。\nイ．相手方の意思に反して、その耳元で楽器を大音量で鳴らし続けた場合には、人の身体に対し\nて不法な攻撃を加えたものとして暴行罪が成立し得る。\nウ．ひそかに相手方に睡眠薬を摂取させ、2時間にわたり意識を失わせるとともに筋弛緩作用を\n伴う急性薬物中毒の症状を生じさせたとしても、覚醒後の健康状態に支障がない場合には、傷\n害罪が成立することはない。\nエ．性病を有する者が、性行為を行えば相手方に感染させる危険性があると認識しながら、情を\n秘して同人と性行為を行い、同人に性病を感染させたとしても、同人が性行為に同意している\n場合には、傷害罪が成立することはない。\nオ．相手方に暴行を加えて負傷させた者が、傷害結果が発生することについて認識を欠いている\n場合には、傷害罪が成立することはない。",
