    "year_label": "R5",
    "subject": "刑法",
    "label": "第3問",
    "question": "学生Ａ及びＢは、次の【事例】における甲の罪責について、後記【会話】のとおり議論している。\n【会話】中の①から⑤までの（ ）内から適切な語句を選んだ場合、正しいものの組合せは、後記\n1から5までのうちどれか。\n【事 例】\n甲は、Ｘ県から代金1億円で請け負った土木工事を完成させ、同工事で生じた汚泥5トンを搬\n出して適法に処理した。上記工事に関する請負契約では、甲が工事で生じた汚泥を全て搬出する\nことが義務付けられていたが、請負代金はその搬出量にかかわらず定額とされ、汚泥の処理方法\nについての定めもなかった。もっとも、上記契約締結の際、Ｘ県が汚泥搬出量は50トンを下ら\nないと予測していたため、甲は、実際の搬出量を報告すれば、Ｘ県が行う工事完成検査の際に不\n法投棄を疑われ、その調査のために請負代金の支払が延期されると懸念し、Ｘ県に対し、汚泥5\n0トンを搬出して適法に処理したと虚偽の報告をし、Ｘ県職員をその旨誤信させ、請負代金1億\n円の支払を受けた。なお、甲が虚偽の報告をしなければ、Ｘ県が不法投棄について調査を行い、\n請負代金の支払時期が遅れたことは確実であった。\n【会 話】\n学生Ａ．詐欺罪の成否を問題とした場合、財産上の損害をどう考えますか。\n学生Ｂ．詐欺罪における財産上の損害の有無は、①（ａ．財物の占有・支配の喪失それ自体によ\nって・ｂ．被害者の取引目的達成の有無も考慮して）判断すべきです。本事例では、請負\n契約の目的である工事が完成し、かつ、その請負代金は定額なので、Ｘ県に財産上の損害\nはないと考えます。\n学生Ａ．Ｂさんのように、財産上の損害を実質的に把握するとしても、本事例では、②（ｃ．Ｘ\n県の代金支払時期を早めた・ｄ．Ｘ県の代金減額請求権を侵害した）という点で、財産上\nの損害を認め得ると思います。\n学生Ｂ．Ａさんの見解では、③（ｅ．一日でも支払時期を早めれば詐欺罪が成立する・ｆ．未成\n年であることを秘して成人向け雑誌を購入した者にまで詐欺罪が成立する）ことになりか\nねず、妥当でないと考えます。\n学生Ａ．いや、私は、判例と同様に、④（ｇ．全体財産の減少が認められる・ｈ．社会通念上別\n個の支払に当たるといい得る程度の期間、支払時期を早めた）場合に限って財産上の損害\nを認めますので、その批判は当たりません。ところで、Ｂさんは、本事例において、詐欺\n未遂罪の成立も否定しますか。\n学生Ｂ．甲の虚偽報告の有無にかかわらずＸ県は代金を支払わざるを得ませんので、そもそも、\n⑤（ｉ．欺罔行為がない・ｊ．財物の交付行為がない）と考えます。したがって、詐欺未\n遂罪も成立しません。",
