    "question": "緊急避難に関する次のアからオまでの各記述を判例の立場に従って検討した場合、正しいものの\n組合せは、後記1から5までのうちどれか。\nア．緊急避難は、自己又は他人の生命、身体、自由又は財産という個人的法益に対する現在の危\n難を避けるためにした行為に成立するものであるから、国家的法益に対する危難を避けるため\nにした行為に緊急避難が成立することはない。\nイ．避難行為により避けようとした害の程度が生じた害の程度を上回る場合だけでなく、両者が\n同程度の場合にも、緊急避難は成立し得る。\nウ．緊急避難における現在の危難は、危難が現に存在している場合のみならず、間近に押し迫っ\nている場合も含む。\nエ．過剰避難が成立する場合、情状によって、その刑を減軽することはできるが免除することは\nできない。\nオ．緊急避難におけるやむを得ずにした行為とは、正当防衛におけるのと同様に、手段として必\n要最小限度のものであること、すなわち相当性を有するものであれば足りる。",
