    "label": "第7問",
    "question": "共犯の要素従属性に関して、学生Ａ及びＢが次の【会話】のとおり議論している。【会話】中の\n①から⑥までの（ ）内に後記【語句群】から適切な語句を入れた場合、正しいものの組合せは、\n後記1から5までのうちどれか。なお、①から⑥までの（ ）内にはそれぞれ異なる語句が入る。\n\n【会 話】\n学生Ａ．（①）ことからも、共犯を処罰するためには、正犯が（②）を備える必要があると考え\nます。\n学生Ｂ．Ａさんの見解によれば、甲が乙に指示して構成要件に該当する行為を実行させたが、\n（③）において、甲に責任を問うことができなくなり、不当ではありませんか。\n学生Ａ．その場合、甲に（④）を幅広く認めることで妥当な結論を得られます。\n学生Ｂ．でも、乙が刑事未成年者ながら是非弁別能力があり、その意思が抑圧されていない場合\nにまで（④）を認めることは無理がありますね。他方で、適法な行為を援助する行為を処\n罰の対象とするのは妥当ではありません。私は、（⑤）べきと考えるので、共犯を処罰す\nるためには、正犯が（⑥）を備えることが必要であり、それで足りることになります。\n【語句群】\nａ．違法は連帯的に作用するが、責任は個別的に作用する\nｂ．教唆犯については刑法第61条が「犯罪」という文言を使っている\nｃ．違法性阻却事由については、行為者ごとの違法の相対性も認められる\nｄ．構成要件該当性 ｅ．構成要件該当性及び違法性\nｆ．構成要件該当性、違法性及び有責性\nｇ．乙の行為に違法性阻却事由が認められる事案\nｈ．乙の行為に責任阻却事由が認められる事案\nｉ．間接正犯 ｊ．幇助犯",
