    "question": "学生Ａ及びＢは、次の【事例】における甲の罪責について、後記【会話】のとおり議論している。\n【会話】中の①から⑤までの（ ）内に後記【語句群】から適切な語句を入れた場合、正しいもの\nの組合せは、後記1から5までのうちどれか。なお、①から⑤までの（ ）内にはそれぞれ異なる\n語句が入る。\n【事 例】\n甲は、殺意をもって、Ｘの腕の静脈内に蒸留水と空気を注射したが、当該空気量が疾病のない\n健常人に対する致死量未満であったためＸは死ななかった。また、甲は、当該空気量が上記致死\n量未満とは知らなかった。なお、当該空気量であっても被注射者の身体的条件等によっては死亡\nする危険はあった。\n【会 話】\n学生Ａ．未遂犯と不能犯の区別に関してはいろいろな考え方がありますが、行為の時点において\n一般人が認識し得た事情と行為者が特に知っていた事情を基礎とし、一般人が結果発生の\n危険を感じる場合には可罰的未遂を肯定する考え方に立ち、本事例では一般人が結果発生\nの危険を感じるとすれば、甲に殺人未遂罪が（①）ことになりますね。\n学生Ｂ．この考え方に対しては、（②）ことになるという批判がありますね。では、結果発生の\n危険性を事後的客観的に判断する考え方に立った場合、甲の罪責をどう考えますか。\n学生Ａ．（③）という考え方によれば、身体的条件等によっては死亡の危険があったので、甲に\n殺人未遂罪が成立します。一方で、結果発生の危険性を事後的客観的に判断する考え方を\n徹底すれば、（④）ことになりませんか。\n学生Ｂ．そうとは限りませんよ。結果が発生しなかった原因究明と同時に、いかなる事情があれ\nば結果発生があり得たかを明らかにし、（⑤）可能性を判断すれば妥当な結論を導けます。\n【語句群】\nａ．成立する ｂ．成立しない ｃ．迷信犯に未遂犯を認める\nｄ．印象で未遂犯処罰を決める\nｅ．行為者の認識内容が客観的真実に合致するか否かによって区別する\nｆ．結果発生の絶対的不能・相対的不能によって区別する\nｇ．行為者の誤信が相当と認められる\nｈ．結果発生をもたらす仮定的事実が存在し得た\nｉ．結果不発生の原因を解明できた場合、すべて不能犯となる",
    "question_no": 11,
