    "subject": "刑事訴訟法",
    "label": "第14問",
    "question": "捜査の端緒に関する次のアからオまでの各記述のうち、誤っているものの組合せは、後記1から\n5までのうちどれか。ただし、判例がある場合には、それに照らして考えるものとする。（解答欄\nは、）\nア．被害者の法定代理人は、被害者の意思に反して告訴をすることはできない。\nイ．検視においては、死因の確認のために必要があるときには、死体の腹部を切開することがで\nきる。\nウ．親告罪の告訴期間の起算点である「犯人を知った」とは、告訴権者において犯人が誰である\nかを知ることをいい、犯人の住所氏名などの詳細を知る必要はない。\nエ．司法警察員は、口頭による告発を受けたときは調書を作らなければならない。\nオ．司法警察員は、自首を受けたときは、速やかにこれに関する書類及び証拠物を検察官に送付\nしなければならない。",
