    "id": "r5_keipo_21",
    "year": 2023,
    "year_label": "R5",
    "subject": "刑事訴訟法",
    "label": "第15問",
    "question": "次のアからオまでの各記述のうち、正しいものは幾つあるか。後記1から6までのうちから選び\nなさい。ただし、判例がある場合には、それに照らして考えるものとする。\nア．強盗殺人事件の捜査に関し、公道上を歩いている被疑者の容ぼう等を撮影することは、防犯\nビデオに写っていた犯人の容ぼう等と被疑者の容ぼう等との同一性の有無という犯人を特定す\nるための重要な判断に必要な証拠資料を入手するためであっても、被疑者の同意がある場合\nか、裁判官の令状がある場合以外には許容されない。\nイ．強制手段とは、有形力の行使を伴う手段を意味するものではなく、個人の意思を制圧し、身\n体、住居、財産等に制約を加えて強制的に捜査目的を実現する行為など、特別の根拠規定がな\nければ許容することが相当でない手段を意味するものであって、この程度に至らない有形力の\n行使は、任意捜査においても許容される場合がある。\nウ．車両に使用者らの承諾なく秘かにＧＰＳ端末を取り付け、情報機器でその位置情報を検索\nし、画面表示を読み取って当該車両の所在と移動状況を把握する捜査手法は、個人のプライバ\nシーの侵害を可能とする機器をその所持品に秘かに装着することによって、合理的に推認され\nる個人の意思に反してその私的領域に侵入するものであり、刑事訴訟法上、特別の根拠規定が\nなければ許容されない強制処分に当たる。\nエ．荷送人や荷受人の承諾を得ることなく、宅配便業者の運送過程下にある荷物について、外部\nからエックス線を照射して内容物の射影を観察する捜査手法は、その射影によって荷物の内容\n物の形状や材質をうかがい知ることができるだけでなく、その品目等を相当程度具体的に特定\nすることも可能である場合には、荷送人や荷受人の内容物に対するプライバシー等を大きく侵\n害するものであるから、検証としての性質を有する強制処分に当たる。\nオ．警察官が、覚醒剤の使用ないし所持の容疑がかなり濃厚に認められる者に対する職務質問中\nに、その者の承諾がないのに、その上衣の内ポケットに手を差し入れて所持品を取り出したう\nえ検査する行為は、職務質問に附随する所持品検査において許容される限度を超えるとの評価\nを受けることはない。",
