    "question": "訴因変更に関する次のアからオまでの各記述のうち、誤っているものの組合せは、後記1から5\nまでのうちどれか。ただし、判例がある場合には、それに照らして考えるものとする。（解答欄\nは、）\nア．「Ａを脅迫して現金を強取した」という強盗の訴因で起訴された甲について、「Ａに暴行を\n加えて現金を交付させた」という恐喝の事実を認定するには、訴因変更の手続を要しない。\nイ．「乙と共謀の上、Ｖに対し、殺意をもって、甲が、Ｖの頸部を絞め付け、窒息死させて殺害\nした」という殺人の共同正犯の訴因で起訴された甲について、「乙と共謀の上、Ｖに対し、殺\n意をもって、甲又は乙あるいはその両名において、Ｖの頸部を絞め付け、窒息死させて殺害し\nた」という事実を認定するには、公判で、殺害行為を行ったのが甲と乙のいずれなのかが争点\nとなっていたとしても、訴因変更の手続を要する。\nウ．「ブレーキペダルと間違えてアクセルペダルを踏んだ過失により、自車を前方のＡ運転の自\n動車に追突させ、Ａに傷害を負わせた」という過失運転致傷の訴因で起訴された甲について、\n「Ａ車の後ろに進行接近する際、ブレーキをかけるのが遅れた過失」を認定するには、訴因変\n更の手続を要する。\nエ．日時、場所、方法を特定した覚醒剤使用の訴因を、別の日時、場所、方法の覚醒剤使用の訴\n因に変更することは、いずれの訴因も被告人の尿中から検出された同一の覚醒剤の使用行為に\n関するものである場合には、公訴事実の同一性に欠けることはなく、許される。\nオ．「Ａ方に侵入し、現金10万円を窃取した」という住居侵入・窃盗の訴因を、別の日時に\n「Ｂ方に侵入し、現金15万円を窃取した」という住居侵入・窃盗の訴因に変更することは、\n両訴因の事実が、実体法上は常習特殊窃盗罪を構成する場合であっても、公訴事実の同一性を\n欠くため、許されない。",
