    "question": "次のアからオまでの各記述は、取調べに際して任意の供述をした者が、公判期日においては前に\nした供述と異なる供述をするおそれがあり、かつ、その者の供述が犯罪の証明に欠くことができな\nいと認められるため、検察官が刑事訴訟法第227条に基づき証人尋問を請求する場合に関する記\n述である。各記述のうち、誤っているものの組合せは、後記1から5までのうちどれか。（解答欄\nは、）\nア．被疑者の共犯者についても、証人尋問を請求することができる。\nイ．第1回公判期日後には証人尋問を請求することができない。\nウ．「異なる供述」とは、供述が、被疑者、被告人に有利に変更される場合だけでなく、不利に\n変更される場合も含む。\nエ．弁護人は、証人尋問が行われる際、その尋問に立ち会う権利を有する。\nオ．公訴提起後に証人尋問を請求する場合は、請求先は裁判官ではなく裁判所である。",
