    "label": "第24問",
    "question": "伝聞証拠に関する次のアからオまでの各記述のうち、誤っているものの組合せは、後記1から5\nまでのうちどれか。ただし、判例がある場合には、それに照らして考えるものとする。（解答欄\nは、）\nア．証人が公判期日において、前に裁判官の面前でした供述と異なった供述をした場合、前にし\nた供述を録取した書面で供述者の署名又は押印のあるものは、公判期日における供述よりも前\nにした供述を信用すべき特別の情況の存するときに限り、これを証拠とすることができる。\nイ．火災原因の調査、判定に関し特別の学識経験を有する私人が、弁護人の依頼を受けて燃焼実\n験を行ってその考察の結果を報告した書面は、裁判所から鑑定を命じられた者が作成した鑑定\nの経過及び結果を記載した書面と同じ要件のもとでこれを証拠とすることができる。\nウ．刑事訴訟法第323条第2号によれば、「業務の通常の過程において作成された書面」は、\nその作成者が公判期日において証人として尋問を受け、その真正に作成されたものであること\nを供述したときに限り、これを証拠とすることができる。\nエ．甲の検察官に対する供述調書中に、被告人乙が甲に対してした「Ｖ方に放火してきた。」旨\nの供述が含まれているときは、刑事訴訟法第321条第1項第2号及び同法第324条によ\nり、これを乙の現住建造物等放火被告事件において証拠とすることができる。\nオ．刑事訴訟法第325条による書面に記載された供述が任意にされたものかどうかの調査は、\n必ずしもその証拠調べの前にされなければならないものではない。",
