    "label": "第25問",
    "question": "次の【事例】について述べた後記アからオまでの【記述】のうち、誤っているものの組合せは、\n後記1から5までのうちどれか。\n【事例】\n甲は、強盗致傷の被疑事実で勾留され、国選弁護人としてＡが選任された。甲は、被疑事実と同\n一の事実により、Ｈ地方裁判所に起訴された。\n本件強盗致傷事件は、公判前整理手続に付されたところ、第1回の公判前整理手続期日に先立\nち、検察官は証明予定事実記載書を提出し、また、証明予定事実を証明するために用いる証拠の取\n調べを請求し、それらを①起訴後においても国選弁護人であるＡに開示した。その中には、本件強\n盗致傷事件の犯人の容ぼうが甲によく似ていると供述する目撃者乙の検察官に対する供述調書が含\nまれていた。②その後、第1回の公判前整理手続期日が指定され、同期日に甲が出頭した。\n第1回の公判前整理手続期日の後、Ａは、検察官に対し、③刑事訴訟法第316条の15に基づ\nき、乙の供述調書の証明力を判断するために重要な証拠として、乙の他の供述録取書等の開示を請\n求し、同条の要件を満たす乙の供述録取書等は全てＡに開示された。\nＡは、その後、裁判所及び検察官に対し、甲は本件強盗致傷事件の発生した日時に、事件現場か\nら遠く離れたＩ市にいたのであって、本件強盗致傷事件に関与していない旨のアリバイ主張を記載\nした予定主張記載書面を提出するとともに、本件犯行日時にＩ市において甲と一緒にいたという甲\nの友人である丙の証人尋問を請求した。④裁判所はこれに対し、検察官の意見を聞いた上で、丙の\n証人尋問を決定した。\nその後、公判前整理手続が終了して公判期日が開かれ、公判期日において丙の証人尋問が行われ\nた。⑤丙は、その証人尋問において、本件犯行日時にＩ市において丙のスマートフォンで撮影した\n写真に偶然、甲が写っているものがある旨の証言をした。なお、Ａ及び甲は、同証人尋問前に丙か\nら同写真の存在を知らされておらず、公判前整理手続において、同写真の証拠調べ請求はされてい\nない。\n【記述】\nア．下線部①で起訴後もＡが国選弁護人の地位にあるためには、改めて第一審の国選弁護人とし\nて選任される必要がある。\nイ．甲に対しては、第1回公判期日の冒頭手続において黙秘権の告知が行われるが、下線部②の\n甲が出頭した最初の公判前整理手続期日においても、裁判長は甲に対し、黙秘権の告知をしな\nければならない。\nウ．弁護人は、検察官が取調べを請求した乙の供述調書について、公判前整理手続中に刑事訴訟\n法第326条の同意をするかどうか、又はその取調べの請求に関し異議がないかどうかの意見\nを明らかにしなければならないが、その時期は、下線部③の開示がされた後でよく、それより\nも前に意見を明らかにする必要はない。\nエ．下線部④の丙の証人尋問のほかにもアリバイ主張に関連してＡが証拠調べを請求した証拠が\nあったとしても、裁判所はそれらについて証拠調べをする決定又は証拠調べの請求を却下する\n決定をしないまま公判前整理手続を終え、丙の証人尋問を実施した後、それらの証拠の取調べ\nをするか否かを決定してもよい。\nオ．下線部⑤の写真について、公判前整理手続の中で証拠調べ請求がされることなく同手続が終\n了した以上、Ａが丙の証人尋問終了後にその証拠調べを請求する余地はない。",
