    "question": "裁判の効力に関する次のアからオまでの各記述のうち、誤っているものの組合せは、後記1から\n5までのうちどれか。ただし、判例がある場合には、それに照らして考えるものとする。（解答欄\nは、）\nア．被告人Ａが甲を殺害した旨の訴因について有罪判決が確定した後、検察官は、ＢがＡと共謀\nの上で甲を殺害した旨の事実でＢを起訴することができる。\nイ．有罪の確定判決について、再審開始の決定が確定したとしても、再審の判決が確定するまで\nは、再審の請求の対象となった確定判決は、その効力を失わない。\nウ．殺人被告事件で勾留中の被告人につき無罪判決が宣告された場合、その判決宣告の時点で、\n被告人に対する勾留状はその効力を失う。\nエ．殺人罪の訴因について無罪判決が確定した後、検察官が被告人の有罪を立証するに十分な新\nたな証拠が発見されたとして、再度、同事件の被告人を同一事実で起訴した場合、裁判所は、\n改めて審理し、有罪の判決をすることができる。\nオ．告訴がないまま起訴された器物損壊事件において、公訴棄却の判決が確定した場合、検察官\nは、その後に被害者から告訴を得たとしても、再度、同事件の被告人を同一事実で起訴するこ\nとはできない。",
