    "question": "意思能力に関する次のアからオまでの各記述のうち、誤っているものを組み合わせたものは、後\n記1から5までのうちどれか。\nア．意思能力とは、自己の行為の責任を弁識する能力をいう。\nイ．契約の当事者がその意思表示をした時に意思能力を有しなかったときは、その契約の無効を\n善意無過失の第三者にも対抗することができる。\nウ．契約の当事者がその意思表示をした時に意思能力を有しなかった場合において、その契約に\n基づく債務の履行として給付を受けたときは、現に利益を受けている限度において、返還の義\n務を負う。\nエ．契約の申込者が申込みの通知を発した後に意思能力を有しない常況にある者となった場合に\nおいて、その相手方が承諾の通知を発するまでにその事実が生じたことを知ったときは、その\n申込みは、その効力を有しない。\nオ．婚姻の当事者が婚姻届を作成した時に意思能力を有しないことは、婚姻の取消しの原因とな\nる。",
