    "question": "条件に関する次のアからオまでの各記述のうち、正しいものを組み合わせたものは、後記1から\n5までのうちどれか。\nア．ＡがＢとの間で、Ｂが一定期間窃盗をしなかったら10万円をＢに与える旨の贈与契約を締\n結した場合において、その期間窃盗をしなかったＢがＡに10万円の支払を請求したときは、\nＡは、これを拒むことができる。\nイ．停止条件付きの動産の贈与契約が締結された場合において、贈与者が信義則に反し故意にそ\nの条件の成就を妨げたときは、受贈者は、動産の引渡しを請求することができる。\nウ．互いに同種の目的を有する債務を負担している者の間で、一定の事由が発生したら意思表示\nを待たずに当然に相殺の効力が生ずる旨の合意をしたとしても、相殺の効力は、その事由の発\n生によって当然には生じない。\nエ．ＡがＢとの間で、Ｂが甲大学に合格したらＡの所有する動産乙をＢに与える旨の贈与契約を\n締結した後、合否未定の間にＡが乙を過失により損傷した場合には、Ｂが甲大学に合格しても、\nＡは、Ｂに対し、損害賠償義務を負わない。\nオ．ＡがＢとの間で、Ａの気が向いたらＢに10万円を与える旨の贈与契約を締結した場合にお\nいて、ＢがＡに10万円の支払を請求したときは、Ａは、これを拒むことができない。",
