    "question": "不動産の譲渡担保に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを\n組み合わせたものは、後記1から5までのうちどれか。\nア．設定者は、被担保債権について不履行があった後は、譲渡担保権者に対し、受戻権を放棄す\nることにより、清算金の支払を請求することができる。\nイ．被担保債権について不履行があった後、譲渡担保権者の債権者が目的物を差し押さえ、その\n旨の登記がされたときは、設定者は、その後に被担保債権を弁済しても、第三者異議の訴えに\nより強制執行の不許を求めることができない。\nウ．設定者は、被担保債権が弁済されない限り、正当な権原なく目的物を占有する者に対し、そ\nの明渡しを請求することができない。\nエ．被担保債権について不履行があった後、譲渡担保権者が譲渡担保権の実行として目的物を譲\n渡したときは、設定者は、譲受人からの明渡請求に対し、譲渡担保権者に対する清算金支払請\n求権を被担保債権とする留置権を主張することができない。\nオ．譲渡担保権者は、被担保債権について不履行があったときは、設定者との間で帰属清算の合\n意がされていたとしても、目的物を処分する権限を取得する。",
