    "question": "履行遅滞に関する次のアからオまでの各記述のうち、判例の趣旨に照らし誤っているものを組み\n合わせたものは、後記1から5までのうちどれか。\nア．取立債務の履行について確定期限がある場合には、債権者が取立行為をしないときであって\nも、債務者は、その期限の到来した時から遅滞の責任を負う。\nイ．債務の履行について不確定期限があるときは、債務者は、その期限の到来後に履行の請求を\n受けた時又はその期限の到来を知った時のいずれか早い時から遅滞の責任を負う。\nウ．返還時期の定めがない消費貸借において、貸主が相当の期間を定めないで催告をしたときは、\n借主は、その催告後相当の期間を経過した時から遅滞の責任を負う。\nエ．債権者が受益者に対する詐害行為取消請求に係る訴えにおいて受領金の返還を請求したとき\nは、その受領金の返還債務は、その請求を認容する判決の確定時に遅滞に陥る。\nオ．不法行為に基づく損害賠償債務は、催告を要することなく、損害の発生と同時に遅滞に陥る。",
