    "question": "ＡのＢに対する金銭債権（以下「甲債権」という。）とＢのＡに対する金銭債権（以下「乙債権」\nという。）との相殺に関する次のアからオまでの各記述のうち、判例の趣旨に照らし誤っているも\nのを組み合わせたものは、後記1から5までのうちどれか。\nア．甲債権が売買代金債権であり、乙債権がＢの所有するパソコンをＡが過失によって損傷した\nことによる不法行為に基づく損害賠償債権であったときは、Ａは、相殺をもってＢに対抗する\nことができる。\nイ．ＡがＢのＣに対する債務をＢの委託を受けて保証していた場合において、Ｂの債権者Ｄが売\n買代金債権である乙債権を差し押さえた後、ＡがＣに対する保証債務を履行し、求償権である\n甲債権を取得したときは、Ａは、相殺をもってＤに対抗することができる。\nウ．甲債権がＡＢ間のパソコンの売買に基づく売買代金債権であったときは、Ａは、Ｂに対して\nパソコンの引渡しの提供をしていなくても、乙債権との相殺をもってＢに対抗することができ\nる。\nエ．甲債権と乙債権とが相殺適状となった後に甲債権が時効によって消滅した場合において、そ\nの後、ＢがＡに対して乙債権の履行を請求したときは、Ａは、相殺をもってＢに対抗すること\nができる。\nオ．甲債権について弁済期が到来していなくても、乙債権について弁済期が到来していれば、Ａ\nは、相殺をもってＢに対抗することができる。",
