    "question": "売買契約に基づき買主Ａが売主Ｂから引渡しを受けた動産甲の品質が契約の内容に適合しないも\nのである場合に関する次のアからオまでの各記述のうち、誤っているものを組み合わせたものは、\n後記1から5までのうちどれか。\nア．Ｂは、Ａから甲の修補の請求を受けた場合であっても、Ａに不相当な負担を課するものでな\nいときは、代替物の引渡しによる履行の追完をすることができる。\nイ．不適合が追完不能であるためにＡのＢに対する履行の追完の請求が認められないときは、Ａ\nは、Ｂに対し、代金の減額を請求することができない。\nウ．不適合がＡの責めに帰すべき事由によるものであるときは、Ａは、Ｂに対し、甲の修補と代\n金の減額のいずれの請求もすることができない。\nエ．不適合がＡＢ双方の責めに帰することができない事由によるものであるときは、Ａは、Ｂに\n対し、代金の減額を請求することができない。\nオ．Ｂが引渡し時に不適合を過失なく知らなかった場合において、Ａが不適合を知った時から法\n定の期間内にその旨をＢに通知しなかったときは、Ａは、Ｂに対し、損害賠償を請求すること\nができない。",
