    "question": "株主総会に関する次のアからオまでの各記述のうち、正しいものを組み合わせたものは、後記\n1から5までのうちどれか。\nア．判例の趣旨によれば、会社法上の公開会社でない取締役会設置会社は、取締役会の決議に\nよるほか株主総会の決議によっても代表取締役を選定することができる旨を定款で定めるこ\nとができる。\nイ．株式会社は、株主総会の場所に存しない株主を、映像と音声の送受信により相手の状態を\n相互に認識しながら通話をすることができる方法によって、当該株主総会に出席させること\nはできない。\nウ．判例の趣旨によれば、定款に株主総会で議決権を行使する代理人を株主に限定する旨の定\nめがある場合には、法人である株主は、その従業員であって株主でない者に株主総会におけ\nる議決権を代理行使させることができない。\nエ．株式会社は、取締役を選任する株主総会の決議について、定足数をなくし、出席した株主\nの議決権の過半数をもって行うこととする旨を定款で定めることができる。\nオ．監査役会設置会社は、取締役の選任について、株主からの請求があるときであっても累積\n投票によらない旨を定款で定めることができる。",
    "question_no": 19,
    "options": [
      "ア ウ",
      "ア オ",
      "イ ウ",
      "イ エ",
      "エ オ"
    ],
    "answer": 1,
    "answer_display": "2",
    "type": "5択",
    "points": 2
