    "question": "取締役会設置会社における株主提案権に関する次のアからオまでの各記述のうち、正しいもの\nを組み合わせたものは、後記1から5までのうちどれか。\nア．議案Ａと実質的に同一の議案Ｂが2年前の株主総会において総株主（議案Ｂについて議決\n権を行使することができない株主を除く。）の議決権の5分の1の賛成を得られたにとどま\nるときは、株主は、株主総会において、議案Ａを提出することができない。\nイ．監査役会設置会社の株主が提出しようとする議案の要領を株主に通知することを請求する\n場合には、当該請求との関係では、監査等委員会を設置する旨の定款変更の議案と監査役及\nび監査役会を廃止する旨の定款変更の議案は、1つの議案とみなされる。\nウ．会社法上の公開会社においては、総株主の議決権の100分の1以上の議決権又は300\n個以上の議決権を6か月前から引き続き有する株主に限り、株主総会において、株主総会の\n目的である事項につき議案を提出することができる。\nエ．株主が提出しようとする複数の取締役の選任に関する議案の要領を株主に通知することを\n請求する場合には、当該請求との関係では、当該議案は、候補者の数にかかわらず1つの議\n案とみなされる。\nオ．10を超える数の議案の要領を株主に通知することを請求した株主が当該請求と併せて当\n該議案相互間の優先順位を定めている場合であっても、取締役は、その裁量により、当該通\n知の対象から除外する議案を定めることができる。",
