    "question": "商業登記に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組み合\nわせたものは、後記1から5までのうちどれか。\nア．株式会社の代表取締役は、代表取締役である旨の登記がされているか否かにかかわらず、\n当該株式会社を代表して取引先である会社に対する売買代金請求の訴えを提起することがで\nきる。\nイ．株式会社の取締役として選任されていない者は、自己を取締役として登記することについ\nて承諾し、その旨の登記がされた場合であっても、積極的に取締役として対外的又は内部的\nな行為をしない限り、会社法第429条第1項の役員等としての責任を負わない。\nウ．会社法の規定により登記すべき事項について、登記の申請がされたものの、登記官の過誤\nにより当該登記がされなかった場合には、当該登記の申請者は、当該事項を善意の第三者に\n対抗することができない。\nエ．会社法の規定により登記すべき事項が登記された後であっても、過失なく負傷したため登\n記簿を閲覧することができなかったことにより、その登記があることを知らなかった者に対\nしては、当該事項を対抗することができない。\nオ．申請された登記事項について登記官の過誤により誤った内容が登記された場合には、当該\n登記の申請者は、当該事項が不実であることを善意の第三者に対抗することができない。",
