    "subject": "商法",
    "label": "第29問",
    "question": "ホテルを経営するＡの宿泊客Ｂに対する責任に関する次のアからオまでの各記述のうち、誤っ\nているものを組み合わせたものは、後記1から5までのうちどれか。\nア．Ａは、Ｂからバッグを預かるに当たってバッグの中に1億円相当の宝石が入っていること\nを告げられていなかった場合において、その宝石の存在を知ることができず、かつ、その宝\n石の滅失につき悪意も重大な過失もないときは、その宝石の滅失によって生じた損害を賠償\nする責任を負わない。\nイ．ＡがＢから預かったバッグが滅失したときは、Ａは、その保管につき注意を怠らなかった\nことを証明することにより、Ｂのバッグの滅失によって生じた損害を賠償する責任を免れる\nことができる。\nウ．Ａが注意を怠らなかったにもかかわらず、Ｂの宿泊部屋内に置かれていたＢのバッグが滅\n失した場合には、Ａは、Ｂのバッグの滅失によって生じた損害を賠償する責任を負わない。\nエ．Ａは、「当ホテルは、フロントへお預けいただいていない携帯品の滅失又は損傷の損害に\nついては、いかなる責任も負いません。」とホテルの正面玄関に掲示していたときは、宿泊\n中のホテル内におけるＢのバッグの滅失によって生じた損害を賠償する責任を免れることが\nできる。\nオ．ＡがＢから預かったバッグが損傷した場合におけるＢのＡに対する場屋営業者の責任に係\nる債権は、ＢがＡからバッグを返還された時から1年間行使しないときは、Ａがバッグの損\n傷につき悪意でなければ、時効によって消滅する。",
