    "label": "第30問",
    "question": "ＡがＢに対して振り出した約束手形に関する次のアからオまでの各記述のうち、判例の趣旨に\n照らし正しいものを組み合わせたものは、後記1から5までのうちどれか。\nア．ＡがＢの強迫を理由に当該約束手形の振出しに係る意思表示を取り消した場合において、\nＢがそのことにつき善意のＣに対して当該約束手形を裏書譲渡したときは、Ａは、Ｃからの\n当該約束手形に係る手形金請求を拒むことができる。\nイ．ＡＢ間の当該約束手形振出しの原因関係上の債務と当該約束手形上の債務が併存する場合\nにおいて、当該原因関係上の債務が履行されたときは、Ａは、Ｂからの当該約束手形に係る\n手形金請求を拒むことができる。\nウ．ＡＢ間の当該約束手形振出しの原因関係上の債務が当該約束手形の振出しによって消滅す\nるか否かについての当事者の意思が明らかでない場合には、当該約束手形の振出しは、当該\n原因関係上の債務の支払に代えてされたものと推定される。\nエ．ＡＢ間の当該約束手形振出しの原因関係上の債務と当該約束手形上の債務が併存する場合\nには、Ａは、Ｂからの当該原因関係上の債務の履行の請求について、当該原因関係上の債務\nの履行は当該約束手形の返還と引換えにする旨を主張することができない。\nオ．Ｂが、ＡのＢに対する人的抗弁につき善意のＣに対して当該約束手形を裏書譲渡し、Ｃ\nが、当該人的抗弁につき悪意のＤに対して当該約束手形を裏書譲渡した場合には、Ａは、Ｄ\nからの当該約束手形に係る手形金請求を拒むことができない。",
