    "question": "専門委員に関する次のアからオまでの各記述のうち、正しいものを組み合わせたものは、後記1\nから5までのうちどれか。\nア．裁判所は、当事者の同意を得たとしても、和解を試みる期日において、専門委員を手続に関\n与させることはできない。\nイ．裁判所が専門委員を手続に関与させる決定をした後に、当事者双方から当該決定の取消しの\n申立てがあった場合には、裁判所は当該決定を取り消さなければならない。\nウ．受命裁判官が弁論準備手続で争点の整理を行う場合に、受命裁判官の命令によっては、専門\n委員を手続に関与させることはできない。\nエ．裁判長は、証拠調べ手続に関与させた専門委員に、当事者の同意を得た上で、証人に対して\n直接に問いを発することを許すことができる。\nオ．裁判所は、専ら訴訟手続の円滑な進行を図るためとして、専門委員を手続に関与させる決定\nをすることはできない。",
