    "question": "送達に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組み合わせた\nものは、後記1から5までのうちどれか。\nア．書類の受領について相当のわきまえのある同居者が受送達者宛ての訴訟関係書類の交付を受\nけた場合には、当該同居者と受送達者との間にその訴訟に関して事実上の利害関係の対立があ\nるときであっても、受送達者に対する送達の効力が生ずる。\nイ．書留郵便等に付する送達の方法により受送達者の住民票上の住所に宛てて訴訟関係書類を発\n送した場合には、実際には発送時に既に受送達者が当該住所から転居していたときであって\nも、受送達者に対する送達の効力が生ずる。\nウ．一人の当事者について委任による訴訟代理人が数人あるときは、訴訟関係書類の送達は、そ\nの全員にしなければならない。\nエ．公示送達は、申立てにより、裁判長の許可の裁判を得て、裁判所書記官が行う。\nオ．少額訴訟において、公示送達によらなければ被告に対する最初にすべき口頭弁論の期日の呼\n出しをすることができないときは、裁判所は、訴訟を通常の手続により審理及び裁判をする旨\nの決定をしなければならない。",
