    "question": "訴状に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組み合わせた\nものは、後記1から5までのうちどれか。\nア．給付を求める訴えにおいて、請求を特定するのに必要な事実の記載はあるものの、請求を理\n由付ける事実の記載を欠く訴状の送達を受けた被告が、答弁書その他の準備書面を提出せず、\n口頭弁論期日に出頭しない場合には、裁判所は、直ちに原告の請求を認容する判決をすること\nができる。\nイ．訴状において、被告の現住所の記載を欠くものの、旧住所の記載によって被告の特定ができ\nる場合には、被告の現住所が明らかでないことにより訴状を被告に送達することができなかっ\nたとしても、裁判長は、補正を命ずることはできない。\nウ．原告が、貸金100万円のうち被告から弁済を受けた70万円を控除した残額である30万\n円の返還を求める訴えを提起する場合には、原告は、請求を特定するために、訴状において、\n70万円の弁済を受けたとの事実を記載しなければならない。\nエ．裁判長が訴状の補正を命じた場合に、原告は、その補正命令に対して不服を申し立てること\nができない。\nオ．訴え提起の手数料の納付を命ずる補正命令を受けた者が、当該命令において定められた期間\n内にこれを納付しなかった場合であっても、訴状却下命令が発せられる前にこれを納付したと\nきは、裁判長は、訴状を却下することはできない。",
