    "question": "訴訟行為と条件に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組\nみ合わせたものは、後記1から5までのうちどれか。\nア．原告が被告に対して、主位的に売買契約に基づき代金の支払を求めるとともに、売買契約が\n無効であると判断される場合に備えて、主位的請求が認容されることを解除条件として、予備\n的に所有権に基づき目的物の返還を求めた場合には、裁判所は、目的物の返還請求権の存否に\n先立って、売買代金の支払請求権の存否について判断しなければならない。\nイ．原告が被告に対して貸金の返還を求める訴えにおいて、被告が、弁済の抗弁を主張するとと\nもに、弁済の抗弁が認められることを解除条件として消滅時効の抗弁を主張した場合には、裁\n判所は、消滅時効の抗弁の判断に先立って弁済の抗弁について判断をしなければならない。\nウ．原告が被告に対して、所有権に基づき機械の引渡しを求めるとともに、強制執行が功を奏し\nない場合に備えてあらかじめ目的物の時価相当額の代償金の支払を求める場合には、機械の引\n渡請求を主位的請求とし、代償金の支払請求を予備的請求としなければならない。\nエ．本訴及び反訴の係属中に、本訴原告（反訴被告）が、本訴の訴訟物である債権が時効により\n消滅したと判断されることを停止条件として、反訴において、当該債権を自働債権として相殺\nの抗弁を主張することは許されない。\nオ．所有権に基づき抵当権設定登記の抹消登記手続を求める訴えにおいて、原告が当該抵当権設\n定登記の抹消登記がされることを停止条件として訴えを取り下げることは、不適法なものとし\nて訴訟上許されない。",
