    "question": "条例に関する次のアからウまでの各記述について、最高裁判所の判例の趣旨に照らして、正しい\nものには○、誤っているものには×を付した場合の組合せを、後記1から8までの中から選びなさ\nい。\nア．憲法第94条は、法律の範囲内で条例制定権を認めているが、ある事項について国の法令中\nにこれを規制する明文の規定がない場合であれば、当該事項について規制を設ける条例の規定\nは、国の法令に違反しない。\nイ．条例は、公選の議員をもって組織する地方公共団体の議会の議決を経て制定される自治立法\nであって、国民の公選した議員をもって組織する国会の議決を経て制定される法律に類するも\nのであるから、条例によって刑罰を定める場合、法律による条例への委任は、一般的・包括的\n委任で足りる。\nウ．憲法第94条は、地方公共団体に条例制定権を認めており、ある事項を条例によって規制す\nる結果として、地方公共団体ごとにその取扱いに差異が生じることがあり得るから、ある事項\nについて条例によって刑罰を定める場合、地域によって刑罰の内容に差異が生じることも許容\nされ得る。",
