    "question": "行政調査に関する次のアからエまでの各記述について、法令又は最高裁判所の判例に照らし、そ\nれぞれ正しい場合には1を、誤っている場合には2を選びなさい。\n\nア．国税通則法第74条の2第1項に基づく質問検査は、諸般の具体的事情に鑑み、質問検査の\n客観的な必要性があると判断される場合に認められるものであって、この場合の質問検査の範\n囲、程度、時期、場所等法律上特段の定めのない実施の細目については、上記のような質問検\n査の必要があり、かつ、これと相手方の私的利益との衡量において社会通念上相当な限度にと\nどまる限り、権限ある職員の合理的な選択に委ねられている。\n（参照条文）国税通則法\n（当該職員の所得税等に関する調査に係る質問検査権）\n第74条の2 国税庁、国税局若しくは税務署（中略）又は税関の当該職員（中略）は、所\n得税、法人税、地方法人税又は消費税に関する調査について必要があるときは、次の各号\nに掲げる調査の区分に応じ、当該各号に定める者に質問し、その者の事業に関する帳簿書\n類その他の物件（中略）を検査し、又は当該物件（中略）の提示若しくは提出を求めるこ\nとができる。\n一～四 （略）\n2～5 （略）",
