    "question": "当事者訴訟に関する教員と学生による以下の対話中の次のアからエまでの【 】内の各記述につ\nいて、法令又は最高裁判所の判例に照らし、それぞれ正しい場合には1を、誤っている場合には2\nを選びなさい。\n教員：行政事件訴訟法第4条は、当事者訴訟として、「当事者間の法律関係を確認し又は形成す\nる処分又は裁決に関する訴訟で法令の規定によりその法律関係の当事者の一方を被告とする\nもの」と「公法上の法律関係に関する確認の訴えその他の公法上の法律関係に関する訴訟」\nの二つの類型を規定しています。これから、前者を「形式的当事者訴訟」、後者を「実質的\n当事者訴訟」と呼ぶこととしますが、まず、形式的当事者訴訟としては具体的にどのような\n訴訟がありますか。\n学生：\n\n【イ】教員：行政事件訴訟法第4条は、当事者訴訟として、「当事者間の法律関係を確認し又は形成す\nる処分又は裁決に関する訴訟で法令の規定によりその法律関係の当事者の一方を被告とする\nもの」と「公法上の法律関係に関する確認の訴えその他の公法上の法律関係に関する訴訟」\nの二つの類型を規定しています。これから、前者を「形式的当事者訴訟」、後者を「実質的\n当事者訴訟」と呼ぶこととしますが、まず、形式的当事者訴訟としては具体的にどのような\n訴訟がありますか。\n学生：はい。形式的当事者訴訟が提起された場合には、被告は、当該処分又は裁決をした\n行政庁が所属する国又は公共団体に対し、遅滞なく、その訴訟の告知をしなければならない\nとされています。",
