    "question": "学生Ａ、Ｂ及びＣは、次の【会話】のとおり議論している。【会話】中の①から⑤までの（ ）\n内から適切な語句を選んだ場合、正しいものの組合せは、後記1から5までのうちどれか。（解答\n欄は、）\n【会 話】\n学生Ａ．状態犯とは、法益侵害の発生と同時に犯罪が終了するが、その後も法益侵害状態が残存\nする犯罪です。傷害罪がその典型です。これに対し、継続犯とは、法益侵害が継続してい\nる間は犯罪の継続が認められる犯罪であり、監禁罪や、①（ａ．保護責任者不保護罪・ｂ．\n窃盗罪）がこれに当たると考えられます。\n学生Ｂ．住居侵入罪を状態犯と解すべきか、継続犯と解すべきかは争いがあります。②（ｃ．状\n態犯・ｄ．継続犯）と解する立場は、反対説によると、侵入後の現場滞留についても住居\n侵入罪が成立し、不退去罪が規定されている意味が失われてしまうと同説を批判します。\n学生Ｃ．私は、継続犯は、③（ｅ．構成要件該当行為・ｆ．構成要件的結果）が継続する犯罪で\nあると考えます。私の見解からは、被害者の監禁中に監禁罪の法定刑を引き上げる新法が\n施行された場合、それ以降の監禁については、④（ｇ．新法・ｈ．旧法）が適用されるこ\nとになります。\n学生Ａ．私は、Ｃさんの継続犯に関する理解には賛成できません。例えば、行為者が被害者を監\n禁した後に眠り込んだ場合であっても犯罪は継続しますが、行為者が眠り込んだ後には意\n思に基づく身体の動静がない以上、Ｃさんの見解のように理解するのは困難だと考えるか\nらです。\n学生Ｂ．ところで、状態犯についても、犯罪の終了時期と既遂時期の関係について考える必要が\nあります。私は、傷害罪については、両者は、⑤（ｉ．常に一致する・ｊ．一致するとは\n限らない）と考えます。被害者が一旦負傷した後、その傷害が悪化し続けることがあるか\nらです。",
