    "question": "背任罪に関する次のアからオまでの各記述を判例の立場に従って検討した場合、誤っているもの\nの組合せは、後記1から5までのうちどれか。\nア．甲は、信用保証協会の支所長であり、金融機関が中小企業者等に対して行う融資に関して、\n信用保証をなす業務を行っていたところ、乙の利益を図る目的で、乙に返済能力がないことを\n知りながら、乙が金融機関から融資を受けるに際し、確実かつ十分な担保の徴求をしないまま、\n同協会にその保証債務を負担させた。この場合、乙の金融機関に対する債務がいまだ不履行の\n状態に至らず、上記協会に、代位弁済による現実の損失がいまだ生じていなくても、甲に背任\n罪が成立する。\nイ．甲は、乙から頼まれ、乙が丙に対する貸金債権の質物として提供を受けていた丙所有の絵画\nを甲の自宅倉庫で保管していたが、乙に嫌がらせをする目的で、同絵画を乙に無断で丙に返還\nした。この場合、甲に背任罪が成立する。\nウ．甲は、乙が自身の有していた丙に対する債権を丁に譲渡した後、丁が対抗要件を具備する前\nに、同債権が丁に譲渡済みであることを確実に知りながら、同債権を転売して利益を得る目的\nで、乙に強く働き掛けて、乙から同債権を譲り受け、その対抗要件も具備した。この場合、甲\nと乙はいわゆる必要的共犯の関係に立つため、甲に背任罪の共同正犯が成立することはない。\nエ．甲は、返済期日までに返済できないときは同期日に改めて甲の所有する土地に抵当権を設定\nする旨を述べて、乙を安心させて乙から金を借りたが、同期日が到来する前に、丙に対する借\n金を返済する目的で、乙に無断で同土地を丙に売却した。この場合、甲に背任罪が成立する。\nオ．甲は、債権者乙との間で甲所有家屋を目的とする根抵当権設定契約を締結し、乙にその登記\nに必要な登記済証、白紙委任状及び印鑑証明を交付していたが、乙がその登記をしない間に、\n自らの利益を図る目的で、丙から金を借りて同家屋に根抵当権を設定し、丙が第1順位の根抵\n当権設定登記を了し、乙はそのために債権の回収が困難になった。この場合、甲に背任罪が成\n立する。",
