    "subject": "刑法",
    "label": "第7問",
    "question": "学生Ａ、Ｂ及びＣは、次の【事例】における甲の罪責について、後記【会話】のとおり議論して\nいる。【会話】中の①から⑦までの（ ）内から適切な語句を選んだ場合、正しいものの組合せは、\n後記1から5までのうちどれか。\n【事 例】\n甲は、先輩乙からの依頼を断り切れず、乙がＶ方に侵入して強盗を行うに当たり、乙をＶ方まで\n自動車で送り届けるとともに、乙がＶ方に侵入してＶから100万円を強取するまでの間、Ｖ方付\n近の路上で周囲を見張り、強盗を終えた乙を自動車に乗せて逃走した。乙は、甲の支援があったこ\nとから安心して強盗を完遂し、甲に対し、上記100万円のうち10万円を報酬として支払った。\n【会 話】\n学生Ａ．私は、共同正犯と幇助犯の区別の基準として、①（ａ．行為者の主観的事情・ｂ．行為\nの客観面）が重視されるべきだと考える。そうすると、【事例】では、そもそも、甲が侵\n入強盗の送迎や見張りをしたのは、先輩である乙からの依頼を断り切れなかったためであ\nるから、甲は、②（ｃ．共同正犯・ｄ．幇助犯）ということになるね。\n学生Ｂ．そうは簡単に言えないと思う。自己の犯罪を遂行する意思かどうかについて、私は、③\n（ｅ．故意の同一性・ｆ．行為者が果たした役割の重要性）も踏まえて判断すべきだと考\nえる。そうであれば、犯行の実現に送迎や見張りが必要とされた事情によっては、Ａさん\nとは違って、甲を、④（ｇ．共同正犯・ｈ．幇助犯）と解することもあるのではないかな。\n学生Ｃ．私は、共犯の処罰根拠から考えるべきだと思う。つまり、共犯の処罰根拠は、⑤（ｉ．\n正犯者を誘惑し、犯意を抱かせたこと・ｊ．法益侵害やその危険を間接的に惹起したこ\nと）にあることからすれば、共犯においては、結果への因果的寄与が要求される。だから、\n共同正犯か幇助犯かは、自己の犯罪を遂行する意思かどうかではなくて、この因果的寄与\nの存在を前提として、関与内容が客観的に重要なものといえるかで区別されるべきだよ。\n学生Ａ．しかし、因果的寄与といっても、共同正犯といえるためには、⑥（ｋ．意思連絡・ｌ．\n実行行為の分担）が要求されるべきであるから、Ｃさんの立場からも、⑦（ｍ．物理的因\n果性・ｎ．心理的因果性）が不可欠の要件になり、また、その程度が正犯性の判断に影響\nを及ぼすはずだよ。\n学生Ｃ．そうすると、【事例】では、Ｂさんの挙げた事情だけではなく、甲と乙との関係性や乙\nが甲に支援を依頼した理由も重視することになるね。",
