    "label": "第10問",
    "question": "過失に関する次の各【見解】についての後記アからオまでの各【記述】のうち、誤っているもの\nの組合せは、後記1から5までのうちどれか。\n【見 解】\nＡ説：過失の本質は、結果の発生を予見することができたのに、精神を緊張させずにこれを予見しな\nかったことにある。\nＢ説：過失の本質は、社会生活上必要な注意を怠り、結果を回避するための適切な措置を採らなかっ\nたことにあり、その前提として、構成要件的結果及び因果経過の基本部分に対する具体的な予見\n可能性が必要になる。\nＣ説：過失の本質は、Ｂ説と同様であるが、結果に対する具体的な予見可能性を必要とせず、一般人\nに対して何らかの結果回避措置を命じるのが合理的であるといえる程度の危惧感があれば足り\nる。\n【記 述】\nア．Ａ説からは、いわゆる信頼の原則を過失犯に適用する余地はない。\nイ．Ａ説は、故意犯と過失犯は客観面が共通であり、両者は主観面において区別されるとの見解\nと親和的である。\nウ．Ｂ説に対しては、結果回避のための適切な措置と行政取締法規が定める義務とを区別するの\nは困難であり、行政取締法規の義務違反が刑法上の過失になってしまうとの批判が可能である。\nエ．Ｂ説に対しては、自動車運転はそれ自体危険な行為であり、いかなる運転行為からも死傷結\n果が生じ得る以上、容易に予見可能性が認められ、過失犯の成立範囲が広くなりすぎるとの批\n判が可能である。\nオ．Ｃ説に対しては、構成要件該当事実に関する具体的な予見可能性がないにもかかわらず、漠\n然とした危惧感だけで過失責任を追及することは責任主義に反するとの批判が可能である。",
