    "question": "次のアからオまでの各記述を判例の立場に従って検討した場合、誤っているものの組合せは、後\n記1から5までのうちどれか。\nア．甲は、Ａから金銭を借り入れるに際し、借入金を返済する意思も能力もないのに、知人Ｂに\n対し、「借入金は必ず自分で返済する。Ｂには迷惑をかけないので、保証人になってほしい。」\nとうそを言い、その旨Ｂを誤信させ、Ａに差し入れる予定の甲を借主とする金銭消費貸借契約\n書を閲読させ、その保証人欄に署名押印させた。この場合、甲には、有印私文書偽造罪が成立\nする。\nイ．甲は、窃取したＡ名義のクレジットカードの番号等を冒用し、インターネット上の決済手段\nとして使用できる電子マネーを不正入手しようと考え、Ａの氏名、同番号等の情報をインター\nネットを介してクレジットカード決済代行業者のコンピュータに送信し、Ａが上記電子マネー\n10万円分を購入した旨の電磁的記録を作出し、これによってインターネット上で同電子マネ\nーを利用することを可能とした。この場合、甲には、支払用カード電磁的記録不正作出罪が成\n立する。\nウ．県立高校を中途退学した甲は、母親Ａに見せて安心させる目的で、偽造された同高校校長Ｂ\n名義の甲の卒業証書を真正なものとしてＡに提示した。この場合、甲には、偽造有印公文書行\n使罪が成立する。\nエ．指名手配され逃走中の甲は、本名を隠してＡ会社に正社員として就職しようと考え、同社に\n提出する目的で、履歴書用紙の氏名欄にＢという架空の氏名を記載し、その横にＢの姓を刻し\nた印鑑を押印した上、真実と異なる生年月日、住所及び経歴を記載して履歴書を作成したが、\nその顔写真欄には甲自身の顔写真を貼付していた。この場合、甲には、有印私文書偽造罪が成\n立する。\nオ．甲は、Ａから金銭を借り入れるに際し、数日前にＢが死亡したことを知りながら、Ａに差し\n入れる予定の金銭消費貸借契約書の借受人欄に、Ｂの氏名を冒用して署名押印し、一般人をし\nてＢが生存中に作成したと誤信させるおそれが十分に認められる文書を作成した。この場合、\n甲には、有印私文書偽造罪が成立する。",
