    "question": "遺棄の罪に関する次の【見解】についての後記アからオまでの各【記述】のうち、誤っているも\nのの組合せは、後記1から5までのうちどれか。\n【見 解】\n遺棄とは、場所的離隔を生じさせることにより、要扶助者を保護のない状態に置くことをいう\nところ、遺棄罪（刑法第217条）の「遺棄」は、要扶助者を移動させる行為（移置）のみに限\nられるが、保護責任者遺棄等罪（同法第218条）の「遺棄」は、移置のほか、置き去りのよう\nに、要扶助者の移動を伴わず、行為者自身が移動することで要扶助者との場所的離隔を生じさせ\nる行為を含む。同罪の「不保護」は、場所的離隔を伴わずに、要扶助者の生存に必要な保護を行\nわないことをいう。また、同罪の「保護する責任」と不真正不作為犯における作為義務は一致す\nる。\n【記 述】\nア．この【見解】によれば、保護責任を有しない者が置き去り行為をした場合、刑法第217条\nで処罰することが可能である。\nイ．この【見解】に対しては、不真正不作為犯において、作為との同価値性を基礎付ける要件に\nすぎないはずの作為義務が、加重処罰の要件である保護責任と同視されており、妥当でないと\nの批判が可能である。\nウ．この【見解】によれば、保護責任を有する者が要扶助者から離れ、要扶助者を保護のない状\n況に置いた場合、刑法第218条で処罰することが可能である。\nエ．この【見解】に対しては、隣り合った条文で用いられている同一の文言の解釈が異なること\nとなり、妥当でないとの批判が可能である。\nオ．この【見解】によれば、保護責任を有する者の行為によって要扶助者の生命に対する危険が\n具体化した場合に限り、刑法第218条で処罰することが可能である。",
