    "question": "勾留に関する次のアからオまでの各記述のうち、正しいものの組合せは、後記1から5までのう\nちどれか。ただし、判例がある場合には、それに照らして考えるものとする。\nア．裁判官は、検察官から勾留の請求を受けた被疑者について勾留の裁判をするに当たり、被疑\n者が逃亡した場合を除き、被疑者に対し被疑事件を告げこれに関する陳述を聴く手続を行わな\nければならない。\nイ．裁判官は、検察官から勾留期間の延長の請求を受けた被疑者について勾留期間の延長の裁判\nをするに当たり、被疑者が逃亡した場合を除き、被疑者に対し被疑事件を告げこれに関する陳\n述を聴く手続を行わなければならない。\nウ．裁判官は、勾留されている被疑者がその被疑事実と同一の事実で公訴を提起された場合にお\nいて、その勾留を継続する必要があると認めるときは、被告人が逃亡した場合を除き、被告人\nに対し被告事件を告げこれに関する陳述を聴く手続を行わなければならない。\nエ．裁判所は、勾留されていない被告人について勾留の裁判をするに当たり、既に被告事件の審\n理の際に被告人から被告事件に関する陳述を聴いている場合には、改めて被告人に対し被告事\n件を告げこれに関する陳述を聴く手続を行う必要はない。\nオ．裁判所は、勾留期間の更新の裁判をするに当たり、被告人が逃亡した場合を除き、被告人に\n対し被告事件を告げこれに関する陳述を聴く手続を行わなければならない。",
