    "label": "第16問",
    "question": "体液等の採取に関する次のアからオまでの各記述のうち、誤っているものの組合せは、後記1か\nら5までのうちどれか。ただし、判例がある場合には、それに照らして考えるものとする。（解答\n欄は、）\nア．強制採尿のための捜索差押許可状には、強制採尿は医師をして医学的に相当と認められる方\n法により行わせなければならない旨の条件を記載することが望ましいが、かかる記載は不可\n欠ではない。\nイ．身体を拘束されていない被疑者を採尿場所へ任意に同行することが事実上不可能であると認\nめられる場合には、強制採尿のための捜索差押許可状の効力として、採尿に適する最寄りの場\n所まで被疑者を連行することができる。\nウ．尿を任意に提出しない被疑者の体内からカテーテルを用いて強制的に尿を採取することは、\n被疑事件の重大性、嫌疑の存在、当該証拠の重要性とその取得の必要性、適当な代替手段の不\n存在等の事情に照らし、捜査上真にやむを得ないと認められる場合には、最終的手段として、\n適切な法律上の手続を経て行うことが許される。\nエ．警察官が強盗殺人事件の捜査において、捜索差押許可状の発付を受けることなく、被疑者が\n不要物として公道上のゴミ集積所に排出したゴミ袋を領置することは、違法ではない。\nオ．被疑者の唾液を採取する場合は、被疑者がこれを任意に提出することを承諾したとしても、\n唾液に含まれる口腔内細胞は遺伝情報を含むから、身体検査令状の発付を受けることなく、こ\nれを採取することはできない。",
