    "question": "次のアからオまでの各記述のうち、正しいものの組合せは、後記1から5までのうちどれか。た\nだし、判例がある場合には、それに照らして考えるものとする。\nア．身体の拘束を受けている被疑者に、取調べのために出頭し滞留する義務があると解すること\nは、直ちに被疑者からその意思に反して供述することを拒否する自由を奪うことを意味する\nものではない。\nイ．被告人が自らの氏名を一貫して明らかにせず、刑事施設の居室番号の自署、拇印等により自\n己を表示し、弁護人が署名押印した弁護人選任届を提出した場合にも、被告人には自らの氏\n名を開示する義務はないので、その選任届が不適法として却下されることはない。\nウ．捜査機関は、犯罪の被害者を参考人として取り調べるに当たり、あらかじめ自己の意思に反\nして供述をする必要がない旨を告げなければならない。\nエ．被告事件を審理する裁判所の裁判長は、冒頭手続において起訴状の朗読が終わった後、被告\n人に対し、終始沈黙し又個々の質問に対し陳述を拒むことができる旨のほか、陳述すること\nもできる旨及び陳述をすれば自己に不利益な証拠ともなり又利益な証拠ともなるべき旨を告\nげなければならない。\nオ．証人は、自己が刑事訴追を受けるおそれのある証言を拒むに当たり、その事由を示す必要は\nない。",
