    "question": "公判前整理手続に関する次のアからオまでの各記述のうち、誤っているものの組合せは、後記1\nから5までのうちどれか。\nア．検察官、被告人又は弁護人が事件を公判前整理手続に付することを求めたが、裁判所がその\n請求を却下する決定をした場合には、その検察官、被告人又は弁護人は、その却下決定に対し\nて即時抗告をすることができる。\nイ．被告人は、公判前整理手続期日に出頭する義務はなく、裁判所が被告人に対し、公判前整理\n手続期日に出頭することを求めることもできない。\nウ．裁判所は、裁判員裁判の対象事件については、第1回の公判期日前に、これを公判前整理手\n続に付さなければならない。\nエ．公判前整理手続において、被告人又は弁護人は、証明予定事実その他の公判期日においてす\nることを予定している事実上及び法律上の主張があるときは、裁判所及び検察官に対し、これ\nを明らかにしなければならない。\nオ．公判前整理手続に付された事件については、検察官及び被告人又は弁護人は、やむを得ない\n事由によって公判前整理手続において請求することができなかったものを除き、当該公判前整\n理手続が終わった後には、証拠調べを請求することができない。",
