    "question": "証人等の保護に関する次のアからオまでの各記述のうち、誤っているものの組合せは、後記1か\nら5までのうちどれか。\nア．裁判所は、弁護人が出頭している法廷で証人を尋問する場合において、証人が被告人の面前\nにおいては圧迫を受け充分な供述をすることができないと認めるときは、証人と被告人の間の\n遮へい措置又はビデオリンク方式が採られている場合を除き、検察官及び弁護人の意見を聴き、\nその証人の供述中被告人を退廷させることができる。\nイ．裁判所は、証人を尋問する場合において、証人の年齢、心身の状態その他の事情を考慮し、\n証人が著しく不安又は緊張を覚えるおそれがあると認めるときは、検察官及び被告人又は弁護\n人の意見を聴き、その不安又は緊張を緩和するのに適当であり、かつ、裁判官若しくは訴訟関\n係人の尋問若しくは証人の供述を妨げ、又はその供述の内容に不当な影響を与えるおそれがな\nいと認める者を、その証人の供述中、証人に付き添わせることができる。\nウ．裁判所は、被害者等が意見陳述をする場合において、被害者等の年齢、心身の状態その他の\n事情を考慮し、被害者等が著しく不安又は緊張を覚えるおそれがあると認めるときは、検察官\n及び被告人又は弁護人の意見を聴き、その不安又は緊張を緩和するのに適当であり、かつ、裁\n判官若しくは訴訟関係人の尋問若しくは被害者等の供述を妨げ、又はその供述の内容に不当な\n影響を与えるおそれがないと認める者を、被害者等の意見陳述中、被害者等に付き添わせるこ\nとができる。\nエ．被害者特定事項を公開の法廷で明らかにしない旨の決定があったときは、検察官は、被害者\n特定事項を明らかにしない方法で起訴状の朗読を行い、起訴状を被告人に示さなければならな\nい。\nオ．裁判所は、被害者特定事項を公開の法廷で明らかにしない旨の決定をすることはできるが、\n証人、鑑定人、通訳人又は翻訳人に係る特定事項を公開の法廷で明らかにしない旨の決定をす\nることはできない。",
