    "subject": "刑事訴訟法",
    "label": "第23問",
    "question": "次のⅠ及びⅡの【見解】は、人の健康に係る公害犯罪の処罰に関する法律第5条の推定規定の意\n味に関するものである。【見解】に関する後記アからオまでの【記述】のうち、正しいものの組合\nせは、後記1から5までのうちどれか。\n【見解】\nⅠ．本条は、被告人が、公衆の生命又は身体の危険が、被告人の排出した物質によって生じたも\nのでないことを立証できない場合には、裁判所が、その危険は、被告人の排出した物質によっ\nて生じたものと認定しなければならないことを定めたものである。\nⅡ．本条は、被告人が、公衆の生命又は身体の危険が、被告人の排出した物質によって生じたも\nのでないことを立証できない場合には、裁判所が、その危険は、被告人の排出した物質によっ\nて生じたものと認定することができることを定めたものである。\n【記述】\nア．Ⅰの見解は、本条は、物質の排出と公衆の生命又は身体の危険の発生との因果関係につき、\n被告人に挙証責任を転換する規定であるとするものである。\nイ．Ⅰの見解は、被告人は、自らが排出した物質によって公衆の生命又は身体の危険が生じたも\nのではないことを、合理的な疑いを超える程度に立証しなければならないとするものである。\nウ．Ⅱの見解によれば、被告人が、自らが排出した物質によって公衆の生命又は身体の危険が生\nじたものではないことを立証できなかった場合に、その危険が被告人の排出した物質によって\n生じたものと認定するかどうかは、裁判所の裁量に委ねられることになる。\nエ．Ⅱの見解に対しては、それによると、本条は「疑わしきは被告人の利益に」の原則に反する\nことになるとする批判がある。\nオ．Ⅱの見解は、本条は、被告人が、自らが排出した物質によって公衆の生命又は身体の危険が\n生じていないという立証ができないことを、一つの情況証拠とすることを認める規定であると\nするものである。",
