    "question": "自白の補強証拠に関する次のアからオまでの各記述のうち、誤っているものは幾つあるか。後記\n1から6までのうちから選びなさい。ただし、判例がある場合には、それに照らして考えるものと\nする。\nア．補強証拠は、自白に係る犯罪組成事実の全部にわたって、もれなく、これを裏付けするよう\nなものでなければならないわけではなく、自白に係る事実の真実性を保障し得るものであれ\nば足りる。\nイ．無免許運転の罪においては、運転行為のみならず、運転免許を受けていなかったという事実\nについても、被告人の自白のほかに、補強証拠が必要である。\nウ．自白以外の補強証拠によって、既に犯罪の客観的事実が認められ得る場合においては、犯意\nや知情といった犯罪の主観面について、自白が唯一の証拠であっても差し支えない。\nエ．自白以外の補強証拠によって、犯罪が架空のものではなく、現実に行われたものであること\nが証明される場合においても、被告人の自白した犯罪が被告人によって行われたという、犯\n罪と被告人との結び付きについては、補強証拠が必要である。\nオ．補強証拠の証明力については、自白と補強証拠とが相まって犯罪構成要件たる事実を総体的\nに認定することができればそれで足り、補強証拠だけでその事実を立証できる程度の証明力\nまでは必要ない。",
