    "question": "動産の引渡しに関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組み\n合わせたものは、後記1から5までのうちどれか。\nア．Ａがその所有する絵画甲をＢに預けたままＣに売却した場合において、ＡがＢに対して以後\nＣのために甲を占有すべきことを命じ、Ｂがこれを承諾したときは、Ｃは、甲の所有権の取得\nを第三者に対抗することができる。\nイ．Ａはその所有する登録済みの自動車甲をＢに売却して現実に引き渡したが、登録名義はＡの\nままであった。その後、Ａが甲をＣに売却し、登録名義をＣに移転した場合、Ｂは、甲の所有\n権の取得をＣに対抗することができる。\nウ．Ａは、その所有する絵画甲をＢに売却したが、甲の占有を継続し、以後Ｂのために占有する\n意思を表示した。その後、ＡはＢへの売却の事実を知っているＣに甲を売却し、現実に引き渡\nした。この場合、Ｃは、甲の所有権の取得をＢに対抗することができる。\nエ．Ａはその所有する絵画甲をＢに預けていたが、Ｂは、Ａに無断で、Ｂが甲の所有者であると\n過失なく信じているＣに甲を売却した。Ｂは甲の占有を継続し、以後Ｃのために占有する意思\nを表示した。その後ＡがＢから甲の返還を受けた場合、ＣはＡに対し、所有権に基づいて甲の\n引渡しを請求することができない。\nオ．Ａからその所有する絵画甲を預かり占有していたＢが、Ａから甲を購入した場合において、\n占有をＢに移転する旨の意思表示がＡＢ間でされたときは、Ｂは、甲の所有権の取得を第三者\nに対抗することができる。",
