    "question": "Ａ株式会社（以下「Ａ社」という。）の支配株主であるＢ株式会社（以下「Ｂ社」という。）は、\nＡ社の少数株主Ｃらの個別の承諾を得ることなく、Ａ社を完全子会社にしたいと考え、そのための\n手法を検討している。次のアからオまでの各記述のうち、誤っているものを組み合わせたものは、\n後記1から5までのうちどれか。\nア．株式の併合、全部取得条項付種類株式の取得及び特別支配株主の株式等売渡請求のいずれの\n手法を用いる場合も、Ａ社において株主総会の特別決議が必要である。\nイ．株式の併合又は全部取得条項付種類株式の取得の手法を用いる場合において、一株に満たな\nい端数の処理として、その端数の合計数に相当する数の株式を裁判所の許可を得て競売以外の\n方法により売却するためには、Ａ社の取締役の全員の同意を得る必要がある。\nウ．特別支配株主の株式等売渡請求の手法を用いる場合には、Ａ社の新株予約権についても売り\n渡すことを請求することができるが、株式の併合又は全部取得条項付種類株式の取得の手法を\n用いる場合には、Ａ社の新株予約権に取得条項が定められていない限り、その新株予約権を当\n然には取得することができない。\nエ．Ｂ社がＡ社の総株主の議決権の10分の7を有し、Ｄ株式会社（Ｂ社がその総株主の議決権\nの3分の2を有している。）がＡ社の総株主の議決権の10分の2を有しているときは、Ｂ社\nは、特別支配株主の株式等売渡請求の手法を用いることができる。\nオ．Ｂ社は、Ａ社との間で株式交換契約を締結し、Ｃらに対価として金銭又はＢ社の株式を交付\nすることによって、Ｃらの有するＡ社の株式を取得することができる。",
