    "question": "株券に関する次のアからオまでの各記述のうち、誤っているものを組み合わせたものは、後記1\nから5までのうちどれか。\nア．判例の趣旨によれば、株券としての効力が発生するのは、株式会社が会社法所定の形式を具\n備した文書を作成した時ではなく、当該文書を株主に交付した時である。\nイ．一部の種類の株式についてのみ譲渡制限がある株式会社は、株主から請求があるまでは、株\n券を発行しないことができる。\nウ．株主は、株式会社に対し、株券の所持を希望しない旨を申し出ることができ、当該株主が所\n持していた株券は、当該株主が当該株券を当該株式会社に提出した時に無効となる。\nエ．株券喪失登録がされた株券は、その登録が抹消された場合又は株式会社が株券発行会社でな\nくなることにより株券が無効となった場合を除き、株券喪失登録日の翌日から起算して1年を\n経過した日に無効となる。\nオ．株式会社がその株式に係る株券を発行する旨の定款の定めを廃止する定款変更をしたときは、\n当該株式会社の株券は、株主が株券を当該株式会社に提出しなくても、当該定款変更がその効\n力を生ずる日に無効となる。",
