    "question": "取締役会設置会社の取締役に関する次のアからオまでの各記述のうち、誤っているものを組み合\nわせたものは、後記1から5までのうちどれか。\nア．判例の趣旨によれば、会社法上の公開会社でない株式会社において、取締役会の決議による\nほか株主総会の決議によって代表取締役を定めることも、その旨の定款の定めがあれば、許さ\nれる。\nイ．代表取締役は、自己の職務の執行の状況の取締役会への報告につき、6か月に1回、取締役\nの全員に対してその状況を通知することをもって、取締役会への報告を省略することも、その\n旨の定款の定めがあれば、許される。\nウ．判例の趣旨によれば、取締役会を構成する取締役は、取締役会に上程された事柄について監\n視するにとどまらず、代表取締役による会社の業務執行一般につき、これを監視する職務を有\nする。\nエ．判例の趣旨によれば、取締役は、株主総会の決議によって当該取締役の報酬額が具体的に定\nめられた場合には、その後の株主総会によってその報酬を無報酬に変更する旨の決議がされた\nとしても、その変更に同意しない限り、報酬請求権を失わない。\nオ．取締役会の決議に反対した取締役は、自己が反対したことを明記していない議事録に異議を\nとどめないで署名又は記名押印した場合には、当該決議に賛成したものとみなされる。",
