    "question": "大会社における取締役及び取締役会に関する次のアからオまでの各記述のうち、正しいものを組\nみ合わせたものは、後記1から5までのうちどれか。\nア．監査等委員会設置会社における監査等委員である取締役の任期は、選任後2年以内に終了す\nる事業年度のうち最終のものに関する定時株主総会の終結の時までであり、定款又は株主総会\nの決議によって、その任期を短縮することはできない。\nイ．監査等委員会設置会社及び指名委員会等設置会社においては、社外取締役を選任することが\n義務付けられるが、監査役会設置会社においては、社外監査役を選任することが義務付けられ\nるものの、社外取締役の選任が義務付けられることはない。\nウ．取締役会を招集する取締役が定款又は取締役会で定められている場合でも、監査等委員会が\n選定する監査等委員又は監査委員会が選定する監査委員は、取締役会を招集することができる。\nエ．監査等委員は、監査等委員会設置会社の取締役会において、監査委員は、指名委員会等設置\n会社の取締役会において、それぞれ意見を述べることができるが、監査役は、取締役ではない\nから、監査役会設置会社の取締役会において意見を述べることができない。\nオ．監査役会設置会社及び監査等委員会設置会社の取締役会は、株式会社の業務並びに当該株式\n会社及びその子会社から成る企業集団の業務の適正を確保するために必要なものとして法務省\n令で定める体制の整備に係る決定を取締役に委任することができないが、指名委員会等設置会\n社の取締役会は、当該決定を執行役に委任することができる。",
