    "label": "第22問",
    "question": "取締役会設置会社（監査等委員会設置会社を除く。）の取締役の当該会社に対する損害賠償責任\nに関する次のアからオまでの各記述のうち、正しいものを組み合わせたものは、後記1から5まで\nのうちどれか。\nア．取締役が自己又は第三者のために当該会社と取引をした場合において、当該取引によって当\n該会社に損害が生じたときは、当該取締役は、取締役会において、当該取引につき重要な事実\nを開示し、その承認を受けていたとしても、取締役の任務を怠ったものと推定される。\nイ．取締役が自己又は第三者のために当該会社の事業の部類に属する取引をした場合において、\n当該取引によって当該会社に損害が生じたときは、当該取締役は、取締役会において、当該取\n引につき重要な事実を開示し、その承認を受けていたとしても、取締役の任務を怠ったものと\n推定される。\nウ．取締役が自己又は第三者のために当該会社と取引をした場合において、当該取締役が、取締\n役会において、当該取引につき重要な事実を開示せず、その承認を受けていなかったときは、\n当該取引によって当該取締役又は当該第三者が得た利益の額は、当該取締役の任務懈怠によっ\nて生じた損害の額と推定される。\nエ．取締役が自己又は第三者のために当該会社と取引をした場合において、当該取引によって当\n該会社に損害が生じたときは、当該取締役又は当該第三者と当該取引をすることを決定した当\n該会社の代表取締役は、任務を怠ったことが当該代表取締役の責めに帰することができない事\n由によるものであることを証明することにより、その責任を免れることができる。\nオ．当該会社が取締役の債務の保証をすることその他取締役以外の者との間において当該会社と\n取締役との利益が相反する取引をした場合において、当該取引によって当該会社に損害が生じ\nたときは、当該取締役は、任務を怠ったことが当該取締役の責めに帰することができない事由\nによるものであることを証明しても、その責任を免れることができない。",
