    "subject": "商法",
    "label": "第26問",
    "question": "株式会社の解散及び清算に関する次のアからオまでの各記述のうち、誤っているものを組み合わ\nせたものは、後記1から5までのうちどれか。\nア．清算株式会社の清算人については、定款で定める者及び株主総会の決議によって選任された\n者がいない場合には、当該会社に取締役がいるときであっても、利害関係人の申立てにより、\n裁判所が選任する。\nイ．清算人は、清算株式会社の財産がその債務を完済するのに足りないことが明らかになったと\nきは、直ちに破産手続開始の申立てをしなければならない。\nウ．清算人は、清算人会の承認を受けた決算報告を株主総会に提出してその承認を受けた場合に\nは、その職務の執行に関し不正の行為があったときを除き、任務を怠ったことによる損害賠償\nの責任を免除されたものとみなされる。\nエ．代表清算人は、清算株式会社の本店の所在地における清算結了の登記の時から10年間、当\n該会社の帳簿を保存しなければならない。\nオ．株式会社は、株主総会の決議によって解散した時に消滅する。",
