    "label": "第27問",
    "question": "営業又は事業の譲渡に関する次のアからオまでの各記述のうち、正しいものを組み合わせたもの\nは、後記1から5までのうちどれか。\nア．営業又は事業の譲渡の効果として、特段の手続を要することなく、営業又は事業を構成する\n資産及び債権債務は譲渡人から譲受人に当然に移転する。\nイ．判例の趣旨によれば、単なる事業用財産の譲渡は、たとえそれが譲渡会社に重大な影響を及\nぼすようなものであっても事業の譲渡に該当しない。\nウ．営業又は事業の譲渡が行われた場合に生じる譲渡人の競業避止義務は、譲渡人と譲受人との\n間の合意によってもこれを免除することはできない。\nエ．営業又は事業の譲渡人が、譲受人に承継されない債務の債権者を害することを知って営業又\nは事業を譲渡し、当該譲受人が、当該譲渡の効力が生じた時までに当該債権者を害することを\n知っていた場合には、当該譲受人が当該譲渡人の商号を続用しないときであっても、当該債権\n者は、当該譲受人に対し、承継した財産の価額を限度として、当該債務の履行の請求をするこ\nとができる。\nオ．判例の趣旨によれば、預託金会員制のゴルフクラブが設けられているゴルフ場の営業又は事\n業の譲受人が、当該ゴルフクラブの名称を続用しており、当該ゴルフクラブの名称が当該ゴル\nフ場の営業又は事業の主体を表示するものである場合であっても、当該譲受人は、譲渡人の商\n号を続用していない限り、当該ゴルフクラブの会員が当該譲渡人に交付した預託金の返還義務\nを負わない。",
