    "question": "代理商、仲立人及び問屋に関する次のアからオまでの各記述のうち、誤っているものを組み合わ\nせたものは、後記1から5までのうちどれか。\nア．商人から物品の販売又はその媒介の委託を受けた代理商は、委託を受けた事項に関する一切\nの裁判外の行為をする権限を有する。\nイ．代理商は、商人のために取引の代理又は媒介をしたときは、遅滞なく、その商人に対して、\nその旨の通知を発しなければならない。\nウ．仲立人は、当事者の一方の氏名又は名称をその相手方に示さなかったときは、当該相手方に\n対して自ら履行する責任を負う。\nエ．問屋は、別段の意思表示がない限り、販売又は買入れにより生じた債権が弁済期にあるとき\nは、その弁済を受けるまで、委託者のために占有する物又は有価証券を留置することができる。\nオ．問屋は、委託者の許可を得ない限り、自己又は第三者のために、委託者の営業又は事業の部\n類に属する取引をすることができない。",
