    "question": "約束手形及び小切手に関する次のアからオまでの各記述のうち、正しいものを組み合わせたもの\nは、後記1から5までのうちどれか。\nア．約束手形の振出人は、適法な所持人に対して手形金を支払う手形法上の義務を負うが、小切\n手の支払人は、支払保証をしていない限り、適法な所持人に対して小切手金を支払う小切手法\n上の義務を負わない。\nイ．約束手形が手形要件の一部を欠く場合は白地手形として有効になり得るが、小切手が小切手\n要件の一部を欠く場合は白地小切手として有効になることはない。\nウ．約束手形及び小切手は、いずれも満期として一覧後定期払及び日附後定期払のいずれかを選\n択することができる。\nエ．小切手は支払委託に条件を付すことができるが、約束手形は手形金を支払う旨の約束に条件\nを付すことはできない。\nオ．小切手は記名式でない方法により振り出すことができる。",
