    "question": "裏書の連続に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組み合\nわせたものは、後記1から5までのうちどれか。\nア．裏書の連続が欠ける約束手形の所持人も、裏書の連続が欠ける部分につき、実質的な権利移\n転の事実により自己の権利を証明すれば、手形上の権利を行使することができる。\nイ．約束手形の受取人欄に「法務花子」という記載があり、第一裏書人欄に法務花子の通称であ\nる「司法華子」という署名及びその住所の記載がある場合には、当該約束手形には裏書の連続\nがある。\nウ．約束手形の最後の裏書が白地式裏書であり、それより前の裏書が連続している場合には、当\n該約束手形の所持人は権利者と推定される。\nエ．約束手形の受取人欄に「Ａ」という記載、第一裏書人欄に「Ａ」という署名及びその住所の\n記載、第一被裏書人欄に「Ｂ」の記載、第二裏書人欄に「Ｃ」という署名及びその住所の記載、\n第二被裏書人欄に「Ｄ」の記載があるが、第一被裏書人欄の「Ｂ」の記載が抹消された場合に\nは、その抹消が権限のある者によってされたことを所持人が証明した場合に限り、第一裏書は\n白地式裏書となり、当該約束手形には裏書の連続があるものとされる。\nオ．約束手形の受取人欄に「Ａ株式会社 法務太郎 支店長」という記載があり、第一裏書人欄に\n「法務太郎」という署名及びその住所の記載がある場合には、当該約束手形に裏書の連続があ\nるとはいえない。",
