    "label": "第33問",
    "question": "既判力に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正しいものを組み合わせ\nたものは、後記1から5までのうちどれか。\nア．ＸがＹに対して取得時効による所有権取得を主張して提起した甲土地の所有権確認を求め\nる訴え（前訴）について請求を棄却する判決が確定した後、ＸがＹに対して甲土地の共有持\n分権確認を求める訴え（後訴）を提起した場合に、後訴裁判所が、前訴基準時前の相続によ\nる共有持分権の取得を理由としてＸの請求を認容することは、前訴の確定判決の既判力に抵\n触しない。\nイ．ＸがＹに対して提起した500万円の貸金の返還を求める訴え（前訴）について、Ｙによ\nる限定承認の抗弁を容れ、Ｙに対して相続によって得た財産の限度で500万円の支払を命\nずる判決が確定した後、ＸがＹに対して相続財産の範囲にかかわらず前記貸金の返還を求め\nる訴え（後訴）を提起した場合に、後訴裁判所が、前訴基準時前の法定単純承認事由に基づ\nき、Ｙに対して相続財産の範囲にかかわらず500万円の支払を命ずることは、前訴の確定\n判決の既判力に抵触し、許されない。\nウ．ＸがＹに対して総額1000万円のうち200万円の支払を求めることを明示した上で提\n起した貸金の返還を求める訴え（前訴）について弁済を理由として請求を棄却する判決が確\n定した後、ＸがＹに対して前記貸金の残額800万円の支払を求める訴え（後訴）を提起し\nた場合に、後訴裁判所が、Ｘの請求を認容することは、前訴の確定判決の既判力に抵触しな\nい。\nエ．ＸがＹに対して提起した所有権に基づく甲建物に係るＹ名義の所有権保存登記抹消登記手\n続を求める訴え（前訴）について請求を認容する判決が確定した後、ＹがＸに対して甲建物\nの所有権確認を求める訴え（後訴）を提起した場合に、後訴裁判所が、前訴基準時前の相続\nによる所有権取得を理由にＹの請求を認容することは、前訴の確定判決の既判力に抵触し、\n許されない。\nオ．ＸのＹに対する甲債権に係る500万円の支払請求訴訟（前訴）において、Ｙが800万\n円の乙債権による相殺の抗弁を提出したところ、裁判所は、甲債権、乙債権双方とも全額認\nめられ、相殺により対当額で消滅したとの理由で、Ｘの請求を棄却する判決をし、同判決は\n確定した。その後、Ｙが、乙債権のうち前訴で対当額による相殺に供しなかった300万円\nの支払を求める訴え（後訴）を提起した場合に、後訴裁判所が、前訴基準時前に乙債権は消\n滅していたという理由でＹの請求を棄却することは、前訴の確定判決の既判力に抵触しない。",
