    "question": "直接主義に関わる手続についての次のアからオまでの各記述のうち、判例の趣旨に照らし誤って\nいるものを組み合わせたものは、後記1から5までのうちどれか。\nア．裁判官が代わり、当事者が従前の口頭弁論の結果を陳述する場合に、当事者の一方が欠席\nしたときは、出頭した他方当事者だけではこの陳述をすることができない。\nイ．控訴審において、当事者は、第一審における口頭弁論の結果を陳述しなければならない。\nウ．大規模訴訟（当事者が著しく多数で、かつ、尋問すべき証人又は当事者本人が著しく多数\nである訴訟）に係る事件について、合議体である受訴裁判所は、当事者に異議がないときは、\n裁判所内において受命裁判官に証人尋問をさせることができる。\nエ．検証は、受訴裁判所が相当と認めるときは、検証物の所在地を管轄する地方裁判所又は簡\n易裁判所に嘱託して、受託裁判官に裁判所外において実施させることができる 。\nオ．裁判官が単独で審理する事件について、その裁判官を含む合議体に審理が移行した場合に\nは、当事者は従前の口頭弁論の結果を陳述する必要がない。",
