    "subject": "民事訴訟法",
    "label": "第43問",
    "question": "裁判によらない訴訟の完結に関する次のアからオまでの各記述のうち、判例の趣旨に照らし正し\nいものを組み合わせたものは、後記1から5までのうちどれか。\nア．原告が、被告の脅迫により訴えを取り下げたとしても、当該訴えの取下げは有効である。\nイ．被告が本案について答弁書を提出した後、原告が訴えの取下書を提出し、被告がこれに対す\nる同意を確定的に拒絶した場合には、後に被告が改めて同意をしても、当該訴えの取下げは\n効力を生じない。\nウ．訴訟上の和解が成立した場合には、和解の当事者は、その和解の内容である私法上の契約に\n係る意思表示の重要な部分に錯誤があったとして当該和解の効力を争うことはできない。\nエ．訴訟上の和解によって訴訟が終了したが、その後その和解の内容である私法上の契約が債務\n不履行により解除されるに至ったとしても、そのことによっては、一旦終了した訴訟は復活\nしない。\nオ．原告が被告に対し証書真否確認の訴えを提起した場合において、確認の対象となる文書が、\n法律関係を証する書面に該当しないものでも、被告が口頭弁論の期日において原告の請求を\n認諾する旨の陳述をし、それが調書に記載されたときは、当該訴訟は終了する。",
