    "label": "第44問",
    "question": "簡易裁判所における訴訟手続に関する次のアからオまでの各記述のうち、誤っているものを組み\n合わせたものは、後記1から5までのうちどれか。\nア．簡易裁判所は、相当と認める場合であっても、当事者に異議があるときは、証人の尋問に\n代えて、書面の提出をさせることはできない。\nイ．簡易裁判所の判決書に事実及び理由を記載するには、請求の趣旨及び原因の要旨に加え、\n請求の原因の有無と、請求を排斥する理由である抗弁の要旨を表示すれば足りる。\nウ．簡易裁判所は、金銭の支払の請求を目的とする訴えにつき、被告が口頭弁論において原告\nの主張した事実を全て争わず、その他何らの防御の方法をも提出しない場合において、相当\nと認めるときは、原告の意見を聴いた上で、当該請求に係る金銭の支払について分割払の定\nめをして、当該金銭の支払を命ずる決定をすることができる。\nエ．原告が被告に対して50万円の支払を求める訴えを簡易裁判所に提起した後に、被告が原\n告に200万円の支払を求める反訴を提起した場合には、簡易裁判所は、職権で、本訴及び\n反訴を地方裁判所に移送しなければならない。\nオ．簡易裁判所は、訴訟の目的の価額が100万円である不動産明渡請求訴訟について、被告\nが本案について弁論をする前に移送の申立てをした場合には、当該訴訟を不動産の所在地を\n管轄する地方裁判所に移送しなければならない。",
