    "label": "第45問",
    "question": "控訴に関する次のアからオまでの各記述のうち、正しいものを組み合わせたものは、後記1から\n5までのうちどれか。\nア．控訴の提起は、判決書又は判決書に代わる調書の送達を受けた日から2週間の不変期間内に、\n控訴状を控訴裁判所に提出してしなければならない。\nイ．原告が貸金の返還請求と不法行為に基づく損害賠償請求とを併合して提起した訴えに係る訴\n訟において、第一審裁判所が原告の請求のうち貸金の返還請求を認容し、その余の請求を棄\n却する判決をしたところ、被告のみが自らの敗訴部分につき控訴を提起した場合には、第一\n審判決のうち不法行為に基づく損害賠償請求に係る部分は、控訴期間の満了に伴い確定する。\nウ．控訴人が、控訴状に控訴理由を記載せず、控訴の提起後50日以内に控訴理由書を控訴裁判\n所に提出しなかった場合には、当該控訴は不適法なものとして却下される。\nエ．原告が貸金500万円の返還請求をした訴訟において、被告が500万円の弁済の抗弁と消\n滅時効の抗弁を主張したところ、第一審裁判所が弁済の抗弁を認めて原告の請求を全て棄却\nする判決をし、原告が控訴を提起した場合において、控訴裁判所は、500万円の弁済の事\n実は認められないが、貸金債権全額について消滅時効が完成したという心証を抱いたときは、\n当該控訴を棄却しなければならない。\nオ．原告が貸金800万円の返還請求をした訴訟において、第一審裁判所が原告の請求のうち5\n00万円の返還請求を認容し、その余の請求を棄却する判決をしたところ、原告が控訴期間\n内に控訴を提起し、その後、被告が自らの控訴期間内に附帯控訴を提起した場合に、控訴人\n兼附帯被控訴人が控訴審の終局判決前に控訴を取り下げたときは、当該附帯控訴は、控訴期\n間以外の控訴の要件も備える限り、独立した控訴とみなされる。",
