    "question": "私人間における人権保障に関する次のアからウまでの各記述について，最高裁判所の判例の趣旨\nに照らして，それぞれ正しい場合には1を，誤っている場合には2を選びなさい。（解答欄は，ア\nからウの順にから）\nア．企業者は，憲法第22条，第29条等において経済活動の自由の一環として契約締結の自由\nを保障されているので，特定の思想，信条を有する者をそのゆえをもって雇い入れることを拒\nんでも違法ではない。それゆえ，企業者が，労働者の採否決定に際し，労働者の思想，信条を\n調査したり，その者から思想，信条自体の申告を求めることも，公序良俗に反しない。\nイ．大学は，学生の教育と学術の研究を目的とする公共的な施設であり，その設置目的を達成す\nるために必要な事項を学則等により一方的に制定し，これによって在学する学生を規律する包\n括的権能を有する。それゆえ，比較的保守的な校風を有する私立大学が，学内外を問わず学生\nの政治的活動につきかなり広範な規律を及ぼしても，これをもって直ちに社会通念上学生の自\n由に対する不合理な制限であるということはできない。\nウ．労働組合の活動に対する組合員の協力義務の範囲は，問題とされている具体的な組合活動の\n内容・性質，組合員に求められる協力の内容・程度・態様等を比較考量し，多数決原理に基づ\nく組合活動の実効性と組合員個人の基本的利益の調和という観点から，合理的な限定を加えら\nれるべきである。それゆえ，組合員は，組合が支援する公職選挙候補者が所属する政党への寄\n付のために徴収する臨時組合費について納入義務を負わない。",
