    "question": "行政上の即時強制に関する教員と学生による以下の対話中の次のアからエまでの【 】内の各記\n述について，法令又は最高裁判所の判例に照らし，それぞれ正しい場合には1を，誤っている場合\nには2を選びなさい。（解答欄は，アからエの順にから）\n教員：即時強制は，行政上の目的を達成するために国民の身体又は財産に対して加えられる行政\n主体による実力行使であるといわれることがありますが，このような即時強制としての実\n力行使の例としてはどのようなものがありますか。\n学生：例えば，（ア）【消火活動のための土地の使用，感染症の病原体に汚染された場所の交通制\n限・遮断，警察官が現行犯逮捕をする際の武器の使用】等が挙げられます。\n教員：即時強制については，実力行使を伴う強制執行の一手段である直接強制との類似性が指摘\nされていますが，両者はどのような点が異なるのでしょうか。\n学生：（イ）【直接強制では，相手方に義務を賦課する行為が実力行使に先行しますが，即時強制\nでは，緊急性に応じて，義務を賦課する行為が先行する場合と，これが先行することなく\n実力行使がされる場合の両者が含まれる点】が異なります。\n教員：公務員である鉄道公安職員が，鉄道施設に立ち入り，座り込むなどした労働組合員を実力\nで退去させた事案に関する最高裁判所大法廷判決の多数意見は，当該退去に係る即時強制\nの適法性を肯定したものと理解されています。多数意見は即時強制の適法性をどのような\n理由で肯定したのでしょうか。\n学生：多数意見は，鉄道公安職員による強制的な退去行為について，（ウ）【危険が切迫する等や\nむを得ない事情が認められる場合には，法律による明文の根拠がなくても，具体的事情\nに応じて必要最小限度の強制力を用いることができる】として適法性を肯定しました。\n教員：即時強制の実力行使により国民の身体や財産は大きな影響を受けることがありますが，違\n法な即時強制がなされるおそれがある場合の事前の救済手段としては，どのようなものが\nありますか。\n学生：抗告訴訟による事前の救済手段としては，（エ）【即時強制が行われる前に差止めの訴えを\n提起することができます。】\n- 10 -",
