    "question": "国家賠償法に関する次のアからウまでの各記述について，最高裁判所の判例に照らし，正しいも\nのに○，誤っているものに×を付した場合の組合せを，後記1から8までの中から選びなさい。（解\n答欄は，）\nア．憲法第17条は，国又は公共団体が公務員のどのような行為によりいかなる要件で損害賠償\n責任を負うかを立法府の政策判断に委ねたものであるから，公務員の不法行為による国又は\n公共団体の損害賠償責任を免除し，又は制限する内容の法律の規定が同条に違反するとして，\n無効とされることはない。\nイ．国家賠償法第2条第1項の営造物責任に関し，同法第3条第1項の「費用を負担する者」に\nは，当該営造物の設置費用につき法律上負担義務を負う者だけでなく，この者と同等又はこ\nれに近い設置費用を負担し，実質的にこの者と当該営造物による事業を共同して執行してい\nると認められる者であって，当該営造物の瑕疵による危険を効果的に防止し得る者も含まれ\nる。\nウ．税務署長のする所得税の更正は，所得金額を過大に認定していた場合であっても，当該税務\n署長において職務上通常尽くすべき注意義務を尽くすことなく漫然と更正をしたと認め得る\nような事情がない限り，国家賠償法第1条第1項にいう違法があったとの評価を受けない。\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
