    "year_label": "R3",
    "subject": "刑法",
    "label": "第4問",
    "question": "名誉毀損罪及び侮辱罪に関する次のアからオまでの各記述を判例の立場に従って検討した場合，\n正しいものの組合せは，後記1から5までのうちどれか。（解答欄は，）\nア．事実を摘示せずに公然と人を侮辱することを教唆した者に，侮辱教唆罪が成立することはな\nい。\nイ．弁護人が被告人の利益を擁護するためにした弁護活動であれば，それが名誉毀損罪の構成要\n件に該当する行為であっても，違法性が阻却されるため，名誉毀損罪が成立することはない。\nウ．人の社会的評価を害するに足りる事実を公然と摘示したとしても，その人の社会的評価が現\n実に害されていない場合，刑法第230条第1項にいう「人の名誉を毀損した」とはいえない\nため，名誉毀損罪は成立しない。\nエ．私人の私生活の行状であっても，その携わる社会的活動の性質及びこれを通じて社会に及ぼ\nす影響力の程度等によっては，刑法第230条の2第1項にいう「公共の利害に関する事実」\nに当たる場合がある。\nオ．インターネットを利用して公然と虚偽の事実を摘示し，人の名誉を毀損した場合，他の表現\n手段を利用する場合と異なり，インターネットの個人利用者に要求される水準を満たす調査に\nよって摘示した事実が真実か否かを確かめることなく発信したときに限り名誉毀損罪が成立す\nる。",
