    "id": "r3_keipo_06",
    "year": 2021,
    "year_label": "R3",
    "subject": "刑法",
    "label": "第5問",
    "question": "学生Ａ，Ｂ及びＣは，次の【事例】における甲の罪責について，後記【会話】のとおり議論して\nいる。【会話】中の①から⑤までの（ ）内から適切な語句を選んだ場合，正しいものの組合せは，\n後記1から5までのうちどれか。（解答欄は，）\n【事 例】\n甲は，乙を殺せとの幻聴に従い，殺意をもって，乙の腹部を包丁で刺して死亡させた。甲の精\n神鑑定を行った精神科医丙は，上記犯行当時，甲が重篤な統合失調症を患っており，これに基づ\nく幻覚妄想に支配された状態にあったと鑑定した。\n【会 話】\n学生Ａ．甲の責任能力についてはどのように考えていくべきだろうか。いくら精神科医であって\nも，統合失調症等の重い精神障害が①（ａ．生物学的要素・ｂ．心理学的要素）に与えた\n影響など分からないのではないかな。\n学生Ｂ．確かに，精神科医の中でも，Ａ君の見解，つまり不可知論を採用する方もいるようだね。\nでも，判例はそのように考えていないんだ。判例による心神喪失の定義が，精神の障害に\nより，事物の理非善悪を弁識する能力が欠如し，②（ｃ．又は・ｄ．かつ），この弁識に\n従って行動する能力が欠如している場合とされていることからも分かるよね。\n学生Ｃ．では，精神障害による影響の程度は，誰がどのようにして判断するのだろうか。特に，\n専門家である医師が述べている意見については，どう考えるべきなのかな。丙医師の意見\nに従えば，心神喪失になるのではないかと思うんだけど。\n学生Ｂ．判例は，生物学的要素である精神障害の有無及び程度並びにこれが心理学的要素に与え\nた影響の有無及び程度については，その診断が③（ｅ．臨床精神医学の本分・ｆ．非医学\n的知見も加味した総合的判断）であることからすれば，専門家たる精神医学者の意見が鑑\n定等として証拠となっている場合には，④（ｇ．これを採用し得ない合理的な事情が認め\nられるのでない限り，その意見を十分に尊重して・ｈ．生物学的要素の判断に関する限り，\nその意見に従って）認定すべきであると判示しているね。もっとも，一方で判例は，被告\n人の精神状態が心神喪失・心神耗弱に該当するかは，⑤（ｉ．事実判断・ｊ．法律判断）\nであって，裁判所の専権事項であり，その前提となる生物学的要素・心理学的要素につい\nても，究極的には裁判所の判断に委ねられるべき問題であると判示しているね。",
    "question_no": 6,
