    "year_label": "R3",
    "subject": "刑法",
    "label": "第9問",
    "question": "緊急避難に関する次のアからオまでの各記述を判例の立場に従って検討した場合，正しいものの\n組合せは，後記1から5までのうちどれか。（解答欄は，）\nア．豪雨により稲苗が水に沈む危険が生じていたことから，排水のため他人の所有する下流の板\n堰を損壊した場合，「現在の危難」があるとは認められないので，緊急避難は成立しない。\nイ．警察官の適法な逮捕行為に対し，逮捕を免れるためには他に方法がなかったので，第三者を\n突き飛ばして逃走し，よって同人に傷害を負わせた場合，緊急避難が成立し得る。\nウ．頭に拳銃を突き付けられて，覚醒剤の自己使用を強要され，これを拒むことができず，自己\nに覚醒剤を注射して使用した場合，犯罪行為の強要の手段は「現在の危難」に当たらないので，\n緊急避難は成立しない。\nエ．吊橋が腐朽し，通行の際の揺れにより通行者の生命，身体等に危険が生じていたため，ダイ\nナマイトを使用して同吊橋を爆破したが，通行制限の強化等適当な手段，方法を講ずる余地が\nあった場合，同爆破行為は，「やむを得ずにした行為」とは認められないので，緊急避難は成\n立しない。\nオ．甲が飼い犬Ａ（時価30万円相当）を連れて山道を散歩中，乙が設置していた害獣駆除用の\n罠（時価3万円相当）にＡがかかり，その生命に危険が生じ，Ａを保護するためには他に方法\nがなかったので，その罠を損壊した場合，緊急避難が成立する（甲及び乙いずれにも過失がな\nかったものとする。）。",
