    "label": "第11問",
    "question": "因果関係に関する次のアからオまでの各記述を判例の立場に従って検討した場合，誤っているも\nのの個数を後記1から5までの中から選びなさい。（解答欄は，）\nア．甲は，他の共犯者5名と共に，約3時間にわたり，マンションの一室において，Ｖの頭部，\n腹部等を木刀で多数回殴打していたところ，これにより極度の恐怖感を抱いたＶが，同室から\n逃走し，甲らによる追跡から逃れるために，同マンション付近にある高速道路に進入し，疾走\nしてきた自動車に衝突され，死亡した。この場合，甲らの上記殴打行為とＶの死亡との間に，\n因果関係はない。\nイ．甲は，Ｖの頸部を包丁で刺突し，致命傷になり得る頸部刺創の傷害をＶに負わせたところ，\nＶは，病院で緊急手術を受けたため一命をとりとめ，引き続き安静な状態で治療を継続すれば\n数週間で退院することが可能となったが，安静にせず，病室内を歩き回ったことから治療の効\n果が上がらず，同頸部刺創に基づく血液循環障害による肝機能障害により死亡した。この場合，\n甲の上記刺突行為とＶの死亡との間に，因果関係はない。\nウ．甲は，Ｖの顔面を1回足で蹴ったところ，特殊な病気により脆弱となっていたＶの脳組織が\n崩壊してＶが死亡したが，当該病気の存在について，一般人は認識することができず，甲も認\n識していなかった。この場合，甲の上記足蹴り行為とＶの死亡との間に，因果関係はない。\nエ．甲は，医師資格のない柔道整復師であるところ，自己に全幅の信頼を寄せるＶから，風邪の\n治療について相談を持ち掛けられた際に，Ｖに対し，食事や水分補給を控える一方，発汗を促\nすという医学的に明らかに誤った治療法を繰り返して指示し，これに忠実に従ったＶが症状を\n悪化させ，脱水症状に陥り，死亡した。この場合，甲の上記指示行為とＶの死亡との間に，因\n果関係はない。\nオ．甲は，自動車を運転中，路上で過失により通行人Ｖに同車を衝突させてＶを同車の屋根に跳\nね上げ，意識を喪失したＶに気付かないまま，同車の運転を続けていたところ，同乗者がＶに\n気付き，走行中の同車の屋根からＶを引きずり降ろして路上に転落させ，Ｖは，頭部打撲に基\nづく脳くも膜下出血により死亡したが，これが同車との衝突の際に生じたものか，路上に転落\nした際に生じたものかは不明であった。この場合，甲の上記衝突行為とＶの死亡との間に，因\n果関係はない。",
