    "subject": "刑事訴訟法",
    "label": "第14問",
    "question": "警察官職務執行法上の職務質問に関する次のアからオまでの各記述のうち，判例に照らして正し\nいものは幾つあるか。後記1から6までのうちから選びなさい。（解答欄は，）\nア．警察官が，駐在所で職務質問中に突然逃げ出した相手方の後を，約130メートル追いかけ，\n背後からその腕に手をかけることは，職務質問を行うため相手方を停止させる行為として許さ\nれる場合がある。\nイ．警察官が，相手方の運転車両の窓から手を差し入れ，エンジンキーを回転してスイッチを切\nることは，職務質問を行うため相手方を停止させる行為として許される場合がある。\nウ．警察官が，相手方の運転車両の窓から手を差し入れ，エンジンキーを引き抜いて取り上げる\nことは，職務質問を行うため相手方を停止させる行為として許される場合がある。\nエ．警察官が，ホテル客室（ホテル内の通路に面して外ドアがあり，これを開けると内玄関に入\nることができ，そこにある内ドアを開けると客室に入る構造）の無施錠の外ドアを開けて内玄\n関に立ち入り，内ドア越しに客室内に向かって声をかけたところ，相手方が，内ドアを開けた\nが，警察官の姿を見て慌ててそれを閉めたのに対して，警察官が，内ドアを押し開け，内玄関\nと客室の境の敷居上辺りに足を踏み入れ，内ドアが閉められるのを防止することは，職務質問\nに付随する行為として許される場合がある。\nオ．警察官が，相手方の承諾を得ることなく，携行中の所持品であるバッグの施錠されていない\nチャックを開披し内部を一べつすることは，職務質問に付随する行為として許される場合があ\nる。",
