    "subject": "刑事訴訟法",
    "label": "第15問",
    "question": "逮捕・勾留に関する次のアからオまでの各記述のうち，正しいものの組合せは，後記1から5ま\nでのうちどれか。（解答欄は，）\nア．逮捕状を所持しないため被疑者にこれを示すことができない場合において，急速を要すると\nきは，被疑者に対し被疑事実の要旨及び令状が発せられている旨を告げて被疑者を逮捕するこ\nとができ，以後も被疑者に逮捕状を示す必要はない。\nイ．司法警察員は，逮捕状により被疑者を逮捕した場合には，留置の必要がないと思料するとき\nでも，これを釈放することなく，被疑者が身体を拘束された時から48時間以内に書類及び証\n拠物とともにこれを検察官に送致しなければならない。\nウ．窃盗の事実で逮捕した後に釈放した被疑者を同一の窃盗の事実で再び逮捕することが許され\nる場合もある。\nエ．検察官は，恐喝及び傷害の事実で逮捕した被疑者につき，その逮捕中に，同一の事実が強盗\n致傷罪に当たると疑うに足りる相当な理由が生じた場合には，強盗致傷罪で勾留を請求するこ\nとができる。\nオ．検察官は，逮捕した被疑者につき，逮捕中に公訴を提起することはできず，勾留を請求する\nか，又は釈放しなければならない。",
