    "year_label": "R3",
    "subject": "刑事訴訟法",
    "label": "第16問",
    "question": "次のⅠ及びⅡの【見解】は，刑事訴訟法第220条第1項第2号及び同条第3項において，逮捕\nの現場における令状によらない捜索差押えが認められている根拠に関する考え方を述べたものであ\nる。これらの【見解】に関する学生ＡないしＥの【発言】のうち，誤った発言をしている学生の組\n合せは，後記1から5までのうちどれか。（解答欄は，）\n【見解】\nⅠ．逮捕の現場には証拠の存在する蓋然性が一般的に高いので，合理的な証拠収集手段として認\nめられる。\nⅡ．逮捕者の身体の安全を図る必要があり，また，被逮捕者による証拠の隠滅を防ぐ必要がある\nために認められる。\n【発言】\n学生Ａ：見解Ⅰに立つと，被逮捕者が逮捕の現場から逃走した場合であっても，引き続きその現\n場の捜索が可能であると考えることができるね。\n学生Ｂ：見解Ⅰに立っても，見解Ⅱに立っても，差押えの対象は，逮捕の理由とされた被疑事実\nに関する証拠物に限られないことになるので，別途捜査中の他の事件に関する証拠物を偶\n然発見した場合，これを差し押さえることができるね。\n学生Ｃ：見解Ⅱに立つと，差押えの対象は，被逮捕者の身体及びその直接の支配下にある範囲の\n証拠物に限られると考えることができるね。\n学生Ｄ：見解Ⅱに立つと，見解Ⅰと異なり，逮捕の現場には証拠の存在する蓋然性が一般的に高\nいという前提は否定せざるを得ないね。\n学生Ｅ：見解Ⅱに立つと，同条第1項柱書の「逮捕する場合」の解釈については，現実に被疑者\nを逮捕することができる状況の存在が必要であると考えることができるし，見解Ⅰに立っ\nて同様に考えることもできるね。",
