    "question": "次のⅠ及びⅡの【見解】は，逮捕・勾留中の被疑者に，被疑事実に係る取調べのために出頭し，\n滞留する義務が認められるか否かという解釈問題に関するものである。後記【発言】は，学生Ａな\nいしＥが，Ⅰ又はⅡのいずれかの【見解】を採って意見を述べたものである。【見解】と【発言】\nを対応させた場合，その組合せとして最も適切なものは，後記1から6までのうちどれか。（解答\n欄は，）\n【見解】\nⅠ．前記義務が認められる。\nⅡ．前記義務は認められない。\n【発言】\n学生Ａ：私と異なる見解のように考えると，供述の義務はないといっても，実質的には供述を強\nいるのと異ならないので，黙秘権を侵すことになってしまうのではないでしょうか。\n学生Ｂ：私のように考えたとしても，直ちに被疑者からその意思に反して供述することを拒否す\nる自由を奪うことを意味するものでないことは明らかだと考えます。\n学生Ｃ：私が採る見解は，現行法が第一次的に当事者主義を採っており，被疑者も捜査機関と相\n対立する一方当事者であると考えられることと，より整合的だと考えます。\n学生Ｄ：逮捕・勾留は，将来の公判への出頭を確保するためのものであると考えると，私が採る\n見解とより整合性があると思います。\n学生Ｅ：私は，刑事訴訟法第198条第1項但書の「但し，被疑者は，逮捕又は勾留されている\n場合を除いては，出頭を拒み，又は出頭後，何時でも退去することができる。」という規\n定を反対解釈するのが相当だと思います。\n1．Ⅰ．学生Ａ 学生Ｃ 学生Ｄ Ⅱ．学生Ｂ 学生Ｅ\n2．Ⅰ．学生Ａ 学生Ｃ 学生Ｅ Ⅱ．学生Ｂ 学生Ｄ\n3．Ⅰ．学生Ａ 学生Ｄ Ⅱ．学生Ｂ 学生Ｃ 学生Ｅ\n4．Ⅰ．学生Ｂ 学生Ｄ 学生Ｅ Ⅱ．学生Ａ 学生Ｃ\n5．Ⅰ．学生Ｂ 学生Ｃ Ⅱ．学生Ａ 学生Ｄ 学生Ｅ\n6．Ⅰ．学生Ｂ 学生Ｅ Ⅱ．学生Ａ 学生Ｃ 学生Ｄ",
