    "question": "接見に関する次のアからオまでの各記述のうち，誤っているものの組合せは，後記1から5まで\nのうちどれか。ただし，判例がある場合には，それに照らして考えるものとする。（解答欄は，）\nア. 鑑定留置されている被疑者は，弁護人又は弁護人となろうとする者と立会人なくして接見す\nることができる。\nイ．弁護人又は弁護人となろうとする者と被疑者との逮捕直後の初回の接見については，被疑者\nの防御の準備のため特に重要であるから，捜査機関による接見の日時，場所及び時間の指定が\n許されることはない。\nウ．勾留されている被告人が同時に余罪の被疑者として勾留されている場合，検察官は，その余\n罪である被疑事件の捜査のため必要があるときは，被告事件について防御権の不当な制限にわ\nたらない限り，被告事件の弁護人と被告人との接見に関し，その日時，場所及び時間を指定す\nることができる。\nエ．弁護人は，検察官のした接見指定について，裁判所にその処分の取消し又は変更を請求する\nことはできない。\nオ．裁判所は，勾留されている被告人と弁護人又は弁護人となろうとする者以外の者との接見を\n禁じ，又は糧食を除く書類その他の物の授受を禁じ，若しくはこれを差し押えることができる。",
