    "label": "第19問",
    "question": "司法警察員から検察官への事件送致及び検察官の訴追裁量権に関する次のアからオまでの各記述\nのうち，正しいものに1を，誤っているものには2を選びなさい。（解答欄は，から）\nア．司法警察員は，犯罪の捜査をしたときは，例外なく，速やかに書類及び証拠物とともに事件\nを検察官に送致しなければならない。\nイ．刑事訴訟法では起訴独占主義が採られているため，起訴・不起訴について検察官の判断を一\n切経ることなく，事件が公訴提起されることはない。\nウ．刑法第177条（強制性交等）の罪及びその未遂罪について告訴又は告発をした者は，当該\n事件につき検察官のした公訴を提起しない処分に不服があるときは，刑事訴訟法に基づき，そ\nの検察官を指揮監督する検事正に当該処分の見直しを請求することができる。\nエ．検察審査会が，検察官の公訴を提起しない処分の当否に関し，起訴を相当とする議決をした\nときは，検察官は，当該議決に従って公訴を提起しなければならない。\nオ．告訴又は告発をした者は，当該事件につき検察官のした公訴を提起しない処分に不服がある\nときは，付審判請求をすることができるが，その対象事件には限定がない。",
