    "id": "r3_keipo_28",
    "year": 2021,
    "year_label": "R3",
    "subject": "刑事訴訟法",
    "label": "第22問",
    "question": "後記アからオまでの【記述】のうち，次に掲げる【判例】（住居侵入，窃盗，現住建造物等放火\n被告事件に係る最高裁判所平成24年9月7日第二小法廷判決・刑集66巻9号907頁）に整合\nしないものは幾つあるか。後記1から6までのうちから選びなさい。（解答欄は，）\n【判例】\n「前科も一つの事実であり，前科証拠（被告人の前科の存在を示す証拠）は，一般的には犯罪事\n実について，様々な面で証拠としての価値（自然的関連性）を有している。反面，前科，特に同種\n前科については，被告人の犯罪性向といった実証的根拠の乏しい人格評価につながりやすく，その\nために事実認定を誤らせるおそれがあり，また，これを回避し，同種前科の証明力を合理的な推論\nの範囲に限定するため，当事者が前科の内容に立ち入った攻撃防御を行う必要が生じるなど，その\n取調べに付随して争点が拡散するおそれもある。したがって，前科証拠は，単に証拠としての価値\nがあるかどうか，言い換えれば自然的関連性があるかどうかのみによって証拠能力の有無が決せら\nれるものではなく，前科証拠によって証明しようとする事実について，実証的根拠の乏しい人格評\n価によって誤った事実認定に至るおそれがないと認められるときに初めて証拠とすることが許され\nると解するべきである。本件のように，前科証拠を被告人と犯人の同一性の証明に用いる場合につ\nいていうならば，前科に係る犯罪事実が顕著な特徴を有し，かつ，それが起訴に係る犯罪事実と相\n当程度類似することから，それ自体で両者の犯人が同一であることを合理的に推認させるようなも\nのであって，初めて証拠として採用できるものというべきである。」\n【記述】\nア．前科証拠を用いて，被告人と起訴に係る事件の犯人の同一性を証明しようとする場合，当該\n前科証拠と証明すべき事実との間に自然的関連性があるかどうかのみによって，その証拠能力\nの有無が決せられるわけではない。\nイ．前科証拠を用いて，被告人に起訴に係る犯罪事実と同種の前科があるという事実から，起訴\nに係る事件の犯人が被告人であることを推認しようとする場合は，実証的根拠の乏しい人格評\n価につながりやすい。\nウ．前科証拠を用いて，起訴に係る事件の犯人が被告人であることを推認しようとする場合に伴\nう弊害には，訴訟の円滑な進行に支障をもたらすおそれがあることが含まれる。\nエ．前科証拠を用いて，被告人と起訴に係る事件の犯人の同一性を証明しようとする場合におい\nて，当該前科に係る犯罪事実の有する特徴が顕著なものではないため，その特徴が起訴に係る\n犯罪事実と相当程度類似していても，それ自体で両者の犯人が同一であることを合理的に推認\nさせるとはいえないときは，これを証拠として採用することはできない。\nオ．事実認定者が前科証拠に触れることに伴う弊害を軽視することは相当ではないから，裁判員\nの参加する合議体が審理する事件においては，前科証拠を証拠として採用することはできない。",
