    "year_label": "R3",
    "subject": "刑事訴訟法",
    "label": "第23問",
    "question": "次の【事例】について述べた後記アからオまでの【記述】のうち，正しいものの組合せは，後記\n1から5までのうちどれか。（解答欄は，）\n【事例】\n甲は，「令和2年12月5日午前1時頃，Ｈ市内のＩ公園内で，ゴルフクラブでＶを殴打して殺\nした。」との殺人の事実により，Ｈ地方裁判所に起訴された。公判において，犯行の目撃者Ａ，甲\nの妻Ｂ，甲の知人Ｃの証人尋問が，それぞれ実施された。\n【記述】\nア．Ａの，「話をしていた2人のうち1人が『甲，お前に貸した金を早く返せ。』と言うと，言い\n争いになり，その後，言われた方がもう一方に棒のようなものを振り下ろした。」旨の証言は，\n要証事実を「甲がＶに借金をしていたこと」とした場合，伝聞証拠に当たらない。\nイ．Ａの，「話をしていた2人のうち1人が『甲，お前に貸した金を早く返せ。』と言うと，言い\n争いになり，その後，言われた方がもう一方に棒のようなものを振り下ろした。」旨の証言は，\n要証事実を「犯人がＶから甲と呼ばれていたこと」とした場合，伝聞証拠に当たる。\nウ．Ｂの，「令和2年12月1日午後1時頃，自宅において，甲から『探していたゴルフクラブ\nを家の物置で見つけた。』と言われた。」旨の証言は，要証事実を「甲が犯行時点よりも前から\nゴルフクラブを所持していたこと」とした場合，伝聞証拠に当たる。\nエ．Ｂの，「令和2年12月8日午後3時頃，自宅において，甲から『3日前の午前1時頃，Ｈ\n市内のＩ公園で，Ｖをゴルフクラブで殴り殺した。』と言われた。」旨の証言は，要証事実を「Ｖ\nを殺したのが甲であったこと」とした場合，伝聞証拠に当たる。\nオ．Ｃの，「令和2年12月7日午後5時頃，甲から電話があり，『2日前の午前1時頃には，俺\nは自宅でテレビ番組を見ていた。』と言われた。」旨の証言は，要証事実を「Ｖが殺されたとき\n甲が自宅にいたこと」とした場合，伝聞証拠に当たらない。",
