    "subject": "刑事訴訟法",
    "label": "第24問",
    "question": "証人尋問に関する次のアからオまでの各記述のうち，誤っているものの組合せは，後記1から5\nまでのうちどれか。ただし，判例がある場合には，それに照らして考えるものとする。（解答欄は，\n）\nア．刑事訴訟規則は，書面又は物に関しその成立，同一性その他これに準ずる事項についてその\n書面又は物を示してする尋問は，裁判長の許可が必要であると定めている。\nイ．証人の供述を明確にするため，図面，写真，模型，装置等を利用して尋問する際，それらの\n図面等が証拠調べを終わったものでないときは，あらかじめ，相手方に閲覧する機会を与えな\nければならないが，相手方に異議がないときは，この限りでない。\nウ．刑事訴訟規則は，証人の記憶が明らかでない事項についてその記憶を喚起するため必要があ\nるときに示すことができる書面について，供述を録取した書面を条文上除外している。\nエ．証拠として採用されていない書面であっても，その書面を証人に示した尋問が行われて証人\n尋問調書に添付された場合にはその書面が証人尋問調書と一体になるから，その書面を証拠と\nして取り調べなくても，証言で引用されていない部分を含むその書面の全部を事実認定の用に\n供することができる。\nオ．証拠として採用されていない鑑定書であっても，鑑定書の作成者の証人尋問において，作成\nの真正を立証するために，その作成者欄の署名押印部分を証人に示して証人の署名押印である\nかを確認する尋問は許される。",
