    "subject": "刑事訴訟法",
    "label": "第26問",
    "question": "刑事事件の上告審に関する次のアからオまでの各記述のうち，正しいものの組合せは，後記1か\nら5までのうちどれか。（解答欄は，）\nア．憲法の違反があること又は憲法の解釈に誤りがあることは適法な上告理由となる。\nイ．単なる事実誤認は適法な上告理由に当たらないが，判決に影響を及ぼすべき重大な事実の誤\n認があることは適法な上告理由となる。\nウ．単なる量刑不当は適法な上告理由に当たらないが，刑の量定が甚しく不当で，原判決を破棄\nしなければ著しく正義に反すると認められることは適法な上告理由となる。\nエ．大審院の判例と相反する判断をしたことが適法な上告理由となることはない。\nオ．上告審は法律審であるが，上告裁判所である最高裁判所は，上告趣意書に包含された事項を\n調査するについて必要があるときは，検察官，被告人若しくは弁護人の請求により又は職権で\n事実の取調べをすることができる。",
