    "question": "物権的請求権に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っているものを\n組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．甲土地の所有者Ａは，Ｂが所有する乙土地上に甲土地のための通行地役権の設定を受けた。\nその後，Ｂが乙土地上に大型トラック丙を駐車してＡによる乙土地の通行を妨げた場合，Ａは，\nＢに対して通行地役権に基づき丙の撤去を請求することができる。\nイ．Ａ，Ｂ及びＣが甲土地を持分3分の1ずつで共有している場合，Ｃは単独で，甲土地を何の\n権原もなく占有するＤに対して甲土地の明渡しを請求することができない。\nウ．Ａは，Ｂが所有する甲土地上に何の権原もなく乙建物を建築し，その所有権保存登記がされ\nた。その後，Ａが乙建物をＣに売却して所有権を移転した場合，Ｃヘの所有権移転登記がされ\nていなくても，Ｂは，Ｃに対して所有権に基づき乙建物の収去を請求することができる。\nエ．Ａが所有する甲土地にＢのために抵当権が設定され，その登記がされた後，Ｃは，甲土地上\nにＡが所有する樹木を何の権原もなく伐採し始めた。この場合，Ｂは，被担保債権の弁済期前\nであっても，Ｃに対して伐採の禁止を請求することができる。\nオ．甲土地に設定された第一順位の抵当権の被担保債務が消滅したにもかかわらずその登記が抹\n消されていない場合，甲土地の第二順位の抵当権者は，第一順位の抵当権者に対してその登記\nの抹消を請求することができない。",
