    "question": "Ａは，自己の所有する甲土地を利用するため，Ｂ所有の乙土地の一部に通路を開設し，その通路\nを通行していた。この事例に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しい\nものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．Ａは，Ｂから通行地役権の設定を受けていたが，未登記であった。Ａによる通路の利用を認\n識していたものの通行地役権の存在は知らなかったＣがＢから乙土地を譲り受けた場合，Ａは，\nＣに通行地役権を対抗することができる。\nイ．ＡがＢから通行地役権の設定を受けていた場合において，その後，Ａがこの通路を全く通行\nしなくなったときは，Ａの地役権は，Ａが通路を通行した最後の時を起算点として消滅時効に\nかかる。\nウ．Ａは，Ｂから通行地役権の設定を受けずに通路を開設して通行していたが，Ｂはそのことを\n知りつつ黙認していた。この場合，Ａは，Ｂに対して通行の対価を支払っていなければ，通行\n地役権を時効取得することができない。\nエ．ＡがＢから通行地役権の設定を受けていた場合，Ａは，乙土地の通行を必要とするＣに対し，\n甲土地の所有権を譲渡することなく，その通行地役権のみを譲渡することができる。\nオ．Ａが甲土地の2分の1の持分をＣに譲渡して，Ａ及びＣが甲土地を共有するに至った場合に\nおいて，Ａが通行地役権を時効により取得したときは，Ｃも通行地役権を取得する。",
