    "question": "ＡがＢに賃貸しているＡ所有の甲建物にＣのための抵当権が設定され，その登記がされている。\nこの場合における抵当権に基づくＣの物上代位権の行使に関する次のアからオまでの各記述のう\nち，判例の趣旨に照らし誤っているものを組み合わせたものは，後記1から5までのうちどれか。\n（解答欄は，）\nア．Ｃのための抵当権の設定登記がされた後にＢがＡに対して金銭を貸し付け，その貸金債権の\n弁済期が到来した場合，ＡのＢに対する賃料債権についてＣが物上代位権を行使して差押えを\nした後であっても，Ｂは，Ａに対する貸金債権を自働債権とし，Ａの賃料債権を受働債権とす\nる相殺をもって，Ｃに対抗することができる。\nイ．ＡのＢに対する賃料債権についてＣが物上代位権を行使して差押えをした場合において，Ｂ\nがＣに賃料を支払わないままＡＢ間の賃貸借契約が終了し，Ｂが甲建物をＡに明け渡した。こ\nの場合において，ＢがＡにあらかじめ敷金を預託していたときは，Ｃが差し押さえた賃料債権\nは，敷金の充当によりその限度で消滅する。\nウ．Ｂが甲建物をＤに転貸した場合，Ｃは，ＢをＡと同視することが相当であるときを除き，Ｂ\nのＤに対する転貸賃料債権について物上代位権を行使することができる。\nエ．ＡのＢに対する賃料債権をＡの一般債権者Ｅが差し押さえて転付命令を取得し，その転付命\n令がＢに送達された後は，Ｃは，同一の債権を差し押さえて物上代位権を行使してＥに対抗す\nることができない。\nオ．ＡのＢに対する賃料債権をＡの一般債権者Ｅが差し押さえ，その差押命令がＢに送達された\n後に，ＡがＣのために甲建物に抵当権を設定し，その登記がされた場合，Ｃは，同一の債権を\n差し押さえて物上代位権を行使してＥに対抗することができない。",
