    "question": "ＡのＢに対する金銭債権（以下「甲債権」という。）とＢのＡに対する金銭債権（以下「乙債\n権」という。）との相殺に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいも\nのを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．甲債権と乙債権の両方の弁済期が到来した後，甲債権がＡからＣに譲渡され，その対抗要件\nが具備された。この場合において，Ｂは，ＣがＢのＣに対する金銭債権（丙債権）と甲債権と\nを相殺した後であっても，乙債権と甲債権との相殺をもってＣに対抗することができる。\nイ．乙債権は，Ａの債権者であるＤが甲債権を差し押さえた後に，Ｂが他人から譲り受けたもの\nであった。この場合，乙債権が差押え前の原因に基づいて生じたものであるとしても，Ｂは，\n乙債権と甲債権との相殺をもってＤに対抗することができない。\nウ．甲債権は，Ｂの悪意による不法行為に基づいて生じたＥのＢに対する損害賠償債権を，Ａが\nＥから譲り受けたものであった。この場合，Ｂは，乙債権と甲債権との相殺をもってＡに対抗\nすることができる。\nエ．甲債権の弁済期が到来した後に，Ａの債権者であるＦが甲債権を差し押さえた場合には，Ｂ\nは，差押え前に取得していた乙債権の弁済期到来前であっても，乙債権と甲債権との相殺をも\nってＦに対抗することができる。\nオ．Ａが甲債権をＧに譲渡し，その対抗要件が具備された後，Ｂが乙債権を取得した。この場合\nにおいて，Ｂは，乙債権が対抗要件具備時より前の原因に基づいてＡＢ間で生じた債権であっ\nても，乙債権と甲債権との相殺をもってＧに対抗することができない。",
