    "question": "寄託に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後記1\nから5までのうちどれか。（解答欄は，）\nア．寄託は，当事者の一方がある物を保管することを相手方に委託し，相手方がこれを承諾する\nことによって，その効力を生ずる。\nイ．受寄者は，寄託者の承諾を得なくても，やむを得ない事由があるときは，寄託物を第三者に\n保管させることができる。\nウ．受寄者は，寄託物について権利を主張する第三者から訴えを提起された場合には，寄託者が\n既にこれを知っているときを除き，遅滞なくその事実を寄託者に通知しなければならない。\nエ．当事者が寄託物の返還の時期を定めた場合には，寄託者は，その返還の時期が到来するまで\n寄託物の返還を請求することができない。\nオ．複数の者が寄託した物の種類及び品質が同一である場合には，受寄者は，各寄託者の承諾を\n得なくても，これらを混合して保管することができる。",
    "question_no": 11,
