    "question": "不法行為に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後記1\nから5までのうちどれか。（解答欄は，）\nア．未成年者が他人に損害を加えた場合，その未成年者の親権者が損害賠償責任を負うことはあ\nっても，未成年者が損害賠償責任を負うことはない。\nイ．故意又は過失によって一時的に自己の行為の責任を弁識する能力を欠く状態を招いた者は，\nその状態にある間に他人に加えた損害について賠償責任を負う。\nウ．使用者が被用者の加害行為につき使用者責任に基づいて第三者に損害賠償をした場合であっ\nても，使用者の被用者に対する求償権は生じない。\nエ．請負人がその仕事について第三者に損害を加えた場合，注文又は指図について過失のない注\n文者は，その第三者に対する損害賠償責任を負わない。\nオ．人の生命又は身体を害する不法行為による損害賠償請求権は，時効によって消滅しない。",
