    "question": "親子関係に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わ\nせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．妻が夫と婚姻中に懐胎し，子を出産した場合において，夫と子との間に生物学上の父子関係\nが認められないことが科学的証拠により明らかであるときは，子は，親子関係不存在確認の訴\nえにより，夫との法律上の父子関係を否定することができる。\nイ．妻が，性同一性障害者の性別の取扱いの特例に関する法律の規定に基づき男性への性別の取\n扱いの変更の審判を受けた夫と婚姻中に懐胎し，子を出産した場合には，子は夫の嫡出子と推\n定される。\nウ．妻が，夫の死亡後に，凍結保存されていた夫の精子を用いて懐胎し，子を出産した場合にお\nいて，夫が生前にその精子を用いて懐胎することに同意していたときであっても，死後認知に\nよって夫と子との間に法律上の父子関係が認められることはない。\nエ．婚姻の届出から1か月後に妻が出産した子について夫がその子との間の法律上の父子関係を\n否定しようとする場合，婚姻前に数年にわたり内縁関係が先行するときは，嫡出否認の訴えに\nよらなければならない。\nオ．生物学上の父子関係がないことを知りながら認知をした者は，認知無効の訴えを提起するこ\nとができない。",
