    "question": "被相続人Ａの配偶者Ｂは，Ａの死亡時に，Ａの財産に属していた甲建物に居住していた。この場\n合における甲建物についてのＢの配偶者居住権に関する次のアからオまでの各記述のうち，誤って\nいるものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．ＡＢの子であるＣが，Ａの死亡時に甲建物をＡと共有していた場合は，Ｂは，配偶者居住権\nを取得しない。\nイ．配偶者居住権を取得したＢは，その配偶者居住権を譲渡することができる。\nウ．配偶者居住権を取得したＢは，甲建物の使用及び収益に必要な修繕をすることができる。\nエ．相続によりＡから甲建物の所有権を取得したＤは，配偶者居住権を取得したＢに対し，配偶\n者居住権の設定の登記を備えさせる義務を負う。\nオ．遺贈によりＢが配偶者居住権を取得した後，遺産分割によりＢ及び相続人Ｅが甲建物の共有\n持分をそれぞれ有するに至った場合は，その配偶者居住権は消滅する。",
