    "question": "株式会社の設立に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，\n後記1から5までのうちどれか。（解答欄は，）\nア．定款の認証の手数料は，定款に記載又は記録がない場合でも，成立後の株式会社が負担する。\nイ．判例の趣旨によれば，定款に記載又は記録しないでされた財産引受けは無効であるが，成立\n後の株式会社が追認すれば遡って有効になる。\nウ．発起人が2人以上ある場合において，定款に記載又は記録しないで，各発起人が割当てを受\nける設立時発行株式の数を定めようとするときは，発起人の過半数の同意を得れば足りる。\nエ．発起人は，引き受けた設立時発行株式につき，その出資に係る金銭の全額を払い込んだ時に，\n当該設立時発行株式の株主となる。\nオ．発起人でない者も，設立時取締役になることができる。",
