    "label": "第17問",
    "question": "譲渡制限株式を発行する株式会社に関する次のアからオまでの各記述のうち，誤っているものを\n組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．事前に株式会社の承認を得ることなくその発行する譲渡制限株式を取得した者は，当該株式\n会社に対し，当該譲渡制限株式を取得したことについて承認をするか否かの決定をすることを\n請求する場合に，その請求と併せて，当該株式会社が承認をしない旨の決定をするときには当\n該株式会社又は指定買取人が当該譲渡制限株式を買い取ることも請求しなければならない。\nイ．判例の趣旨によれば，株券を発行する株式会社の株主が当該株式会社の事前の承認を得るこ\nとなくその発行する譲渡制限株式を譲渡する旨の合意をして株券を交付した場合には，当該譲\n渡は，当該株式会社に対する関係では効力を生じないが，当事者間では有効である。\nウ．株式会社は，その発行する譲渡制限株式を相続により取得した者に対し，当該譲渡制限株式\nを当該株式会社に売り渡すことを請求することができる旨を定款で定めることができる。\nエ．譲渡制限株式を他人に譲渡しようとする株主がその株式会社に対して譲渡を承認するか否か\nの決定をすることを請求した場合において，当該株式会社がその請求の日から2週間又は定款\nで定めたそれより短い期間内に決定の内容を通知しなかったときは，当該株式会社は，当該株\n主との間に別段の合意のない限り，譲渡を承認しない旨の決定をしたものとみなされる。\nオ．株式会社がある種類の株式の内容として譲渡による当該種類の株式の取得について当該株式\n会社の承認を要することの定めを設ける定款の変更をする場合には，当該種類の株式を目的と\nする新株予約権を有する新株予約権者は，当該株式会社に対し，自己の有する新株予約権を公\n正な価格で買い取ることを請求することができる。",
