    "question": "新株予約権に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，\n後記1から5までのうちどれか。（解答欄は，）\nア．募集新株予約権についての払込期日が定められている場合において，新株予約権者が当該払\n込期日までに募集新株予約権の払込金額の全額の払込みをしないときは，当該募集新株予約権\nは消滅する。\nイ．新株予約権者は，募集新株予約権の払込金額の全額の払込みに代えて，払込金額に相当する\n金銭以外の財産を給付しようとする場合だけでなく，その株式会社に対する債権をもって相殺\nする場合にも，当該株式会社の承諾を得なければならない。\nウ．新株予約権者は，現物出資財産の実際の価額が新株予約権の内容として定められた現物出資\n財産の価額に著しく不足することについて，善意でかつ重大な過失がないときであっても，そ\nの株式会社に対し，当該不足額を支払う義務があり，新株予約権の行使に係る意思表示を取り\n消して，その支払義務を免れることはできない。\nエ．公開会社でない取締役会設置会社は，新株予約権を引き受ける者の募集をするに当たって株\n主に新株予約権の割当てを受ける権利を与えることを決定する場合において，取締役会の決議\nによって募集事項等を定めることができる旨の定款の定めを設けることはできない。\nオ．株式交換完全親株式会社は，株式交換契約に定めることにより，株式交換に際して，株式交\n換完全子会社の新株予約権の新株予約権者に対し，当該新株予約権に代わる当該株式交換完全\n親株式会社の新株予約権を交付することができる。",
