    "label": "第19問",
    "question": "共有に属する株式についての権利行使者の指定及び株式会社に対するその通知（以下「権利行使\n者の指定及び通知」という。）に関する次のアからオまでの各記述のうち，正しいものを組み合わ\nせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．判例の趣旨によれば，権利行使者の指定及び通知がされている場合であっても，株主総会の\n決議事項について，その株式の共有者の間に意見の相違が生じたときは，権利行使者として指\n定された者は，自己の判断に基づいて議決権を行使することができない。\nイ．共有に属する株式につき株主総会における議決権を行使する者については，株主総会の都度，\n権利行使者の指定及び通知がされなければならない。\nウ．判例の趣旨によれば，権利行使者の指定及び通知を要する旨の会社法の規定は，民法の共有\nの規定に対する特別の定めに当たる。\nエ．判例の趣旨によれば，各共有者の持分の価格に従い，その過半数を有する株式の共有者は，\n権利行使者の指定及び通知がされなければ，その株式会社の同意があっても，取締役選任決議\nの議決権を行使することはできない。\nオ．判例の趣旨によれば，株式を相続により共有するに至った共同相続人は，株主としての地位\nに基づき株主総会決議不存在確認の訴えを提起する場合であっても，権利行使者の指定及び通\n知がされていないときは，特段の事情がない限り，原告適格を有しない。",
