    "question": "監査役会設置会社における会計監査人に関する次のアからオまでの各記述のうち，誤っているも\nのを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．会計監査人は，定時株主総会において会計監査人の出席を求める決議があったときは，定時\n株主総会に出席して意見を述べる義務がある。\nイ．会計監査人は，その職務を行うに際して取締役の職務の執行に関し法令に違反する重大な事\n実があることを発見したときは，遅滞なく，これを取締役会に報告する義務がある。\nウ．会計監査人は，いつでも，会計帳簿の閲覧及び謄写をし，又は取締役に対し，会計に関する\n報告を求める権限がある。\nエ．会計監査人は，その職務を行うため必要があるときは，会計監査人設置会社の子会社に対し\nて会計に関する報告を求めることはできるが，その子会社の業務及び財産の状況の調査をする\n権限を有しない。\nオ．監査役会を構成する監査役は，その職務を行うため必要があるときは，会計監査人に対し，\nその監査に関する報告を求めることができる。",
