    "question": "商業登記の効力に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，\n後記1から5までのうちどれか。（解答欄は，）\nア．商法の規定によって登記すべき事項は，登記の後でなければ，善意の第三者に対抗すること\nができないが，登記の後であっても，その登記があることを正当な事由によって知らなかった\n第三者に対しては対抗することができない。\nイ．株式会社の代表取締役として選定されていない者について，故意又は過失によりその就任の\n登記をした株式会社は，その事項が不実であることを悪意の第三者に対抗することができない。\nウ．商業登記には，登記された事項が真実であるという法律上の推定力がある。\nエ．個人商人（小商人に当たる者を除く。）が商号を登記した場合において，その商号を変更し\nたときは，変更の登記をしなければならない。\nオ．判例の趣旨によれば，代表取締役の退任について株式会社が登記したときは，その後にその\n者が当該株式会社の代表者として第三者とした取引については，民法の代理権消滅後の表見代\n理に関する規定が適用又は類推適用される。",
