    "question": "約束手形に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後\n記1から5までのうちどれか。（解答欄は，）\nア．全国銀行協会が規格・様式を定めた統一手形用紙によらないで振り出された約束手形も，有\n効である。\nイ．振出人が第三者の住所で支払うべき旨が記載されている約束手形も，有効である。\nウ．約束手形の金額として数字で二つの金額が記載されている場合において，それら二つの金額\nに差異があるときは，当該約束手形は無効である。\nエ．判例の趣旨によれば，振出日として記載された日よりも前の日が満期として記載されている\n確定日払いの約束手形は，無効である。\nオ．判例の趣旨によれば，暦に存在しない平年における2月29日が満期として記載されている\n約束手形は，無効である。",
