    "subject": "商法",
    "label": "第30問",
    "question": "手形上の権利を行使する代理権を付与する目的をもって通常の譲渡裏書の方式でする裏書（隠れ\nた取立委任裏書）について，手形上の権利は依然として裏書人にあり，被裏書人は単に手形上の権\n利行使の資格と権限を授与されるにすぎないとする見解がある。ＡがＢに対して約束手形を振り出\nし，ＢがＣに隠れた取立委任裏書をした場合に関する次のアからオまでの各記述のうち，この見解\nからの結論と整合しないものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，\n）\nア．手形債務者Ａは，被裏書人Ｃに対する人的抗弁をもって被裏書人Ｃに対抗することができな\nい。\nイ．手形債務者Ａは，裏書人Ｂに対する人的抗弁をもって被裏書人Ｃに対抗することができない。\nウ．裏書人Ｂは，被裏書人Ｃに対して担保責任を負わない。\nエ．被裏書人Ｃにつき破産手続が開始された場合，裏書人Ｂは取戻権を有しない。\nオ．取立委任の合意が解除されると，被裏書人Ｃの取立権限は消滅する。",
