    "subject": "民事訴訟法",
    "label": "第32問",
    "question": "多数当事者訴訟の各類型の意義とそれぞれの類型に当てはまる具体的な例に関する次のアからウ\nまでの各記述について説明した後記1から5までの各記述のうち，判例の趣旨に照らし正しいもの\nはどれか。（解答欄は，）\nア．通常共同訴訟は，共同訴訟のうち，訴訟共同の必要がなく，合一確定の必要もない類型のも\nのをいう。通常共同訴訟に当たるものとして，不動産の全共有者であるＸ1及びＸ2が共同し\nて当該不動産の登記名義人Ｙに対して提起する当該不動産全体の共有権に基づく所有権移転登\n記手続請求の訴えがある。\nイ．固有必要的共同訴訟は，共同訴訟のうち，訴訟共同の必要がないが，合一確定の必要はある\n類型のものをいう。固有必要的共同訴訟に当たるものとして，不動産の全共有者であるＸ1及\nびＸ2が共同して当該不動産に隣接する不動産の所有者であるＹに対して提起した筆界（境界）\n確定の訴えがある。\nウ．類似必要的共同訴訟は，共同訴訟のうち，訴訟共同の必要があるが，合一確定の必要がない\n類型のものをいう。類似必要的共同訴訟に当たるものとして，株主Ｘ1及びＸ2が共同して株\n式会社の取締役Ｙに対して提起した責任追及等の訴えがある。",
