    "label": "第33問",
    "question": "補助参加に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わ\nせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．補助参加人は，補助参加をした訴訟において証人となることができる。\nイ．補助参加の許否についての裁判に対しては，不服を申し立てることができない。\nウ．訴訟告知を受けた者は，当然に当該訴訟における補助参加人の地位を取得する。\nエ．原告を補助するためその訴訟に参加した補助参加人は，当該訴訟に係る訴えの取下げをする\nことができない。\nオ．補助参加に係る訴訟における判決の補助参加人に対する効力（いわゆる参加的効力）は，判\n決の主文中の訴訟物に係る判断の前提として理由中でされた事実の認定や先決的権利関係の存\n否についての判断には生じない。",
