    "subject": "民事訴訟法",
    "label": "第34問",
    "question": "訴訟委任を受けた訴訟代理人に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤\nっているものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．訴訟代理人の権限は，書面で証明しなければならない。\nイ．訴訟代理人は，和解条項中に訴訟物たる権利以外の権利に関する条項を含むものでない限り，\n当事者から和解についての特別の委任を受けていない場合であっても，訴訟上の和解をするこ\nとができる。\nウ．訴訟代理人の事実に関する陳述を当事者が直ちに更正したときは，その陳述は効力を生じな\nい。\nエ．訴訟代理人が故意又は重大な過失により真実に反して文書の成立の真正を争ったときであっ\nても，訴訟代理人が過料に処せられることはない。\nオ．訴訟代理人が適法に選任した訴訟復代理人は，訴訟代理人の死亡によっては訴訟代理権を失\nわない。",
