    "subject": "民事訴訟法",
    "label": "第35問",
    "question": "確定判決の効力に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組\nみ合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．Ａを債務者とする債権がＸに帰属することの確認を求める旨のＸのＹに対する訴訟において，\n請求を認容するとの判決が確定した場合に，この判決の効力は，Ａに対して及ぶ。\nイ．Ｘが，Ｘに対して連帯債務を負うＹとＺのうちＹに対してのみその債務の履行を求める訴訟\nにおいて，相殺を理由として請求を一部棄却するとの判決が確定した場合に，この判決の効力\nは，Ｚに及ぶ。\nウ．ＸのＹに対する賃貸借契約の終了に基づく土地明渡請求訴訟において，賃料不払による解除\nを理由として請求を認容するとの判決が確定した場合に，この判決の効力は，この訴訟の口頭\n弁論終結の前からその土地を転借しているＺに対しては及ばない。\nエ．ＸのＹに対する動産引渡請求訴訟において，請求を認容するとの判決が確定した場合に，こ\nの判決の効力は，この訴訟の口頭弁論終結の前から，Ｙの委託に基づき無償でその動産を保管\nしているＺに及ぶ。\nオ．Ｘが宗教法人Ｙの代表役員の地位にあることの確認を求める旨のＸのＹに対する訴訟におい\nて，請求を認容するとの判決が確定した場合に，この判決は，対世的効力を有しない。",
