    "question": "反訴に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わせた\nものは，後記1から5までのうちどれか。（解答欄は，）\nア．訴訟委任に基づく訴訟代理人は，特別の委任を受けることなく，反訴を提起することができ\nる。\nイ．補助参加人は，被参加人である被告のために反訴を提起することはできない。\nウ．反訴状は，反訴原告（本訴被告）が反訴被告（本訴原告）に対しその写しを直接送付するこ\nとで足り，裁判所が送達することを要しない。\nエ．本訴取下げ後における反訴の取下げには，反訴被告の同意を要しない。\nオ．上告審においては，相手方の同意がある場合に限り，反訴を提起することができる。",
