    "year_label": "R3",
    "subject": "民事訴訟法",
    "label": "第37問",
    "question": "口頭弁論の分離及び併合に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤って\nいるものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．主債務者と連帯保証人を共同被告として訴えが提起された場合に，裁判所は，不出頭の連帯\n保証人につき口頭弁論を分離して判決をすることができない。\nイ．共同被告の一方に対する訴訟の目的である権利と共同被告の他方に対する訴訟の目的である\n権利とが法律上併存し得ない関係にある場合において，原告の申出があったときは，裁判所は，\n弁論及び裁判は分離しないでしなければならない。\nウ．離婚訴訟が家庭裁判所に係属中に，離婚原因である不貞行為によって生じた損害の賠償を求\nめる訴えが地方裁判所に提起されたが，その地方裁判所が当該訴えに係る訴訟を離婚訴訟が係\n属する家庭裁判所に移送した場合には，移送を受けた家庭裁判所は，これらの訴訟に係る事件\nについて口頭弁論の併合を命じなければならない。\nエ．裁判所は，一つの請求について数個の独立した攻撃防御方法が提出されている場合には，そ\nれぞれの攻撃防御方法ごとに口頭弁論の分離を命ずることができる。\nオ．裁判所は，当事者を異にする事件について口頭弁論の併合を命じた場合に，併合前に尋問を\nした証人について，尋問の機会がなかった当事者から尋問の申出がないときは，その尋問をす\nる必要はない。",
