    "question": "証拠保全に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後\n記1から5までのうちどれか。（解答欄は，）\nア．訴え提起後における証拠保全の申立ては，最初の口頭弁論の期日が指定された後口頭弁論の\n終結に至るまでの間は，急迫の事情がある場合を除き，受訴裁判所にしなければならない。\nイ．裁判所は，必要があると認めるときは，訴訟の係属中，職権で，証拠保全の決定をすること\nができる。\nウ．証拠保全として，文書の取調べをすることはできるが，証人尋問をすることはできない。\nエ．証拠保全の決定は，口頭弁論又は相手方が立ち会うことができる審尋の期日を経なければ，\nこれをすることができない。\nオ．証拠保全の申立てを却下する決定に対しては，抗告をすることができる。",
