    "question": "裁判によらない訴訟の完結に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っ\nているものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．請求の認諾は，和解の期日においてもすることができる。\nイ．請求の放棄は，被告が本案について口頭弁論をした後にあっても，その同意を得ることなく\nすることができる。\nウ．当事者双方が裁判外で訴えを取り下げる旨の合意をし，被告がその合意の存在を口頭弁論又\nは弁論準備手続の期日において主張立証した場合には，訴えの取下げがあったものとみなされ\nる。\nエ．裁判所は，当事者双方のための衡平を考慮し，職権で，事件の解決のために適当な和解条項\nを定めることができ，当事者双方がその和解条項の告知を受けたときは，訴訟上の和解が調っ\nたものとみなされる。\nオ．訴訟が訴訟上の和解により終了した場合において，その後，その和解の内容である私法上の\n契約が債務不履行により解除されたとしても，和解による訴訟終了の効果には影響を及ぼさな\nい。",
