    "subject": "憲法",
    "label": "第2問",
    "question": "思想・良心の自由に関する次のアからウまでの各記述について，最高裁判所の判例の趣旨に照ら\nして，正しいものには〇，誤っているものには×を付した場合の組合せを，後記1から8までの中\nから選びなさい。（解答欄は，）\nア．企業内においても労働者の思想，信条等の精神的自由は十分尊重されるべきであることに鑑\nみると，企業がその労働者に対して特定政党への所属の有無を確認するだけでなく，当該政党\nに所属しない旨の書面を要求する行為は，それが企業秘密の漏えいという企業秩序違反行為に\n関する調査の一環として行われたとしても，労働者の思想・信条の自由に対する直接的制約で\nあるから，その経緯や調査方法の相当性にかかわらず，違法性が認められる。\nイ．公立学校の卒業式等の式典においてその教員に国旗掲揚の下での国歌斉唱の際に起立斉唱を\n求めることは，慣例上の儀礼的な所作を求めるものではあるが，自らの歴史観ないし世界観と\nの関係で国歌や国旗に対する敬意の表明には応じ難いと考える者がこれらに対する敬意の表明\nの要素を含む行為を求められることは，その者の歴史観ないし世界観に由来する行動とは異な\nる外部的行動を求められることになり，その限りにおいて思想及び良心の自由についての間接\n的な制約となる面がある。\nウ．政治団体への寄付が強制加入団体である税理士会の目的の範囲内かどうかを判断するに当た\nっては，会員の思想・信条の自由との関係で，その会員には様々の思想・信条及び主義・主張\nを有する者が存在することが当然に予定されていること，政治団体に寄付するかどうかは選挙\nにおける投票の自由と表裏をなすものとして会員各人が個人的な政治的思想，見解，判断等に\n基づいて自主的に決定すべき事柄であることなどを考慮することが必要である。\n1．ア〇 イ〇 ウ〇 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ〇\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ〇 6．ア× イ〇 ウ×\n7．ア× イ× ウ〇 8．ア× イ× ウ×",
