    "subject": "憲法",
    "label": "第3問",
    "question": "表現の自由に関する次のアからウまでの各記述について，最高裁判所の判例の趣旨に照らして，\n正しいものには〇，誤っているものには×を付した場合の組合せを，後記1から8までの中から選\nびなさい。（解答欄は，）\nア．自己の政治的意見を記載したビラを配布することは表現の自由の行使ということができるが，\n居住者が私的生活を営む場所である集合住宅の共用部分や敷地内に管理権者の承諾なく立ち入\nり，集合郵便受けや各室玄関ドアの郵便受けに当該ビラを投かんする行為は，管理権者の管理\n権を侵害するのみならず，そこで生活する者の私生活の平穏を侵害するものであるから，この\nような立入り行為をもって邸宅侵入の罪に問うことは許される。\nイ．表現の自由も絶対無制限に保障されるものではなく，公共の福祉のため必要かつ合理的な制\n限は是認されるものであって，たとえ思想を外部に発表するための手段であっても，その手段\nが他人の財産権，管理権を不当に害するごときものは許されないといわなければならないから，\n私鉄の駅構内において，同駅管理者の許諾を受けずにビラ配布や拡声器による演説を行い，駅\n構内からの退去要求を受けながらそれを無視して約20分間同駅構内に滞留した行為を不退去\n罪等により処罰することは許される。\nウ．公共の福祉のため，表現の自由に対し必要かつ合理的な制限をすることは許されるが，政治\n的表現の自由は，民主政に資する価値を有する特に重要な権利であるから，政党の演説会開催\nの告知宣伝を内容とする立て看板を街路樹にくくりつける行為について，美観風致の維持及び\n公衆に対する危害防止の目的のために屋外広告物の表示の場所・方法等を規制する屋外広告物\n条例を適用して処罰することは，許されない。\n1．ア〇 イ〇 ウ〇 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ〇\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ〇 6．ア× イ〇 ウ×\n7．ア× イ× ウ〇 8．ア× イ× ウ×",
