    "question": "行政指導に関する次のアからウまでの各記述について，行政手続法に照らし，正しいものに○，\n誤っているものに×を付した場合の組合せを，後記1から8までの中から選びなさい。（解答欄は，\n）\nア．行政指導に携わる者は，当該行政指導をする際に，行政機関が許認可等をする権限又は許\n認可等に基づく処分をする権限を行使し得る旨を示すときは，その相手方に対して，当該権\n限を行使し得る根拠となる法令の条項及び当該条項に規定する要件を示さなければならない\nが，当該権限の行使が当該条項に規定する要件に適合する理由を示す必要はない。\nイ．法令に違反する行為の是正を求める行政指導を受けた者が，当該行政指導をした行政機関\nに対し，当該行政指導がその根拠となる法律の規定する要件に適合しない旨を申し出て，当\n該行政指導の中止その他必要な措置をとることを求めたときは，当該行政機関は，当該行政\n指導が当該法律に規定する要件に適合することを確認するまでの間，当該行政指導を一時中\n止しなければならない。\nウ．行政指導の内容はあくまでも相手方の任意の協力によってのみ実現されるものでなければな\nらないから，許認可等に基づく処分をする権限を有する行政機関が当該権限を行使する意思が\nない場合においてする行政指導にあっては，当該行政指導に携わる者は，当該権限を行使し得\nる旨を殊更に示すことにより相手方に当該行政指導に従うことを余儀なくさせるようなことを\nしてはならない。\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
