    "subject": "行政法",
    "label": "第16問",
    "question": "医師法第7条の3第1項に基づく立入検査に関する教員と学生による以下の対話中の次のアから\nウまでの【 】内の各記述について，正しいものに○，誤っているものに×を付した場合の組合せ\nを，後記1から8までの中から選びなさい。（解答欄は，）\n教員：医師法第7条の3第1項に基づく立入検査の強制力について，どのようなことがいえます\nか。\n学生：（ア）【医師法第33条の2第3号により，立入検査の拒否に罰則が定められていることか\nらすると，同法は，間接的心理的に立入検査の受忍を強制しようとするものといえます。】\n教員：それでは，ある医師について，医師法第7条第1項の規定による処分をすべきか否かを調\n査するため，同法第7条の3第1項に基づく当該医師の開設する病院の立入検査が行わ\nれようとしているにもかかわらず，当該医師が立入検査を拒否しているという事例を想\n定してください。立入検査に関しては，医師法上，第7条の3以外の規定はありません\nが，立入検査をしようとする行政庁の職員はどのようなことができますか。\n学生：（イ）【立入検査をしようとする職員は，必要最小限の実力を行使して当該医師を排除した\n上で，立入検査を行うことができます。】\n教員：税務調査に関する最高裁判所の判例に照らすと，立入検査が医師法第7条の3第3項の規\n定に反するのは，どのような場合であるといえますか。\n学生：（ウ）【立入検査の権限を犯罪捜査のための手段として行使したような場合には，その立入\n検査は医師法第7条の3第3項に違反します。】\n（参照条文）医師法\n第4条 次の各号のいずれかに該当する者には，免許を与えないことがある。\n一 心身の障害により医師の業務を適正に行うことができない者として厚生労働省令で定\nめるもの\n二 麻薬，大麻又はあへんの中毒者\n三 罰金以上の刑に処せられた者\n四 前号に該当する者を除くほか，医事に関し犯罪又は不正の行為のあつた者\n第7条 医師が第4条各号のいずれかに該当し，又は医師としての品位を損するような行\n為のあつたときは，厚生労働大臣は，次に掲げる処分をすることができる。\n一 戒告\n二 3年以内の医業の停止\n三 免許の取消し\n2～17 （略）\n第7条の3 厚生労働大臣は，医師について第7条第1項の規定による処分をすべきか否\nかを調査する必要があると認めるときは，当該事案に関係する者若しくは参考人から意\n見若しくは報告を徴し，診療録その他の物件の所有者に対し，当該物件の提出を命じ，\n又は当該職員をして当該事案に関係のある病院その他の場所に立ち入り，診療録その他\nの物件を検査させることができる。\n2 前項の規定により立入検査をしようとする職員は，その身分を示す証明書を携帯し，\n関係人の請求があつたときは，これを提示しなければならない。\n3 第1項の規定による立入検査の権限は，犯罪捜査のために認められたものと解しては\nならない。\n第33条の2 次の各号のいずれかに該当する者は，50万円以下の罰金に処する。\n一，二 （略）\n三 第7条の3第1項の規定による陳述をせず，報告をせず，若しくは虚偽の陳述若し\nくは報告をし，物件を提出せず，又は検査を拒み，妨げ，若しくは忌避した者\n- 9 -\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
