    "id": "r2_35",
    "year": 2020,
    "year_label": "R2",
    "subject": "行政法",
    "label": "第17問",
    "question": "甲市では，市内の住宅において，物の堆積又は放置あるいは雑草の繁茂等により，不良な生活環\n境が生じている例が見られ，行政の対応が求められていた。そこで，甲市は新たな条例（以下「本\n件条例」という。）を定めることにより，住宅における不良な生活環境に対処することを検討して\nいる。本件条例を所掌する部門の部長と職員による以下の対話中の次のアからエまでの【 】内の\n各記述について，それぞれ正しい場合には1を，誤っている場合には2を選びなさい。（解答欄は，\nアからエの順にから）\n部長：本件条例では，住宅に不良な生活環境が生じている場合には，当該住宅の所有者に堆積\nした物の撤去等の適切な措置をとることを命令することができると定めます。しかし，\n命令の相手方が従うとは限りませんから，命令の実効性を確保する仕組みを条例に定め\nる必要があります。どのような仕組みが考えられますか。\n職員：（ア）【命令に従わない場合には，行政刑罰を科すことが考えられます。行政刑罰は刑事\n罰の一種で，原則として刑事訴訟法が適用されます。】\n部長：他にどのような仕組みが考えられますか。\n職員：（イ）【執行罰が考えられます。執行罰は命令による義務の不履行に対して一定額の過料\nを科すこととし，不履行があった場合には強制的にこれを徴収するというものです。た\nだし，1回の不履行に対して1回しか徴収することはできず，義務が履行されるまで何\n度も徴収することはできないとされています。】\n部長：次に，行政代執行について考えてみましょう。行政代執行法が，独自に定められた条例\nに適用されるかについては，消極的な見解も見られますが，ここでは，本件条例に基づ\nく命令について，行政代執行法が適用されるとの前提で考えてみましょう。例えば，住\n宅に生じている不良な生活環境がこれ以上悪化しないように，条例に基づく当該住宅の\n使用禁止命令を発することができる場合，その実効性を確保するために，行政代執行法\nに基づいて，当該住宅の封鎖を行うことは可能でしょうか。\n職員：（ウ）【使用禁止命令は，行政代執行法における「他人が代つてなすことのできる行為」\nに関するものではないので，行政代執行を行うことはできません。】しかし，堆積した物\nの撤去を命じる命令であれば，行政代執行によって行うことができます。\n部長：行政代執行法によると，代執行に要した費用は義務者から徴収することとされています。\n仮に，義務者が費用を支払わない場合，義務者から代執行に要した費用を強制的に徴収\nすることはできますか。\n職員：（エ）【行政代執行法には明文の定めはありませんが，このような権力的な行政活動に基づ\nく債権については，国税滞納処分の例によって徴収することができると考えられていま\nす。】\n- 11 -",
