    "question": "緊急避難（刑法第37条第1項）に関する次の【記述】の中の①から⑥までの（ ）内に，後記\nアからスまでの【語句群】から適切な語句を入れた場合，（ ）内に入るものの組合せとして正し\nいものは，後記1から5までのうちどれか。なお，①から⑥までの（ ）内にはそれぞれ異なる語\n句が入る。（解答欄は，）\n【記 述】\n緊急避難を（①）と解する見解によれば，その不処罰の根拠は，切迫した心理状態のために適法\nな行為を期待し得ないことに求められる。この見解によれば，緊急避難によって侵害を転嫁される\n第三者は緊急避難行為に対して（②）で対抗できることになる。この見解に対しては，刑法第37\n条第1項が（③）を守るための緊急避難を認めていることと整合しないという批判がある。他方，\n緊急避難を（④）と解する見解によれば，その不処罰の根拠は，法益が衝突する状況下で被侵害法\n益と同等以上の法益を保全する行為は社会全体の利益を（⑤）させるものではないことに求められ\nる。また，この見解に立つと，緊急避難行為に対して（②）で対抗することを認めるのは困難であ\nる。さらに，緊急避難を基本的には（④）と解しつつ，保全法益と被侵害法益がいずれも生命であ\nる場合には，（①）であると解する見解もある。この見解は，自己又は第三者の生命に対する危難\nを避けるために無関係の第三者の生命を犠牲にする行為を（⑥）と評価するのは不当であるという\n考え方に基づくものである。\n【語句群】\nア．違法性阻却事由 イ．責任阻却事由 ウ．個人的法益 エ．社会的法益\nオ．他人の法益 カ．自己の法益 キ．増加 ク．減少 ケ．正当行為\nコ．正当防衛 サ．緊急避難 シ．違法 ス．違法でない",
    "question_no": 1,
