    "question": "共犯と錯誤に関する次のアからオまでの各記述を判例の立場に従って検討した場合，正しいもの\nの個数を後記1から5までの中から選びなさい。（解答欄は，）\nア．甲及び乙がＡに対する暴行を共謀したが，Ａの態度に激高した甲が殺意をもってＡを殺害し\nた場合，甲及び乙に殺人罪の共同正犯が成立するが，乙は傷害致死罪の刑で処断される。\nイ．甲及び乙がＡに対する強盗を共謀したが，その強盗の機会に，甲が過失によってＡに傷害を\n負わせた場合，甲及び乙に強盗致傷罪の共同正犯が成立する。\nウ．甲及び乙が共謀して，公務員Ａに虚偽の内容の公文書の作成を教唆することにしたが，乙は\nＡを買収することに失敗したため，甲に無断で，Ｂに公文書を偽造することを教唆し，Ｂが公\n文書を偽造した場合，甲に虚偽公文書作成罪の教唆犯が成立する。\nエ．甲が乙にＡ方に侵入して金品を窃取するように教唆して，その犯行を決意させたが，乙はＡ\n方と誤認して隣のＢ方に侵入してしまい，Ｂ方から金品を窃取した場合，甲にＢ方への住居侵\n入罪及びＢに対する窃盗罪の教唆犯は成立しない。\nオ．甲が乙の傷害行為を幇助する意思で，乙に包丁を貸与したところ，乙が殺意をもってその包\n丁でＡを刺殺した場合，甲に殺人罪の幇助犯が成立し，傷害致死罪の幇助犯は成立しない。",
