    "subject": "刑法",
    "label": "第5問",
    "question": "結果的加重犯について，学生Ａ及びＢが次の【会話】のとおり議論している。【会話】中の①か\nら⑧までの（ ）内に後記アからスまでの【語句群】の中から適切なものを選んだ場合，正しいも\nのの組合せは，後記1から5までのうちどれか。なお，①から⑧までの（ ）内にはそれぞれ異な\nる語句が入る。（解答欄は，）\n【会 話】\n学生Ａ．結果的加重犯について，判例は，基本犯と加重結果との間に（①）があれば足りるとし\nていると解されていますね。\n学生Ｂ．判例の立場は（②）の点から疑問があります。私は，加重結果の発生について行為者に\n（③）がなければ，結果的加重犯の成立を認めることは許されないと考えます。\n学生Ａ．確かに，判例が求めている（①）を単なる（④）と解するのであれば，（②）の点から\n問題だと思いますが，私は（①）の有無については（⑤）が認められるか否かを基準に考\nえますので，（②）の点も問題ないと考えます。ところで，あなたのように加重結果の発\n生について行為者に（③）を要求するのであれば，加重結果の（⑥）があることが必要と\nなりますが，誰を基準にそれを考えるのですか。\n学生Ｂ. （⑥）は（⑦）の前提要件であることから客観的に判断すべきであり，それゆえ，（⑧）\nを基準にすべきと考えます。\n学生Ａ．そうすると，私の見解でも，（⑤）の有無の判断の基礎となる事情の一つとして，行為\nの時点において（⑧）が認識可能であった事情を考慮するので，あなたの見解と変わりは\nないのではないですか。\n【語句群】\nア．故意 イ．過失 ウ．注意義務 エ．期待可能性\nオ．予見可能性 カ．一般人 キ．行為者 ク．因果関係\nケ．条件関係 コ．実行行為性 サ．相当因果関係 シ．責任主義\nス．法益保護主義",
