    "id": "r2_keipo_11",
    "year": 2020,
    "year_label": "R2",
    "subject": "刑法",
    "label": "第9問",
    "question": "原因において自由な行為に関する次の各【見解】に従って後記の各【事例】における甲の罪責を\n検討した場合，後記1から5までの各【記述】のうち，誤っているものはどれか。（解答欄は，）\n【見 解】\nＡ．責任能力がある状態で行われた原因行為を実行行為と捉える。\nＢ．責任能力を欠いた状態で行われた結果行為を実行行為と捉えつつ，責任能力は意思決定時に\n存在すれば足り，必ずしも実行行為時に存在することは必要ない。\n【事 例】\nⅠ．甲は，Ｘ宅に赴いて同人を殺害しようと決意し，心神喪失状態に陥る可能性があることを認\n識しつつ，自宅において景気づけのために覚醒剤を使用したところ，心神喪失状態に陥り，当\n初の計画どおりＸを殺害した。\nⅡ．甲は，Ｘ宅に赴いて同人を殺害しようと決意し，心神喪失状態に陥る可能性があることを認\n識しつつ，自宅において景気づけのために覚醒剤を使用したところ，心神喪失状態に陥ったが，\nＸ宅には赴かず，Ｘの殺害には及ばなかった。\nⅢ．甲は，覚醒剤を使用すると粗暴になり周囲に暴行を加える習癖があると知りつつ，覚醒剤を\n使用した結果，心神喪失状態に陥り，Ｘと口論になり，殺意を生じて同人を殺害した。\n【記 述】",
