    "question": "次の【事例】に関する後記アからエまでの各【記述】を判例の立場に従って検討した場合，正し\nいものの個数を後記1から5までの中から選びなさい。（解答欄は，）\n【事 例】\n甲は，某所公園内において，ベンチ上に置いてあるバッグ1個（以下「本件バッグ」という。）\nを発見し，誰かが置き忘れたものと考え，警察に届け出るため，これを手に取り，同公園から路\n上に出た。一方，本件バッグをベンチに置き忘れたことに気付いたＶは，同公園に戻ろうとして\n同路上に至ったところ，甲を発見した。Ｖは，甲が本件バッグを盗んだと疑い，「バッグを返せ。」\nと言いながら，甲の腹部を2回足で蹴り，甲から本件バッグを奪い，さらに，甲を蹴り上げるよ\nうな仕草を続けた。甲は，Ｖの暴行を避けようとして，その胸付近を1回平手で突いたところ，\nその勢いでＶが後方に転倒し，後頭部を路面に打ち付け，失神した。甲は，その頃には，Ｖが本\n件バッグの所有者であると分かっていたが，Ｖの態度に怒りを覚えたことなどから，本件バッグ\nを自己のものにしようと考え，失神しているＶからこれを取り上げて自宅に持ち帰った。\nその後，甲が本件バッグ内を確認したところ，Ｖ名義の預金口座のキャッシュカード等在中の\n財布，Ｖ所有の携帯電話機等の物品が入っていた。甲は，これらを見て，Ｖの氏名，勤務先のほ\nか，携帯電話機にわいせつな盗撮画像が保存されていることを知り，これを奇貨とし，Ｖから上\n記キャッシュカードの暗証番号を聞き出して上記口座から預金を引き出そうと思い，勤務先にい\nたＶに電話をかけ，「あんた盗撮してるな。警察に携帯を持って行かれたくないなら，あんたの\nキャッシュカードの暗証番号を教えろ。」と要求するなどした。Ｖは，この要求を断れば，盗撮\nの事実が警察に露見すると思い，やむを得ず甲に同暗証番号を教えた。その後，甲は，上記キャ\nッシュカードを用いて現金自動預払機から現金50万円を引き出した。\n【記 述】\nア．甲が本件バッグを警察に届け出るために某所公園内から持ち出した行為は，Ｖによる占有の\n回復を困難にする行為であるため，窃盗罪又は占有離脱物横領罪が成立する。\nイ．Ｖは本件バッグを甲から取り返す目的で暴行を加えており，この暴行は正当行為に該当する\nため，甲がＶの胸付近を1回平手で突いた行為の違法性が阻却される余地はなく，甲には，暴\n行罪又は傷害罪が成立する。\nウ．甲が本件バッグをＶから取り上げた行為は，甲の暴行に起因するＶの失神状態に乗じて本件\nバッグの占有を取得したといえるため，強盗罪が成立する。\nエ．甲が現金自動預払機から現金50万円を引き出した行為は，甲が，これに先行してＶから暗\n証番号を聞き出した時点で，Ｖの預金の払戻しを受け得る地位を得たことにより，その預金の\n占有を取得したといえるため，窃盗罪は成立しない。",
    "question_no": 18,
