    "label": "第18問",
    "question": "次の学生ＡないしＤの【会話】は，医師が捜査機関の依頼に基づき，人の身体から注射器を用い\nて直接強制により血液を採取するために必要と考えられる令状に関する議論である。学生Ａないし\nＤが必要と考えている令状として正しい組合せは，後記1から5までのうちどれか。（解答欄は，）\n【会話】\n学生Ａ：私は，一般に身体内にある体液を採取するために必要な令状については，強制採尿に関\nする判例が採用した考え方と同じでよいと思う。\n学生Ｂ：しかし，同じ体液といっても，尿と血液とでは性質が全然違うからなあ。\n学生Ｃ：そういうＢさんの見解も，対象者が採血を拒否した場合には直接強制するための明文が\nないのが問題だ。\n学生Ｂ：その点は，刑事訴訟法第172条の類推適用で対応できると思う。\n学生Ｄ：Ｃさんの見解だって，もともとその令状が想定している範囲は，身体の外表か，せいぜ\nい肛門等の体腔を外部から確認する程度であって，身体の損傷を伴う血液の採取をその令\n状で行い得るとするのは行き過ぎだ。\n学生Ｃ：そういうＤさんの見解も，それぞれの令状が単独ではできないことを，令状を併用すれ\nばできるとするのは，便宜に過ぎるのではないかと批判されているよね。\n学生Ｄ：でも，Ｂさんの見解のように，直接の明文規定を欠いているにもかかわらず，条文の類\n推適用によって直接強制し得るとするよりは良いと思う。",
