    "question": "検察官の権限に関する次の学生ＡないしＥの【発言】のうち，正しいものの組合せは，後記1か\nら5までのうちどれか。（解答欄は，）\n【発言】\n教 授：刑事訴訟法上，検察官の権限やその行使の在り方について様々な規定がありますね。\n学生Ａ：はい。検察官は，公訴権を有していますが，証拠に基づき有罪判決を得られる高度の見\n込みがある場合には，公訴を提起しなければならないと定められています。\n学生Ｂ：公訴権は，原則として検察官が独占していますが，裁判所の付審判決定があったときは\n公訴の提起があったものとみなされます。これは，起訴独占主義の例外の一つです。\n学生Ｃ：第一審の判決があるまで，検察官は，公訴を取り消すことができますが，検察官が公訴\nを取り消すには，裁判所の許可が必要です。\n学生Ｄ：検察官は，公訴を提起した後も，必要と認めるときは，自らその犯罪を捜査することが\nできます。\n学生Ｅ：検察官は，再審請求権を有していますが，有罪の言渡しを受けた者の利益のために，再\n審を請求することはできません。",
