    "id": "r2_keipo_32",
    "year": 2020,
    "year_label": "R2",
    "subject": "刑事訴訟法",
    "label": "第23問",
    "question": "次の【事例】に関する教授と学生ＡないしＤの【会話】のうち，誤った発言をしている学生は何\n人いるか。後記1から5までのうちから選びなさい。ただし，判例がある場合には，それに照らし\nて考えるものとする。（解答欄は，）\n【事例】\n甲は，令和2年3月1日，Ｈ市内の甲方において，乙から現金30万円を受け取り，同日，同所\nにおいて，公務員である丙に対して，乙から受け取った同現金30万円を交付した。\n【会話】\n教 授：この事例について，検察官が，「甲は，丙と共謀の上，令和2年3月1日，Ｈ市内の甲\n方において，乙から賄賂金30万円を収受した。」という収賄罪の共同正犯の訴因で起訴\nしたとします。審理の結果，裁判所が，当該賄賂金の授受があった日は，令和2年3月1\n0日であり，場所は，Ｈ市内の丙方であるとの心証を形成した場合，裁判所は，どうすべ\nきですか。\n学生Ａ：訴因の機能は，裁判所に対し審判の対象を限定するとともに，被告人に対し防御の範囲\nを示すことにあります。審理の経過に鑑み，犯罪の実行行為がなされた日時場所について，\n訴因と異なる日時場所を認定することにより，被告人に不意打ちを与える場合には，その\n防御に実質的な不利益を与えることになります。その場合には，訴因変更の手続を経ずに，\n「甲は，丙と共謀の上，令和2年3月10日，Ｈ市内の丙方において，乙から賄賂金30\n万円を収受した。」という事実を認定することはできません。\n学生Ｂ：裁判所は，検察官に対して，心証に沿った事実を内容とする訴因への変更を促し，検察\n官が応じない場合には，訴因の変更を命ずることが考えられます。\n学生Ｃ：裁判所は，検察官が訴因変更命令に応じなかったとしても，訴因変更命令により訴因が\n変更されたものとして，「甲は，丙と共謀の上，令和2年3月10日，Ｈ市内の丙方にお\nいて，乙から賄賂金30万円を収受した。」という事実を認定して，有罪判決を言い渡す\nことができます。\n教 授：それでは，裁判所は，審理の結果，甲が，令和2年3月1日，Ｈ市内の甲方において，\n乙から現金30万円を受け取り，同日，同所において，公務員である丙に対して，同現金\n30万円を交付した事実は間違いないが，収賄罪の共同正犯ではなく，「甲は，乙と共謀\nの上，丙に対し，賄賂金30万円を供与した。」という贈賄罪の共同正犯が成立するとの\n心証を形成したとします。その場合，裁判所は，どうすべきですか。\n学生Ｄ：この場合，一連の同一の行為についての法的評価を異にするにすぎないので，訴因変更\nの手続を経ることなく，贈賄罪の共同正犯を認定して，有罪判決を言い渡すことができま\nす。",
