    "subject": "刑事訴訟法",
    "label": "第26問",
    "question": "次のⅠないしⅢの【見解】は，「Ｙに対する保護責任者遺棄致死罪で起訴された甲の公判におい\nて，証拠調べの結果，甲がＹを遺棄した当時，Ｙが生きていたか死亡していたかが判明せず，甲に\n保護責任者遺棄致死罪と死体遺棄罪のどちらかが成立することは疑いがないが，どちらであるかは\n確定できなかった場合に，裁判所は，どのような判決を言い渡すべきか。」という問題に関する考\nえ方を述べたものである。【見解】に関する後記アからオまでの【記述】のうち，誤っているもの\nは幾つあるか。後記1から6までのうちから選びなさい。（解答欄は，）\n【見解】\nⅠ．無罪判決を言い渡すべきである。\nⅡ．保護責任者遺棄致死罪又は死体遺棄罪のいずれかの事実が認定できるという択一的認定をし\nて，有罪判決を言い渡すべきであるが，量刑は，軽い死体遺棄罪の刑によるべきである。\nⅢ．軽い死体遺棄罪の事実を認定して，有罪判決を言い渡すべきである。\n【記述】\nア．Ⅰの見解に対しては，国民の法感情に反するという批判がある。\nイ．Ⅰの見解に対しては，刑事訴訟において重要なのは，特定の犯罪に当たる事実の証明がされ\nたかどうかであるとの批判がある。\nウ．Ⅱの見解は，保護責任者遺棄致死罪又は死体遺棄罪のいずれかであることは疑いがない以上，\n軽い罪の刑で処罰するのであれば，「疑わしきは被告人の利益に」の原則に反しないとする。\nエ．Ⅱの見解に対しては，合成的な構成要件を設定して処罰することになり，罪刑法定主義に反\nするという批判がある。\nオ．Ⅲの見解は，保護責任者遺棄致死罪又は死体遺棄罪のどちらかが成立することは疑いがない\n状況で，重い保護責任者遺棄致死罪の事実が認定できないのであれば，死体遺棄罪が疑いなく\n証明されたと考えるべきであるとする。",
