    "id": "r2_minpo_01",
    "year": 2020,
    "year_label": "R2",
    "subject": "民法",
    "label": "第1問",
    "question": "錯誤に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後記1から\n5までのうちどれか。（解答欄は，）\nア．錯誤を理由とする意思表示の取消しの可否について，錯誤の重要性は，表意者を基準とし\nて判断される。\nイ．ＡのＢに対する意思表示がＡの錯誤を理由として取り消すことができるものである場合，\nＢも，Ａの錯誤を理由としてＡの意思表示を取り消すことができる。\nウ．負担のない贈与について贈与者であるＡの錯誤を理由とする取消しがされたが，受贈者で\nあるＢが既に当該贈与契約に基づいて給付を受けていた場合，Ｂは，給付を受けた時に当該\n贈与契約が取り消すことができるものであることを知らなかったときは，現に利益を受けて\nいる限度において返還の義務を負う。\nエ．ＡのＢに対する意思表示が錯誤を理由として取り消された場合，Ａは，その取消し前に利\n害関係を有するに至った善意無過失のＣに，その取消しを対抗することができない。\nオ．ＡのＢに対する意思表示が錯誤に基づくものであって，その錯誤がＡの重大な過失による\nものであった場合，Ａは，ＢがＡに錯誤があることを知り，又は重大な過失によって知らな\nかったときを除いて，錯誤を理由としてその意思表示を取り消すことができない。",
