    "question": "債務者Ａは債権者ＢのためにＡの所有する不動産甲に抵当権を設定し，その旨の登記がされた。\nこの場合における抵当権の消滅に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正\nしいものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．Ａは，抵当権を実行することができる時から20年が経過すれば，被担保債権が消滅して\nいなくても，抵当権が時効により消滅したと主張することができる。\nイ．甲について，その後，ＡがＣのために抵当権を設定し，その旨の登記がされた場合におい\nて，ＢがＡから甲を買い受けたときは，Ｂの抵当権は消滅しない。\nウ．Ａの一般債権者が甲につき強制競売の申立てをし，当該強制競売手続において甲が売却さ\nれたときは，Ｂの抵当権は消滅する。\nエ．甲について，その後，Ａから譲渡担保権の設定を受けたＤは，譲渡担保権の実行前であっ\nても，抵当権消滅請求をすることにより，Ｂの抵当権を消滅させることができる。\nオ．甲が建物である場合において，Ａが故意に甲を焼失させたときは，Ｂの抵当権は消滅しな\nい。",
