    "question": "Ａは，その債権者を害することを知りながら，所有する骨董品甲をＢに贈与し，その際，Ｂも甲\nの贈与がＡの債権者を害することを知っていた。この事例におけるＡの債権者Ｃによる詐害行為取\n消権行使に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後記1か\nら5までのうちどれか。（解答欄は，）\nア．Ｃが詐害行為取消訴訟を提起する場合，Ａを被告としなければならない。\nイ．Ｂが，甲の贈与がＡの債権者を害することを知っていたＤに甲を売却し，引き渡した場合，\nＣは，Ｄに対し，ＢＤ間の甲の売買の取消しを請求することができる。\nウ．Ｂが，甲の贈与がＡの債権者を害することを知っていたＤに甲を売却し，引き渡した場合，\nＣは，Ｂに対し，ＡＢ間の甲の贈与の取消しを請求することができる。\nエ．Ｃによる詐害行為取消請求を認容する確定判決の効力は，Ａの全ての債権者に対してもそ\nの効力を有する。\nオ．Ｂが，甲の贈与がＡの債権者を害することを知っていたＤに甲を売却し，引き渡した場合\nにおいて，ＣのＤに対する詐害行為取消請求を認容する判決が確定したときは，Ｄは，Ｂに\n対し，代金の返還を請求することができる。",
