    "question": "ＡＢＣは，Ｄに対して，60万円の借入金債務（以下「甲債務」という。）を連帯して負担し，\n負担部分は均等とする合意をしていた。この事例に関する次のアからオまでの各記述のうち，正し\nいものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．ＤがＡに対して甲債務の支払請求訴訟を提起し，請求を認容する判決が確定した場合にお\nいて，Ｄ及びＢが別段の意思を表示していないときは，甲債務の消滅時効は，Ｂについても\n判決確定の時から新たにその進行を始める。\nイ．ＤがＣに対して甲債務を免除する意思表示をした場合において，Ｄ及びＡが別段の意思を\n表示していないときは，ＤがＡの債務を免除する意思を有していなかったとしても，Ｄは，\nＡに対して60万円の支払を請求することはできない。\nウ．甲債務と相殺適状にある30万円の乙債務をＤがＣに対して負担している場合において，\nＣが乙債務につき相殺を援用しない間に，ＤがＡに60万円の支払を請求したときは，Ａは，\n20万円についてその支払を拒むことができる。\nエ．Ｂは，甲債務の履行期にＤに対して18万円を支払った場合，Ａ及びＣに求償することは\nできない。\nオ．甲債務と相殺適状にある20万円の乙債務をＤがＣに対して負担している場合において，\nＡが，Ｃが甲債務の連帯債務者であることを知りながら，Ｃに通知せずにＤに60万円を支\n払ってＣに求償し，Ｃが乙債務との相殺をもってＡに対抗したときは，Ａは，Ｄに対し，相\n殺によって消滅すべきであった乙債務20万円の支払を請求することができる。",
