    "question": "預貯金債権以外の金銭債権についての譲渡制限の意思表示に関する次のアからオまでの各記述の\nうち，誤っているものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．譲渡制限の意思表示がされた債権が譲渡された場合において，その後に債務者が当該譲渡\nを承諾したときは，当該債権の譲渡は譲渡の時に遡って有効になる。\nイ．譲渡制限の意思表示がされた債権の差押えがされた場合，当該債権の債務者は，差押債権\n者に対し，譲渡制限の意思表示がされたことを理由としてその債務の履行を拒むことはでき\nない。\nウ．譲渡制限の意思表示がされていることを知りながら債権を譲り受けた譲受人は，債務者が\n譲受人に対して任意に弁済をしようとしても，これを直接受けることができない。\nエ．譲渡制限の意思表示がされた債権が譲渡された場合，譲受人が譲渡制限の意思表示がされ\nたことを過失なく知らなかったときであっても，債務者は，弁済の責任を免れるために，そ\nの債権の全額に相当する金銭を供託することができる。\nオ．譲渡制限の意思表示がされた債権の全額が譲渡された場合において，譲渡人について破産\n手続開始の決定があったときは，債権譲渡について第三者対抗要件を備えた譲受人は，債務\n者にその債権の全額に相当する金銭の供託をするよう請求することができる。",
