    "question": "契約の解除に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，\n後記1から5までのうちどれか。（解答欄は，）\nア．解除権の行使について期間の定めがない場合において，相手方が，解除権を有する者に対\nし，相当の期間を定めて，その期間内に解除をするかどうかを確答すべき旨の催告をしたに\nもかかわらず，当該期間内に解除の通知を受けないときは，解除権は消滅する。\nイ．契約の性質又は当事者の意思表示により，特定の日時又は一定の期間内に履行をしなけれ\nば契約の目的を達成することができない債務について，債務者が履行をしないでその時期を\n経過したときは，契約の解除がされたものとみなされ，当該債務は当然に消滅する。\nウ．債務の一部の履行が不能である場合において，残存する部分のみでは契約をした目的を達\nすることができないときは，債権者は，催告をすることなく，直ちに契約の全部の解除をす\nることができる。\nエ．解除権を有する債権者が，過失によって契約の目的物を著しく損傷した場合には，その債\n権者が解除権を有することを知らなかったとしても，解除権は消滅する。\nオ．解除権が行使された場合の原状回復において，金銭以外の物を返還するときは，その物を\n受領した時以後に生じた果実をも返還する義務がある。",
