    "question": "賃貸借に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後記\n1から5までのうちどれか。（解答欄は，）\nア．賃貸不動産が譲渡され，その不動産の賃貸人たる地位がその譲受人に移転したときは，譲\n渡人が負っていた賃借人に対する費用の償還に係る債務は，譲受人が承継する。\nイ．賃貸人は，賃借人の責めに帰すべき事由によって賃貸物の使用及び収益のために修繕が必\n要となったときであっても，その修繕をする義務を負う。\nウ．賃借物の一部が滅失その他の事由により使用及び収益をすることができなくなった場合に\nおいて，それが賃借人の責めに帰することができない事由によるものであるときは，賃料は，\nその使用及び収益をすることができなくなった部分の割合に応じて，減額される。\nエ．賃借人が適法に賃借物を転貸し，その後，賃貸人が賃借人との間の賃貸借を合意により解\n除した場合，賃貸人は，その解除の当時，賃借人の債務不履行による解除権を有していたと\nきであっても，その合意解除をもって転借人に対抗することはできない。\nオ．賃貸借が終了した場合，賃借人は，通常の使用及び収益によって生じた賃借物の損耗につ\nいては，原状に復する義務を負わない。",
