    "question": "組合に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後記1から\n5までのうちどれか。（解答欄は，）\nア．組合員は，組合財産に属する金銭債権につき，その持分に応じて単独で権利を行使するこ\nとができる。\nイ．組合の業務の決定は，業務執行者があるときであっても，組合員の過半数をもってする。\nウ．組合の存続期間を定めた場合であっても，各組合員は，やむを得ない事由があるときは，\n脱退することができる。\nエ．組合の成立後に新たに加入した組合員は，その加入前に生じた組合の債務について弁済す\nる責任を負わない。\nオ．組合員は，組合員の過半数の同意がある場合には，清算前に組合財産の分割を求めること\nができる。",
