    "question": "普通養子縁組に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，\n後記1から5までのうちどれか。（解答欄は，）\nア．17歳の者が縁組をして養子となるには，その法定代理人の同意を得なければならない。\nイ．後見人が被後見人を養子とするには，家庭裁判所の許可を得なければならない。\nウ．配偶者のある者が配偶者の嫡出子を養子とする場合には，配偶者の同意を得ることを要し\nない。\nエ．自己の孫を養子とする場合には，その孫が未成年者であっても，家庭裁判所の許可を得る\nことを要しない。\nオ．縁組の当事者の一方が死亡した場合には，他方の当事者は，家庭裁判所の許可を得なけれ\nば離縁をすることができない。",
