    "question": "後見に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後記1\nから5までのうちどれか。（解答欄は，）\nア．未成年後見人が数人ある場合，身上の監護に関する権限については，家庭裁判所は，職権\nで，各未成年後見人が単独で又は数人の未成年後見人が職務を分掌して，その権限を行使す\nべきことを定めることができる。\nイ．成年後見人が成年被後見人を代理してその居住している建物を売却する場合には，家庭裁\n判所の許可を得なければならない。\nウ．未成年被後見人Ａが成年に達した後後見の計算の終了前にＡと未成年後見人との間で契約\nを締結した場合，Ａは，その契約を取り消すことができる。\nエ．成年後見人が成年被後見人を代理して預金の払戻しを受けるには，後見監督人があるとき\nは，その同意を得なければならない。\nオ．任意後見契約が登記されている場合に家庭裁判所が後見開始の審判をするには，本人の利\n益のため特に必要があると認めるときでなければならない。",
