    "label": "第15問",
    "question": "相続と贈与に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っているものを組\nみ合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．特別受益に当たる贈与の価額がその受贈者である相続人の具体的相続分の価額を超える場\n合，その相続人は，超過した価額に相当する財産を他の共同相続人に返還しなければならな\nい。\nイ．Ａが，婚姻後21年が経過した時点で，Ａとその配偶者Ｂが居住するＡ所有のマンション\n甲をＢに贈与し，その後に死亡した場合，当該贈与については，その財産の価額を相続財産\nに算入することを要しない旨の意思表示（持戻し免除の意思表示）がされたものと推定され\nる。\nウ．特別受益に当たる贈与は，地震により目的物が滅失した場合であっても，相続開始の時に\nおいてなお原状のままであるものとみなしてその価額を定める。\nエ．不動産の死因贈与の受贈者Ａが贈与者Ｂの相続人である場合において，限定承認がされた\nときは，死因贈与に基づくＢからＡへの所有権移転登記が相続債権者Ｃによる差押登記より\nも先にされたとしても，Ａは，Ｃに対し，その不動産の所有権の取得を対抗することができ\nない。\nオ．特別受益に当たる贈与は，当事者双方が遺留分権利者に損害を加えることを知ってしたも\nのでない場合，相続開始前の10年間にしたものに限り，遺留分を算定するための財産の価\n額に算入される。",
