    "question": "監査役会設置会社及び監査等委員会設置会社に関する次のアからオまでの各記述のうち，正しい\nものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．監査役会設置会社においては，各監査役は，監査報告を作成することを要しない。\nイ．監査等委員会設置会社において，監査等委員会が選定する監査等委員は，株主総会において，\n監査等委員である取締役以外の取締役の報酬について監査等委員会の意見を述べることがで\nきる。\nウ．監査役会設置会社において，監査役の報酬について，株主総会の決議によって，監査役の全\n員の報酬の総額のみを定めたときは，各監査役の個人別の報酬の額は，当該総額の範囲内に\nおいて，監査役の過半数をもって行う監査役会の決議によって定めなければならない。\nエ．監査等委員会設置会社は，取締役会の決議によって重要な財産の処分及び譲受けの決定を取\n締役に委任することができる旨を定款で定めることができる。\nオ．監査役会設置会社は，監査役会を招集する監査役を特定の監査役に限定する旨を定款で定め\nることができる。",
