    "question": "株式会社の資本金の額及び発行済株式の総数に関する次のアからオまでの各記述のうち，誤って\nいるものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．株式会社が自己株式を消却することにより，発行済株式の総数は減少するが，資本金の額は\n減少しない。\nイ．株式会社が株式の併合をすることにより，発行済株式の総数は減少するが，資本金の額は減\n少しない。\nウ．株式会社がその処分する自己株式を引き受ける者の募集をし，自己株式を処分することによ\nり，発行済株式の総数は増加しないが，資本金の額は増加する。\nエ．資本金の額は，株式会社の業績と連動して増加し，又は減少する。\nオ．発行済株式の総数が増加し，又は減少した場合には，変更の登記をしなければならない。",
