    "label": "第24問",
    "question": "持分会社に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後\n記1から5までのうちどれか。（解答欄は，）\nア．合名会社を設立する場合には，当該合名会社の社員になろうとする者は，定款の作成後，合\n名会社の設立の登記をする時までに，その出資の全部を履行しなければならない。\nイ．合資会社の有限責任社員が無限責任社員となった場合には，当該無限責任社員となった者は，\nその者が無限責任社員となる前に生じた当該合資会社の債務については，無限責任社員とし\nてこれを弁済する責任を負わない。\nウ．債権者が合資会社の社員の持分を差し押さえたときは，その差押えは，持分の払戻しを請求\nする権利に対しても，その効力を有する。\nエ．合名会社は，会計帳簿及び各事業年度に係る計算書類を作成し，会社法所定の期間保存しな\nければならない。\nオ．合同会社は，その社員の全部を無限責任社員とする定款の変更をすることにより，合名会社\nとなる。",
