    "label": "第27問",
    "question": "個人商人（小商人に当たる者を除く。）に関する次のアからオまでの各記述のうち，正しいもの\nを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．個人商人の商号は，その個人商人の氏又は名のいずれかを含まなければならない。\nイ．個人商人は，その商号の登記をしないこともできる。\nウ．支配人は，個人商人に代わって，その営業に関し，裁判外の行為をする権限は有するが，裁\n判上の行為をする権限は有しない。\nエ．個人商人は，貸借対照表を作成しなければならないが，それを公告することは要しない。\nオ．代理商の留置権の目的物は，個人商人の所有する物又は有価証券であることを要する。",
