    "year": 2020,
    "year_label": "R2",
    "subject": "民事訴訟法",
    "label": "第36問",
    "question": "送達に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わせ\nたものは，後記1から5までのうちどれか。（解答欄は，）\nア．訴訟代理人がある間は，当事者本人に対してした訴訟関係書類の送達は無効である。\nイ．不適法なことが明らかな訴えであって，当事者のその後の訴訟活動により適法とすること\nが全く期待することができないものを，口頭弁論を経ずに判決で却下する場合には，被告に\n対し訴状を送達することを要しない。\nウ．訴訟代理人がない場合には，当事者は，送達を受けるべき場所を受訴裁判所に届け出るこ\nとを要しない。\nエ．訴状及び第1回口頭弁論期日の呼出状の公示送達がされた場合には，被告が口頭弁論の期\n日に出頭せず訴状に記載された請求原因事実を争うことを明らかにしないときであっても，\n被告がその事実を自白したものとはみなされない。\nオ．書類の受領について相当のわきまえのある同居者が受送達者宛ての訴訟関係書類の交付を\n受けた場合において，当該同居者と受送達者との間に，その訴訟に関して事実上の利害関係\nの対立があるときは，受送達者に対する送達の効力が生じない。",
