    "question": "弁論準備手続と書面による準備手続との比較に関する次のアからオまでの各記述のうち，正し\nいものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．地方裁判所においては，弁論準備手続及び書面による準備手続のいずれであっても，受命\n裁判官が手続を主宰することができる。\nイ．音声の送受信により同時に通話をすることができる方法（以下「電話会議」という。）によ\nり手続を行う場合に，弁論準備手続の期日においては必ず当事者の一方が裁判所に出頭しな\nければならないが，書面による準備手続の協議においてはいずれの当事者も裁判所に出頭し\nなくともよい。\nウ．弁論準備手続の期日及び書面による準備手続のいずれにおいても，裁判所は，文書の証拠\n調べをすることができない。\nエ．裁判長は，弁論準備手続及び書面による準備手続のいずれにおいても，準備書面の提出を\nすべき期間を定めなければならない。\nオ．電話会議により手続が行われる場合に，弁論準備手続期日においては当事者双方が口頭に\nより訴訟上の和解をすることができるが，書面による準備手続の協議においてはすることが\nできない。",
