    "question": "法の下の平等に関する次のアからウまでの各記述のうち，ａは最高裁判所の判例を要約したもの\nであり，ｂはその批判として書かれたものである。ｂがａの批判となっている場合には1を，そう\nでない場合には2を選びなさい。（解答欄は，アからウの順にから）\n\nア．ａ．尊属の殺害について，尊属に対する尊重報恩は，社会生活上の基本的道義であり，この\nような自然的情愛ないし普遍的倫理の維持は，刑法上の保護に値するから，これを刑の加\n重要件とする規定を設けても，直ちに合理的な根拠を欠くものとは認められない。\nｂ．尊属がただ尊属なるがゆえに特別の保護を受けるべきであるとの考えは，個人の尊厳と\n人格価値の平等を基本とする民主主義の理念と抵触する。",
