    "question": "憲法第21条に関する次のアからウまでの各記述について，ｂの見解がａの見解の根拠となって\nいる場合には1を，そうでない場合には2を選びなさい。（解答欄は，アからウの順にか\nら）\n\nア．ａ．「検閲」とは，行政権が主体となって，思想内容等の表現物を対象とし，その全部又は\n一部の発表の禁止を目的として，対象とされる一定の表現物につき網羅的一般的に，発表\n前にその内容を審査した上，不適当と認めるものの発表を禁止することを，その特質とし\nて備えるものであり，絶対的に禁止される。\nｂ．大日本帝国憲法下においては，文書，図画ないし新聞，雑誌等を出版直前ないし発行時\nに提出させた上，その発売，頒布を禁止する権限が内務大臣に与えられ，その運用を通じ\nて実質的な検閲が行われたほか，映画フィルムにつき典型的な検閲が行われる等，思想の\n自由な発表，交流が妨げられるに至った経験を有する。",
