    "question": "憲法第21条に関する次のアからウまでの各記述について，ｂの見解がａの見解の根拠となって\nいる場合には1を，そうでない場合には2を選びなさい。（解答欄は，アからウの順にか\nら）\n\nイ．ａ．公務員又は公職選挙の候補者に対する評価，批判等の表現行為に関する出版物の公布等\nの事前差止めは，原則として許されず，その表現内容が真実でなく，又はそれが専ら公益\nを図る目的のものではないことが明白であって，かつ，被害者が重大にして著しく回復困\n難な損害を被るおそれがあるときにのみ例外的に許される。\nｂ．表現行為に対する事前抑制は，表現物がその自由市場に出る前に抑止してその内容を読\n者等の側に到達させる途を閉ざし又はその到達を遅らせてその意義を失わせ，公の批判の\n機会を減少させるものであり，性質上，予測に基づくものとならざるを得ないこと等から\n広汎にわたりやすく，濫用のおそれがある上，実際上の抑止的効果が大きい。",
