    "question": "文書偽造罪に関する次のアからオまでの各記述を判例の立場に従って検討した場合，誤っている\nものの組合せは，後記1から5までのうちどれか。（解答欄は，）\nア．公文書に限らず，私文書であっても，その写しは，文書偽造罪の客体となり得る。\nイ．行使の目的で，交通事件原票中の供述書の署名欄に，一定の範囲で定着した通称名を記載し\nた場合，私文書偽造罪は成立しない。\nウ．会社の代表取締役が，個人として同社から貸付けを受けていた債務についての抵当権抹消登\n記手続をするため，その権限を濫用し，代表取締役名義の債権放棄書を作成した場合，私文書\n偽造罪は成立しない。\nエ．公文書の内容を改ざんし，これを原稿としてファクシミリで相手方に送信した場合，送信に\n供した当該原稿が公文書偽造罪の客体であって，受信書面は同罪の客体とならない。\nオ．行使の目的で，銀行預金通帳の預金受入年月日を改ざんする行為は，私文書の変造であって，\n偽造ではない。",
