    "id": "r1_keipo_16",
    "year": 2019,
    "year_label": "R1",
    "subject": "刑法",
    "label": "第10問",
    "question": "学生Ａ，Ｂ及びＣは，監禁罪の客体に関して，次の各【見解】のうち，いずれか異なる見解を採\nり，後記【事例】について【会話】のとおり検討している。学生Ａ，Ｂ及びＣの採る見解として正\nしいものの組合せは，後記1から5までのうちどれか。（解答欄は，）\n【見解】\nア．監禁されている時点で移動する一般的な能力がある者は，その時点で移動できなくても，監\n禁罪の客体となる。\nイ．監禁されている時点で移動する一般的な能力があり，その時点で現実に移動できる者は，監\n禁罪の客体となる。\nウ．監禁されている時点で移動する一般的な能力があり，その時点で現実に移動でき，かつ，移\n動する意思がある者は，監禁罪の客体となる。\n【事例】\n乙が窓のない部屋の中に一人でいたところ，甲は，午後1時から午後3時までの間，その部屋\nの唯一の出入口であるドアに外から施錠し，その間，乙がその部屋の外に出られないようにした。\n【会話】\n学生Ａ．乙が甲による施錠に気付かなかった場合，Ｂ君が採る見解によれば，監禁罪は成立しま\nすか。\n学生Ｂ．成立します。\n学生Ｃ．私が採る見解でも成立します。では，乙が午後0時30分頃に眠ってしまい，その後，\n午後2時頃に目覚めて，甲による施錠に気付かないまま午後4時まで室内で過ごした場合，\nＡ君が採る見解によれば，監禁罪は成立しますか。\n学生Ａ．成立しません。\n学生Ｂ．私が採る見解では，結論はＡ君と異なります。では，今のＣ君の事例を少し修正し，乙\nが午後3時過ぎに目覚め，甲による施錠に気付かなかったという場合，Ｃ君が採る見解に\nよれば，監禁罪は成立しますか。\n学生Ｃ．成立しません。",
    "question_no": 16,
