    "year_label": "R1",
    "subject": "刑事訴訟法",
    "label": "第18問",
    "question": "弁護人の活動に関する次のアからオまでの各記述のうち，正しいものの組合せは，後記1から5\nまでのうちどれか。（解答欄は，）\nア．警察官が捜索許可状に基づき被疑者方を捜索する場合，弁護人は，当該捜索許可状の執行に\n立ち会う権利がある。\nイ．裁判官は，逃亡し又は罪証を隠滅すると疑うに足りる相当な理由があるときは，検察官の請\n求により又は職権で，勾留されている被疑者と弁護人との接見を禁じることができる。\nウ．弁護人は，勾留されている被疑者の勾留の期間を延長する裁判に対して，準抗告をすること\nができる。\nエ．勾留されている被疑者の弁護人は，裁判官に勾留の理由の開示を請求することができる。\nオ．弁護人は，起訴前に，被疑者の勾留状の謄本の交付を請求することはできない。",
