    "subject": "刑事訴訟法",
    "label": "第19問",
    "question": "公訴の提起に関する次のアからオまでの各記述のうち，誤っているものは幾つあるか。後記1か\nら6までのうちから選びなさい。ただし，判例がある場合には，それに照らして考えるものとする。\n（解答欄は，）\nア．公訴事実として，数個の訴因を予備的に記載することは許されない。\nイ．起訴状の謄本が公訴の提起があった日から2か月以内に被告人に送達されなかったため，公\n訴が棄却された場合，公訴の提起により進行を停止していた公訴時効は，公訴棄却の裁判が確\n定した時から再びその進行を始める。\nウ．共犯の1人に対してした公訴の提起による時効の停止は，他の共犯に対してその効力を有し\nない。\nエ．検察官は，公訴を提起するに足りる犯罪の嫌疑が十分にあると思料するときは，必ず公訴を\n提起しなければならない。\nオ．公訴の提起は，緊急やむを得ない場合には，起訴状の提出によらず，口頭によることもでき\nる。",
