    "subject": "刑事訴訟法",
    "label": "第20問",
    "question": "被害者特定事項の秘匿に関する次のアからオまでの各記述のうち，正しいものの組合せは，後記\n1から5までのうちどれか。（解答欄は，）\nア．強制わいせつ致死事件の被害者の兄弟姉妹は，被害者特定事項を公開の法廷で明らかにしな\nいよう申し出ることはできない。\nイ．傷害事件の被害者は，犯行の態様，被害の状況その他の事情により，被害者特定事項が公開\nの法廷で明らかにされることにより被害者の名誉又は社会生活の平穏が著しく害されるおそれ\nがある場合，被害者特定事項を公開の法廷で明らかにしないよう申し出ることができる。\nウ．被害者特定事項を公開の法廷で明らかにしない旨の決定がされた場合，被害者を証人として\n尋問する際には，被告人と被害者との間で相互に相手の状態を認識することができないように\nするための遮へい措置を講じなければならない。\nエ．被害者特定事項を公開の法廷で明らかにしない旨の決定がされた場合，裁判長は，弁護人の\n尋問が被害者特定事項にわたるときは，当該尋問を必ず制限しなければならない。\nオ．被害者特定事項を公開の法廷で明らかにしない旨の決定に対して，抗告することはできない。",
