    "year_label": "R1",
    "subject": "刑事訴訟法",
    "label": "第21問",
    "question": "次の【事例】における被害者Ｖの証人尋問に関して述べた後記アからオまでの【記述】のうち，\n誤っているものの組合せは，後記1から5までのうちどれか。ただし，判例がある場合には，それ\nに照らして考えるものとし，対象となる書面又は物については，あらかじめ相手方に閲覧する機会\nを与えたものとする。（解答欄は，）\n【事例】\n甲は，Ｖの顔面を鉄パイプで殴打して傷害を負わせたという傷害の事実で公訴を提起された。甲\nは，公判において公訴事実を否認し，検察官の請求により，Ｖの証人尋問が実施された。\n【記述】\nア．検察官は，Ｖの供述を明確にするため必要があるときは，裁判長の許可を受けて，実況見分\n調書に添付された現場見取図を利用して尋問することができる。\nイ．検察官や弁護人は，証拠調べを終わったものでない書面又は物については，これをＶに示し\nて尋問することができない。\nウ．検察官は，現場に遺留された鉄パイプにつき，犯行に使用された鉄パイプとの同一性をＶに\n尋問する場合に必要があるときは，裁判長の許可を受けずにこれを示すことができる。\nエ．検察官が，捜査段階で撮影されたＶによる被害再現写真をＶに示すことについては，弁護人\nが異議がないと述べた場合に限り許される。\nオ．検察官は，Ｖの記憶が明らかでない被害状況についてその記憶を喚起するため必要があると\nきは，裁判長の許可を受けて，Ｖが被害状況について記載していたメモを示して尋問すること\nができる。",
