    "year": 2019,
    "year_label": "R1",
    "subject": "刑事訴訟法",
    "label": "第23問ア",
    "question": "違法収集証拠の証拠能力に関する次のアからオまでの各記述のうち，正しいものには1を，誤っ\nているものには2を選びなさい。ただし，判例がある場合には，それに照らして考えるものとする。\n（解答欄は，アからオの順にから）\n\nア．違法に収集された証拠物の証拠能力が否定されるか否かは，専ら憲法の解釈に委ねられてお\nり，憲法第31条の適正手続の保障自体の要請として，証拠物の収集手続に重大な違法があり，\nこれを使用して被告人を処罰することによって手続全体が適正を欠くものとなる場合に限っ\nて，その証拠能力が否定される。",
