    "subject": "刑事訴訟法",
    "label": "第23問ウ",
    "question": "違法収集証拠の証拠能力に関する次のアからオまでの各記述のうち，正しいものには1を，誤っ\nているものには2を選びなさい。ただし，判例がある場合には，それに照らして考えるものとする。\n（解答欄は，アからオの順にから）\n\nウ．証拠物の収集手続にその証拠能力を否定すべき重大な違法があるか否かを判断するに当たり，\n手続違反がなされた際の状況や適法になし得た行為からの逸脱の程度を考慮することはできる\n- 14 -\nが，警察官の，令状主義に関する諸規定を潜脱しようとの意図の有無を考慮することはできな\nい。",
