    "subject": "刑事訴訟法",
    "label": "第24問",
    "question": "次のⅠ，Ⅱの【見解】は，犯行を否認する甲を有罪とするに当たり，甲と共に犯行を行った旨自\n白する乙の供述につき，補強証拠を必要とするか否かに関するものである。【見解】に関する後記\nアからオまでの【記述】のうち，正しいものは幾つあるか。後記1から6までのうちから選びなさ\nい。（解答欄は，）\n【見解】\nⅠ．甲を有罪とするには，乙の供述につき補強証拠を必要とする。\nⅡ．甲を有罪とするには，乙の供述につき補強証拠を必要としない。\n【記述】\nア．刑事訴訟法第319条第2項の規定は，自由心証主義の例外であるから限定的に解すべきで\nあると考えると，Ⅱの見解に結び付きやすい。\nイ．Ⅰの見解に対しては，他に補強証拠がない限り，否認した甲は有罪，自白した乙は無罪にな\nるという非常識な結論が生じるとの批判がある。\nウ．自白の証明力の過大評価を防止するという刑事訴訟法第319条第2項の規定の趣旨からす\nれば，本人の自白と共犯者の自白を区別する理由がないと考えると，Ⅱの見解に結び付きやす\nい。\nエ．共犯者である乙の自白は，甲の公判において反対尋問による吟味を経るため，証明力が高い\nと考えると，Ⅱの見解に結び付きやすい。\nオ．Ⅰの見解のうち，補強証拠を必要とする範囲を法益侵害があった事実とそれが何人かの犯罪\n行為によるものであることで足りるとする立場に対しては，共犯者の自白には，引込みや責任\n転嫁の危険があるが，それらの危険を防止することはできないとの批判がある。",
