    "question": "次のアからオまでの各記述のうち，正しいものの組合せは，後記1から5までのうちどれか。た\nだし，判例がある場合には，それに照らして考えるものとする。（解答欄は，）\nア．有罪認定に必要とされる立証の程度としての「合理的な疑いを差し挟む余地がない」とは，\n反対事実が存在する疑いを全く残さない場合をいうものではなく，抽象的な可能性としては反\n対事実が存在するとの疑いを入れる余地があっても，健全な社会常識に照らして，その疑いに\n合理性がないと一般的に判断される場合には有罪認定を可能とする趣旨である。\nイ．直接証拠によって事実を認定すべき場合と，情況証拠によって事実を認定すべき場合とで，\n求められる証明の程度に異なるところはない。\nウ．裁判官が，証人の証言の信用性を判断する際には，その証言内容のみによって判断しなけれ\nばならず，その証人の公判廷での表情や態度を考慮してはならない。\nエ．略式手続においては，犯罪の証明の程度は，証拠の優越で足りる。\nオ．裁判所は，被告人の精神状態につき，精神医学者の意見が鑑定等として証拠になっている場\n合には，その意見のとおりに認定しなければならない。",
