    "question": "Ａ，Ｂ及びＣが各3分の1の割合で甲建物を共有している場合に関する次のアからオまでの各記\n述のうち，判例の趣旨に照らし正しいものを組み合わせたものは，後記1から5までのうちどれか。\n（解答欄は，）\nア．Ａは，その持分に抵当権を設定する場合，Ｂ及びＣの同意を得る必要がある。\nイ．ＤがＡ，Ｂ及びＣに無断でＤ名義の所有権移転登記をした場合，Ａは，Ｂ及びＣの同意を得\nることなく単独で，Ｄに対してその所有権移転登記の抹消登記手続を請求することができる。\nウ．Ａは，その持分を放棄する場合，Ｂ又はＣの同意を得る必要がある。\nエ．ＡがＢ及びＣに無断で甲建物をＥに引き渡し，無償で使用させている場合，Ｂは，Ｃの同意\nを得ることなく単独で，Ｅに対して甲建物の明渡しを請求することができる。\nオ．ＡがＢに対して甲建物の管理に関する債権を有する場合において，Ｂがその持分をＦに譲渡\nしたときは，Ａは，Ｆに対してもその債権を行使することができる。",
