    "question": "財産分与に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っているものを組み\n合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．離婚に伴う財産分与は，離婚後における一方の当事者の生計の維持を図ることを目的として\nもすることができる。\nイ．離婚に伴う財産分与請求権については，協議又は審判その他の手続によって具体的内容が形\n成されるまでは，これを保全するために債権者代位権を行使することはできない。\nウ．離婚に伴う財産分与を得た者は，その財産分与が損害賠償の要素を含む趣旨とは解されない\nときには，別個に不法行為を理由として離婚による慰謝料を請求することを妨げられない。\nエ．離婚に伴う財産分与としてされた財産処分は，詐害行為として取り消されることはない。\nオ．内縁の夫が死亡して内縁関係が解消したときには，内縁の妻は，内縁の夫の相続人に対し，\n財産の分与を請求することができる。",
