    "question": "異なる種類の株式に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたも\nのは，後記1から5までのうちどれか。（解答欄は，）\nア．会社法上の公開会社は，株主に対してその有する当該種類の株式の数にかかわらず同額の剰\n余金の配当をすることを内容とする種類の株式を発行することはできない。\nイ．会社法上の公開会社は，当該種類の株式の株主が1株につき複数個の議決権を有することを\n内容とする種類の株式を発行することができる。\nウ．指名委員会等設置会社は，当該種類の株式の種類株主を構成員とする種類株主総会において\n取締役を選任することを内容とする種類の株式を発行することができない。\nエ．株主総会において決議をすることができる事項の全部につき議決権を行使することができな\nい議決権制限株式の株主であっても，当該種類の株式の種類株主を構成員とする種類株主総\n会においては，議決権を有する。\nオ．定款で定めた各種類の株式の発行可能種類株式総数の合計数は，定款で定めた発行可能株式\n総数と一致していなければならない。",
