    "subject": "商法",
    "label": "第18問",
    "question": "株式の譲渡及び株主名簿の名義書換に関する次のアからオまでの各記述のうち，正しいものを組\nみ合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．判例の趣旨によれば，株式を譲り受けた株式取得者が株主名簿の名義書換の請求をしたにも\nかかわらず，株式会社が正当な事由なく当該請求に応じなかったときは，当該株式会社は，\n株主名簿の名義書換がないことを理由として，株式の譲渡を否定することができず，当該株\n式取得者を株主として取り扱わなければならない。\nイ．判例の趣旨によれば，株券発行会社の株式について，株式会社が定めた剰余金の配当の基準\n日より前に株券が交付されて譲渡されたが，当該基準日までに株主名簿の名義書換の請求が\nされなかったときは，株主名簿上の株主である譲渡人が適法に配当金を受領することができ，\n譲渡人は，譲受人に対し，受領した配当金相当額の金員について不当利得返還義務を負わな\nい。\nウ．相続により譲渡制限株式を取得した株式取得者が株式会社に対し，株主名簿の名義書換の請\n求をするには，当該譲渡制限株式を取得したことについて当該株式会社の承認を受けていな\nければならない。\nエ．振替株式は，株券発行会社でない株式会社の株式であるから，振替株式の譲渡は，当事者間\nにおいては，意思表示のみによって，その効力を生ずる。\nオ．振替株式に係る株主名簿の名義書換は，振替機関から株式会社に対してされる総株主通知に\n基づいて行われる。",
