    "question": "種類株式発行会社でない株式会社の株主総会に関する次のアからオまでの各記述のうち，正しい\nものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．株式会社が特定の株主から当該株式会社の株式を有償で取得する旨の株主総会の議案につい\nて，特定の株主に自己をも加えたものとすることを請求した株主は，特定の株主以外の株主\nの全部が当該議案について議決権を行使することができない場合を除き，当該議案について\n議決権を行使することができない。\nイ．取締役会設置会社でない株式会社が当該株式会社の譲渡制限株式の相続人に対し，当該譲渡\n制限株式を当該株式会社に売り渡すことを請求することを議案とする株主総会を招集する場\n合には，当該相続人である株主に対しては当該株主総会の招集の通知を発することを要しな\nい。\nウ．会社法上の公開会社が支配株主の異動を伴う募集株式の発行をする場合において，総株主の\n議決権の10分の1以上の議決権を有する株主が特定引受人による募集株式の引受けに反対\nする旨を当該公開会社に対し通知したときは，定款に別段の定めがある場合を除き，株主総\n会の特別決議によって，当該特定引受人に対する募集株式の割当ての承認を受けなければな\nらない。\nエ．株主総会において議決権を行使することができる株主の数が1000人以上である株式会社\nにおいて，株主総会に出席しない株主が電磁的方法による議決権の行使をすることができる\n旨を定めたときは，当該株主が書面による議決権の行使をすることができる旨を定めること\nを要しない。\nオ．吸収合併契約の承認を議案とする株主総会において書面又は電磁的方法による議決権の行使\nをすることができることとされた株主が，株主総会の日の前日までに，書面又は電磁的方法\nによって当該議案に反対する議決権の行使をした場合には，当該株主総会に先立って当該吸\n収合併に反対する旨を株式会社に対し通知したものと認められ，反対株主として株式買取請\n求をすることができる。",
