    "question": "取締役に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後記\n1から5までのうちどれか。（解答欄は，）\nア．株式会社は，破産手続開始の決定を受け，復権していない自然人を取締役として選任するこ\nとができる。\nイ．取締役会設置会社においては，第三者のために当該取締役会設置会社の事業の部類に属する\n取引をした取締役は，当該取引につき取締役会の承認を受けなかった場合であっても，当該\n取引後，遅滞なく，当該取引についての重要な事実を取締役会に報告しなければならない。\nウ．監査役設置会社が当該監査役設置会社の取締役であった者に対してその責任を追及する訴え\nを提起する場合には，当該訴えについては，代表取締役が当該監査役設置会社を代表する。\nエ．株式会社の取締役が自己のために当該株式会社とした取引によって当該株式会社に損害が生\nじたときは，当該取締役の当該株式会社に対する損害賠償責任は，総株主の同意によっても，\n免除することができない。\nオ．監査等委員会設置会社の取締役のうち社外取締役であるものについては，社外取締役である\n旨を登記しなければならない。",
