    "subject": "商法",
    "label": "第23問",
    "question": "株式会社の資本金及び準備金に関する次のアからオまでの各記述のうち，正しいものを組み合わ\nせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．株式会社が取得条項付新株予約権を取得するのと引換えに当該取得条項付新株予約権の新株\n予約権者に対して当該株式会社の新たに発行する株式を交付するときは，当該株式会社は，\n資本金の額を増加することができない。\nイ．株式会社が株式の発行と同時に資本金の額を減少する場合において，当該資本金の額の減少\nの効力が生ずる日後の資本金の額が当該日前の資本金の額を下回らないときは，当該株式会\n社の債権者は，当該株式会社に対し，当該資本金の額の減少について異議を述べることがで\nきない。\nウ．株式会社が準備金の額を減少する場合において，減少する準備金の額の全部を資本金とする\nときは，当該株式会社の債権者は，当該株式会社に対し，当該準備金の額の減少について異\n議を述べることができない。\nエ．株式会社が剰余金の額を減少して，資本金の額を増加するには，株主総会の特別決議によら\nなければならない。\nオ．株式会社における資本金の額の減少について承認をしたものとみなされた債権者は，当該資\n本金の額の減少の無効の訴えを提起することができない。",
