    "year": 2019,
    "year_label": "R1",
    "subject": "民事訴訟法",
    "label": "第32問",
    "question": "選定当事者に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み\n合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．訴訟の目的である権利が同一の事実上及び法律上の原因に基づき，かつ，主要な攻撃防御\n方法が共通である複数の者は，民事訴訟法第30条第1項の「共同の利益を有する多数の者」\nに当たる。\nイ．複数の選定当事者が選定されている場合において，その一部が訴訟係属中に死亡したとき\nは，他の選定当事者は，その資格を失う。\nウ．選定当事者は，選定者の特別の授権がなければ，選定者のために訴えの取下げ，和解並び\nに請求の放棄及び認諾をすることができない。\nエ．訴訟係属後に選定当事者が選定された場合には，選定者は，脱退のための行為をしなくと\nも，当該訴訟から脱退する。\nオ．選定者が訴訟係属後に選定当事者の選定の取消しをした場合には，当該選定者が裁判所に\n対しその事実を書面で証明しなければ，当該取消しの効力は生じない。",
