    "subject": "民事訴訟法",
    "label": "第38問",
    "question": "弁論準備手続に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，\n後記1から5までのうちどれか。（解答欄は，）\nア．裁判所は，事件を弁論準備手続に付する場合には，当事者の意見を聴かなければならない。\nイ．裁判所は，弁論準備手続において，当事者の一方が申し出た者の傍聴を許す場合には，他\n方の当事者の意見を聴かなければならない。\nウ．裁判所は，弁論準備手続において，証拠の申出に関する裁判をすることはできるが，証拠\n調べをすることはできない。\nエ．当事者は，口頭弁論において，弁論準備手続の結果を陳述しなければならない。\nオ．裁判所は，受命裁判官又は受託裁判官に弁論準備手続を行わせることができる。",
