    "question": "確定判決の効力が及ぶ者に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っ\nているものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．ＸがＹに対して土地の賃貸借契約終了に基づき建物収去土地明渡しを求める訴えを提起し，\nＸの請求を認容する判決が確定した後，ＺがＹから当該建物を借り受けて当該土地を占有す\nる場合に，この判決の効力は，Ｚにも及ぶ。\nイ．ＸがＹ法人に対して損害賠償を求める訴えを提起し，Ｘの請求を認容する判決が確定した\n後，Ｙ法人がＺ法人を新たに設立して資産を移転したが，法人格の濫用であるとしてＺ法人\nの法人格が否認される場合に，この判決の効力は，Ｚ法人にも及ぶ。\nウ．ＸがＹを被告として離婚の訴えを提起し，Ｘの請求を棄却する判決が確定した場合に，こ\nの判決の効力は，第三者にも及ぶ。\nエ．ＸがＹに対して動産の引渡しを求める訴えを提起し，Ｘの請求を認容する判決が確定した\n場合に，この判決の効力は，その訴えに係る第一審の口頭弁論の終結前にＹから当該動産を\n賃借したＺにも及ぶ。\nオ．ＸがＹに対して所有権移転登記の原因となる行為の不存在を理由として所有権に基づき不\n動産の所有権移転登記抹消登記手続を求める訴えを提起し，Ｘの請求を認容する判決が確定\nした後，ＹがＺに対して当該不動産の所有権移転登記手続をした場合に，この判決の効力は，\nＺにも及ぶ。",
