    "question": "次の対話は，公務員の人権に関する教授と学生の対話である。教授の各質問に対する次のアから\nウまでの学生の各回答について，それぞれ正しい場合には1を，誤っている場合には2を選びなさ\nい。（解答欄は，アからウの順にから）\n教授．公務員の地位のように権利主体と公権力との間に特殊な法律関係がある場合には，憲法の\n人権保障が原則として及ばないなどとする理論がありますね。このような理論によって公務\n員の人権に対する制約を正当化した最高裁判所の判決がありますか。\n\nア．はい。猿払事件判決（最高裁判所昭和49年11月6日大法廷判決，刑集28巻9号39\n3頁）が，先生のおっしゃる趣旨の判示をして，公務員の政治的意見表明の自由に対する制\n約を正当化しています。\n教授．あなたの言うその判決は，国家公務員法第102条第1項が一定の行動類型に属する政治\n的行為を禁止していることに伴い生じ得る意見表明の自由の制約については，どのような判\n示をしていますか。",
