    "question": "法の下の平等に関する次のアからウまでの各記述について，最高裁判所の判例の趣旨に照らして，\n正しいものには○，誤っているものには×を付した場合の組合せを，後記1から8までの中から選\nびなさい。（解答欄は，）\nア．子にとって自ら選択できないような事柄を理由に不利益を及ぼすことは許されず，子を個人\nとして尊重し，その権利を保障すべきであるという考えが確立されてきたという事情は，嫡出\n子と嫡出でない子の法定相続分を区別する合理的な根拠が失われたと判断すべき根拠となる。\nイ．憲法第14条第1項は国民に対し法の下の平等を保障した規定であり，平等の要請は，事柄\nの性質に即応した合理的な根拠に基づくものでない限り，差別的な取扱いをすることを禁止す\nる趣旨と解され，特に同項後段の事項は，合憲性の推定が排除される事項を限定列挙したもの\nである。\nウ．地方公共団体が法律の範囲内で条例を制定することができるとしている条例制定権の規定\n（憲法第94条）に照らすと，地方公共団体が売春の取締りについて各別に条例を制定する結\n果，その取扱いに差別を生ずることがあっても，地域差の故をもって憲法第14条第1項に反\nするとはいえない。",
