    "question": "次の見解は，インターネット上の名誉毀損罪の成否と表現の自由について論じたものである。こ\nの見解に関する次のアからエまでの各記述について，それぞれ正しい場合には1を，誤っている場\n合には2を選びなさい。（解答欄は，アからエの順にから）\n「インターネットの利用者は，自己の見解を外部に向かって発信することができるから，インタ\nーネットを利用している被害者は，自己に向けられた加害者のインターネット上の表現行為に対し，\n言論による反論が可能である。したがって，インターネットの利用者が名誉毀損の表現行為をした\n場合には，新聞などのマス・メディアを通じた表現の場合よりも，名誉毀損罪の成立する範囲を限\n定すべきである。」\n\nイ．言論の応酬により当不当を判断することができるのは意見や論評であって，事実の摘示によ\nる名誉毀損の場合には，被害者と加害者が言論の応酬をしても，インターネット利用者は真偽\nを判断することができないという指摘は，この見解の根拠となり得る。",
