    "question": "取材フィルム又はビデオテープの押収が問題となった「博多駅事件決定」（最高裁判所昭和44\n年11月26日大法廷決定，刑集23巻11号1490頁），「日本テレビ事件決定」(最高裁判所\n平成元年1月30日第二小法廷決定，刑集43巻1号19頁)及び「ＴＢＳ事件決定」(最高裁判所\n平成2年7月9日第二小法廷決定，刑集44巻5号421頁)に関する次のアからウまでの各記述\nについて，それぞれ正しい場合には1を，誤っている場合には2を選びなさい。（解答欄は，アか\nらウの順にから）\nア．「博多駅事件決定」は，裁判所の提出命令について適法としたが，「日本テレビ事件決定」と\n「ＴＢＳ事件決定」は，公正な刑事裁判を実現するためには，適正迅速な捜査が不可欠である\nとして，検察事務官や司法警察職員がした差押えについても，適法と認められる場合があると\nした。\nイ．「日本テレビ事件決定」と「ＴＢＳ事件決定」では，対象のビデオテープは，事件の全容を\n解明し犯罪の成否を判断する上でほとんど不可欠と認められるものであったのに対し，「博多\n駅事件決定」では，犯罪の成立は他の証拠上認められるが，事件の重要な部分の真相を明らか\nにする必要があるとして，取材フィルムの提出命令を適法とした。\nウ．3事件いずれの決定においても，それぞれその対象となった取材フィルム又はビデオテープ\nは，既にそれらが編集された上放映されており，提出命令又は差押えによって放映が不可能と\nなって報道の機会が奪われたというものではなかった。",
