    "question": "学問の自由及び教育の自由に関する次のアからウまでの各記述について，最高裁判所の判例の趣\n旨に照らして，正しいものには○，誤っているものには×を付した場合の組合せを，後記1から8\nまでの中から選びなさい。（解答欄は，）\nア．大学における学生の集会が，大学の公認した団体が大学の許可を得て開催したものであれば，\n真に学問的な研究又はその結果の発表のためのものでなく，実社会の政治的社会的活動に当た\nる場合であっても，同集会への警察官の立入りは，大学の有する学問の自由と自治を侵害する\nこととなる。\nイ．学問の自由は，学問研究の自由とその研究結果の発表の自由だけでなく，その研究結果を教\n授する自由をも含むところ，教育の本質上，教師は，高等学校以下の普通教育においても，教\n授の自由を有し，自らの判断で教育内容を決定することができるのであって，国が教育内容の\n決定に介入することは許されない。\nウ．親は，子の将来に関して最も深い関心を持ち，かつ，配慮をすべき立場にある者として，子\nに対する教育の自由を有しており，このような親の教育の自由は，主として家庭教育等学校外\nにおける教育や学校選択の自由にあらわれるところ，親の学校選択の自由は，特定の学校の選\n択を強要又は妨害された場合，その侵害が問題となり得る。",
