    "question": "居住・移転の自由に関する次のアからエまでの各記述について，明らかに誤っているものの組合\nせを，後記1から6までの中から選びなさい。（解答欄は，）\nア．自衛官につき，防衛大臣が指定する場所に居住しなければならないとする法律の規定は，当\n該国民が自ら自衛官に志願した結果として課される制約であるところ，我が国の防衛のためい\nつでも職務に従事できる態勢にあることが求められるという自衛官の職務の性質に照らし，こ\nのような居住地の制限は合理的な制限であって合憲と解される。\nイ．外務大臣において，著しくかつ直接に日本国の利益又は公安を害するおそれがあると認める\nに足りる相当な理由がある者につき一般旅券を発給しないことができるとする法律の規定は，\n単に旅券の発給を制限するに過ぎず，海外渡航の自由を制約するものではないため合憲と解さ\nれる。\nウ．住民が住所を変更したときには市町村長に届け出なければならない旨を義務付ける法律の規\n定は，住所・居所の決定や移転それ自体を制限するものではなく，規制態様が軽微である反面，\n住民票の整備により得られる公益が大きいことから合憲と解される。\nエ．破産手続中の破産者につき，裁判所の許可なく居住地を離れることを禁止する法律の規定は，\n破産手続という限られた期間内にのみ適用されるものに過ぎず，仮に裁判所の許可が得られな\nくても破産手続が終結すれば自由に居住地を離れることができるため，居住・移転の自由に対\nする制約が認められず合憲と解される。\n1．ア イ 2．ア ウ 3．ア エ 4．イ ウ 5．イ エ 6．ウ エ",
