    "subject": "行政法",
    "label": "第13問",
    "question": "以下のＡからＣは，行政上の法律関係における信義則の法理の適用に関する文章である。次のア\nからウまでの【 】内の各記述について，最高裁判所の判例に照らし，正しいものに○，誤ってい\nるものに×を付した場合の組合せを，後記1から8までの中から選びなさい。（解答欄は，）\nＡ：納税者が，所得税について，青色申告の承認を受けることなく，青色申告書による確定申告\nをしたところ，税務署長が青色申告の承認があるかどうかの確認を怠り申告書を受理し，さら\nに，翌年分以降の所得税についても青色申告用紙を送付し，青色申告書による確定申告を受理\nするなどしてきた事案に関する最高裁判所昭和62年10月30日第三小法廷判決（裁判集民\n事152号93頁）は，（ア）【租税法律主義の原則が貫かれるべき租税法律関係において，信\n義則の法理の適用が認められるかどうかの判断に当たっては，納税者が税務官庁の表示した公\n的見解を信頼して行動した後に，その表示に反する課税処分が行われたため，経済的不利益を\n受けることになったかどうか，また，その表示を信頼し，その信頼に基づいて行動したことに\nついて納税者に帰責事由がないかどうか，という点の考慮が不可欠であると判断したものであ\nる。】\nＢ：地方公共団体が一定内容の継続的な施策を決定し，特定の者に対し同施策に適合する特定内\n容の活動を促す個別的具体的な勧告ないし勧誘をし，当該特定の者も，相当長期にわたる同施\n策の継続を前提にして初めて投入した資金や労力に相応する効果を生じ得るような性質の特定\n内容の活動を行ったが，その後の施策の変更により，当該特定の者に看過し得ない程度の積極\n的損害が発生した事案に関する最高裁判所昭和56年1月27日第三小法廷判決（民集35巻\n1号35頁）は，（イ）【上記事情の下において上記損害を補償するなどの代償的措置を講ずる\nことなく施策を変更することは，それがやむを得ない客観的事情によるのでない限り，当事者\n間に形成された信頼関係を不当に破壊するものとして違法性を帯びると判断したものである。】\nＣ：原子爆弾被爆者に対する援護に関する法律等に基づき被爆者に対して支給される健康管理手\n当の受給権につき，法令上の根拠がないのに，被爆者が国外に居住地を移した場合に失権の取\n扱いとなるものと定めた違法な通達に基づき，地方公共団体が支給を打ち切った事案に関する\n最高裁判所平成19年2月6日第三小法廷判決（民集61巻1号122頁）は，（ウ）【上記通\n達に基づき違法な事務処理をしていた地方公共団体が，未支給の健康管理手当の支給義務を免\nれるために消滅時効を主張することは，特段の事情のない限り，信義則に反し許されないと判\n断したものである。】\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
