    "subject": "行政法",
    "label": "第14問",
    "question": "行政処分の効力に関する教員と学生の対話中の次のアからウまでの【 】内の各記述について，\n最高裁判所の判例に照らし，正しいものに○，誤っているものに×を付した場合の組合せを，後記\n1から8までの中から選びなさい。なお，解答に当たっては，行政庁が以下の農地買収計画を定め\nることが，いずれも旧自作農創設特別措置法（昭和21年法律第43号。昭和27年廃止）に基づ\nく行政処分であること，同法に基づく農地買収計画に対する争訟の手続は，買収対象となる農地の\n所有者が異議申立てや訴願（以下，これらを併せて「不服申立て」という。）を前置する制度であ\nったこと，同法に基づく農地買収計画に係る最高裁判所の判例で示された行政処分の効力に係る行\n政法の理論が現行法においても通用することを前提としなさい。（解答欄は，）\n教員：行政庁が，ある農地買収計画を定めた後に，その農地買収計画の内容が違法又は不当であ\nると判断した場合の行政処分の効力について考えてみましょう。当該行政庁は，当該農地買\n収計画に係る法定の不服申立て期間が徒過した後において，法律上の定めがなくても，当該\n農地買収計画を自ら取り消すことはできるでしょうか。\n学生：（ア）【農地買収計画を定めた行政庁は，当該農地買収計画に係る法定の不服申立て期間の\n徒過により争訟手続によってその効力を争い得なくなった後は，当然無効と認められる場合\nを除き，当該農地買収計画を自ら取り消すことができないものと解されます。】\n教員：では，農地買収計画が違法であるが，権限ある機関により取り消されていない場合に，そ\nの行政処分の効力がない場合とはどのような場合ですか。\n学生：（イ）【農地買収計画の違法が重大かつ明白で当然無効ならしめるものと認められる場合に\nは，権限ある機関による取消しを待たずに，その効力を有しないものと解されます。】\n教員：では，行政庁がある農地について農地買収計画を定めたが，裁決庁が当該農地の所有者か\nらの不服申立てにより当該農地買収計画から当該農地を除外する旨の裁決を行い確定したと\nいう事例で，行政処分の効力について考えてみましょう。当該裁決庁は，その裁決が違法で\nあると判断する場合に，特別の規定がなくてもその裁決を自ら職権で取り消すことができる\nでしょうか。当該裁決では，一定の争訟手続に従い，当事者を手続に関与させて，紛争の終\n局的解決を図ることを目的として，実質的には法律上の争訟を裁判していたものと認められ\nることを前提として，考えてください。\n学生：（ウ）【当該裁決は，実質的には法律上の争訟を裁判するものであることから，特別の規定\nがない限り，裁決庁が自ら取り消すことはできないものと解されます。】\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
