    "question": "行政裁量に関する次のアからウまでの各記述について，最高裁判所の判例に照らし，正しいもの\nに○，誤っているものに×を付した場合の組合せを，後記1から8までの中から選びなさい。（解\n答欄は，）\nア．裁判所は，出入国管理及び難民認定法に基づく，「在留期間の更新を適当と認めるに足りる\n相当の理由」があるかどうかに関する法務大臣の判断について，それが違法となるかどうかを\n審理，判断するに当たっては，上記法務大臣の判断が裁量権の行使としてされたものであるこ\nとを前提として，その判断の基礎とされた重要な事実に誤認があること等により上記判断が全\nく事実の基礎を欠くかどうか，又は事実に対する評価が明白に合理性を欠くこと等により上記\n判断が社会通念に照らし著しく妥当性を欠くことが明らかであるかどうかについて審理し，そ\nれが認められる場合に限り，上記判断が裁量権の範囲を超え又はその濫用があったものとして\n違法であるとすべきものである。\nイ．高等学校用の教科用図書の検定における合否の判定等に係る文部科学大臣の判断について，\n教科用図書検定調査審議会の判断の過程に，原稿の記述内容又は欠陥の指摘の根拠となるべき\n検定当時の学説状況，教育状況についての認識や，検定の基準に違反するとの評価等に看過し\n難い過誤があって，文部科学大臣の判断がこれに依拠してされたと認められる場合には，上記\n判断は，裁量権の範囲を逸脱したものとして，国家賠償法上違法となる。\nウ．公害健康被害の補償等に関する法律に基づく水俣病の認定の申請を棄却する処分の取消訴訟\nにおける裁判所の審理，判断は，処分行政庁の判断の基準とされた認定の基準に現在の最新の\n医学水準に照らして不合理な点があるか否か，公害健康被害認定審査会の調査審議及び判断の\n過程に看過し難い過誤，欠落があってこれに依拠してされた処分行政庁の判断に不合理な点が\nあるか否かといった観点から行われるべきものである。\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
