    "question": "処分性に関する次のアからウまでの各記述について，最高裁判所の判例に照らし，正しいものに\n○，誤っているものに×を付した場合の組合せを，後記1から8までの中から選びなさい。（解答\n欄は，）\nア．告示により一定の条件に合致する道を一括して道路に指定する方法でされた建築基準法第4\n2条第2項所定のいわゆるみなし道路の指定は，特定の土地について個別具体的にこれを指定\nするものではなく，不特定多数の者に対して一般的抽象的な基準を定立するものにすぎないの\nであって，これによって直ちに建築制限等の私権制限が生じるものでないから，抗告訴訟の対\n象となる行政処分に当たらない。\n（参照条文）建築基準法\n（道路の定義）\n第42条 （略）\n2 この章の規定が適用されるに至つた際現に建築物が立ち並んでいる幅員4メートル未満\nの道で，特定行政庁の指定したものは，前項の規定にかかわらず，同項の道路とみなし，\nその中心線からの水平距離2メートル（中略）の線をその道路の境界線とみなす。（以下\n略）\n3～6 （略）\nイ．労災就学援護費について，労働者災害補償保険法及び同法施行規則は，その支給の実体的及\nび手続的な要件や金額について何ら定めていないから，労災就学援護費を支給しない旨の決定\nは，行政庁が公権力の行使として一方的に決定し，取消訴訟によらなければその判断を覆すこ\nとができないとの効力が法律上与えられたものとはいえず，抗告訴訟の対象となる行政処分に\n当たらない。\nウ．病院開設中止の勧告は，医療法上は当該勧告を受けた者が任意にこれに従うことを期待して\nされる行政指導として定められているものの，当該勧告を受けた者に対し，これに従わない場\n合には，相当程度の確実さをもって，病院を開設しても保険医療機関の指定を受けることがで\nきなくなるという結果をもたらすものであり，その結果，実際上病院の開設自体を断念せざる\nを得ないことになるから，上記勧告は，抗告訴訟の対象となる行政処分に当たる。\n- 12 -\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
