    "question": "次の【事例】における甲の罪責について，判例の立場に従って検討した場合，正しいものは，後\n記1から5までのうちどれか。（解答欄は，）\n【事 例】\n甲は，バーの経営者Ａから現金を強取しようと考え，12歳の長男乙に，「Ａのバーに行って\nお金をとってきて。覆面を付けて，『金だ。』とか言ってモデルガンを見せなさい。」と言い聞か\nせた。乙は，当初警察に捕まることを恐れて嫌がっていたが，結局小遣い欲しさから承諾し，甲\nから覆面とモデルガンを受け取った。\n乙は，Ａのバーまで行き，甲から指示された方法に従って，覆面を付けモデルガンを拳銃のよ\nうに見せ掛け，Ａを脅迫してその反抗を抑圧した。さらに，乙は，自己の判断により，外から人\nが来ないようにするためバーの出入口ドアの鍵を掛け，Ａをバーのトイレに閉じ込めた。その後，\n乙は，レジ内の現金を強取し，外に出ようとしたところ，トイレから脱出して乙に向かってきた\nＡから腕をつかまれたため，これを激しく振り払った。その結果，Ａは転倒して負傷した。\n乙は，逃走して自宅に戻り，強取した現金を全て甲に渡した。甲はその現金の中から乙に小遣\nいを与え，その余を生活費等に費消した。",
