    "question": "故意に関する次の各【見解】に従って後記1から5までの各【事例】における甲の罪責を検討し\nた場合，いずれの【見解】に従うかによって，結論が異なるものはどれか。（解答欄は，）\n【見 解】\nＡ説：行為者が認識していた事実と発生した事実とが，構成要件的評価として一致する限り，発\n生した事実についての故意が認められ，殺人罪においては，客体が「およそ人」という点で\n一致していれば故意が認められる。\nＢ説：行為者が認識していた事実と発生した事実とが，具体的に一致しない限り，発生した事実\nについての故意は否定され，殺人罪においては，客体が「その人」という点で一致していな\nければ故意は認められない。\n【事 例】",
