    "label": "第7問",
    "question": "次のアからオまでの各記述を判例の立場に従って検討した場合，正しいものの組合せは，後記1\nから5までのうちどれか。（解答欄は，）\nア．甲は，同僚Ａを会社の備品倉庫内に閉じ込めて困らせようと考え，午後7時頃，Ａが一人で\n作業をしていた同倉庫の全ての出入口扉に外側から鍵を掛けた。Ａはそのことに気付かず，も\nともと同倉庫で深夜遅くまで仕事をするつもりであったので，そのまま作業を続けていたとこ\nろ，午後10時頃，たまたま同倉庫にやって来た他の従業員が出入口扉の鍵を開けた。この場\n合，甲には監禁罪は成立し得ない。\nイ．甲は，別居中の元妻Ａが単独で親権を有する生後数日のＢを連れ去ろうと考え，Ａ方を訪問\nした上，Ａがトイレに行っている隙に，ベビーベッドで寝ていたＢを連れ去った。この場合，\nＢには移動の自由が全くないから，甲には未成年者略取罪は成立し得ない。\nウ．甲は，捜査車両をのぞき見て同車両のナンバーを把握するため，警察署の建物及び敷地への\n外部からの立入りを制限するとともに内部をのぞき見ることができない構造として作用し，建\n物の利用のために供されている高さ約2．5メートルのコンクリート塀を正当な理由なくよじ\n登り，その上部に立って同警察署の敷地内の捜査車両を見て立ち去った。この場合，甲には建\n造物侵入罪は成立し得ない。\nエ．甲は，Ａに恨みを抱き，「ふざけるな。おまえの妻Ｂを酷い目に遭わせてやる。」という電子\nメールをＡ宛てに送り付けた。ＢがＡの内縁の妻であった場合，甲には脅迫罪は成立し得ない。\nオ．甲は，深夜，Ａ方に侵入し，泥酔して熟睡中のＡにわいせつ行為をして，Ａに全く気付かれ\nないままＡ方を出た後，Ａ方から約100メートル離れた路上で，警ら中の警察官Ｂから職務\n質問を受けたため，逮捕を免れる目的で，Ｂを拳骨で殴打してＢに傷害を負わせた。この場合，\n甲には準強制わいせつ致傷罪は成立し得ない。",
