    "question": "任意代理に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後\n記1から5までのうちどれか。（解答欄は，）\nア．特定の法律行為をすることを委託された代理人が本人の指図に従ってその行為をした場合，\n本人は，自ら過失によって知らなかった事情について代理人が過失なく知らなかったことを主\n張することができない。\nイ．権限の定めのない代理人は，保存行為をする権限のみを有する。\nウ．代理人が相手方と通謀して売買契約の締結を仮装した場合，相手方は，本人がその通謀虚偽\n表示を知っていたか否かにかかわらず，当該売買契約の無効を主張することができる。\nエ．代理人が保佐開始の審判を受けたときは，代理権は消滅する。\nオ．代理人が相手方と売買契約を締結した後，その代理人が制限行為能力者であったことが判明\nした場合であっても，本人は当該売買契約を行為能力の制限によって取り消すことができない。",
