    "question": "法定地上権に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合\nわせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．Ａが所有する甲土地及びその上の乙建物にＢのために共同抵当権が設定された後，乙建物が\n取り壊され，甲土地上に新たにＡが所有する丙建物が建築されて，丙建物につきＣのために抵\n当権が設定された場合において，甲土地に対するＢの抵当権の実行によりＤが甲土地を取得し\nたときは，法定地上権が成立する。\nイ．Ａが所有する更地の甲土地に第一順位の抵当権が設定された後，甲土地上にＡが所有する乙\n建物が建築され，甲土地に第二順位の抵当権が設定された場合において，第二順位の抵当権の\n実行によりＢが甲土地を取得したときは，法定地上権は成立しない。\nウ．Ａが所有する甲土地上にＢが所有する乙建物があるところ，甲土地にＣのために第一順位の\n抵当権が設定された後，Ｂが甲土地の所有権を取得し，甲土地にＤのために第二順位の抵当権\nを設定した場合において，Ｃの抵当権が弁済により消滅し，その後，Ｄの抵当権の実行により\nＥが甲土地を取得したときは，法定地上権が成立する。\nエ．Ａが甲土地及びその上の乙建物を所有しているが，甲土地の所有権移転登記をしていなかっ\nたところ，乙建物に抵当権が設定され，抵当権の実行によりＢが乙建物を取得したときは，法\n定地上権は成立しない。\nオ．ＡとＢが共有する甲土地上にＡが所有する乙建物があるところ，Ａが甲土地の共有持分につ\nいて抵当権を設定した場合において，抵当権の実行によりＣがその共有持分を取得したときは，\n法定地上権が成立する。",
