    "question": "詐害行為取消権に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組\nみ合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．相続の放棄は，相続の放棄をした債務者が債務の履行を長期間怠るなど背信性の程度が著し\nい場合に限り，詐害行為取消権の対象となる。\nイ．不動産の買主は，その売主がその不動産を第三者に贈与した場合，それによって売主が無資\n力となったとしても，当該贈与を詐害行為取消権の対象とすることができない。\nウ．詐害行為取消権の対象となる贈与の目的物が不可分なものであるときは，その価額が債権額\nを超過する場合であっても，贈与の全部について取り消すことができる。\nエ．贈与が虚偽表示に該当することを知らない転得者との関係において，当該贈与を詐害行為取\n消権の対象とすることはできない。\nオ．債務者が自己の第三者に対する債権を譲渡した場合において，債務者がこれについてした確\n定日付のある債権譲渡の通知は，詐害行為取消権行使の対象とならない。",
