    "question": "保証に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っているものを組み合わ\nせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．保証が付された債権が譲渡された場合においては，譲渡人から主たる債務者に対して債権譲\n渡の通知をすれば，保証人に対して通知をしなくても，譲受人は保証人に対して保証債務の履\n行を請求することができる。\nイ．未成年者が法定代理人の同意を得ずに債務を負担する行為をした場合において，その債務の\n保証人は，保証契約締結の当時，未成年者が法定代理人の同意を得ずに債務を負担する行為を\nしたことを知っており，かつ，その後に，当該未成年者の行為が，未成年者の行為であること\nを理由に取り消されたときは，当該未成年者が負担していた債務と同一の目的を有する独立の\n債務を負担したものと推定される。\nウ．主たる債務者が債権者に対し反対債権を有している場合であっても，保証人は，債権者から\n保証債務の履行を請求されたときは，保証債務を履行しなければならない。\nエ．主たる債務について違約金の定めがない場合，保証人は，債権者との間で，保証債務につい\nてのみ違約金を約定することができない。\nオ．特定物の売買契約が売主の債務不履行により解除され，売主が代金返還義務を負担したとき\nは，売主のための保証人は，反対の特約のない限り，当該代金返還義務について保証の責任を\n負う。",
