    "question": "遺言の方式に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っているものを組\nみ合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．自筆証書遺言における押印を指印によってすることはできない。\nイ．秘密証書遺言をするには，遺言者が証書の本文及び氏名を自書し，押印をしなければならな\nい。\nウ．公正証書遺言において，遺言者が署名することができない場合には，公証人がその事由を付\n記して，署名に代えることができる。\nエ．自筆証書遺言の加除その他の変更は，遺言者が，その場所を指示し，これを変更した旨を付\n記して特にこれに署名し，かつ，その変更の場所に押印をしなければ，その効力を生じない。\nオ．成年被後見人が事理弁識能力を一時回復した時において遺言をするには，医師二人以上の立\n会いがなければならない。",
