    "subject": "商法",
    "label": "第17問",
    "question": "株主の権利に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っているものを組\nみ合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．基準日前に株式の譲渡があった場合には，会社側においては，株主名簿の名義書換が何らか\nの都合でされていなくとも，当該譲渡を認め，基準日が定められた権利を譲受人に行使させる\nことができる。\nイ．株式会社の株主が，当該株式会社の業務及び財産の状況を調査させるため，裁判所に検査役\n選任の申立てをした時点で，当該申立てをするために必要な持株要件を満たしていたとしても，\nその後，当該株式会社が新株を発行したことにより，当該株主が当該持株要件を満たさないも\nのとなった場合には，特段の事情のない限り，当該申立ては，申立人の適格を欠くものとして\n不適法となる。\nウ．株式会社の会計帳簿の閲覧の請求をする株主は，当該請求の理由を明らかにし，かつ，当該\n請求の理由を基礎付ける事実が客観的に存在することを立証しなければならない。\nエ．株式会社の会計帳簿の閲覧の請求をした株主が当該株式会社の業務と実質的に競争関係にあ\nる事業を営む場合には，当該株式会社は，当該株主に会計帳簿の閲覧によって知り得る情報を\n自己の事業に利用するなどの主観的意図がないときであっても，当該請求を拒むことができる。\nオ．株主の提起した株主総会の決議の取消しの訴えの係属中当該株主が死亡した場合には，相続\nにより株式を取得した相続人はその訴訟の原告たる地位を承継せず，その訴訟は当然に終了す\nる。",
