    "subject": "商法",
    "label": "第18問",
    "question": "新株予約権に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後記\n1から5までのうちどれか。（解答欄は，）\nア．会社法上の公開会社が，その取締役に対し，職務執行の対価として，募集新株予約権と引換\nえに金銭の払込みを要しないこととして，その新株予約権を発行する場合には，金銭の払込み\nを要しないこととすることが当該取締役に特に有利な条件でないときであっても，株主総会の\n特別決議によって，当該募集新株予約権の募集事項を定めなければならない。\nイ．株式会社が新株予約権を発行する場合には，当該新株予約権の内容として，合併により当該\n株式会社が消滅するときは，当該新株予約権の新株予約権者に合併後存続する株式会社の新株\n予約権を交付することとする旨及びその条件を定めることはできない。\nウ. 譲渡制限新株予約権の新株予約権者は，株式会社に対し譲渡等承認請求をする場合において，\n当該株式会社が譲渡を承認しない旨の決定をするときは，当該株式会社又は当該株式会社の指\n定する者が当該譲渡制限新株予約権を買い取ることを請求することはできない。\nエ．募集新株予約権の発行が著しく不公正な方法により行われる場合において，株主が不利益を\n受けるおそれがあるときは，株主は，株式会社に対し，当該新株予約権の発行をやめることを\n請求することができる。\nオ．株式会社は，会社法の規定に基づき，新株予約権の併合又は新株予約権の分割をすることが\nできる。",
