    "label": "第22問",
    "question": "株式会社の役員等の損害賠償責任に関する次のアからオまでの各記述のうち，誤っているものを\n組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．取締役会設置会社の取締役が取締役会の承認を受けないで自己のために当該取締役会設置会\n社と取引をしたときは，当該取引によって当該取締役が得た利益の額は，当該取締役がその任\n務を怠ったことによって当該取締役会設置会社に生じた損害の額と推定される。\nイ．監査役会設置会社においては，取締役は，定款を変更して当該監査役会設置会社が責任限定\n契約を社外取締役と締結することができる旨の定款の定めを設ける議案を株主総会に提出する\nには，各監査役の同意を得なければならない。\nウ．株式会社の取締役が第三者のために当該株式会社と取引をした場合において，当該取締役が\nその任務を怠ったことによって当該株式会社に損害が生じたときは，当該取締役の当該株式会\n社に対する損害賠償責任は，任務を怠ったことが当該取締役の責めに帰することができない事\n由によるものであることをもって免れることができない。\nエ．監査役は，監査報告に記載すべき重要な事項についての虚偽の記載をしたときは，当該記載\nをすることについて注意を怠らなかったことを証明した場合を除き，これによって第三者に生\nじた損害を賠償する責任を負う。\nオ．執行役がその職務を行うについて悪意又は重大な過失があったことにより第三者に生じた損\n害を賠償する責任を負う場合において，監査委員である取締役もその職務を行うについて悪意\n又は重大な過失があったことにより当該損害を賠償する責任を負うときは，これらの者は，連\n帯債務者とされる。",
