    "question": "債権者異議手続に関する次のアからオまでの各記述のうち，誤ったものを組み合わせたものは，\n後記1から5までのうちどれか。（解答欄は，）\nア．組織変更をする株式会社の債権者は，当該株式会社に対し，組織変更について異議を述べる\nことができない。\nイ．新設合併をする株式会社の債権者は，当該株式会社に対し，新設合併について異議を述べる\nことができる。\nウ．吸収分割をする株式会社が株主総会の決議によって吸収分割契約の承認を受けなければなら\nない場合において，当該株式会社の債権者が当該株式会社に対し吸収分割について異議を述べ\nることができるときは，当該債権者が異議を述べることができる期間の初日は，当該承認があ\nった日後の日でなければならない。\nエ．株式交換完全親株式会社が株式交換に際して株式交換完全子会社の株主に対して交付する対\n価が金銭のみである場合には，当該株式交換完全親株式会社の債権者は，当該株式交換完全親\n株式会社に対し，株式交換について異議を述べることができる。\nオ．社債管理者の設置がされていない社債の社債権者が，当該社債を発行した株式会社に対し，\n資本金の額の減少について異議を述べるには，社債権者集会の決議によらなければならない。",
