    "year_label": "H30",
    "subject": "商法",
    "label": "第26問",
    "question": "株主代表訴訟に係る会社法上の制度に関する次のアからオまでの各記述のうち，当該制度の趣旨\nがなれ合いの訴訟による弊害の防止を目的とするものとしてふさわしいものを組み合わせたものは，\n後記1から5までのうちどれか。（解答欄は，）\nア. 会社法上の公開会社においては，6か月（これを下回る期間を定款で定めた場合にあっては，\nその期間）前から引き続き株式を有する株主でなければ，株主代表訴訟を提起することができ\nない。\nイ．株主が株主代表訴訟を提起したときは，裁判所は，被告の申立てにより，当該株主に対し，\n相当の担保を立てるべきことを命ずることができる。\nウ．会社法上の公開会社は，株主代表訴訟を提起した株主から訴訟告知を受けたときは，遅滞な\nく，その旨を公告し，又は株主に通知しなければならない。\nエ．株主代表訴訟を提起した株主が勝訴した場合において，当該株主代表訴訟に関し，必要な費\n用を支出したときは，当該株式会社に対し，その費用の額の範囲内で相当と認められる額の支\n払を請求することができる。\nオ．一定の場合には，株主は，株主代表訴訟に係る確定した終局判決に対し，再審の訴えをもっ\nて，不服を申し立てることができる。",
