    "subject": "商法",
    "label": "第29問",
    "question": "小切手に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後記\n1から5までのうちどれか。（解答欄は，）\nア．小切手は，引受けをすることができない。\nイ．小切手は，振出人の自己宛てで振り出すことができない。\nウ．特定の日に支払う旨の記載をした小切手であっても，一覧払のものとされる。\nエ．一般線引小切手は，二条の平行線内に銀行の名称を記載することにより，特定線引小切手に\n変更することができる。\nオ．小切手の所持人の裏書人，振出人その他の債務者に対する遡求権は，支払呈示期間経過後3\n年をもって時効によって消滅する。",
