    "year_label": "H30",
    "subject": "商法",
    "label": "第30問",
    "question": "約束手形の振出人が負う手形債務がどのようにして生ずるかについては，幾つかの立場がある。\n次のアからオまでの各記述のうち，「この立場」が，当該手形債務は，手形の作成及び署名という\n一方的行為によって発生すると解する立場を指すものとしてふさわしいものを組み合わせたものは，\n後記1から5までのうちどれか。（解答欄は，）\nア．「この立場」は，一般に，署名によって署名者自身を権利者とする手形上の権利が成立し，\nその権利が手形の交付によって相手方に譲渡されると解している。\nイ．「この立場」は，手形という書面を通じて意思表示がされ，手形の授受により，意思表示が\n相手方に到達すると解している。\nウ．「この立場」は，手形を一旦作成し，署名した後であっても，占有を手放すまでは，署名者\nは自由に手形債務の内容を変更し，又は消滅させることができるから，手形を相手方に交付し\nて初めて債務を負担すると解することが手形行為者の通常の意思に合致すると主張する。\nエ．「この立場」に対しては，民法上も単独行為によって債権債務関係は生じ得るし，相手方の\n承諾を必要と考えるのは擬制的であるという批判がある。\nオ．「この立場」は，振出人が署名したが，受取人に交付する前の手形が振出人の下で保管され\nていた間に盗取されたときは，当該手形を盗取した者から，善意でかつ重大な過失がなく当該\n手形を取得した者は，善意取得によって保護されると解している。",
