    "subject": "民事訴訟法",
    "label": "第37問",
    "question": "先行する訴訟行為を前提とした新たな訴訟行為の可否に関する次のアからオまでの各記述のうち，\n判例の趣旨に照らし誤っているものを組み合わせたものは，後記1から5までのうちどれか。（解\n答欄は，）\nア．被告が主張する積極否認の内容となる重要な間接事実に立脚した新たな請求の追加的変更で\nあっても，従前の請求と請求の基礎の同一性がない場合には，このような訴えの変更は，許さ\nれない。\nイ．原告の土地明渡請求に対し，第一審裁判所が判決でその土地について賃借権を有するとの被\n告の抗弁に係る事実を認めた場合には，被告は，控訴審において，反訴として，原告の同意を\n要せずに，その土地についての賃借権存在確認の訴えを提起することができる。\nウ．附帯控訴は，一旦取り下げても，口頭弁論終結に至るまでは，再び申し立てることができる。\nエ．本案について終局判決があった後に訴えを取り下げた者は，その訴えと訴訟物を同一とする\n再訴の提起を正当なものとする新たな利益又は必要性が存するときは，取り下げた訴えと訴訟\n物を同一とする再訴を提起することができる。\nオ．第一審において全部勝訴の判決を得た原告は，被告が控訴した場合であっても，附帯控訴の\n形式で請求を拡張することができない。",
