    "question": "抗弁に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後記1\nから5までのうちどれか（解答欄は，）。\nア．10年の時効取得を原因とする土地の所有権移転登記手続を求める訴えの請求原因に対する\n「原告は，占有開始の時に当該土地の所有権を有しないことを知っていた。」との主張は，抗\n弁である。\nイ．売買契約に基づく動産の引渡しを求める訴えの請求原因に対する「原告が被告に対して代金\nの支払をするまで当該動産の引渡しを拒絶する。」との主張は，抗弁である。\nウ．消費貸借契約に基づく貸金返還を求める訴えの請求原因に対する「金銭の交付が贈与契約に\n基づくものであったから，金銭の返還請求権は発生しない。」との主張は，抗弁である。\nエ．所有権に基づく土地の明渡しを求める訴えの請求原因に対する「原告は，他の第三者に対し\nて当該土地を売り，所有権を失った。」との主張は，抗弁である。\nオ．保証契約に基づく保証債務の履行を求める訴えの請求原因に対する「主債務者が保証契約書\nを偽造した。」との主張は，抗弁である。",
