    "subject": "民事訴訟法",
    "label": "第43問",
    "question": "決定又は命令に対する不服申立てに関する次のアからオまでの各記述のうち，判例の趣旨に照ら\nし正しいものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．簡易裁判所の裁判官の訴状却下命令に対しては，地方裁判所に即時抗告をすることができる。\nイ．地方裁判所が文書提出命令の申立てについてその文書の証拠調べをする必要性がないという\n理由でこれを却下するとした決定に対しては，その必要性があることを理由として，即時抗告\nをすることができる。\nウ．高等裁判所が再抗告についてした決定に対しては，その決定が憲法に違反することを理由と\nして，特別抗告をすることができる。\nエ．高等裁判所がその決定に対する許可抗告の申立てについて抗告を許可しなかった場合であっ\nても，最高裁判所は，法令の解釈に関する重要な事項を含むと認めるときは，抗告を受理する\nことができる。\nオ．決定に対して再審の申立てをすることはできない。",
