    "subject": "民事訴訟法",
    "label": "第45問",
    "question": "少額訴訟に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後記1\nから5までのうちどれか。（解答欄は，）\nア．被告は，反訴を提起することができる。\nイ．証拠調べは，即時に取り調べることができる証拠に限りすることができる。\nウ．被告は，口頭弁論の終結がされるまで，訴訟を通常の手続に移行させる旨の申述をすること\nができる。\nエ．裁判所は，請求を認容する判決をする場合に，被告の資力その他の事情を考慮して特に必要\nがあると認めるときは，判決の言渡しの日から3年を超えない範囲内において，認容する請求\nに係る金銭の支払について，その分割払の定めをすることができる。\nオ．少額訴訟の終局判決に対して適法な異議がされ，通常の手続により審理及び裁判をすること\nとされた場合の終局判決に対しては，控訴をすることができる。",
