    "question": "知る権利や表現の自由に関する次のアからウまでの各記述について，最高裁判所の判例の趣旨に\n照らして，それぞれ正しい場合には1を，誤っている場合には2を選びなさい。（解答欄は，アか\nらウの順にから）\nア．放送事業者は，権利の侵害を受けた者の請求に基づく調査によって放送内容が真実でないこ\nとが判明した場合，放送法の規定により訂正放送をしなければならないが，これは，放送内容\nの真実性の保障及び干渉排除による表現の自由の確保の観点から，放送事業者において自律的\nに訂正放送を行うことを公法上の義務として定めたものである。\nイ．裁判の傍聴人が法廷においてメモを取ることについては，憲法第21条第1項の規定により\n憲法上の権利として保障されており，法廷警察権によってこれを制限又は禁止することは，公\n正かつ円滑な訴訟の運営の妨げとなるおそれがあるにとどまらず，訴訟の運営に具体的な支障\nが現実に生じている場合でなければ許されない。\nウ．報道機関の報道は，民主主義社会において，国民が国政に関与するにつき重要な判断の資料\nを提供し，国民の「知る権利」に奉仕するものであることから，事実の報道の自由は，思想の\n表明の自由と同様に憲法第21条の保障のもとにあり，報道が正しい内容を持つためには，報\n道のための取材の自由についても，憲法第21条の精神に照らし十分尊重に値する。",
