    "question": "外国人の人権に関する次のアからウまでの各記述について，最高裁判所の判例の趣旨に照らして，\n正しいものには○，誤っているものには×を付した場合の組合せを，後記1から8までの中から選\nびなさい。（解答欄は，）\nア．地方公務員のうち，住民の権利義務を直接形成し，その範囲を確定するなどの公権力の行使\nに当たる行為を行い，若しくは普通地方公共団体の重要な施策に関する決定を行い，又はこれ\nらに参画することを職務とするものについては，原則として日本国籍を有する者が就任するこ\nとが想定され，外国人が就任することは想定されていない。\nイ．我が国に在留する外国人のうち，永住者等でその居住する区域の地方公共団体と特段に緊密\nな関係を持つに至ったと認められる者についてであっても，法律をもって，地方公共団体の長，\nその議会の議員等に対する選挙権を付与する措置を講ずることは，憲法上禁止されている。\nウ．基本的人権の保障は，権利の性質上日本国民のみを対象としていると解されるものを除き，\n外国人に対しても等しく及ぶものと解すべきで，政治活動の自由についても，政治的意思決定\n又はその実施に影響を及ぼす活動等外国人の地位に鑑み相当でないと解されるものを除き，そ\nの保障が及ぶ。",
