    "question": "生存権とこれを具体化した法制度に関する次のアからウまでの各記述について，最高裁判所の判\n例の趣旨に照らして，正しいものには○，誤っているものには×を付した場合の組合せを，後記1\nから8までの中から選びなさい。（解答欄は，）\nア．国民年金制度は，憲法第25条の趣旨を実現するために設けられた社会保障上の制度である\nから，同条の趣旨にこたえて具体的にどのような立法措置を講ずるかの選択決定は，立法府の\n広い裁量にゆだねられており，著しく合理性を欠き明らかに裁量の逸脱，濫用とみざるを得な\nいような場合を除いて，裁判所が審査判断するに適しない事柄であり，何ら合理的理由のない\n不当な差別的取扱いがあっても，憲法第14条違反の問題は生じ得ない。\nイ．憲法第25条にいう「健康で文化的な最低限度の生活」は，きわめて抽象的・相対的な概念\nであって，その具体的内容は，その時々における文化の発達の程度，経済的・社会的条件，一\n般的な国民生活の状況等との相関関係において判断決定されるべきものであるから，国の立法\nとして具体化される場合にも，国の財政事情は考慮されるべきではない。\nウ．国は，難民条約の批准及びこれに伴う国会審議等を契機に，外国人に対する生活保護につい\nて一定の範囲で国際法及び国内公法上の義務を負うことを認めるに至ったものであり，少なく\nとも永住外国人にも憲法第25条第1項の保障が及ぶものとなったと解すべきであるから，生\n活保護法の適用対象となる「国民」には永住外国人も含まれる。",
