    "question": "選挙権及び選挙制度に関する次のアからウまでの各記述について，最高裁判所の判例の趣旨に照\nらして，それぞれ正しい場合には1を，誤っている場合には2を選びなさい。（解答欄は，アから\nウの順にから）\nア．憲法は，国民主権の原理に基づき，国民に対して，両議院の議員の選挙において投票をする\nことによって国の政治に参加することができる権利の保障は認めているが，投票をする機会\nの平等までは保障していない。\nイ．選挙運動の一つの手段である政見放送において，政見放送の品位を損なう言動を禁止した公\n職選挙法第150条の2の規定に違反する言動がそのまま放送される利益は，法的に保護さ\nれた利益とはいえず，したがって，上記言動がそのまま放送されなかったとしても，法的利\n益の侵害があったとはいえない。\nウ．憲法は，両議院の議員の選挙において投票をすることを，一定の年齢に達した国民の固有の\n権利として保障しており，自ら選挙の公正を害する行為をした者等の選挙権について一定の制\n限をすることは別として，選挙権又はその行使を制限するためには，そのような制限をするこ\nとがやむを得ないと認められる事由がなければならない。",
