    "question": "以下のＡからＣは，法律と法規命令との関係が問題とされた最高裁判所の判決に関する文章であ\nる。次のアからウまでの【 】内の各記述について，正しいものに○，誤っているものに×を付し\nた場合の組合せを，後記1から8までの中から選びなさい。（解答欄は，）\nＡ：被勾留者の接見について，原則として幼年者との接見を許さないとした上で例外として限ら\nれた場合に監獄の長の裁量によりこれを許すこととしていた旧監獄法施行規則の規定と，旧監\n獄法との関係が問題とされた最高裁判所平成3年7月9日第三小法廷判決（民集45巻6号1\n049頁）は，（ア）【憲法及び旧監獄法による委任の趣旨を踏まえて限定的に解釈すれば，上\n記施行規則の規定は旧監獄法による委任の範囲を超えていないとしたものである。】\nＢ：父から認知された婚姻外懐胎児童を児童扶養手当の支給対象となる児童の範囲から除外した\n児童扶養手当法施行令の規定の一部と，児童扶養手当法との関係が問題とされた最高裁判所平\n成14年1月31日第一小法廷判決（民集56巻1号246頁）は，（イ）【児童扶養手当法に\nよる委任の範囲を逸脱したものとして，上記施行令の規定の一部を違法無効と判断したもので\nある。】\nＣ：国家公務員に禁止される「政治的行為」の具体的内容を定めた人事院規則の規定と，国家公\n務員法との関係が問題とされた最高裁判所平成24年12月7日第二小法廷判決（刑集66巻\n12号1722頁）は，（ウ）【憲法の規定及び国家公務員法の委任の趣旨を踏まえて，上記規\n則の規定を限定的に解釈したものである。】\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
