    "question": "行政上の法律関係に対する民事法の適用に関する次のアからウまでの各記述について，最高裁判\n所の判例に照らし，正しいものに○，誤っているものに×を付した場合の組合せを，後記1から8\nまでの中から選びなさい。（解答欄は，）\nア．普通地方公共団体の長が当該普通地方公共団体を代表して行う契約の締結行為であっても，\n私人間における双方代理と同様の利害状況となることがあり得るから，双方代理を禁じた民法\n第108条の規定が類推適用されるが，その代表権は執行機関に専属する権限であるから，双\n方代理行為がされた後に議会の追認の議決があっても，民法第116条の規定を類推適用して\n本人による追認の効果が生ずるものではない。\nイ．建物を築造する場合に境界線から50センチメートル以上の距離を保つべきことを定める民\n法第234条第1項の規定は，建築基準法第65条の定める防火地域又は準防火地域内にある\n耐火構造の外壁を有する建築物についても，直ちに適用が排除されるものではなく，民法の規\n定により保護される隣地の採光・通風，相隣者間の生活利益を犠牲にしてもなお制限を超える\n建築を許すだけの合理的な理由がある場合に限って，建築基準法の規定が優先適用される。\n（参照条文）建築基準法\n（隣地境界線に接する外壁）\n第65条 防火地域又は準防火地域内にある建築物で，外壁が耐火構造のものについては，\nその外壁を隣地境界線に接して設けることができる。\nウ．生活保護法に基づき被保護者が受ける保護受給権は，当該個人に与えられた一身専属の権利\nであって，原則として相続の対象となるものではないが，被保護者の生存中の金銭給付を内容\nとする扶助で既に遅滞にあるものについては，相続の対象となる。\n- 8 -\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
