    "subject": "行政法",
    "label": "第16問",
    "question": "行政裁量に関する次のアからウまでの各記述について，最高裁判所の判例に照らし，正しいもの\nに○，誤っているものに×を付した場合の組合せを，後記1から8までの中から選びなさい。（解\n答欄は，）\nア．公立高等専門学校の校長が学生に対し退学処分を行うかどうかの判断は，校長の合理的な教\n育的裁量に委ねられるべきものであるが，退学処分は，当該学生を学外に排除することが教育\n上やむを得ないと認められる場合に限って選択されるべきであり，その要件の認定につき他の\n処分の選択に比較して特に慎重な配慮が要請される。\nイ．原子炉施設の安全性に関する判断の適否が争われる原子炉設置許可処分の取消訴訟における\n裁判所の審理，判断は，専門技術的な調査審議及び判断を基にしてされた行政庁の判断に不合\n理な点があるか否かという観点から行われるべきであるから，その合理性の有無は当該設置許\n可処分時の科学技術水準に照らして審理，判断されるべきである。\nウ．公立学校施設の目的外使用を許可するか否かは，原則として，管理者の裁量に委ねられてい\nるものと解されるが，学校施設の設置目的に照らせば，学校教育上支障がない場合には原則と\nして許可すべきものであり，学校教育上の支障がないにもかかわらず不許可とすることは管理\n者の裁量権の範囲の逸脱又はその濫用となる。\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
