    "question": "国家賠償と損失補償に関する教員と学生の対話中の次のアからウまでの【 】内の各記述につい\nて，法令又は最高裁判所の判例に照らし，正しいものに○，誤っているものに×を付した場合の組\n合せを，後記1から8までの中から選びなさい。（解答欄は，）\n教員：今日は損失補償と国家賠償の違いについて考えてみましょう。国家賠償と比べた損失補償\nの特徴は何でしょうか。\n学生：一つ目の特徴としては，損失補償について定めた一般法は存在しないということです。\n（ア）【個別法に損失補償を認める規定が存在しない場合には，裁判を提起して損失補償を\n求めることはできないと解されています。】\n教員：なるほど。では，その他の特徴は何でしょうか。\n学生：損失補償は，適法な公権力の行使により特別の犠牲が生じた場合に，公平負担の見地から\n認められるものですので，公権力の行使が適法であることが前提とされています。\n教員：そこでいう特別の犠牲とは，財産上の損害に限られるのでしょうか。\n学生：難しい問題ですが，（イ）【予防接種による副作用被害が問題となった事案では，生命や身\n体に対する損害であっても損失補償の対象になり得ると主張されました。しかし，このよう\nな損失補償による救済を明示的に認めた最高裁判所の判例はありません。】\n教員：それでは，最後の質問ですが，損失補償が認められる場合に，その補償はどの程度の額で\nなければならないのでしょうか。\n学生：はい，損失補償に際しては「正当な補償」が必要であると解されています。ただ，(ウ)【第\n二次世界大戦後の農地改革をめぐる最高裁判所の判例では，この「正当な補償」の額は，そ\nの当時の経済状態において成立すると考えられる価格と完全に一致することを要しないとさ\nれました。】\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
