    "question": "行政庁の権限の委任及び専決に関する次のアからウまでの各記述について，法令又は最高裁判所\nの判例に照らし，正しいものに○，誤っているものに×を付した場合の組合せを，後記1から8ま\nでの中から選びなさい。（解答欄は，）\nア．行政庁が他の行政機関に法律に基づく処分の権限を委任することは，法律の根拠がなければ\n行うことができないが，行政庁がその権限に属する行為を他の行政機関に専決させることは，\n法律の根拠がなくても行うことができる。\nイ．行政庁Ａの有する処分の権限が行政機関Ｂに委任された場合，当該処分はＢの名で行われ，\nＢが当該処分をした行政庁となる。\nウ．行政庁Ａの権限とされている処分を行政機関Ｂが専決により行う場合，当該処分はＡの名で\n行われ，Ａが当該処分をした行政庁となる。\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
