    "question": "略取，誘拐及び人身売買の罪に関する次のアからオまでの各記述を判例の立場に従って検討した\n場合，誤っているものの組合せは，後記1から5までのうちどれか。（解答欄は，）\nア．営利の目的で未成年者を買い受けた場合，未成年者買受け罪のみが成立する。\nイ．身の代金目的誘拐罪は，近親者その他誘拐された者の安否を憂慮する者の憂慮に乗じてその\n財物を交付させる目的を主観的要素とする目的犯である。\nウ．身の代金目的で成年者を略取し，公訴が提起される前に同成年者を安全な場所に解放すれば，\n身の代金目的略取罪の刑が必要的に減軽される。\nエ．未成年者誘拐罪は親告罪である。\nオ．親権者は，未成年者誘拐罪の主体とはならない。",
