    "subject": "刑法",
    "label": "第3問",
    "question": "次の【記述】中の①から④までの（ ）内から適切な語句を選んだ場合，その組合せとして正し\nいものは，後記1から5までのうちどれか。（解答欄は，）\n【記 述】\n被害者の同意が問題となる場合としては，一般に以下のような分類がなされている。第1は，\n被害者の意思に反することが構成要件要素になっている場合であり，この類型においては，被害\n者の同意は構成要件該当性を阻却する。窃盗罪は，この類型に①（ａ．入る・ｂ．入らない）。\n第2は，被害者の同意の有無が犯罪の成立に影響を及ぼさない場合である。13歳未満の者に対\nするわいせつ行為は，この類型に②（ｃ．入る・ｄ．入らない）。第3は，被害者の同意がある\n場合とない場合が分けて規定され，被害者の同意があると軽い方の罪が成立する場合である。業\n務上堕胎罪は，この類型に③（ｅ．入る・ｆ．入らない）。第4は，被害者の同意が行為の違法\n性を阻却する場合である。住居侵入罪の「侵入」を住居権者・管理権者の意思に反する立入りと\n解した場合，同罪は，この類型に④（ｇ．入る・ｈ．入らない）。",
