    "question": "わいせつ物頒布等の罪に関する次のアからオまでの各記述を判例の立場に従って検討し，甲に\n（ ）内の罪が成立しないものの組合せは，後記1から5までのうちどれか。（解答欄は，）\nア．インターネットを介した書籍販売業を営む甲は，日本語で書かれたわいせつな文書である\n小説を，その購入を申し込んできた日本国内在住の多数の外国人に販売したところ，いずれ\nの外国人も日本語の読解能力に乏しく，同小説の内容を理解できなかった。（わいせつ物頒布\n罪）\nイ．甲は，インターネットを介して多数の希望者を募った上，その希望者らに無料で交付する\n目的で，わいせつな映像を記録したＤＶＤを所持した。（わいせつ物有償頒布目的所持罪）\nウ．甲は，わいせつな映像を記録したＤＶＤの販売業者に対してそのＤＶＤの購入を申し込み，\nこれを購入した。（わいせつ物頒布罪の教唆犯）\nエ．ＤＶＤのレンタル業を営む甲は，わいせつな映像を記録したＤＶＤを，多数の顧客へ有償\nで貸し出した。（わいせつ物頒布罪）\nオ．甲がインターネットを介したわいせつな映像の販売業を営み始めたところ，その購入を申\nし込んできた顧客は1名だけであったが，甲は，その者に対して，電子メールに同映像のデ\nータを添付して送信した。（わいせつ物頒布罪）",
