    "year_label": "H29",
    "subject": "刑法",
    "label": "第5問",
    "question": "次の【事例】に関する後記アからエまでの各【記述】を判例の立場に従って検討し，誤っている\nものを全て選んだ場合の組合せは，後記1から5までのうちどれか。（解答欄は，）\n【事 例】\n土木作業員甲及び乙は，現場監督者丙の監督の下で，Ｘ川に架かる鉄橋の橋脚を特殊なＡ鋼材\nを用いて補強する工事に従事していたが，作業に手間取り，工期が迫ってきたことから，甲及び\n乙の2人で相談した上で，より短期間で作業を終えることができる強度の弱いＢ鋼材を用いた補\n強工事を共同して行った。その結果，工期内に工事を終えることはできたものの，その後発生し\nた豪雨の際，Ａ鋼材ではなくＢ鋼材を用いたことによる強度不足のために前記橋脚が崩落し，た\nまたま前記鉄橋上を走行していたＶ1運転のトラックがＸ川に転落し，Ｖ1が死亡した。なお，\n甲及び乙は同等の立場にあり，甲及び乙のいずれについても，Ｂ鋼材を工事に用いた場合に強度\n不足のために前記橋脚が崩落することを予見していなかったものの，その予見可能性があったも\nのとする。\n【記 述】\nア．甲及び乙には，強度の弱いＢ鋼材で補強工事を行うことの意思連絡はあるが，不注意の共同\nはあり得ないから，甲及び乙に業務上過失致死罪の共同正犯が成立する余地はない。\nイ．丙は，甲及び乙が強度の弱いＢ鋼材で補強工事を行っていることを認識していたが，工期が\n迫っていたことから，これを黙認したという場合，直接行為者である甲及び乙に過失が認めら\nれたとしても，更に丙に過失が認められる余地がある。\nウ．仮に，甲及び乙において，Ｖ1が死亡するに至る実際の因果経過を具体的に予見することが\n不可能であった場合，甲及び乙には業務上過失致死罪は成立しない。\nエ．仮に，Ｖ1運転のトラックの荷台に，Ｖ1に無断でＶ2が乗り込んでおり，同トラックがＸ\n川に転落したことによって，Ｖ1及びＶ2の両名が死亡した場合，甲及び乙にはＶ2に対する\n業務上過失致死罪は成立しない。",
