    "label": "第14問ア",
    "question": "次のアからオまでの各記述のうち，正しいものには1を，誤っているものには2を選びなさい。\nただし，判例がある場合には，それに照らして考えるものとする。（解答欄は，アからオの順に\nから）\n\nア．強制手段とは，有形力の行使を伴う手段を意味するものではなく，個人の意思を制圧し，身\n体，住居，財産等に制約を加えて強制的に捜査目的を実現する行為など，特別の根拠規定がな\nければ許容することが相当でない手段を意味するものであって，この程度に至らない有形力の\n行使は，任意捜査においても許容される場合がある。",
    "question_no": 20,
