    "year_label": "H29",
    "subject": "刑事訴訟法",
    "label": "第14問イ",
    "question": "次のアからオまでの各記述のうち，正しいものには1を，誤っているものには2を選びなさい。\nただし，判例がある場合には，それに照らして考えるものとする。（解答欄は，アからオの順に\nから）\n\nイ．荷送人の依頼に基づき宅配便業者の運送過程下にある荷物について，捜査機関が，捜査目的\nを達成するため，荷送人や荷受人の承諾を得ることなく，その荷物に外部からエックス線を照\n射して内容物の射影を観察した行為は，任意処分として許される。",
    "question_no": 21,
