    "label": "第14問エ",
    "question": "次のアからオまでの各記述のうち，正しいものには1を，誤っているものには2を選びなさい。\nただし，判例がある場合には，それに照らして考えるものとする。（解答欄は，アからオの順に\nから）\n\nエ．警察官が，交通取締りの一環として交通違反の多発する地域等の適当な場所において，交通\n違反の予防，検挙のための自動車検問を実施し，同所を通過する自動車に対して走行の外観上\nの不審な点の有無にかかわりなく短時分の停止を求めて，運転者などに対し必要な事項につい\nての質問などをすることは，それが相手方の任意の協力を求める形で行われ，自動車の利用者\nの自由を不当に制約することにならない方法，態様で行われる限り，適法である。",
