    "question": "次の【事例】は，被疑者甲の身体拘束の経過である。甲の勾留期間の満了日は後記1から5まで\nのうちどれか。（解答欄は，）\n【事 例】\n司法警察員Ｘは，平成28年10月1日，Ｌ地方裁判所裁判官から，被疑者を甲，罪名を傷害，\n有効期間を「平成28年10月8日まで」などとする逮捕状の発付を受け，同月6日午後6時，\n甲を逮捕した。その後，Ｘは，同日午後7時，甲をＭ警察署に引致し，司法警察員Ｙは，同月7\n日午後4時に甲を書類及び証拠物とともにＬ地方検察庁検察官に送致する手続をした。同日午後\n4時30分に送致を受けたＬ地方検察庁検察官は，同月8日午後3時，Ｌ地方裁判所裁判官に，\n逮捕事実と同じ被疑事実で甲の勾留を請求し，Ｌ地方裁判所裁判官は，同月9日午後1時，被疑\n者を甲，罪名を傷害，有効期間を「平成28年10月16日まで」などとする勾留状を発付した。\nこれを受けて，司法警察員Ｚは，同月9日午後1時20分，同勾留状を執行し，同日午後2時，\n甲をＭ警察署に勾留した。その後，甲の勾留期間は延長されなかった。",
