    "question": "身体検査に関する次のアからオまでの各記述のうち，正しいものの組合せは，後記1から5まで\nのうちどれか。ただし，判例がある場合には，それに照らして考えるものとする。（解答欄は，）\nア．捜査機関から鑑定の嘱託を受けた者は，鑑定処分許可状に基づき，身体検査を拒否する者に\n対して，直接強制として身体検査を行うことができる。\nイ．捜査機関が身体の拘束を受けている被疑者の顔写真を撮影するには，身体検査令状による必\n要はない。\nウ．捜査機関が女子の身体を検査する場合，身体検査令状に医師又は成年の女子を立ち会わせる\n旨の条件が付されていない限り，これらの者を立ち会わせる必要はない。\nエ．捜査機関が人の着用している下着の中を捜索して物を差し押さえるためには，捜索差押許可\n状によれば足り，併せて身体検査令状の発付を受ける必要はない。\nオ．捜査機関が人の身体から直接強制として尿を採取するには身体検査令状による必要がある。",
