    "year_label": "H29",
    "subject": "刑事訴訟法",
    "label": "第20問",
    "question": "第1回公判期日後の保釈，勾留の取消し，勾留執行停止に関する次のアからオまでの各記述のう\nち，誤っているものの組合せは，後記1から5までのうちどれか。ただし，判例がある場合には，\nそれに照らして考えるものとする。（解答欄は，）\nア．裁判所は，保釈を許すときには，検察官の意見を聴かなければならないが，保釈の請求を却\n下するときには，検察官の意見を聴かなくてもよい。\nイ．裁判所は，検察官の請求がなくとも，職権で保釈を取り消すことができる。\nウ．勾留されている被告人の配偶者は，被告人と独立して，裁判所に対し，被告人の保釈の請求\nをすることができる。\nエ．勾留の必要がなくなったとき，検察官は，裁判所に対し，被告人の勾留の取消しを請求する\nことができる。\nオ．被告人から勾留執行停止の申立てがあった場合，裁判所は，勾留の執行を停止するか否かの\n裁判をしなければならない。",
