    "subject": "民法",
    "label": "第1問",
    "question": "Ａが19歳で，親権に服する男性であることを前提として，次のアからオまでの各記述のうち，\n正しいものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．Ａがその親権者から営業を行うことを許可された後に親権者の同意を得ずに売買契約を締\n結した場合には，その売買契約がその営業に関しないものであっても，Ａは，その売買契約\nを取り消すことができない。\nイ．Ａの親権者が，新聞配達のアルバイトによりＡが得る金銭の処分をＡに許していた場合に\nおいて，Ａがそのアルバイトによって得た金銭で自転車を購入したときは，Ａがその売買契\n約を締結する際に親権者の同意を得ていないときであっても，Ａは，その売買契約を取り消\nすことができない。\nウ．Ａがその親権者の同意を得ずにＡＢ間に生まれた子を認知した場合であっても，Ａは，そ\nの認知を取り消すことができない。\nエ．Ａが精神上の障害により事理を弁識する能力を欠く常況にある場合でも，Ａが成年に達す\nるまでは，家庭裁判所は，Ａについて後見開始の審判をすることができない。\nオ．Ａが相続によって得た財産から100万円をＢに贈与する旨の契約を書面によらずに締結\nした場合において，書面によらない贈与であることを理由にＡがその贈与を撤回したときで\nも，Ａが贈与の撤回について親権者の同意を得ていなかったときは，Ａは，贈与の撤回を取\nり消すことができる。",
