    "label": "第2問",
    "question": "失踪宣告に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わ\nせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．沈没した船舶の中に在ったＡについて失踪宣告がされた場合には，Ａはその沈没事故の後\n1年が経過した時に死亡したものとみなされる。\nイ．Ａの生死が7年間明らかでなかったことから，Ａについて失踪宣告がされた場合には，Ａ\nは，7年間の期間が満了した時に死亡したものとみなされる。\nウ．Ａの生死が7年間明らかでなかったことから，Ａについて失踪宣告がされ，Ａが死亡した\nものとみなされた後にＡの生存が判明した場合でも，失踪宣告がされた後にＡがした売買契\n約は，失踪宣告が取り消されなければ有効とはならない。\nエ．Ａの生死が7年間明らかでなかったことから，Ａについて失踪宣告がされ，Ａが死亡した\nものとみなされた後に，Ａの子であるＢがＡ所有の甲土地を遺産分割により取得した。その\n後，Ｂは，Ｃに甲土地を売却したが，その売却後にＡの生存が判明し，Ａの失踪宣告は取り\n消された。その売買契約の時点で，Ａの生存についてＢが善意であっても，Ｃが悪意である\nときは，Ｃは，甲土地の所有権を取得することができない。\nオ．Ａの生死が7年間明らかでなかったことから，Ａについて失踪宣告がされ，Ａが死亡した\nものとみなされた後に，Ａの生存が判明したが，失踪宣告が取り消されずにＡが死亡した場\n合には，もはやその失踪宣告を取り消すことができない。",
