    "subject": "民法",
    "label": "第4問",
    "question": "複数の者が共同で権利を有する場合に関する次のアからオまでの各記述のうち，判例の趣旨に照\nらし正しいものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．Ａ，Ｂ及びＣの3名が各3分の1の割合による持分を有する建物について，Ａが単独でそ\nの建物を占有している場合，Ｂは，Ａに対し，その建物の明渡しを請求することができる。\nイ．Ａ，Ｂ及びＣの3名が各3分の1の割合による持分を有する土地につき，Ａがその所有者\nをＡのみとする登記をした場合，Ｂは，Ａに対し，Ａ，Ｂ及びＣの3名の持分を各3分の1\nとする更正登記手続を求めることができる。\nウ．Ａ，Ｂ及びＣの3名が共同相続し，その遺産分割の前に，法定相続分に応じた持分の割合\nにより相続登記がされた土地につき，ＣからＤに不実の持分権移転登記がされた場合，Ａは，\nＤに対し，当該持分権移転登記の抹消登記手続を求めることができる。\nエ．入会権は，登記がなくても第三者に対抗することができる。\nオ．入会団体の構成員が採枝・採草の収益を行う権能を有する入会地がある場合において，そ\nの入会地にＡ名義の不実の地上権設定登記があるときは，その入会団体の構成員であるＢは，\nＡに対し，入会地におけるＢの使用収益権に基づき，当該地上権設定登記の抹消登記手続を\n求めることができる。",
