    "subject": "民法",
    "label": "第5問",
    "question": "留置権に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わせ\nたものは，後記1から5までのうちどれか。（解答欄は，）\nア．ＡがＢから甲建物を賃借し，Ｂに敷金を交付していた場合において，その賃貸借契約が終\n了したときは，Ａは，敷金が返還されるまで甲建物を留置することができる。\nイ．ＡからＢ，ＢからＣに建設機械が順次売却され，ＢがＡに対して代金を支払っていない場\n合に，Ｃが提起した所有権に基づく建設機械の引渡請求訴訟においてＡの留置権が認められ\nるときは，Ｃの請求は棄却される。\nウ．ＡがＢから甲建物を賃借していたが，Ａの賃料不払によりその賃貸借契約が解除された後，\n明渡しの準備をしている間にＡが甲建物について有益費を支出した場合，Ａは，Ｂに対し，\nその費用の償還請求権を被担保債権とする留置権を行使して甲建物の明渡しを拒むことはで\nきない。\nエ．甲土地の借地権者であるＡが甲土地上にある建物について買取請求権を行使した場合，Ａ\nは，甲土地の賃貸人であるＢに対し，その買取代金債権を被担保債権とする留置権を行使し\nて甲土地の明渡しを拒むことはできない。\nオ．甲建物の賃貸人Ａが，賃借人Ｂに対して賃貸借契約の終了に基づき甲建物の明渡しを請求\nしたのに対し，Ｂが賃貸借の期間中に支出した有益費の償還請求権に基づいて留置権を行使\nし，従前と同様の態様で甲建物に居住した場合，Ｂは，Ａに対し，その居住による利得を返\n還する義務を負う。",
