    "year": 2017,
    "year_label": "H29",
    "subject": "民法",
    "label": "第6問",
    "question": "ＡのＢに対する債権を被担保債権として，Ｃ所有の甲土地について抵当権（以下「本件抵当権」\nという。）が設定され，その旨の登記がされている場合に関する次のアからオまでの各記述のうち，\n判例の趣旨に照らし誤っているものを組み合わせたものは，後記1から5までのうちどれか。（解\n答欄は，）\nア．甲土地の従物である石灯籠が本件抵当権の設定前に備え付けられていた場合，本件抵当権\nの効力は，その石灯籠には及ばない。\nイ．Ｃが甲土地をＤに賃貸し，さらにＤが甲土地をＥに転貸したときは，ＤをＣと同視するこ\nとを相当とする場合を除き，Ａは，Ｄが取得する転貸賃料債権について物上代位権を行使す\nることができない。\nウ．本件抵当権が根抵当権でない場合において，ＡがＢに対して被担保債権として元本債権の\nほか3年分の利息債権を有しているときは，Ｃは，Ａに対して，元本債権のほかその最後の\n2年分の利息債権を弁済すれば，本件抵当権を消滅させることができる。\nエ．被担保債権の弁済期が到来した場合であっても，Ｃは，Ａに対し，本件抵当権が実行され\nる前に，あらかじめ求償権を行使することはできない。\nオ．本件抵当権の登記がされた後に，ＣがＤに対し甲土地を賃貸し，Ｄが甲土地上に乙建物を\n建築して所有する場合において，Ｄが甲土地の占有についてＡに対抗することができる権利\nを有しないときは，Ａは，Ｄの承諾の有無にかかわらず，甲土地及び乙建物を一括して競売\nすることができる。",
