    "year_label": "H29",
    "subject": "民法",
    "label": "第7問",
    "question": "債務不履行に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合\nわせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．動産の売買契約が締結され，その代金の一部が支払われた後で，当該売買契約が債務不履\n行を理由に解除された場合，売主は，受領した売買代金の一部を返還するに当たり，その受\n領の時からの利息を付す必要はない。\nイ．売買代金の履行遅滞に基づく損害賠償請求において，同時履行の抗弁権が存在する場合に\nは履行遅滞に陥らないとの見解に立つ場合，損害賠償を求める原告は，請求原因事実として\n自己の債務の履行又は履行の提供を主張立証しなければならない。\nウ．ＡＢ間で売買契約が締結され，Ａが債務不履行に陥っている場合において，ＡがＢに対し\nて相当の期間を定めて契約を解除するかどうかを確答すべき旨の催告をしたにもかかわらず，\nＢがその期間内に解除の通知をしないときは，Ａは，以後債務不履行責任を負わない。\nエ．ＡがＢに建物を賃貸し，ＢがＡの承諾を得てＣに同建物を転貸した場合において，ＡＢ間\nの賃貸借契約がＢの債務不履行を理由とする解除により終了したときは，ＡがＣに建物の返\n還を請求しても，Ａが転貸借を承諾していた以上，ＢＣ間の転貸借契約におけるＢのＣに対\nする債務は履行不能とはならない。\nオ．期限の定めのない金銭消費貸借契約の借主は，貸主が相当の期間を定めずに催告をしても，\n相当の期間を経過した時から履行遅滞の責任を負う。",
