    "label": "第8問",
    "question": "指名債権の譲渡に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っているもの\nを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．債権譲渡禁止の特約に反して債権を譲渡した債権者は，債務者が譲渡を承諾した場合を除\nき，同特約の存在を理由に譲渡の無効を主張することができる。\nイ．債権の譲受人は，譲渡人に代位して債務者に対して債権譲渡の通知をすることにより，そ\nの債権譲渡を債務者に対抗することはできない。\nウ．抵当不動産の第三取得者が被担保債権の弁済をしたことによって抵当権が消滅した場合，\nその後，被担保債権の債権者がその債権を第三者に譲渡し，債務者が異議をとどめないで債\n権譲渡を承諾しても，当該第三取得者に対する関係においては，抵当権の効力は復活しない。\nエ．債権が二重に譲渡され，第一の債権譲渡について譲渡人が債務者に対して確定日付のある\n証書によらずに通知をした後に，第二の債権譲渡について譲渡人が債務者に対して確定日付\nのある証書による通知をした場合，第一の譲受人は債権の取得を債務者にも対抗することが\nできない。\nオ．債権が二重に譲渡され，確定日付のある証書による通知が同時に債務者に到達したときは，\n譲受人の一人から弁済の請求を受けた債務者は，同順位の譲受人が他に存在することを理由\nとして弁済の責任を免れることができる。",
    "question_no": 8,
    "options": [
      "ア イ",
      "ア オ",
      "イ エ",
      "ウ エ",
      "ウ オ"
    ],
    "answer": 1,
