    "question": "相殺に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わせた\nものは，後記1から5までのうちどれか。（解答欄は，）\nア．相殺の意思表示に条件を付することはできないが，期限を付することはできる。\nイ．債権者Ａの債務者Ｂに対する甲債権がＡの債権者Ｃに差し押さえられても，差押え前から\nＢがＡに対する乙債権を有していた場合，Ｂは，甲債権と乙債権の弁済期の先後を問わず，\n相殺適状にあれば，相殺をすることができる。\nウ．時効によって消滅した債権を自働債権とする相殺をするためには，消滅時効が援用された\n自働債権は，その消滅時効期間が経過する以前に受働債権と相殺適状にあったことを要する。\nエ．請負契約の注文者は，瑕疵修補に代わる損害賠償債権と請負代金債権が同時履行の関係に\nある場合には，前者を自働債権，後者を受働債権として相殺することはできない。\nオ．不法行為に基づく損害賠償債務を負う債務者であっても，自働債権と受働債権のいずれも\nが不法行為に基づく損害賠償債権である場合には，相殺をすることができる。",
