    "question": "売買契約の解除に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組\nみ合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．債務不履行を理由に売買契約が解除された場合において，その債務不履行の時から10年\nを経過したときは，解除による原状回復請求権の消滅時効が完成する。\nイ．売主が目的物を引き渡し，買主が代金の一部を支払った場合において，債務不履行を理由\nに売買契約が解除されたときは，売主の目的物返還請求権と買主の代金返還請求権とは，同\n時履行の関係にない。\nウ．売主が目的物を引き渡したが，買主が代金を履行期の経過後も支払わない場合において，\n売主が買主に対して相当の期間を定めて債務の履行の催告をしたとしても，売主がその催告\nに際して履行がなければ解除する旨の通知をしていないときは，売主は，相当期間の経過後\nも当該売買契約を解除することができない。\nエ．売主が目的物を引き渡したが，買主が代金を履行期の経過後も支払わない場合において，\n売主が買主に対して相当の期間を定めて代金の支払を催告したにもかかわらず，買主が代金\nの支払を拒絶する意思を明確に表示したときは，売主は，相当の期間が経過する前であって\nも，当該売買契約を解除することができる。\nオ．買主の債務不履行を理由に売主が解除権を取得したとしても，その解除権の行使前に買主\nがその債務を履行したときは，売主は，その解除権を行使することができない。",
