    "question": "不動産の売買契約と同時にされた買戻しの特約に関する次のアからオまでの各記述のうち，判例\nの趣旨に照らし誤っているものを組み合わせたものは，後記1から5までのうちどれか。（解答欄\nは，）\nア．買戻しの期間は，10年を超えることができない。\nイ．買戻しの特約において，その期間を定めたときであっても，後日これを伸長することができ\nる。\nウ．売買契約と同時に買戻しの特約を登記したときは，買戻しは，第三者に対しても，その効\n力を生ずる。\nエ．売主は，買戻しの特約により，買主が支払った代金及び契約の費用を返還して，売買の解\n除をすることができる。\nオ．売主が買戻しの実行をしたときは，買主は，売買契約締結後買戻しの実行までの間に取得\nした果実を売主に返還しなければならない。",
