    "question": "Ａが運転するタクシーとＢが運転するタクシーが衝突する交通事故（以下「本件事故」という。）\nが発生し，Ａが運転するタクシーの乗客Ｃが負傷し，Ｃに300万円の損害が生じた。本件事故に\nついての過失割合は，Ａが4割で，Ｂが6割であり，Ｃに過失はなかった。この事例に関する次の\nアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わせたものは，後記1から\n5までのうちどれか。（解答欄は，）\nア．ＣがＡに対して本件事故後3年以内に損害賠償を請求する訴訟を提起すれば，ＣのＢに対\nする損害賠償請求権の消滅時効も中断する。\nイ．ＢがＣに対して損害賠償債務の弁済として100万円の支払をした場合には，Ｂは，Ａに\n対し，40万円を求償することができる。\nウ．Ｂが，Ｃとの間で，ＢがＣに対して200万円を支払うとともに，ＣがＡの損害賠償債務\n及びＢのその余の損害賠償債務を免除する旨の和解契約を締結した場合であっても，Ｃは，\nＡに対し，100万円の支払を求めることができる。\nエ．Ａに使用者Ｄがおり，Ｄが本件事故について使用者責任を負う場合において，ＤがＣに対\nして損害賠償債務の弁済として300万円を支払ったときは，Ｄは，Ａに対し，信義則上相\n当と認められる限度において求償することができる。\nオ．Ｂに使用者Ｅがおり，Ｅが本件事故について使用者責任を負う場合において，ＡがＣに対\nして損害賠償債務の弁済として300万円を支払ったときは，Ａは，Ｅに対し，180万円\nを求償することができる。",
