    "question": "契約の第三者に対する効力に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っ\nているものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．建物建築工事請負契約において，注文者と請負人との間に，契約が中途で解除された際の出\n来形部分の所有権は注文者に帰属する旨の約定がある場合に，当該契約が中途で解除された\nときは，その請負人が下請負人に当該工事を請け負わせ，下請負人が自ら材料を提供して出\n来形部分を築造したとしても，当該出来形部分の所有権は注文者に帰属する。\nイ．債務者と引受人との間の契約でする併存的債務引受は，債権者が引受けによる利益を享受す\nる意思を表示しなくても，その効力が生ずる。\nウ．委任による代理人が適法に復代理人を選任した場合において，その復代理人が委任事務を処\n理するに当たり金銭その他の物を受領したときは，復代理人は，本人に対して受領物を引き\n渡す義務を負う。\nエ．受寄者が寄託された宝石を適法に第三者に保管させたときは，その第三者は寄託者に対して，\n保管費用の償還を請求することができる。\nオ．賃借人が適法に賃借物を転貸したときは，転借人は賃貸人に対して，賃借物の修繕を請求す\nることができる。",
