    "label": "第17問",
    "question": "譲渡による株式の取得について取締役会の承認を要する旨の定款の定めを設けている取締役会設\n置会社における株式の取得に関する次のアからオまでの各記述のうち，正しいものを組み合わせた\nものは，後記1から5までのうちどれか。（解答欄は，）\nア．譲渡制限株式に関しては，相続その他の一般承継による当該株式の取得について取締役会の\n承認を要する旨を定款で定めることができる。\nイ．譲渡制限株式に関しては，当該株式を従業員以外の者に譲渡する場合に限り，取締役会の承\n認を要する旨を定款で定めることができる。\nウ．判例の趣旨によれば，いわゆる一人会社であっても，取締役会の承認がない限り，譲渡制限\n株式の譲渡は，会社に対し，その効力を有しない。\nエ．取締役会の承認を得ないで譲渡制限株式が譲渡された場合には，当該株式の譲受人は，当該\n株式の取得について取締役会の承認を求めることができない。\nオ．取締役会が譲渡制限株式の取得について承認をしない旨の決定をし，会社が当該株式を買い\n取り，又は当該株式を買い取る者（以下「指定買取人」という。）を指定しなければならない\nときは，当該会社は，当該株式の一部について買い取り，残りについて指定買取人を指定する\nことができる。",
