    "subject": "商法",
    "label": "第18問",
    "question": "種類株式発行会社でない取締役会設置会社における株式の併合及び株式の分割に関する次のアか\nらオまでの各記述のうち，正しいものを組み合わせたものは，後記1から5までのうちどれか。な\nお，各記述について，定款には，単元株式数の定めがないものとする。（解答欄は，）\nア．株式の併合については，株式の併合が法令又は定款に違反する場合において，株主が不利益\nを受けるおそれがあるときは，株主が会社に対し株式の併合をやめることを請求することがで\nきる権利が会社法に規定されているが，株式の分割については，株主が会社に対し株式の分割\nをやめることを請求することができる権利が会社法に規定されていない。\nイ．株式の併合及び株式の分割のいずれについても，反対株主の株式買取請求権が会社法に規定\nされている。\nウ．会社は，取締役会の決議によって株式の併合をすることができる旨を定款で定めることがで\nきる。\nエ．発行可能株式総数が1000株であって，発行済株式の総数が300株である会社が1株を\n5株とする株式の分割をする場合には，株主総会の決議によらないで，発行可能株式総数を4\n000株に増加する定款の変更をすることができる。\nオ．会社が会社法上の公開会社である場合であっても，株式の併合により，その効力が生ずる日\nにおける発行可能株式総数が発行済株式の総数の4倍を超えることとなることが認められる。",
