    "year_label": "H29",
    "subject": "商法",
    "label": "第24問",
    "question": "株式会社を各当事会社とする事業譲渡及び吸収分割に関する次のアからオまでの各記述のうち，\n正しいものを組み合わせたものは，後記1から5までのうちどれか。なお，特別法の規定の適用が\nある場合は，考慮しないものとする。（解答欄は，）\nア．事業譲渡をする場合には，譲渡会社の新株予約権者は，譲渡会社に対し，自己の有する新株\n予約権を買い取ることを請求することができないが，吸収分割をする場合には，吸収分割会社\nの新株予約権者は，吸収分割会社に対し，自己の有する新株予約権を買い取ることを請求する\nことができることがある。\nイ．譲渡会社及び吸収分割会社のいずれについても，当事会社の別段の意思表示がない限り競業\n避止義務を負う旨が会社法に規定されている。\nウ．事業譲渡については，債権者異議手続をすることを要しないが，吸収分割については，債権\n者異議手続をしなければならないことがある。\nエ．事業譲渡の無効及び吸収分割の無効は，いずれも訴えをもってのみ主張することができる。\nオ．吸収分割会社が吸収分割承継会社に承継されない債務の債権者を害することを知って吸収分\n割をした場合には，当該債権者が吸収分割承継会社に対して当該債務の履行を請求することが\nできるときがあることが会社法に規定されているが，譲渡会社が譲受会社に承継されない債務\nの債権者を害することを知って事業譲渡をした場合には，当該債権者が譲受会社に対して当該\n債務の履行を請求することができるときがあることは会社法に規定されていない。",
    "question_no": 24,
