    "subject": "民事訴訟法",
    "label": "第35問",
    "question": "専門委員に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後\n記1から5までのうちどれか。（解答欄は，）\nア．専門委員について除斥の申立てがあったときは，その専門委員は，その申立てについての決\n定が確定するまでその申立てがあった事件の手続に関与することができない。\nイ．裁判所は，争点の整理をするに当たり，訴訟関係を明瞭にするため必要があると認めるとき\nは，当事者の意見を聴けばその同意がなくとも，専門的な知見に基づく説明を聴くために専門\n委員を手続に関与させることができる。\nウ．裁判所は，当事者双方の申立てがあるときは，専門委員を手続に関与させる決定を取り消さ\nなければならない。\nエ．裁判長は，当事者の意見を聴けばその同意がなくとも，証拠調べの手続に関与している専門\n委員が証拠調べの期日において証人に対して直接に問いを発することを許すことができる。\nオ．裁判所は，和解を試みるに当たり，必要があると認めるときは，当事者の意見を聴けばその\n同意がなくとも，当事者双方が立ち会うことができる和解を試みる期日において専門的な知見\nに基づく説明を聴くために専門委員を手続に関与させることができる。",
    "question_no": 37,
    "options": [
      "ア イ",
      "ア オ",
      "イ ウ",
      "ウ エ",
      "エ オ"
    ],
