    "year_label": "H29",
    "subject": "民事訴訟法",
    "label": "第36問",
    "question": "訴訟手続の中断に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っているもの\nを組み合わせたものは，後記1から5までのうちどれか。ただし，アからエまでの各記述において，\n訴訟代理人は選任されていなかったものとする。（解答欄は，）\nア．貸金請求訴訟において，口頭弁論終結後判決の言渡し前に被告が死亡した場合には，訴訟\n手続は中断しない。\nイ．訴訟物が一身専属権である訴訟において，原告が死亡した場合には，訴訟手続は中断せず，\n訴訟は終了する。\nウ．ある訴訟に第三者が独立当事者参加をした場合において，当該第三者が死亡したときは，\n訴訟手続は中断する。\nエ．債権者が債権者代位権に基づきその債務者に属する債権を行使する訴訟において，当該債\n務者が死亡した場合には，訴訟手続は中断しない。\nオ．訴訟代理人が選任されている訴訟において，訴訟代理人が死亡した場合には，訴訟手続は\n中断する。",
