    "subject": "民事訴訟法",
    "label": "第41問",
    "question": "処分権主義に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合\nわせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．裁判所は，原告が500万円の債務のうち200万円の存在は認めるもののそれを超える\n債務の不存在の確認を求める訴訟において，300万円の債務が存在すると認めるときは，\n500万円の債務のうち300万円を超える債務の不存在を確認し，その余の部分につき請\n求を棄却する判決をしなければならない。\nイ．裁判所は，訴訟外において原告が被告との間で訴えを取り下げる旨の合意をしたと認める\nときは，訴えの取下げによる訴訟終了の宣言をしなければならない。\nウ．財産権上の請求に関する判決については，裁判所は，原告の申立てがない場合であっても，\n必要があると認めるときは，仮執行宣言を付すことができる。\nエ．裁判所は，少額訴訟につき請求を認容する判決をする場合において，被告の資力その他の\n事情を考慮して特に必要があると認めるときは，認容する請求に係る金銭の支払について分\n割払の定めをし，かつ，これと併せて期限の利益を喪失することなく支払をした額の合計額\nが元本のうち一定額を超えた場合には残部の支払義務を免除する旨の定めをすることができ\nる。\nオ．裁判所は，特定の金銭債権の一部を請求する訴訟において，相殺の抗弁に理由があると認\nめるときは，請求額から自働債権の額を控除した残存額の限度で請求を認容する判決をしな\nければならない。",
