    "subject": "民事訴訟法",
    "label": "第45問",
    "question": "貸金100万円の返還を求める訴えが簡易裁判所に提起された場合の手続に関する次のアからオ\nまでの各記述のうち，正しいものを組み合わせたものは，後記1から5までのうちどれか。（解答\n欄は，）\nア．口頭弁論は，相手方が準備をしなければ陳述をすることができないと認めるべき事項につい\nても，書面で準備する必要はなく，口頭弁論前直接に相手方に通知する必要もない。\nイ．裁判所は，相当と認める場合には，当事者に異議がないときに限り，証人の尋問に代え，書\n面の提出をさせることができる。\nウ．裁判所は，必要があると認めるときは，司法委員を審理に立ち会わせて事件につきその意見\nを聴くことができる。\nエ．裁判所は，被告が口頭弁論において原告の主張した事実を争わず，その他何らの防御の方法\nをも提出しない場合において，相当と認めるときは，和解に代わる決定をすることができる。\nオ．被告は，反訴を提起することができない。",
