    "question": "(配点：3)\n私人間における人権保障に関する次のアからウまでの各記述について，判例の趣旨に照らして，\nそれぞれ正しい場合には1を，誤っている場合には2を選びなさい｡（解答欄は,アからウの順にから）\n\nア．企業者は，雇用の自由を有するから，労働者の思想，信条を理由として雇入れを拒んでも当\n然に違法ということはできないが，労働者の採否決定に当たり，その思想，信条を調査し，労\n働者に関連事項の申告を求めることまでは許されない。",
