    "question": "(配点：3)\n私人間における人権保障に関する次のアからウまでの各記述について，判例の趣旨に照らして，\nそれぞれ正しい場合には1を，誤っている場合には2を選びなさい｡（解答欄は,アからウの順にから）\n\nイ．大学は，その設置目的を達成するため，必要な事項を定めて学生を規律する権能を有するか\nら，私立大学が，その伝統，校風や教育方針に鑑み，学内外における学生の政治的活動につき，\nかなり広範な規律を及ぼしても，直ちに不合理ということはできない。",
