    "label": "第5問",
    "question": "(配点：2)\n学問の自由に関する次のアからウまでの各記述について，判例の趣旨に照らして，正しいも\nのには○を，誤っているものには×を付した場合の組合せを，後記1から8までの中から選び\nなさい｡（解答欄は，）\nア．学問の自由は，学問的研究の自由とその研究成果の発表の自由を指しており，憲法第23条\nは大学が学術の中心として深く真理を探究することを本質とすることに鑑みて規定されたもの\nであるから，同条の保障は大学の教授や研究者を対象とするものであり，国民一般はその保障\nの対象ではない。\nイ．大学における学問の自由を保障するために伝統的に大学の自治が認められているところ，学\n内集会について大学の自治の保障が及ぶか否かの判断に当たって，その集会の目的や性格を考\n慮することは，学内で行われる活動をその思想内容に着目して規制することになり，大学の自\n治を認めた趣旨に抵触するから，許されない。\nウ．普通教育の場において使用される教科書は学術研究の結果の発表を目的とするものではなく，\n教科書検定は，記載内容がいまだ学界において支持を得ていないとき，あるいは当該教科課程\nで取り上げるにふさわしい内容と認められないときなど一定の検定基準に違反する場合に，教\n科書の形態における研究結果の発表を制限するにすぎないから，憲法第23条に反しない。",
