    "question": "(配点：3)\n労働基本権に関する次のアからウまでの各記述について，それぞれ正しい場合には1を，誤って\nいる場合には2を選びなさい｡（解答欄は，アからウの順にから）\n\nア．公務員の争議行為の制限は国民生活全体の利益を維持増進する必要との調和の見地から合理\n性の認められる必要最小限度のものでなければならず，職務の性質や違いを考慮することなく\n公務員の争議行為を一律に禁止することは憲法上許されないとするのが判例の立場である｡",
