    "question": "(配点：2)\n天皇が国会開会式に出席した上で述べる「おことば」の憲法上の位置付けに関する次のアからウ\nまでの各記述について，正しいものには○，誤っているものには×を付した場合の組合せを，後記\n1から8までの中から選びなさい｡（解答欄は，）\nア．「おことば」を象徴としての地位に基づく公的行為であると捉える見解については，象徴と\nしての地位が天皇の一身専属のものであることを前提にすると，天皇の権能を代行する摂政は\n「おことば」を述べることができないのではないかという問題点がある。\nイ．「おことば」を国事行為である国会の召集（憲法第7条第2号）と密接に関連する行為とし\nて準国事行為と位置付ける見解については，「おことば」について内閣による「助言と承認」\nを通じたコントロールを及ぼす余地がなくなるという問題点がある。\nウ．「おことば」は国事行為である「儀式を行ふ」（憲法第7条第10号）に含まれるという見\n解については，上記「儀式を行ふ」を「儀式を主宰する」という意味に解すると，文理上無理\nがあるという問題点がある。",
