    "question": "(配点：2)\n政党に関する次のアからウまでの各記述について，正しいものには○，誤っているものには×を\n付した場合の組合せを，後記1から8までの中から選びなさい｡（解答欄は，）\nア．政党は，政治上の信条，意見等を共通にする者が任意に結成するものであって，党員に対し\nて政治的忠誠を要求し，一定の統制を施すなどの自治権能を有する。\nイ．政党は，内部的自律権を有し，政党が組織内の自律的運用として党員に対してした除名等の\n処分の当否については，原則として政党による自律的な解決に委ねられる。\nウ．小選挙区選出の衆議院議員について，政党の方針に反したことを理由として除名された場合\nに議員の身分を当然喪失するとの制度を設けても，違憲とは解されない。",
