    "question": "(配点：3)\nいわゆる在外邦人選挙権制限違憲訴訟上告審判決（最高裁判所平成17年9月14日大法廷判決，\n民集59巻7号2087頁）に関する次のアからウまでの各記述について，それぞれ正しい場合に\nは1を，誤っている場合には2を選びなさい｡（解答欄は，アからウの順にから）\n\nア．前記判決は，国政選挙の選挙権について，「国民の国政への参加の機会を保障する基本的権\n利として議会制民主主義の根幹を成すものであり，民主国家においては，一定の年齢に達した\n国民の全てに平等に与えられるべきものである」と指摘しているが，同判決の考え方に従った\nとしても，自ら選挙の公正を害する行為をした者の選挙権について一定の制限をすることまで\n違憲となるわけではない。",
