    "year_label": "H28",
    "subject": "憲法",
    "label": "第10問",
    "question": "(配点：2)\n内閣及び内閣総理大臣に関する次のアからウまでの各記述について，正しいものには○，誤って\nいるものには×を付した場合の組合せを，後記1から8までの中から選びなさい｡（解答欄は，）\nア．大日本帝国憲法において内閣総理大臣は同輩中の首席にすぎなかったのに対し，日本国憲法\nが内閣総理大臣に首長としての地位を認め，その権限を強化しているのは，内閣の一体性と統\n一性を確保し，内閣の国会に対する連帯責任の強化を図るものである。\nイ．判例によれば，内閣総理大臣は，閣議にかけて決定した方針が存在しない場合においても，\n少なくとも内閣の明示の意思に反しない限り，行政各部に対し，随時その所掌事務について一\n定の方向で処理するよう指導，助言等の指示を与える権限を有する。\nウ．内閣は，憲法第73条第1号により法律を執行する義務を負うから，たとえ内閣が違憲と判\n断する法律であっても，その法律を執行しなければならず，また，最高裁判所が違憲と判断し\nた場合でも，国会がその法律を改廃しない限りは，その執行をしなければならない。",
