    "question": "(配点：3)\n違憲審査に関する次のアからウまでの各記述について，判例の趣旨に照らして，それぞれ正しい\n場合には1を，誤っている場合には2を選びなさい｡（解答欄は，アからウの順にから）\n\nア．第三者の所有物を没収する言渡しを受けた被告人は，当該第三者の権利を援用して，所有者\nに対し何ら告知，弁解，防御の機会を与えることなくその所有権を奪うことは憲法に違反する\n旨主張することはできない。",
