    "question": "(配点：3）\n最高裁判所平成25年1月11日第二小法廷判決（民集67巻1号1頁。以下「本判決」とい\nう。）は，一般用医薬品のうち第一類医薬品及び第二類医薬品について，インターネット販売を含\nむ郵便等販売を規制する薬事法施行規則（平成26年厚生労働省令第8号による改正前のもの。以\n下「本件施行規則」という。）の薬事法（平成25年法律第103号による改正前のもの。以下同\nじ。）への適合性について判断した判決である。問題となった本件施行規則は，第一類医薬品及び\n第二類医薬品につき，店舗販売業者による店舗以外の場所にいる者に対する郵便等販売を一律に禁\n止するものであった。本判決に関する次のアからエまでの各記述について，それぞれ正しい場合に\nは1を，誤っている場合には2を選びなさい。（解答欄は，アからエの順にから）\n\nエ．本判決は，従前違法とされていなかった第一類医薬品及び第二類医薬品の郵便等販売を一律\nに禁止する本件施行規則は，職業活動の自由を相当程度制約するものであるから，憲法第22\n条第1項に違反すると判示したものである。\n（参照条文）薬事法（平成25年法律第103号による改正前のもの）\n（一般用医薬品の区分）\n第36条の3 一般用医薬品（専ら動物のために使用されることが目的とされているものを\n除く。）は，次のように区分する。\n一 第一類医薬品 その副作用等により日常生活に支障を来す程度の健康被害が生ずるお\nそれがある医薬品のうちその使用に関し特に注意が必要なものとして厚生労働大臣が指\n定するもの及びその製造販売の承認の申請に際して第14条第8項第1号に該当すると\nされた医薬品（注：既に製造販売の承認を与えられている医薬品と，有効成分，分量，\n用法，用量，効能，効果等が明らかに異なるとされた医薬品）であつて当該申請に係る\n承認を受けてから厚生労働省令で定める期間を経過しないもの\n二 第二類医薬品 その副作用等により日常生活に支障を来す程度の健康被害が生ずるお\nそれがある医薬品（第一類医薬品を除く。）であつて厚生労働大臣が指定するもの\n三 第三類医薬品 第一類医薬品及び第二類医薬品以外の一般用医薬品\n2，3 （略）\n- 7 -",
