    "question": "(配点：2）\nＡ県知事は，介護保険法に基づく指定居宅サービス事業者Ｂについて，介護報酬の不正請求が行\nわれているとの内部通報を受けたため，調査の上，不利益処分をすることにした。次のアからウま\nでの各記述について，行政手続法に照らし，正しいものに○，誤っているものに×を付した場合の\n組合せを，後記1から8までの中から選びなさい。（解答欄は，）\nア．Ａ県知事がＢに対し，指定の効力の一部停止処分をしようとする場合には，原則として聴聞\n手続を執らなければならない。\nイ．Ｂに対する不利益処分の発動に強い関心を持っているライバル事業者Ｃは，聴聞手続におい\nて，Ａ県知事に対し，当該処分の原因となる事実を証する資料の閲覧を求めることができる。\nウ．Ｂからサービスを受けている高齢者Ｄは，サービスを受けられなくなると日常生活に困難を\n来すことから，Ｂに対する不利益処分の発動に反対するため，主宰者の許可を得て聴聞手続に\n参加し，口頭で意見を述べることができる。\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
