    "question": "(配点：2）\n次のアからエまでの各記述は，行政上の義務の実効性を確保するための条文の規定を示したもの\nである。それぞれの【 】内の行為のうち，その性質がいわゆる執行罰に当たるものを一つ，後記\n1から4までの中から選びなさい。（解答欄は，）\nア．私的独占の禁止及び公正取引の確保に関する法律（昭和22年法律第54号）\n第97条 排除措置命令（注：私的独占など私的独占の禁止及び公正取引の確保に関する法律\nの規定に違反する行為を行った事業者に対して公正取引委員会が当該違反行為を排除するた\nめに必要な措置を命じることを指す。）に違反したものは，50万円以下の【過料に処す\nる】。ただし，その行為につき刑を科するべきときは，この限りでない。\nイ．成田国際空港の安全確保に関する緊急措置法（昭和53年法律第42号）\n第3条 国土交通大臣は，規制区域内に所在する建築物その他の工作物について，その工作物\nが次の各号に掲げる用に供され，又は供されるおそれがあると認めるときは，当該工作物の\n所有者，管理者又は占有者に対して，期限を付して，当該工作物をその用に供することを禁\n止することを命ずることができる。\n一 多数の暴力主義的破壊活動者の集合の用\n二 暴力主義的破壊活動等に使用され，又は使用されるおそれがあると認められる爆発物，\n火炎びん等の物の製造又は保管の場所の用\n三 成田国際空港又はその周辺における航空機の航行に対する暴力主義的破壊活動者による\n妨害の用\n2～5（略）\n6 国土交通大臣は，第1項の禁止命令に係る工作物が当該命令に違反して同項各号に掲げる\n用に供されていると認めるときは，当該工作物について【封鎖その他その用に供させないた\nめに必要な措置を講ずること】ができる。\nウ．砂防法（明治30年法律第29号）\n第36条 私人ニ於テ此ノ法律若ハ此ノ法律ニ基キテ発スル命令ニ依ル義務ヲ怠ルトキハ国土\n交通大臣若ハ都道府県知事ハ一定ノ期限ヲ示シ若シ期限内ニ履行セサルトキ若ハ之ヲ履行ス\nルモ不充分ナルトキハ500円以内ニ於テ指定シタル【過料ニ処スルコト】ヲ予告シテ其ノ\n履行ヲ命スルコトヲ得\nエ．行政代執行法（昭和23年法律第43号）\n第2条 法律（法律の委任に基く命令，規則及び条例を含む。以下同じ。）により直接に命ぜ\n- 9 -\nられ，又は法律に基き行政庁により命ぜられた行為（他人が代つてなすことのできる行為に\n限る。）について義務者がこれを履行しない場合，他の手段によつてその履行を確保するこ\nとが困難であり，且つその不履行を放置することが著しく公益に反すると認められるときは，\n当該行政庁は，【自ら義務者のなすべき行為をなし，又は第三者をしてこれをなさしめ，そ\nの費用を義務者から徴収すること】ができる。\n1．ア 2．イ 3．ウ 4．エ",
