    "question": "(配点：2）\n行政機関の保有する情報の公開に関する法律及びその適用に関する次のアからウまでの各記述に\nついて，法令又は最高裁判所の判例に照らし，正しいものに○，誤っているものに×を付した場合\nの組合せを，後記1から8までの中から選びなさい。（解答欄は，）\nア．開示請求の対象とされた行政文書を行政機関が保有していないことを理由とする不開示決定\nの取消訴訟においては，その取消しを求める者が，当該不開示決定時に当該行政機関が当該行\n政文書を保有していたことについて主張立証責任を負う。\nイ．行政機関の長が，開示請求があった日から30日以内に開示請求に係る行政文書の全部若し\nくは一部を開示する旨の決定又は開示をしない旨の決定をしないときは，開示をしない旨の決\n定があったものとみなされる。\nウ．行政文書を開示しない旨の決定について行政不服審査法に基づく審査請求があったときは，\n当該審査請求に対する裁決をすべき行政機関の長は，必ず情報公開・個人情報保護審査会に諮\n問しなければならない。\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
