    "subject": "行政法",
    "label": "第19問",
    "question": "(配点：2）\n訴えの利益に関する次のアからウまでの各記述について，最高裁判所の判例に照らし，正しいも\nのに○，誤っているものに×を付した場合の組合せを，後記1から8までの中から選びなさい。\n（解答欄は，）\nア．道路交通法に基づき，自動車運転免許の効力停止処分を受けた者は，無違反，無処分で法定\nの期間を経過し，以後，前歴のない者として取り扱われるに至ったとしても，当該処分の記載\nのある免許証を所持することにより，名誉，信用等を損なう可能性が継続して存在し，その程\n度は重大なものであって，それを排除することは法の保護に値する利益であるといえるから，\n当該処分の取消しにつき，訴えの利益を有する。\nイ．道路交通法は，優良運転者の実績を賞揚し，優良な運転をするように自動車運転免許証の保\n有者を誘導して交通事故の防止を図る目的で，優良運転者であることを免許証に記載して公に\n明らかにするとともに，優良運転者に対し更新手続上の優遇措置を講じていることなどに照ら\nせば，免許証の有効期間の更新に当たり，一般運転者として扱われ，優良運転者である旨の記\n載のない免許証を交付されて更新処分を受けた者は，上記記載のある免許証を交付して行う更\n新処分を受ける法律上の地位を否定されたことを理由として，これを回復するため，当該更新\n処分の取消しを求める訴えの利益を有する。\nウ．建築基準法に基づく建築確認は，それを受けなければ工事をすることができないという法的\n効果が付与されているものにすぎないが，建築確認が違法であるとして判決で取り消されれば，\n相当程度の確実さをもって，工事完了後，建築主事等において検査済証の交付を拒否すること\nになるか，又は特定行政庁において違反是正命令を発すべきことになるのであるから，当該工\n事が完了した場合においても，その取消しを求める訴えの利益は失われない。\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
