    "question": "(配点：2）\n行政事件訴訟法第3条第6項，第7項に定める「義務付けの訴え」及び「差止めの訴え」に関す\nる次のアからウまでの各記述について，法令又は最高裁判所の判例に照らし，正しいものに○，誤\nっているものに×を付した場合の組合せを，後記1から8までの中から選びなさい。（解答欄は，\n）\nア．行政庁が一定の処分をすべき旨を命ずる判決は，常に第三者に対しても効力を有するから，\n行政庁が判決に従って当該処分をした場合，当該処分の名宛人は当該処分の効力を争うことは\nできない。\nイ．「差止めの訴え」の訴訟要件については，一定の処分がされようとしていること，すなわち，\n行政庁によって一定の処分がされる蓋然性があることが，救済の必要性を基礎付ける前提とし\nて必要となる。\nウ．裁判所が，「差止めの訴え」に係る処分につき，行政庁がその処分をしてはならない旨を命\nずる判決をすることができるのは，その処分につき行政庁に裁量が認められていない場合に限\nられる。\n1．ア〇 イ〇 ウ○ 2．ア〇 イ〇 ウ× 3．ア〇 イ× ウ○\n4．ア〇 イ× ウ× 5．ア× イ〇 ウ○ 6．ア× イ〇 ウ×\n7．ア× イ× ウ○ 8．ア× イ× ウ×",
