    "question": "(配点：3）\n行政処分の執行停止申立手続に関する次のアからエまでの各記述について，それぞれ正しい場合に\nは1を，誤っている場合には2を選びなさい。（解答欄は，アからエの順にから）\n\nイ．執行停止決定がされるための要件の一つとして，当該処分，処分の執行又は手続の続行によ\nり重大な損害を生ずるおそれがあることが必要であるが，その有無を判断するに当たっては，\n損害の回復の困難の程度を考慮するものとし，損害の性質及び程度並びに当該処分の内容及び\n性質をも勘案するものとされている。",
