    "question": "住居を侵す罪に関する次のアからオまでの各記述を判例の立場に従って検討し，正しい場合には1\nを，誤っている場合には2を選びなさい。（解答欄は，アからオの順にから）\n\nア．強盗の意図を隠してＡ方の玄関前で「こんばんは。」と言ったところ，来客と勘違いしたＡ\nから「どうぞお入りください。」と言われてＡ方住居に立ち入った場合，住居侵入罪が成立す\nる。",
