    "subject": "刑法",
    "label": "第6問",
    "question": "文書偽造の罪に関する次のアからオまでの各記述を判例の立場に従って検討した場合，Ｘに\n（ ）内の罪が成立しないものの組合せとして正しいものは，後記1から5までのうちどれか。（解\n答欄は，）\nア．医師Ｘは，Ｙに依頼され，Ｙが保険会社に提出するために虚偽の病名を記載した診断書を作\n成した。（虚偽診断書作成罪）\nイ．Ｘは，自動車運転免許の効力停止中に自動車を運転し，速度違反の取締りを受けた際，警察\n官に対し，あらかじめＹから名義使用の承諾を受けていたことから，Ｙの氏名を名乗り，交通\n事件原票の供述者欄にＹ名義で署名押印した。（有印私文書偽造罪）\nウ．Ｙの代理人でないＸは，Ｙに無断で，行使の目的をもって，金銭消費貸借契約書用紙に「Ｙ\n代理人Ｘ」と記載し，その横に「Ｘ」と刻した印鑑を押すなどして，Ｙを債務者とする金銭消\n費貸借契約書を作成した。（有印私文書偽造罪）\nエ．Ｘは，身分証明書として使おうと考え，Ａ県公安委員会が発行したＹの自動車運転免許証の\n写真をＸの写真に貼り替えた。（有印公文書偽造罪）\nオ．Ｘは，Ｙの所有する不動産を勝手に売却しようと考え，Ｙに無断で，行使の目的をもって，\n- 4 -\n不動産の売買契約書用紙に売主として「Ｙ」と記載するなどして，同不動産の売買契約書を作\n成したが，「Ｙ」と刻した印鑑は押さなかった。（無印私文書偽造罪）",
