    "question": "次の【事例】に関する後記1から5までの各記述のうち，甲に窃盗罪の従犯の成立を肯定する論\n拠となり得ないものはどれか。（解答欄は，）\n【事 例】\n甲は，乙又は乙の友人が窃盗罪を犯そうとしていることを知り，その手助けのため，乙に対し，\n同罪の遂行に必要な道具を貸したところ，さらに，乙はその道具を友人丙に貸し，丙がこれを用\nいて同罪を犯した。\nなお，丙には同罪の正犯が成立し，乙にはその従犯が成立するものとする。",
