    "year_label": "H28",
    "subject": "刑事訴訟法",
    "label": "第14問",
    "question": "次のアからオまでの各記述は，甲が，平成26年11月1日に乙に強姦されたとの事実により乙\nを告訴する場合について述べたものである。これらの記述のうち，正しいものの組合せは，後記1\nから5までのうちどれか。（解答欄は，）\nア．司法警察員は，甲からの告訴を受けたときは，乙を逮捕しなければならない。\nイ．甲は，告訴を一旦取り消した後でも，再度適法に告訴をすることができる。\nウ．告訴は，必ず書面によってしなければならない。\nエ．甲は，公訴の提起があるまでは，告訴を取り消すことができる。\nオ．甲の告訴が犯人を知った日から1年を経過した後にされたときでも，検察官は適法に公訴を\n提起することができる。",
