    "question": "次のアからオまでの各記述のうち，誤っているものの組合せは，後記1から5までのうちどれか。\nただし，判例がある場合には，それに照らして考えるものとする。（解答欄は，）\nア．被告人又は被疑者の兄弟姉妹は，被告人又は被疑者の意思にかかわらず，弁護人を選任する\nことができる。\nイ．被告人の国選弁護人の選任は，審級ごとにしなければならない。\nウ．被疑者の国選弁護人の選任は，勾留の執行停止により被疑者が釈放された場合にはその効力\nを失う。\nエ．国選弁護人は，辞任を申し出ても，裁判所又は裁判官が解任しない限り，弁護人の地位を失\nわない。\nオ．被告人の私選弁護人の選任は，弁護士が裁判所にその旨直接申し出る限り，書面による必要\nはない。",
