    "question": "次のアからオまでの各記述は，刑事訴訟法の各規定の要旨を記述したものである。これらの各記\n述中の（ ）内からそれぞれ適切なものを選んだ場合，ａが正しいものには1を，ｂが正しいもの\nには2を選びなさい。（解答欄は，アからオの順にから）\n\nア．検察官は，逮捕状により被疑者を逮捕したときは，直ちに犯罪事実の要旨及び弁護人を選任\nすることができる旨を告げた上，弁解の機会を与え，留置の必要があると思料するときは被疑\n者が身体を拘束された時から（ａ．24 ｂ．48）時間以内に裁判官に被疑者の勾留を請求\nしなければならない。",
