    "subject": "刑事訴訟法",
    "label": "第20問",
    "question": "公判前整理手続に関する次のアからオまでの各記述のうち，正しいものの組合せは，後記1から\n5までのうちどれか。（解答欄は，）\nア．裁判所は，裁判員裁判の対象事件ではない事件についても，必要があると認めるときは，公\n判前整理手続に付することができる。\nイ．裁判所は，公判前整理手続において，弁護人から，被告人の自白調書につきその自白の任意\n性を争う旨の意見が述べられた場合には，公判前整理手続の終結までに当該自白調書の証拠能\n力を判断しなければならない。\nウ．検察官は，公判前整理手続における証拠開示に関する裁判所の決定に対して，不服申立てを\nすることができない。\nエ．裁判所は，公判前整理手続に付された事件の公判において，検察官，被告人及び弁護人が公\n判前整理手続において取調べを請求しなかった証拠について，やむを得ない事由によって請求\nできなかった場合でなくても，必要と認めるときは，職権で証拠調べをすることができる。\nオ．裁判所は，事件を公判前整理手続に付した場合，同手続を終結させて公判を開始した後には，\n期日間整理手続に付することができない。",
