    "year_label": "H28",
    "subject": "刑事訴訟法",
    "label": "第24問ア",
    "question": "次の【事例】に関し，捜査機関が収集した後記アからオまでの【証拠】について，「直接証拠と\nは，犯罪事実を直接に証明する証拠をいう。」とする見解を前提とした場合，直接証拠に該当する\nものには1を，直接証拠に該当しないものには2を選びなさい。（解答欄は，アからオの順にから）\n【事 例】\n甲は，平成28年2月1日午後7時頃，Ｈマンション401号室のＶ方において，Ｖを包丁で\n刺殺した。\n【証 拠】\n\nア．「平成28年2月1日午後6時58分頃，包丁を持った甲がＨマンション1階でエレベーター\nに乗り，4階で降りた後，401号室方向に向かう状況」を撮影した防犯カメラ映像",
