    "question": "被害者参加制度における被害者参加人又はその委託を受けた弁護士の法律上定められた権限に関\nする次のアからオまでの各記述のうち，正しいものの組合せは，後記1から5までのうちどれか。\n（解答欄は，）\nア．裁判員裁判の対象事件において，公判前整理手続期日に出席することができる。\nイ．情状に関する事項について，証拠調べを請求することができる。\nウ．裁判所が申出を相当と認めるときは，情状に関する事項についての証人の供述の証明力を争\nうために必要な事項について，その証人を尋問することができる。\nエ．裁判所が申出を相当と認めるときは，訴因として特定された事実の範囲内で事実及び法律の\n適用について意見を陳述することができる。\nオ．上訴をすることができる。",
