    "question": "次のアからオまでの各記述は，有罪の確定判決に対する再審について述べたものである。これらの\n記述のうち，誤っているものの組合せは，後記1から5までのうちどれか。（解答欄は，）\nア．有罪の言渡しを受けた者が死亡した場合には，その者の子であっても再審の請求をすること\nができない。\nイ．検察官は，再審の請求をすることができる。\nウ．有罪の言渡しを受けた者は，再審の請求をする場合には，弁護人を選任することができる。\nエ．再審の請求を受けた裁判所は，同請求が理由のあるときは，再審開始の決定をしなければな\nらない。\nオ．再審開始の決定が確定したときは，再審の請求が対象とした確定判決は，その効力を失う。",
