    "question": "意思表示に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後\n記1から5までのうちどれか。（解答欄は，）\nア．成年被後見人であるＡがＢから日用品を買い受けた場合，Ａが成年被後見人であることをＢ\nが知らなかったとしても，Ａの成年後見人Ｃは，当該日用品の売買契約を取り消すことができ\nる。\nイ．ＡがＢから契約解除の意思表示を受けた時にＡが成年被後見人であった場合，Ａの成年後見\n人ＣがＢの契約解除の意思表示を知るまで，当該契約解除の効力は生じない。\nウ．Ａが隔地者Ｂに対し契約申込みの通知を発した後，Ａが行為能力を喪失した場合，Ｂがその\n事実を知っていたとしても，当該契約申込みの効力は生じる。\nエ．Ａが隔地者Ｂに対し契約解除の通知を発した後，Ａが行為能力を喪失した場合，Ｂがその事\n実を知っていたとしても，当該契約解除の効力は生じる。\nオ．Ａが隔地者Ｂに対し契約承諾の通知を発した後，Ａが行為能力を喪失した場合，Ｂがその事\n実を知っていたとしても，当該契約は成立する。",
