    "question": "代理に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わせた\nものは，後記1から5までのうちどれか。（解答欄は，）\nア．無権代理行為の相手方は，代理人が代理権を有しないことを過失によって知らなかったとき\nは，民法上の無権代理人の責任を追及することができない。\nイ．代理権は，代理人が後見開始の審判を受けたときは消滅する。\nウ．成年後見人は，やむを得ない事由があるときでなければ，復代理人を選任することができな\nい。\nエ．委任による代理人がやむを得ない事由があるため復代理人を選任した場合，復代理人は，復\n代理の委任事務を処理するのに必要と認められる費用を支出したときであっても，本人に対し，\nその費用の償還を直接請求することはできない。\nオ．Ａの代理人ＢがＣの詐欺により売買契約を締結した場合，Ｂは当該売買契約を取り消すこと\nができるが，Ａは当該売買契約を取り消すことができない。",
