    "question": "時効の援用に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合\nわせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．抵当不動産の第三取得者は，その抵当権の被担保債権の消滅時効を援用することができる。\nイ．先順位抵当権の被担保債権の消滅により後順位抵当権者に対する配当額が増加する場合，当\n該後順位抵当権者は，先順位抵当権の被担保債権の消滅時効を援用することができる。\nウ．詐害行為の受益者は，詐害行為取消権を行使している債権者の被保全債権について，その消\n滅時効を援用することができない。\nエ．譲渡担保権者が被担保債権の弁済期後に譲渡担保の目的物を第三者に譲渡したときは，その\n- 2 -\n第三者は譲渡担保権設定者が譲渡担保権者に対し有する清算金支払請求権の消滅時効を援用す\nることができる。\nオ．建物の敷地所有権の帰属につき争いがある場合において，その敷地上の建物の賃借人は，建\n物の賃貸人が敷地所有権を時効取得しなければ建物賃借権を失うときは，建物の賃貸人による\n敷地所有権の取得時効を援用することができる。",
