    "id": "h28_minpo_05",
    "year": 2016,
    "year_label": "H28",
    "subject": "民法",
    "label": "第5問",
    "question": "Ａの所有するカメラ（以下「甲」という。）の取引に関する次のアからオまでの各記述のうち，\n判例の趣旨に照らし，正しいものを組み合わせたものは，後記1から5までのうちどれか。（解答\n欄は，）\nア．Ａは，甲をＢに賃貸していたところ，ＣがＢの家から甲を盗み，Ｄに売却した。Ｄは，甲が\nＣの所有物であると過失なく信じて，現実の引渡しを受けた。この場合，Ｂは，甲を盗まれた\n時から2年以内であれば，Ｄに対し，甲の返還を求めることができる。\nイ．Ａは，甲をＢに売却したが，その売買契約当時，Ａは意思能力を有していなかった。その後，\nＢが甲をＣに売却し，Ｃは，甲がＢの所有物であると過失なく信じて，現実の引渡しを受けた。\nこの場合，Ａの法定代理人は，Ｃに対し，甲の返還を求めることができる。\nウ．Ａは，その家で甲を保管していたところ，カメラを販売する商人のＢがＡの家から甲を盗み，\nＣに売却した。Ｃは，甲がＢの所有物であると過失なく信じて，現実の引渡しを受けた。この\n場合，Ａは，甲を盗まれた時から2年以内であっても，ＣがＢに支払った代価を弁償しなけれ\nば，Ｃに対し，甲の返還を求めることができない。\nエ．Ａは，その家で甲を保管していたところ，ＢがＡの家から甲を盗み，Ｃに売却した。その後，\nＣは，甲をＤに転売し，Ｄは，甲がＣの所有物であると過失なく信じて，現実の引渡しを受け\nた。この場合，Ａは，甲を盗まれた時から2年以内であっても，Ｄに対し，甲の返還を求める\nことができない。\nオ．Ａは，甲をＢに賃貸していたところ，Ｂが甲をＣに寄託した。その後，ＢがＡに無断で甲を\nＤに売却するとともに，Ｃに対し以後Ｄのために甲を占有するように命じた。Ｄは，甲がＢの\n所有物であると過失なく信じて，Ｃによる甲の占有を承諾した。この場合，Ａは，Ｄに対し，\n甲の返還を求めることができる。",
