    "year_label": "H28",
    "subject": "民法",
    "label": "第9問",
    "question": "債権者代位権に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み\n合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．名誉侵害を理由とする慰謝料請求権は，具体的な金額が当事者間において客観的に確定した\nときは，債権者代位権の目的となる。\nイ．夫婦間の契約取消権は，夫婦の一方の債権者による債権者代位権の目的となる。\nウ．認知請求権は，認知されていない子の債権者による債権者代位権の目的となる。\nエ．詐欺による取消権は，債権者代位権の目的とはならない。\nオ．遺留分減殺請求権は，遺留分権利者が権利行使の確定的意思を有することを外部に表明した\nと認められる特段の事情がある場合を除き，債権者代位権の目的とはならない。",
