    "question": "契約に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後記1から\n5までのうちどれか。（解答欄は，）\nア．贈与は，当事者の一方が自己の財産を無償で相手方に与える意思を表示し，相手方が受諾を\nすることによって，その効力を生ずるから，贈与を受ける者が贈与の申込みをし，相手方がこ\nれを承諾しても贈与の効力は生じない。\nイ．売買契約において瑕疵担保責任を免除する特約がある場合であっても，その当時売買の目的\n物について瑕疵があることを売主が知りながらその瑕疵があることを告げなかったときには，\n売主は瑕疵担保責任を免れない。\nウ．判例によれば，ＡがＢ所有の甲建物を賃貸権限を有しないＣから賃借している場合において，\nＢがＡに甲建物の明渡しを求めたときは，Ａは，甲建物を使用収益することができなくなるお\nそれが生じたものとして，Ｃに対し，それ以降の賃料の支払を拒絶することができる。\nエ．賃借人が適法に賃借物を転貸した場合において，賃貸人が賃借人に対し賃借物の修繕義務を\n負うときは，賃貸人は，転借人に対しても直接に賃借物の修繕義務を負う。\nオ．有償の金銭消費寄託契約において，当事者が返還の時期を定めなかったときは，寄託者は，\n受寄者に対し相当の期間を定めて催告をしなければ，金銭の返還を請求することができない。",
