    "question": "委任契約に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わ\nせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．委任契約を債務不履行により解除したときは，その解除は，将来に向かってのみその効力を\n生ずる。\nイ．準委任契約は，書面でしなくてもその効力を生ずるが，委任契約は，書面でしなければ，そ\nの効力を生じない。\nウ．受任者がその委任事務処理の必要上負担した債務を委任者に対し受任者に代わって弁済する\nことを請求する権利については，委任者がこれを受働債権として相殺することはできない。\nエ．委任契約は，受任者の死亡によって終了するが，委任者の死亡によっては終了しない。\nオ．受任者は，特約がなくとも，委任者に対して報酬を請求することができる。",
