    "question": "年齢に関する次のアからオまでの各記述のうち，誤っているものを組み合わせたものは，後記1\nから5までのうちどれか。（解答欄は，）\nア．15歳に達した者は，遺言をすることができる。\nイ．妻が26歳，夫が19歳の夫婦は，特別養子縁組における養親となることができる。\nウ．普通養子縁組において養子となる者が18歳であるときは，その法定代理人が，これに代わ\nって，縁組の承諾をすることができる。\nエ．養親となる者が家庭裁判所に対して特別養子縁組の成立の申立てをした時点で，養子となる\n者が10歳であるときは，家庭裁判所は，特別養子縁組を成立させることはできない。\nオ．16歳の子を持つ母がその子の父との婚姻により氏を改めたため，その子が父母と氏を異に\nする場合には，その子は，父母の婚姻中に限り，家庭裁判所の許可を得ないで，戸籍法の定め\nるところにより届け出ることによって，その父母の氏を称することができる。",
