    "question": "夫婦であるＡとＢの間に未成年の子Ｃがいる場合に関する次のアからオまでの各記述のうち，\n誤っているものを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．Ａが成年被後見人である場合には，Ｃに対する親権はＡの成年後見人とＢが共同で行使する。\nイ．ＡとＢがいずれも18歳である場合には，Ｃに対する親権は，Ａの親権者とＢの親権者が共\n同で行使し，ＡとＢのいずれにも親権者がいない場合には，家庭裁判所がＣについて未成年後\n見人を選任する。\nウ．Ｃが18歳である場合には，Ａが死亡し，その後にＢの親権が停止されたときでも，Ｃは，\nＢの同意を得れば婚姻をすることができる。\nエ．ＡとＢが離婚し，ＢがＣの親権者となった後に，ＢがＤと再婚し，ＣがＤの養子となった場\n合には，ＢとＤがＣの親権者となる。\nオ．判例によれば，Ａが死亡し，その相続人がＢとＣの二人であり，ＢがＣの親権者である場合\nにおいて，ＢがＡを被相続人とする相続につき自ら相続放棄をするのと同時にＣを代理してＣ\nについて相続放棄をしたときは，Ｂ及びＣの相続放棄はいずれも有効となる。",
