    "subject": "民法",
    "label": "第15問",
    "question": "共同相続に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組み合わ\nせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．共同相続人であるＡとＢの間で遺産分割協議が成立した場合において，Ａがその協議におい\nて負担した債務を履行しないときであっても，ＢはＡの債務不履行を理由に遺産分割協議を解\n除することはできない。\nイ．共同相続人は，既に成立している遺産分割協議の全部を共同相続人全員の合意により解除し\nた上で，改めて遺産分割協議を成立させることはできない。\nウ．共同相続が生じた場合，相続人の一人であるＡは，遺産の分割までの間は，相続開始時に存\nした金銭を相続財産として保管している他の相続人Ｂに対して，自己の相続分に相当する金銭\nの支払を求めることはできない。\nエ．Ａ及びＢがＣに対して400万円の連帯債務を負担していたところ，Ａが死亡し，その妻Ｄ\n及び子Ｅが相続した場合，Ｃは，Ｅに対して，Ａの負担していた400万円の債務全額の支払\nを請求することができる。\nオ．Ａ，Ｂ及びＣが共同相続した甲土地の共有持分権をＣから譲り受けたＤが，Ａ及びＢとの共\n有関係の解消のためにとるべき裁判手続は，遺産分割審判である。",
