    "year": 2016,
    "year_label": "H28",
    "subject": "商法",
    "label": "第16問",
    "question": "(配点：2）\n株式会社の設立に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，\n後記1から5までのうちどれか。（解答欄は，）\nア．法人は，発起人及び設立時取締役のいずれにもなることができない。\nイ．会社法上の公開会社でない株式会社を設立する場合には，発行可能株式総数を定款で定めな\nければならないが，発行可能株式総数は，設立時発行株式の総数の4倍を超えてもよい。\nウ．発起人のうちの一人が設立時発行株式の株主となる権利を全て失った場合であっても，他の\n発起人がその引き受けた設立時発行株式について出資の履行をした財産の価額が定款に記載さ\nれた設立に際して出資される財産の価額又はその最低額を満たしているときは，株式会社の設\n立の無効事由とはならない。\nエ．設立時募集株式の引受人は，設立時募集株式の払込金額の全額の払込みをする前に設立時募\n集株式の株主となる権利を譲渡した場合には，当該譲渡を成立後の株式会社に対抗することが\nできないが，当該払込みをした後に設立時発行株式の株主となる権利を譲渡した場合には，当\n該譲渡を成立後の株式会社に対抗することができる。\nオ．判例の趣旨によれば，募集設立において払込みの取扱いをした銀行は，払い込まれた金額に\n相当する金銭の保管に関する証明書を発起人に交付した後は，払い込まれた金銭を株式会社の\n成立前に発起人に返還したことをもって成立後の株式会社に対抗することができない。",
    "question_no": 16,
    "options": [
      "ア イ",
      "ア ウ",
      "イ オ",
      "ウ エ",
      "エ オ"
    ],
    "answer": 2,
    "answer_display": "3",
