    "year": 2016,
    "year_label": "H28",
    "subject": "商法",
    "label": "第17問",
    "question": "(配点：2）\n発行済株式の総数が5000株である株式会社が，募集株式について，金銭以外の財産（以下\n「現物出資財産」という。）を出資の目的とする旨並びに当該財産の内容及び価額を定めた場合に\nおける検査役の調査の要否に関する次のアからオまでの各記述のうち，誤っているものを組み合わ\nせたものは，後記1から5までのうちどれか。なお，特別法の規定により現物出資財産の出資に関\nする会社法の規定の適用が除外される場合は，考慮しないものとする。（解答欄は，）\nア．当該株式会社が募集株式の引受人に割り当てる株式の総数が500株である場合には，当該\n募集株式の引受人が給付する現物出資財産の価額に関する検査役の調査は不要である。\nイ．当該株式会社が現物出資財産について定めた価額の総額が500万円である場合には，当該\n現物出資財産の価額に関する検査役の調査は不要である。\nウ．当該株式会社から1000株の割当てを受けた募集株式の引受人が，現物出資財産として，\nその価額が1000万円と定められた市場価格のある有価証券を給付する場合において，法務\n省令で定める方法により算定される当該有価証券の市場価格も1000万円であるときは，当\n該有価証券についての現物出資財産の価額に関する検査役の調査は不要である。\nエ．当該株式会社から1000株の割当てを受けた募集株式の引受人が，現物出資財産として，\nその価額が1000万円と定められた不動産を給付する場合において，当該価額が相当である\nことについて税理士の証明を受けたときは，当該証明を受けた当該不動産についての現物出資\n財産の価額に関する検査役の調査は不要である。\nオ．当該株式会社から1000株の割当てを受けた募集株式の引受人が，現物出資財産として，\n当該株式会社に対する弁済期が到来していない金銭債権を給付する場合において，当該金銭債\n権について定められた価額と当該金銭債権に係る負債の帳簿価額とがいずれも1000万円で\nあるときは，当該金銭債権についての現物出資財産の価額に関する検査役の調査は不要である。",
