    "year_label": "H28",
    "subject": "商法",
    "label": "第18問",
    "question": "(配点：2）\n会社法上の公開会社における募集株式の発行に関する次のアからオまでの各記述のうち，誤って\nいるものを組み合わせたものは，後記1から5までのうちどれか。なお，募集株式を引き受けよう\nとする者がその総数の引受けを行う契約を締結する場合は，考慮しないものとする。（解答欄は，\n）\nア．判例の趣旨によれば，募集事項の株主に対する通知又は公告をいずれも欠いたことは，募集\n株式の発行差止請求をしたとしても差止めの事由がないためにこれが許容されないと認められ\nる場合でない限り，募集株式の発行の無効原因となる。\nイ．募集に係る株式の発行が，法令又は定款に違反しない場合であっても，著しく不公正な方法\nにより行われる場合において，株主が不利益を受けるおそれがあるときは，株主は，株式会社\nに対し，当該株式の発行をやめることを請求することができる。\nウ．株式会社が株主に株式の割当てを受ける権利を与える場合には，株主は，募集株式の引受け\nの申込みをしなくても，募集株式の引受人となる。\nエ．募集株式の引受人は，募集株式の払込金額の払込みをする債務と株式会社に対する債権とを\n相殺することができない。\nオ．募集株式の引受人が募集株式の払込金額の払込みを仮装した場合には，当該払込みの仮装に\n関する職務を行った取締役（当該払込みを仮装したものを除く。）は，その職務を行うについ\nて注意を怠らなかったことを証明したときであっても，株式会社に対し，払込みを仮装した払\n込金額の支払をする義務を負う。",
