    "id": "h28_minpo_19",
    "year": 2016,
    "year_label": "H28",
    "subject": "商法",
    "label": "第19問",
    "question": "(配点：2）\n甲株式会社は，会社法上の公開会社でない取締役会設置会社であり，これまで新株予約権を発行\nしたことがない。甲株式会社の発行可能株式総数は1万株で，発行済株式の総数は8500株（自\n己株式500株を含む。）である。\n甲株式会社が発行する新株予約権に関する次のアからオまでの各記述のうち，正しいものを組み\n合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．甲株式会社は，募集新株予約権について，新株予約権の目的である株式の数を10株，新株\n予約権を行使することができる期間の初日を割当日の1年後の日，募集新株予約権の数を30\n0個と決定し，新株予約権300個を発行することができる。\nイ．甲株式会社が新株予約権の発行後に定款を変更して会社法上の公開会社となる場合には，当\n該新株予約権の新株予約権者は，甲株式会社に対し，自己の有する新株予約権を公正な価格で\n買い取ることを請求することができる。\nウ．甲株式会社の株主総会の決議によって，募集新株予約権についての募集事項の決定を取締役\n会に委任し，取締役会がその委任に基づいて募集事項を決定した場合には，甲株式会社は，割\n当日の2週間前までに，当該募集事項を株主に通知し，又は公告しなければならない。\nエ．甲株式会社がその発行する新株予約権を引き受ける者の募集において株主に新株予約権の割\n当てを受ける権利を与える場合には，甲株式会社も，自己株式について当該権利を有する。\nオ．募集新株予約権の引受けの申込みをした者は，割当日に，甲株式会社の割り当てた募集新株\n予約権の新株予約権者となるが，募集新株予約権と引換えに金銭の払込みを要する場合には，\n募集新株予約権についての払込期日までに，払込金額の全額の払込みをしなければ，当該募集\n新株予約権を行使することができない。",
