    "subject": "商法",
    "label": "第24問",
    "question": "(配点：2）\n持分会社に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後記1\nから5までのうちどれか。（解答欄は，）\nア．業務を執行しない無限責任社員は，業務を執行する社員の全員の承諾があれば，その持分の\n全部を他人に譲渡することができる。\nイ．持分会社の社員が死亡した場合にはその相続人が当該社員の持分を承継する旨の定款の定め\nがあるときは，当該相続人が持分を承継した時に，当該相続人に係る定款の変更をしたものと\nみなされる。\nウ．持分会社の成立後に加入した社員は，その加入前に生じた持分会社の債務については，弁済\nする責任を負わない。\nエ．合資会社を退社した社員は，その登記をする前に生じた当該合資会社の債務について，従前\nの責任の範囲内でこれを弁済する責任を負う。\nオ．合資会社の有限責任社員は，その責任の限度を誤認させる行為をしたときであっても，出資\nの範囲を超えて合資会社の債務を弁済する責任を負わない。",
    "question_no": 26,
