    "year": 2016,
    "year_label": "H28",
    "subject": "商法",
    "label": "第25問",
    "question": "(配点：2）\n株式会社の吸収合併，吸収分割又は株式交換（以下「吸収合併等」という。）に関する次のアか\nらオまでの各規律のうち，株主保護を直接の目的とするものでないものを組み合わせたものは，後\n記1から5までのうちどれか。（解答欄は，）\nア．吸収合併等の各当事会社は，いずれも，原則として，株主総会の特別決議によって，吸収合\n併契約等の承認を受けなければならない。\nイ．吸収合併等の各当事会社は，いずれも，吸収合併契約等備置開始日から，吸収合併契約等の\n内容等を記載し，又は記録した書面又は電磁的記録をその本店に備え置かなければならない。\nウ．振替株式の発行者が吸収合併等をしようとする場合には，当該発行者は，原則として，振替\n機関等に対し，株式買取請求に係る振替株式の振替を行うための口座の開設の申出をしなけれ\nばならない。\nエ．吸収合併等の各当事会社の株主は，一定の場合には，自己が株式を有する会社に対し，吸収\n合併等をやめることを請求することができる。\nオ．吸収合併等の無効の訴えに係る請求を認容する判決は，第三者に対してもその効力を有する。",
