    "id": "h28_minpo_28",
    "year": 2016,
    "year_label": "H28",
    "subject": "商法",
    "label": "第26問",
    "question": "(配点：2）\n会社関係訴訟に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後\n記1から5までのうちどれか。（解答欄は，）\nア．株式の発行の効力が生じた後に株式を取得した株主は，新株発行の無効の訴えを提起するこ\nとができない。\nイ．株式会社が取締役に対してその責任を追及する訴えを提起する場合には，当該取締役の普通\n裁判籍の所在地を管轄する地方裁判所に当該訴えを提起することを要する。\nウ．判例の趣旨によれば，任期の満了により取締役を退任したが，会社法又は定款で定めた取締\n役の員数を欠くため，なお取締役としての権利義務を有する者については，訴えをもってその\n解任を請求することができない。\nエ．最終完全親会社等の株主が特定責任追及の訴え（いわゆる多重代表訴訟）を提起するために\nは，当該株主は，当該最終完全親会社等に対し，書面で特定責任追及の訴えの提起を請求しな\nければならない。\n- 12 -\nオ．会社の設立の無効の訴えについては，当該訴えに係る請求を認容する確定判決が第三者に対\nしてもその効力を有するため，被告は，当該請求を認諾することができない。",
