    "id": "h28_minpo_30",
    "year": 2016,
    "year_label": "H28",
    "subject": "商法",
    "label": "第28問",
    "question": "(配点：2）\n商行為に関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後記1か\nら5までのうちどれか。（解答欄は，）\nア．商人である対話者の間において契約の申込みを受けた者が直ちに承諾をしなかったときは，\nその申込みは，その効力を失う。\nイ．商行為の代理人が本人のためにすることを示さないでこれをした場合には，相手方が，代理\n人が本人のためにすることを知らなかったときであっても，代理人に対して履行の請求をする\nことはできない。\nウ．匿名組合員は，自己の氏名を営業者の商号中に用いることを許諾した場合には，営業者を代\n表することができる。\nエ．商人がその営業の部類に属する契約の申込みを受けた場合において，その申込みとともに受\nけ取った物品があるときは，その申込みを拒絶したときであっても，その物品を保管する必要\nはない。\nオ．商行為によって生じた債権を担保するために設定された質権の質権設定者は，債務の弁済期\n前の契約において，質権者に弁済として質物の所有権を取得させることを約することができる。",
