    "label": "第35問",
    "question": "訴えに関する次のアからオまでの各記述のうち，正しいものを組み合わせたものは，後記1から\n5までのうちどれか。（解答欄は，）\nア．訴えの提起による時効の中断の効力発生の時期は，被告に対する訴状の送達の時である。\nイ．訴えの取下げは，被告に訴状が送達された後は，被告の同意を得なければすることができな\nい。\nウ．訴状が公示送達の方法により送達され，その後，判決も同様に公示送達の方法によって送達\nされた場合には，これらの書類の送達の効力は，掲示を始めた日から2週間を経過することに\nよって生ずる。\nエ．重複する訴えが提起された場合，被告が異議を述べないで本案について弁論をしたときであ\nっても，当該訴えは適法とはならない。\nオ．訴状は，第一回の口頭弁論期日後は，これを却下することができない。",
