    "label": "第37問",
    "question": "重複起訴の禁止に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいものを組\nみ合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．ＸのＹに対する不動産の所有権確認請求訴訟の係属中に，ＸがＺに対して当該不動産の所有\n権の確認を求める別訴を提起することは，許されない。\nイ．ＸのＹに対する貸金300万円の債務不存在確認請求訴訟の係属中に，ＹがＸに対し当該貸\n金の返還を求める別訴を提起することは，許されない。\nウ．ＸのＹに対する売買代金支払請求訴訟であるＡ訴訟とＹのＸに対する貸金返還請求訴訟であ\nるＢ訴訟とがそれぞれ係属中に，Ａ訴訟の被告Ｙが，Ａ訴訟において，Ｂ訴訟で請求している\n貸金債権を自働債権とする相殺の抗弁を主張することは，許されない。\nエ．ＸのＹに対する土地の所有権に基づく所有権移転登記手続請求訴訟の係属中に，ＹがＸに対\nし当該土地の所有権の確認を求める別訴を提起することは，許されない。\nオ．ＸのＹに対する手形金債務不存在確認請求訴訟の係属中に，ＹがＸに対し当該手形金の支払\nを求める別訴を手形訴訟により提起することは，許されない。",
