    "subject": "民事訴訟法",
    "label": "第40問",
    "question": "証拠に関する次のアからオまでの各記述のうち，判例の趣旨に照らし誤っているものを組み合わ\nせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．反対尋問を経ていない証言についても，裁判所は，その証言を事実認定の資料とすることが\nできる。\nイ．当事者の一方が提出した証拠により相手方に有利な事実を認定するには，相手方の援用がな\nければならない。\nウ．口頭弁論の全趣旨のみをもって事実を認定することは，許されない。\nエ．損害が生じたことが認められる場合において，損害の性質上その額を立証することが極めて\n困難であるときは，裁判所は，口頭弁論の全趣旨及び証拠調べの結果に基づき，相当な損害額\nを認定することができる。\nオ．自由心証主義は，職権探知主義による訴訟にも適用される。",
