    "question": "請求の放棄又は認諾に関する次のアからオまでの各記述のうち，判例の趣旨に照らし正しいもの\nを組み合わせたものは，後記1から5までのうちどれか。（解答欄は，）\nア．請求の認諾は，相手方が出頭していない口頭弁論の期日においてもすることができる。\nイ．後見人その他の法定代理人が請求の放棄をするには，特別の授権がなければならない。\nウ．相手方が反対給付を履行することを条件にして，請求の認諾をすることができる。\nエ．請求の放棄をする旨の書面が期日外に裁判所に提出されても，当事者が口頭弁論の期日に出\n席し，その旨を陳述しなければ，請求の放棄の効力は生じない。\nオ．請求の認諾は，訴訟要件を欠く訴えにおいてもすることができる。",
